{"assumptions":[],"created_at":"2026-10-28T01:54:57.595384+00:00","domain":"probability theory","id":"claim_ddcb7fda1d0c8613217bd8c071a532b84b442f9c0415c0166f674ecc4ec3fcbe","kind":"concept","schema_version":1,"statement":"[Lem PL-exp of arXiv:2412.03415, 'Critical first passage percolation on random graphs'] Consider a branching process ${\sf BP}(F^*, h^*)$ with strictly positive lifetime distribution $F^*$. Suppose the offspring distribution $B^*\sim h^*$ is plump. Then the associated age-dependent branching process is explosive if and only if the birth-time distribution $F^*$ satisfies for some $\epsilon>0$,
 \begin{equation} 

\int_0^\epsilon [F^*]^{-1}( \exp(-1/y)) \frac{dy}{y} < \infty,\qquad \text{or equivalently} \qquad \int_{1/\epsilon}^\infty [F^*]^{-1}(e^{-u}) \frac{du}{u} < \infty.
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.353809+00:00","domain":"probability theory","id":"claim_ddcb807ec44a6fbfc4a6f8e113366bc022a4c5168b95bb687d799f281493e3d6","kind":"concept","schema_version":1,"statement":"[Lemma norm-concentration of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Let $U_1,\dots,U_n$ be i.i.d.\ random variables with ${\mathbb E}\,U_i=0$ and ${\mathbb E}\,U_i^2\leq 1$. Define $\bm{U}=(U_1,\dots,U_n)$. Then,
	\begin{align}
		{\mathbb E}\big[\big(|\bm{U}|_2-\sqrt{n}\big)_+^2\big]
		&\leq 2\mathrm{Var}(U_1^2) \leq 2\,{\mathbb E}\,U_1^4.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:02:34.826918+00:00","domain":"probability theory","id":"claim_ddcdd3ac60a00add6e026baa53e27e9899e543ee89a1e889c684c487fe8f4974","kind":"lemma","schema_version":1,"statement":"[Lemma 41 (Short-time full covariance negative moments) of arXiv:2607.19752, 'Weak Equilibrium Measures and Capacity--Hitting Identities\\ for the Hypoelliptic Third-Or'] For every $q\ge1$, after decreasing $t_0$ if necessary,
\[
    \sup_{\substack{
        0\le\delta\le1,\ z\in K_0\\
        0<t\le t_0}}
    \mathbb E_z\left[
        \lambda_{\min}\left(
            T_t^{-1}\mathcal M_{t,r}^{\delta,\mathsf O}T_t^{-1}
        \right)^{-q}
    \right]<\infty .
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.299520+00:00","domain":"probability theory","id":"claim_ddd3fa9182bc42d880bc9acc78436df5bf4883fbe324b47ea060c9b8f7bfa2b2","kind":"concept","schema_version":1,"statement":"[Prop IRL for admissible measures of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Assume~(hyp: pseudo lsc density of the paper),~(hyp: pseudo uniformity of the paper) and~(hyp: null border of the paper). Then, the Ruelle-Lanford function $I_{\mathrm{RL}}$ of $(L_n)$ exists at all $\mu\in \mathcal A$. Moreover, for all $\mu_1,\mu_2\in\mathcal A$ and $\lambda\in [0,1]$ such that $\lambda\mu_1+(1-\lambda)\mu_2\in \mathcal A$,
	\begin{equation}

		I_{\mathrm{RL}}(\lambda\mu_1+(1-\lambda)\mu_2)\leqslant \lambdaI_{\mathrm{RL}}(\mu_1)+(1-\lambda)I_{\mathrm{RL}}(\mu_2).
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.856848+00:00","domain":"probability theory","id":"claim_ddd6bf6d7727ee28596f60948166c25678f85911866ab91084cdc87082f46a04","kind":"concept","schema_version":1,"statement":"[Theorem 6 (Conditional blow-up rate along the transported maximum) of arXiv:2609.02019, '2609.02019'] Suppose that Assumption~\ref{Hypo-sigma} holds. Let $s>7/2$, let
		$v_0\in H^s$ be deterministic, and suppose that $x_0$ is a global
		maximum point of $v_0$ such that
		\[
		M_0=\Lambda v_0(x_0)>0.
		\]
		Let $(v,\tau^*)$ be as in Theorem \ref{Thm-blowup}. Let $z_0$, $M$ and $\mathcal E[f](z^*)$ be given in \eqref{eq:z=phi(x0)}, \eqref{eq:M(t) define} and \eqref{eq:E-functional}, respectively.
		Define
		\begin{equation}
			\Omega_M
			\triangleq
			\left\{
			\tau^*<\infty,
			\ \lim_{t\uparrow\tau^*}M(t)=\infty
			\right\}.
		\end{equation}
		On $\Omega_M$, set
		\begin{equation}
			\eta(t)
			\triangleq
			\frac{\mathcal E[v(t,\cdot)](z_0(t))}{M(t)^2},
			\qquad
			\overline\eta(t)
			\triangleq
			\frac1{\tau^*-t}
			\int_t^{\tau^*}\eta(r)\d r.
		\end{equation}
		Here $\mathcal E$ is the nonnegative functional defined in
		\eqref{eq:E-functional}.  Then the following assertions hold almost surely.
		\begin{enumerate}[label={\rm (\roman*)},leftmargin=0.79cm]
			\item On $\Omega_M$,
			\begin{equation}
				\limsup_{t\uparrow\tau^*}
				M(t)(\tau^*-t)
				\le2.
			\end{equation}
			\item If, on a measurable subevent of $\Omega_M$,
			\begin{equation}
				\eta_{\mathrm{av}}^-
				\triangleq
				\liminf_{t\uparrow\tau^*}\overline\eta(t)>0,
			\end{equation}
			then, on that subevent,
			\begin{equation}
				\limsup_{t\uparrow\tau^*}
				M(t)(\tau^*-t)
				\le
				\frac1{\frac12+\eta_{\mathrm{av}}^-}
				<2.
			\end{equation}
			Here the first upper bound is interpreted as zero if
			$\eta_{\mathrm{av}}^-=+\infty$.
			\item If, on a measurable  subevent of $\Omega_M$, there exists a finite
			nonnegative random variable $\eta_*\in[0,\infty)$ such that  
			\begin{equation}
				\lim_{t\uparrow\tau^*}\overline\eta(t)=\eta_*,
			\end{equation}
			then, on that subevent,
			\begin{equation}
				\lim_{t\uparrow\tau^*}
				M(t)(\tau^*-t)
				=
				\frac1{\frac12+\eta_*}.
			\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:17:33.999314+00:00","domain":"probability theory","id":"claim_ddd766c543bb45f877e01c10eacdc4a3ae0766f02dec3eb231260e6bea44239a","kind":"lemma","schema_version":1,"statement":"[Lemma 34 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Assume $t<0$. Then, the matrix $\frac{1}{\sqrt{-t}}Q_t^{-1}\begin{pmatrix}0&I_m\\I_m&0\end{pmatrix}Q_t$ is $J_0$-unitary and the function
          \begin{equation}

            S(z)=t_{Q_t^{-1}\begin{pmatrix}0&I_m\\I_m&0\end{pmatrix}Q_t}(\sigma)=(-T^{-1}\sigma(z)+(T^{-1}+tTT^{-1/2})((T^{-1}+tT)^{1/2}\sigma(z)+T^{-1})^{-1}
          \end{equation}
          is bounded if and only if $\sigma$ is bounded.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:22:01.662442+00:00","domain":"probability theory","id":"claim_ddd91329f1f1884f4ab6ba7e3a52185da4c7d14d58bfe407ef274b49054a8475","kind":"theorem","schema_version":1,"statement":"[Theorem Tstein of arXiv:2604.06012, 'Large fringe trees for random trees with given vertex degrees'] Let ${\mathbf{n}}$ be a degree statistic and $T\in\mathbb T$ a tree, 
and let $n:=|{\mathbf{n}}|$ and $m:=|T|$.
There exists a universal constant $C$, not depending on ${\mathbf{n}}$ or $T$, such 
that if\/ $\mathcal{T}_{\mathbf{n}}\in {\rm Unif}(\mathbb{T}_{\mathbf{n}})$,
then, with $\lambda:=\operatorname{\mathbb E{}} N_T({\mathcal T}_{{\mathbf{n}}})$,
\begin{align}
d_{\mathrm{TV}}\bigl( N_T({\mathcal T}_{{\mathbf{n}}}),\operatorname{Po}(\lambda)\bigr)
\leqslant C\lambda\sum_{i\in\mathcal D(T)}\frac{n_T(i)^2}{n(i)}
= 
C m^2\frac{\lambda}{n}\sum_{i\in\mathcal D(T)}\frac{p_i({\mathbf{n}}_T)^2}{p_i({\mathbf{n}})}
.\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.212679+00:00","domain":"probability theory","id":"claim_ddde61a913a852e2edb02214fef2bf685fb245f176029002bbddea344cbf292d","kind":"concept","schema_version":1,"statement":"[Proposition prop: poly_internal of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $G$ be a quasi-transitive graph that is of superlinear polynomial growth. Then, there exist positive constants $C = C(\lambda, G)$ and $c = c(\lambda,  G)$ such that, for any $x \in V$, $a > C^{\star}(\lambda,G)>1$, and $A \subseteq B_x(a)$, we have
    \begin{align}
        \mathbb P_{\lambda, a^2} \left( \mathcal{G}_{B_x(a)} \cap A = \varnothing \right) \le C \exp(-c \, |A|) \, . 
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:46:25.372058+00:00","domain":"probability theory","id":"claim_ddded71cf15bbafbdd394f730cbdd156ea28c8493eb12b3de721b70114e24703","kind":"concept","schema_version":1,"statement":"[Lemma calc2ptsimple of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] We have the following summation for $(\varepsilon_1 \varepsilon_2)^{-1/8}\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^{\rm simp}(z_1, z_2))+
o(1)$:
$$(\varepsilon_1 \varepsilon_2)^{-1/8}\sum_{n \in 2\mathbb{Z}} (-1)^{n/2}\mathbb{P}(E^{2\lambda n}_{\varepsilon_1,\varepsilon_2}) + o(1) = C_{\rm simp}
\CR(z_1,D)^{-1/8}\CR(z_2,D)^{-1/8}\sqrt{\frac{\theta_3(q^{1/4})}{\theta_2(q^{1/4})}},$$
where $C_{\rm simp} = \frac{\pi^{1/4} (\mathbf{C}_{\rm{SLE}4}^{\rm loop})^2}{2^{3/4}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:09:43.678809+00:00","domain":"probability theory","id":"claim_dde1016d59346aeaab559f4d5a91b7612b55cf25870f009060b7e326a13d6c27","kind":"definition","schema_version":1,"statement":"[Defn def.Stab.Radius of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Given  a marking  function $\xi :
W_n \times\mathbb{K}\times\hat{\mathcal{N}}_{W_n \times \mathbb{K} }\longrightarrow \mathbb{K}'$, 
 $n\in\mathbb{N} \cup \{\infty\}$ (as usual for $n=\infty$, we take $W_\infty:=\mathbb{R}^d$) and $(x,u)\in\tilde{\mu} \in\mathcal{N}_{W_n \times \mathbb{K}}$  we 
define the radius of stabilization $R_{W_n}^\xi((x,u);\tilde{\mu})$ 
to be the smallest $r \in \mathbb{N}$    such that
\begin{equation}
\xi((x,u), \tilde{\mu} \cap B_r(x)) = \xi((x,u), (\tilde{\mu} \cap B_r(x)) \cup ( \tilde \nu \cap B^c_r(x))) \,
\end{equation}
for  all $\tilde\nu\in \mathcal{N}_{W_n \times \mathbb{K}}$. The definition is naturally extended to $\tilde{\mu} \in\mathcal{N}_{\mathbb{R}^d \times \mathbb{K}}$ by setting $R_{W_n}^\xi((x,u);\tilde{\mu}) := R_{W_n}^\xi((x,u);\tilde{\mu} \cap W_n)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.864271+00:00","domain":"probability theory","id":"claim_dde30fd5aa5b49b5f941f4c370d050aba9bba5cfe37e0fd4579c4356e0ae98d4","kind":"concept","schema_version":1,"statement":"[Theorem 5 of arXiv:2511.23453, 'Convergence rates of self-repellent random walks, their local time and Event Chain Monte C'] If $Q$ is the transition matrix of a simple random walk, then the corresponding transition semigroup $(\hat P_t^{(\gamma)})_{t\geq 0}$ satisfies
    \begin{equation*}
        \norm{\hat P_t^{(\gamma)}f}_{L^2(\hat\mu)} \leq e^{-\nu (t-T)}\norm{f}_{L^2(\hat\mu)}\qquad\text{for all }f\in L_0^2(\hat\mu)\text{ and }t\geq 0
    \end{equation*}
    with $T\in O(n^{3/2})$ and inverse convergence rate
    $$\nu^{-1}\in O\left(\gamma n^3+\gamma^{-1}n^2\right).$$ 
    In particular,
    for $\gamma\propto n^{-3/2}$, the $L^2$-relaxation time is of order $O(n^{5/2})$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.038983+00:00","domain":"probability theory","id":"claim_dde3ac7e05c235b4f0ae1ae9f34338df9484d527011d3515d9fb5bb54c9ff052","kind":"concept","schema_version":1,"statement":"[Theorem 16 (\cite{MR2778606} Theorem 5.1.3) of arXiv:2606.26496, 'Homeomorphism of the Revuz correspondence under Dynkin class assumptions'] The quotient space of $\mathbf{A}_c^+$ under the equivalence relation and the family ${\sf S}$ are in one-to-one correspondence under the following relation: For $\mu \in {\sf S}$ and ${\sf A}\in\mathbf{A}_c^+$,
		 \begin{equation}
		 	\lim_{t \downarrow 0} \frac{1}{t}\int_E \mathbb{E}_x\left[  \int_{0}^{t} f(X_s)\ {\rm d}{\sf A}_s  \right]h(x)\mathfrak{m}({\rm d}x)=\int_E f(x) h(x)\mu({\rm d}x)
		 \end{equation}
		 where $h$ is any $\gamma$-excessive function and $f \in \mathscr{B}_+(E)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:23.331848+00:00","domain":"probability theory","id":"claim_dde40e165ce82c55816ccfbf06bd9531d425265fe944b6f5032b7b248b8b2231","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2506.22040, '\vspace{-3em} Khinchin inequalities for uniforms on spheres with a deficit'] Let $p \geq 2$. Suppose that  $a_1 \geq b_1 \geq b_2 \geq a_2 > 0$ with $a_1^2 + a_2^2 = b_1^2 + b_2^2 = \sigma^2$ for some $\sigma > 0$. For every vector $v$ in $\R^d$, $d \geq 2$, we have
\begin{align}\notag
&\E\left|b_1\xi_1 + b_2\xi_2 + v\right|^p - \E\left|a_1\xi_1 + a_2\xi_2 + v\right|^p \\
&\qquad\qquad\geq \frac{1}{d}(a_1^4+a_2^4 - b_1^4-b_2^4)\cdot \begin{cases}\beta_{p,d}(|v|^2+\sigma^2)^{\frac{p-4}{2}}, & 2 \leq p \leq 4, \\ \frac{p(p-2)}{8}\E|v+\sigma\xi|^{p-4}, & p > 4, \end{cases}
\end{align}
with $\beta_{p,d}$ defined in \eqref{eq:beta-def}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:36.744787+00:00","domain":"probability theory","id":"claim_dde88209bcf1a20a762e712fad82eca210fa245451af0728bfd6290dcaa702bd","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2511.14757, 'A weak convergence approach to the large deviations of the dynamic Schr\"odinger problem'] The sequence of Schr\"odinger bridges $\{\pi_\eta\}_{\eta > 0}$ satisfies an LDP on $\calC_1$ with the rate function $I_D$ given by
    \begin{equation}
    \begin{split}
        I_D(\varphi) &= I_S(\varphi_0, \varphi_1) + I_B^{\varphi_0 \varphi_1}(\varphi) \\
        &= (c - (-\psi \oplus \phi))(\varphi_0, \varphi_1) + \inf_{\nu \in U^{\varphi_0 \varphi_1}_\varphi} \frac{1}{2} \int_0^1 |\nu(t)|^2 dt,
    \end{split}
    \end{equation}
    where $U^{xy}_\varphi \coloneq \{\nu \in L^2([0,1]:\bR^d): \varphi(\cdot) = \int_0^{\cdot} (b(s, \varphi(s) + \sigma(s, \varphi(s))\nu_s)ds\}$, and $(\psi, \phi)$ are a pair Kantorovich potentials. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.198802+00:00","domain":"probability theory","id":"claim_ddf51fb44fb8652d61abf5e22cfc20938b65b8047ca0d956e035635d79d13cd2","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Suppose $(\mathcal{Z}_T$, $\mathcal{T})$ be fixed as in \eqref{def-zt}. Then, a set $\wtilde{\K}\subset\mathcal{Z}_T$ is $\mathcal{T} - $relatively compact if the following three conditions hold:
		\begin{itemize}
			\item[(i)] \begin{equation}
				\sup_{u\in\wtilde{\K}}\sup_{t\in[0,T]}\|u(t)\|_{\Vp}<\infty.
			\end{equation}
			\item[(ii)] $\wtilde{\K}$ is bounded in the space  $L^2(0,T;D(A))$, i.e., 
			\begin{equation}
				\sup_{u\in\wtilde{\K}}\bigg(\int_0^T\|\Delta u(t)\|_{L^2(\bO)}^2dt \bigg) < \infty.
			\end{equation}
			\item[(iii)] \begin{equation}
				\lim_{\delta\to 0}\sup_{u\in\wtilde{\K}}\sup_{s,t\in[0,T],|t-s|\leq\delta}\|u(t) -u(s)\|_{L^2(\bO)} = 0.
			\end{equation}
		\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:45:10.082424+00:00","domain":"probability theory","id":"claim_ddf915f34f2d473e9be4f481694f9eb1c0eeea008f391bd79104a8e132732164","kind":"concept","schema_version":1,"statement":"[Conjecture BigConj of arXiv:2504.18739, 'discrete analogues of second-order Riesz transforms'] For all $j, k=1,2,\ldots,d$, $j\neq k$, 
\begin{align}
    \|\mathcal{R}^{(jk)}\|_{\ell^p\to\ell^p}
    =\|R_{\mathrm{dis}}^{(jk)}\|_{\ell^p\to\ell^p}
    =\|R^{(jk)}\|_{L^p\to L^p}, 
\end{align} 
and
\begin{align}
    \|\mathcal{R}^{(jj)}-\mathcal{R}^{(kk)}\|_{\ell^p\to\ell^p}
    =\|R_{\mathrm{dis}}^{(jj)}-R_{\mathrm{dis}}^{(kk)}\|_{\ell^p\to\ell^p}
    =\|R^{(jj)}-R^{(kk)}\|_{L^p\to L^p}. 
\end{align}
For all $j=1, 2, \dots d$, 
\begin{align}
    \|\mathcal{R}^{(jj)}\|_{\ell^p\to\ell^p}
    =\|R_{\mathrm{dis}}^{(jj)}\|_{\ell^p\to\ell^p}
    =\|R^{(jj)}\|_{L^p\to L^p}.
\end{align} (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:07.309091+00:00","domain":"probability theory","id":"claim_ddfa137829e9ca2e36ffa568fa00a0193ea9d2265cab2633a6ab8ba847e6e8b0","kind":"theorem","schema_version":1,"statement":"[Theorem 3 of arXiv:2606.24485, 'On the convex hull of a planar Brownian bridge with a random Gaussian endpoint'] For $0\le \sigma<1$,
	\begin{equation}
		\E [M_\sigma]
		=
		\frac{1}{\sqrt{2\pi}}
		\ob{\sigma+\frac{\arccos\sigma}{\sqrt{1-\sigma^2}}}.
	\end{equation}
	At $\sigma=1$, the continuous extension is
	\begin{equation}
		\E [M_1]=\sqrt{\frac{2}{\pi}}.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.239992+00:00","domain":"probability theory","id":"claim_de02cf2180dceb2f89d6b854deda3874685365d128d0fbe5fc7e1fd630fa2b46","kind":"definition","schema_version":1,"statement":"[Definition 56 of arXiv:2607.18104, '2607.18104'] Suppose that $(\eta_t)_{t \geq 0}$ is an ASEP on $\Z$, and that $(\bar{\eta}^{\per}_t)_{t \geq 0}$ is an unwrapped periodic ASEP. Fix some $\rho \in [0,1]$ and $\theta \in \R$, which are allowed to depend on $N$. Set
\begin{equation}
    E_t := \left\{ \{ x, x+1 \} \colon x \in \mathcal{I}^{\rho}_{N}(\theta,\theta+1) \right\}  
\end{equation} for all $t\geq 0$. We define the $\boldsymbol{(\rho,\theta,1,N)}$\textbf{-reference frame basic coupling} as follows. 
For all edges, we place independent rate $(1+q)$ Poisson clocks. 
Whenever the clock of an edge $e=\{ x,x+1\}$ rings, and the exclusion processes are in states $\eta$ and $\eta^{\prime}$, respectively, we sample an independent Bernoulli-$(1+q)^{-1}$-distributed random variable $B$. If
\begin{itemize}
\item $B=1$ and $e\in E_t$. Then, if $\eta(x)=1-\eta(x+1)=1$ holds, we move the particle at site $x$ to site $x+1$ in configuration $\eta$. Similarly, if $\bar{\eta}^{\per}(x)=1-\bar{\eta}^{\per}(x+1)=1$ holds, we move for all $j\in \Z$ the particle at site $x+jN$ to site $x+jN+1$ in $\bar{\eta}^{\per}$. 
\item $B=0$ and $e\in E_t$. Then, if $\eta(x)=1-\eta(x+1)=0$ holds, we move the particle at site $x+1$ to site $x$ in configuration $\eta$. Similarly, if $\bar{\eta}^{\per}(x)=1-\bar{\eta}^{\per}(x+1)=0$ holds, we move for all $j\in \Z$ the particle at site $x+jN+1$ to site $x+jN$ in  $\bar{\eta}^{\per}$. 
\item $B=1$ and $e \notin E_t$. Then, if $\eta(x)=1-\eta(x+1)=1$ holds, we move the particle at site $x$ to site $x+1$ in configuration $\eta$.
\item $B=0$ and $e\notin E_t$. Then, if $\eta(x)=1-\eta(x+1)=0$ holds, we move the particle at site $x+1$ to site $x$ in configuration $\eta$.
\end{itemize}
In all other cases, the configuration remains unchanged.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:47.659986+00:00","domain":"probability theory","id":"claim_de08b49e6fdb11f353c3982c1c463ed99b6721fd14c2882ba5e3c980b1e50f2c","kind":"concept","schema_version":1,"statement":"[Lemma 21 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] Let $\mathbf{X} \in \Omega G([0,T], V)$ be a smooth rough path. Then the Schwinger-Dyson kernel equation satisfies the integro-differential equation
  \begin{align*}
      \frac{\partial^2 K_{0}}{\partial s \partial t} &=  \frac{\partial K_{1}(s,t) }{\partial s} [\boldsymbol{x}_t], \\
      \frac{\partial^2 K_{n}}{\partial s \partial t} &= \frac{\partial \sigma_n( \psi_{s, \cdot}, \phi_{\cdot, t})_s}{\partial t}\,[\boldsymbol{x}_s] - \frac{\partial \sigma_n( \psi_{s, \cdot}, \phi_{\cdot, t})_t}{\partial s} [\boldsymbol{x}_t] \\
      &\qquad - \int_s^t \frac{\partial^2 \sigma_n( \psi_{s, \cdot}, \phi_{\cdot, t})_u}{\partial s \partial t} [\boldsymbol{x}_u] du,
  \end{align*}
  with conditions $K_{\bullet}(s,s) = id_{T^{\leq \kappa + \zeta}(V)}$ for every $s \in [0, T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.486808+00:00","domain":"probability theory","id":"claim_de0e7368179c9debd9a66e1379936e75bf6ba68b95cbefc73aa69e4c02c17443","kind":"definition","schema_version":1,"statement":"[Deff eq:doapt of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $S$ be a semigroup  with generator $A$ satisfying $\|S(t)\|_{\mathcal{L}(L^p, L^p)} \lesssim e^{-t}$ (for example if $A$
is a sectorial operator, see (semigrp-deff of the paper)).
  Then for any $\vartheta > 0$ we define the fractional power of $(-A)$ as
  \begin{equation}
      (-A)^{-\vartheta} = \frac{1}{\Gamma(\vartheta)} \int_0^\infty t^{\vartheta - 1} S(t)  dt \,, 
  \end{equation}
  where $\Gamma$ is the usual $\Gamma$-function and the integral exist by the assumed bound on $S$. 

  Furthermore, we define 
  \begin{equation}
      (-A)^\vartheta = ((-A)^{-\vartheta})^{-1} \qquad \textrm{and}\quad A^0 = I \,.
  \end{equation}","status":"unverified"}

