{"assumptions":[],"created_at":"2026-10-28T00:59:45.528160+00:00","domain":"probability theory","id":"claim_dec26e4837b494e1154b26f2c80a13957e5eae7506c3dec744ff80bf82ce4f1d","kind":"definition","schema_version":1,"statement":"[Definition def:entropies of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] Let $\mathtt{p}:=\{p_i, i \geq 0\}$ be a non-degenerate discrete probability distribution.
\begin{enumerate}
\item 
The Shannon entropy of $\mathtt{p}$ is given by the formula
\begin{equation}
\mathbf H_{SH} (\mathtt{p}) =-\sum_{i = 0}^{\infty}  p_i\log {p_i}  =  \sum_{i = 0}^{\infty}   p_i \log\left(\frac{1}{p_i}\right)  .
\end{equation}
\item
The R\'{e}nyi entropy with parameter $\alpha>0,$ $\alpha\ne1$ of $\mathtt{p}$ is given by the formula
\begin{equation}
\mathbf H_{R}(\alpha, \mathtt{p}) = \frac{1}{1-\alpha} \log
\left(\sum_{i=0}^\infty p_i^{\alpha}\right).
\end{equation}

 \item  The generalized R\'enyi entropy with parameter $\alpha > 0$ of $\mathtt{p}$ is given by the formula
    \begin{equation}
    \mathbf H_{GR}(\alpha, \mathtt{p}) = - \frac{\sum_{i = 0}^{\infty} p_i^\alpha   \log{p_i}  }{\sum_{i = 0}^{\infty} p_i^\alpha}
    = \frac{\sum_{i = 0}^{\infty} p_i^\alpha   \log{\frac{1}{p_i}}  }{\sum_{i = 0}^{\infty} p_i^\alpha}.
    \end{equation}

\item
    The generalized R\'enyi entropy with parameters $\alpha > 0$, $\beta > 0$, $\alpha \neq \beta$ of $\mathtt{p}$ is given by the formula
    \begin{equation}
    \mathbf H_{GR}(\alpha, \beta, \mathtt{p}) = \frac{1}{\beta - \alpha}  \log\left(\frac{\sum_{i = 0}^{\infty} p_i^\alpha }{\sum_{i = 0}^{\infty} p_i^\beta}\right).
    \end{equation}

\item
    The Tsallis entropy with parameter $\alpha > 0$, $\alpha \neq 1$ of $\mathtt{p}$ is given by the formula 
    \begin{equation}
    \mathbf H_T(\alpha, \mathtt{p}) = \frac{1}{1-\alpha} \left( \sum_{i = 0}^{\infty} p_i^\alpha - 1 \right).
    \end{equation}

\item
    The Sharma--Mittal entropy with parameters $\alpha > 0$, $\beta > 0$, $\alpha \neq 1$, $\beta \neq 1 $ of $\mathtt{p}$ is given by the formula
    \begin{equation}
    \mathbf H_{SM}(\alpha, \beta, \mathtt{p}) = \frac{1}{1-\beta} \left( \left( \sum_{i = 0}^{\infty} p_i^\alpha \right)^{\frac{1- \beta}{1 - \alpha}} - 1 \right).
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.152788+00:00","domain":"probability theory","id":"claim_dec4981caa5d7485d9a10bee48ecb727b0a027ca88e1cd5cc5716822d4357ac7","kind":"lemma","schema_version":1,"statement":"[Lemma 30 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix $\theta \in (0,\xi_c / 8)$. Then, there exists $\xi_0 \in (0,\xi_c)$ depending only on $\theta$ and a choice of the functions $b,M$ (depending only on $\theta$) such that the following is true for all $\xi \in [\xi_0,\xi_c]$. Fix $\varepsilon \in (0,1)$ and a bounded open set $U \subseteq \CC$. Then, there exists deterministic constant $C>0$ (depending only on $\varepsilon,\theta$, and $U$) such that with probability at least $1-\varepsilon$, we have that
\begin{equation*}
