\end{align*} We will refer to $\mu_B$ as the  \emph{equilibrium measure} and to $k(B)$ as the \emph{Robin constant}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:56:36.587005+00:00","domain":"probability theory","id":"claim_dee61699176b066c0dc5ce2ba41697060d8a2294ec32717e3085b68c349dd160","kind":"lemma","schema_version":1,"statement":"[Lem zetalem of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] We define 
\begin{equation*}
\zeta_1 =
\begin{cases}
\mu_1 b l t^{-\frac{1}{\mu_1 b}}(1-
\frac{(\mu_1 b+1)b}{(\mu_1 b)^3}\frac{\log t+1}{t}) & \text{if $\mu_1>0$,}\\
(2b)^{1/2}e^{-1}l e^{-(2t/b)^{1/2}}t^{1/2} & \text{if $\mu_1=0$}
\end{cases}
\end{equation*}
and
\begin{equation*}
\zeta_2 =
\begin{cases}
 e^{\frac{1}{b\mu_1}-5}t^{-\frac{1}{\mu_1 b}}e^{-\frac{(1-5b\mu_1)\log t}{b^2 \mu_{1}^3 t}}
 & \text{if $\mu_1>0$,}\\
e^{10} t^{-5} e^{-(2t/b)^{1/2}} & \text{if $\mu_1=0$.}
\end{cases}
\end{equation*}
Then, we have
\begin{equation*}
-\frac{\zeta_1}{\zeta_1'}=b\mu_1 t- b\log (-\zeta_{1}')+b\log l+O(t^{-1/2}), \quad \text{as $t\to\infty$}
\end{equation*}
and
\begin{equation*}
-\frac{\zeta_2}{\zeta_2'}= b\mu_1 t- b\log \zeta_2-5b\log t
+O(t^{-1/2}), \quad \text{as $t\to\infty$}.
\end{equation*}
Moreover, if $\mu_1>0$, we have
\begin{equation*}
-\zeta_i'\simeq t^{-\frac{1}{\mu_1 b}-1}, \quad \zeta_i'' \simeq t^{-\frac{1}{\mu_1 b}-2}, \quad  -\zeta_i''' \simeq t^{-\frac{1}{\mu_1 b}-3}
\end{equation*}
for any $i=1,2$ and $t\ge 2$. On the other hand, if $\mu_1=0$, we have
\begin{equation*}
-\zeta_1'\simeq e^{-(2t/b)^{1/2}}, \quad \zeta_1'' \simeq e^{-(2t/b)^{1/2}} t^{-1/2}, \quad  -\zeta_1''' \simeq e^{-(2t/b)^{1/2}} t^{-1}
\end{equation*} 
and
\begin{equation*}
    -\zeta_2'\simeq e^{-(2t/b)^{1/2}}t^{-11/2}, \quad \zeta_2'' \simeq e^{-(2t/b)^{1/2}} t^{-6}, \quad  -\zeta_2''' \simeq e^{-(2t/b)^{1/2}} t^{-13/2}
\end{equation*}
for any $t\ge 2$. Finally, we have 
$$
|(\zeta_2''/\zeta_2')'|=O(t^{-1}|\zeta_2''/\zeta_2'|) \quad \text{as $t\to\infty$.}
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:32:11.130943+00:00","domain":"probability theory","id":"claim_dee6ac9093ef09e6b0e065604edb84429aeea254081100337cc32aaec58c8493","kind":"lemma","schema_version":1,"statement":"[Lemma lem:I:UB of arXiv:2510.09818, 'On the Fourier dimension of fractional Brownian graphs'] There exists $C < \infty$ depending only on $H$ such that
