{"assumptions":[],"created_at":"2026-10-27T23:13:49.973815+00:00","domain":"probability theory","id":"claim_e0248702424ad487374fee51c4621e4c5c189e4e049f5287647db957908b2dc1","kind":"lemma","schema_version":1,"statement":"[Lemma lem:2_35 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] There exist constants $C_{\mathfrak{t}}, C_{1}>0$ and $q \geqslant 1$ such that the following holds. 

  For every initial condition ${\tt u}\in\R^{\mcb{n}}$ and under assumption that (equation eq:assumpV of the paper) holds, the statement of Lemma~(lem:solutionconstruction of the paper) holds with the existence time $\tilde{T}_{\Xi}$ replaced by  $\tilde{T}_{\hat\Xi}$, with $\tilde{T}_{\hat\Xi} = C_{\mathfrak{t}}\hat\Xi^{-p}$ for   
\begin{equ}\hat\Xi =
\max \Big(
{\talloblong \omega\xi \talloblong}_{4}, C_R,
\|V\|_{C^9(\R^{\mcb{n}})} \Big)\,.
\end{equ}
In particular, $\hat{\Xi}$ is independent of ${\tt u}$.

Moreover, on the event $\{T\leqslant \tilde T_{\hat\Xi}\}$, 
    \begin{equs}
       \sup_{t\in[0,T]} |{u_\eps}(t)| \leqslant |{\tt u}|+C_1T^{-q}\,.
    \end{equs}
Finally, in view of the $\eps \downarrow 0$ convergence in probability of $u_\eps$ to a limit $u$ stated in Theorem~(thm:main of the paper), on the event $\{T\leqslant \tilde T_{\hat\Xi}\}$, one has
    \begin{equs}
  \sup_{t\in[0,T]} |{u}(t)|\leqslant    \liminf_{\eps\downarrow0} \sup_{t\in[0,T]} |{u_{\eps}}(t)| \leqslant |u(0)|+C_1T^{-q}\,.
    \end{equs}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.475026+00:00","domain":"probability theory","id":"claim_e02519a67e4173fbc7739433fe5b1ad70b34d7364c4e3c3813b0e6010adc2cad","kind":"lemma","schema_version":1,"statement":"[Lemma lemma8 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold. Let $f: \mathbb{R} \rightarrow \mathbb{R}$ be a deterministic c\`adl\`ag function such that $t \in \mathbb{R} \mapsto f(t) e^{-\alpha t}$ is directly Riemann integrable. Suppose further that $t \in \mathbb{R} \mapsto m_{t}^{f} e^{-\frac{\alpha}{2}t}(1+t^{2})$ is bounded. Then,  
\begin{enumerate}[label=(\textbf{\roman*})]
\item The characteristic  $\chi_{f}$ satisfies (C1 of the paper)-(C3 of the paper). Moreover, for all $h \in \mathbb{N}_{0}$ and $\varepsilon>0$, 
\begin{align} 
\mathbb{E} \left[ \sum_{i=0}^{h} \sum_{|u|=i} \sup_{|s-t|\leq \varepsilon} |\chi_{f,u}(s-S(u))| \mathbf{1}_{(-\infty,0)}(s-S(u)) \right] < \infty
\end{align}
\noindent and 
\begin{align}  
\left(\sum_{i=0}^{h} \left( \sum_{|u|=i} |\chi_{f,u}(s-S(u))| \right)^{2}\right)_{|s-t|\leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}

\item For every $t \in \mathbb{R}$, the series $\mathcal{Z}_{t}^{\chi_{f}}$ converges unconditionally in $L^{1}(\Omega, \mathcal{F}, \mathbb{P})$ and almost surely over every admissible ordering of $\mathcal{I}$. Moreover, for all $t \in \mathbb{R}$, $\mathbb{E}[\chi_{f}(t)] = 0$ and  
\begin{align}
\mathcal{Z}_{t}^{f} - m^{f}_{t} \stackrel{a.s.}{=}  \mathcal{Z}_{t}^{\chi_{f}}. 
\end{align}

\item For $n \in \mathbb{N}_{0}$ and $t \in \mathbb{R}$, 
\begin{align}
\sum_{0\leq |u| \leq n} \chi_{f, u}(t - S(u)) \stackrel{a.s.}{=}  \sum_{0\leq |u| \leq n} f(t - S(u)) - f \ast \nu^{(\infty)}(t) + \sum_{|u| = n+1} f \ast \nu^{(\infty)}(t - S(u)). 
\end{align}
\end{enumerate}","status":"unverified"}

