			\Gamma_{k,n}\cap\{Y_{n-1}=1\}\subseteq\Bigl\{\sup_{0\le s\le n\Delta-\Delta}e_1\cdot X^\lambda(s)\le e_1\cdot X^\lambda(n\Delta)-7R\Bigr\}\, .
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:00:30.487796+00:00","domain":"probability theory","id":"claim_e07db39a410b4cd9a61f3e3091865b8e49175f1c1ce827a41cd1a81fc62de8ad","kind":"lemma","schema_version":1,"statement":"[Lem 1 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] Let $0\leq F\leq G$ in $B\left(H\right)$, and set
