\begin{align} \nonumber
\operatorname{\mathbf{E}}_{\varphi} \left\{ \left. \prod\nolimits_{q\in \mathcal{Q}} \!\left(1+h (q)\right)   \right|  \varphi (0) \right\}
& = \\ 
