{"assumptions":[],"created_at":"2026-10-27T19:33:43.760299+00:00","domain":"probability theory","id":"claim_e1378d6e0ae04e658d3c97778956e77fd455129ddff69dea8e37a558b8811645","kind":"concept","schema_version":1,"statement":"[Prop LDPforINSER of arXiv:2609.02682, 'LDP for tensor forms'] Suppose $H$ is not a tree and \[(n\log n)^{-1/ {\widetilde \Delta}}\ll p_n \ll1 .\]

Then the following conclusions hold:

 \begin{itemize}
     \item[(i)]Suppose ${\bf{X}}=(X_1,\ldots,X_n)$ where $X_i \overset{\text{i.i.d.}}{\sim} \mu$. Then $N_n(\mathrm{Sym}[\mathcal{G}_n],\phi,{{\bf X}})$ satisfies a (conditional) LDP with speed $n$, and the good rate function

 \begin{equation*}
J_{\mathbbm{1}}(t)=\inf_{{\boldsymbol f}\in \mathcal{F}_c:\ { G}_{\mathbbm{1},\phi}({\boldsymbol f})={t}}  \left\{ \int_0^1\sum_{r=1}^c f_{r}(u)\log \frac{f_{r}(u)}{\mu_r}du\right\},
\end{equation*}where $\mathbbm{1}$ denotes the constant graphon that equals 1 at all points in $[0,1]^v$.
\item[(ii)] For any $\beta\in\mathbb{R}$, we have
\begin{align*}
Z_{\mathrm{Sym}[\mathcal{G}_n]}(\beta,\mu)\xrightarrow[n\to\infty]{\mathbb P}\sup_{{\boldsymbol f}\in \mathcal{F}_c}\left\{ \beta\,{G}_{\mathbbm{1},\phi}({\boldsymbol f})
-\int_0^1\sum_{r=1}^c f_r(u)\log \frac{f_r(u)}{\mu_r}\,du\right\}.
		\end{align*}
        Moreover, the maximizers of the above optimization problem are attained.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:47:07.704042+00:00","domain":"probability theory","id":"claim_e138f5977c6b7dfc0e76d99a01570c343469acd952e1765a9d448956dd3b4d46","kind":"theorem","schema_version":1,"statement":"[Proposition 9 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] Assume that $Z$ is a Markov set and let $B\in\cX$
