{"assumptions":[],"created_at":"2026-10-27T07:27:14.773703+00:00","domain":"probability theory","id":"claim_e14b63545d746a2107c177eb24e0e5859a98ea231613e96de9a5349907512990","kind":"definition","schema_version":1,"statement":"[Definition 2 (Sinkhorn Discrepancy) of arXiv:2608.22746, 'Generative Neural Networks for Sinkhorn Distributionally Robust Hypothesis Testing'] Consider any two distributions $\mathbb{P}, \mathbb{Q} \in \mathscr{P}(\Omega)$ and reference measure $\nu \in \mathcal{M}(\Omega)$ such that $\mathbb{Q} \ll \nu$.
For regularization parameter $\Reg > 0$, the Sinkhorn discrepancy between two distributions $\mathbb{P}$ and $\mathbb{Q}$ is defined as
\begin{equation}\nonumber
    \mathcal{S}_{\Reg}(\mathbb{P}, \mathbb{Q}) = \inf_{\gamma\in\Gamma(\mathbb{P}, \mathbb{Q})}~
\left\{
\mathbb{E}_{(\boldsymbol{x},\boldsymbol{z}) \sim \gamma}[c(\boldsymbol{x},\boldsymbol{z})] + \Reg \cdot \mathcal{D}_{\mathrm{KL}}(\gamma \| \mathbb{P} \otimes \nu)
\right\},
\end{equation}
where $c(\boldsymbol{x},\boldsymbol{z})$ represents the transport cost function,  $\Gamma(\mathbb{P}, \mathbb{Q})$ denotes the set of couplings of $\mathbb{P}$ and $\mathbb{Q}$, respectively, and $\mathcal{D}_{\mathrm{KL}}(\gamma \| \mathbb{P} \otimes \nu)$ denotes the relative entropy of distribution $\gamma$ with respect to measure $\mathbb{P} \otimes \nu$, i.e., 
\begin{equation}
\tag*{  $\Diamond$ }
    \mathcal{D}_{\mathrm{KL}}(\gamma \| \mathbb{P} \otimes \nu) = \int_{\Omega \times \Omega}
\log\frac{\diff\gamma(\boldsymbol{x},\boldsymbol{z})}{\diff \mathbb{P}(\boldsymbol{x})\diff \nu(\boldsymbol{z})} \diff\gamma(\boldsymbol{x},\boldsymbol{z}). 
\end{equation}","status":"unverified"}

