{"assumptions":[],"created_at":"2026-10-27T23:05:09.629148+00:00","domain":"probability theory","id":"claim_e1bb6f7324002d6d694547ca567c637816d18f0754c4cf80e5d5791a529c4a59","kind":"concept","schema_version":1,"statement":"[Theorem thm:d_thin_dom_attract of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\alpha \in (0,2)\setminus\{1\}$ and Assumption~(\nameref{asm:T}) hold for some $p>0$. Then, for any $q\in(0,1]$ satisfying the condition $\int_{\mathbb{R}^d\setminus B_{\bm{0}}(1)}|\bm{w}|^q\nu_{\bm{X}}^{\mathrm{d}}(\mathrm{d} \bm{w})<\infty$, we have $\mathds{E}\big[\sup_{s\in[0,1]} |\bm{R}_{st}/t^{1/\alpha}|^q\big] 
    = \mathcal{O} \big(t^{1-q/\alpha}\big)$ as $t \downarrow 0$. Moreover, for any real number $q\in(0,\alpha)\cap(0,1]$, we let $\kappa(t)\coloneqq t^r$ for $t\in(0,1]$ and some $r\geqslant -1/\alpha$. Then, as $t \downarrow 0$, we have
\begin{align}
\mathcal{W}_q\big(\bm{J}^{\bm{S}^t,\kappa(t)},\bm{J}^{\bm{Z},\kappa(t)}\big)
    &=\begin{dcases}
    \mathcal{O}\big(t^{1-q/\alpha}\big(1+\log(1/t)\1_{\{p+q=\alpha,\,r\ne -1/\alpha\}}\big)\big), & \text{for }p+q\geqslant\alpha,\\
    \mathcal{O}\big(t^{p/\alpha + r(p+q-\alpha)}\big), & \text{for }p+q< \alpha. 
    \end{dcases} 
\\
\mathcal{W}_2\big(\bm{D}^{\bm{S}^t,\kappa(t)},\bm{D}^{\bm{Z},\kappa(t)}\big)^2
    &=\mathcal{O}\big(t^{p/\alpha+r(p-\alpha+2)}\big), \\

    |\bm{\gamma}_{\bm{S}^t,\kappa(t)}-\bm{\gamma}_{\bm{Z},\kappa(t)}| 
&=\begin{dcases}
    \mathcal{O}\big(t^{1-1/\alpha}(1+\1_{\{p+1=\alpha,\,r\ne-1/\alpha\}}\log(1/t))\big),
    &p\geqslant \alpha-1>0,\\
    \mathcal{O}(t^{p/\alpha+ r(p-\alpha+1)}),&p<\alpha-1\text{ or }\alpha\in(0,1).
\end{dcases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.414085+00:00","domain":"probability theory","id":"claim_e1bd6c9a8810493fe62a541b0d6097aeb3043153f5dde3d605df6527f8fa88af","kind":"concept","schema_version":1,"statement":"[Theorem thm:funkan of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] {reed1972}}]

	Assume that $A_N$ and $A$ are self-adjoint operators on the same Hilbert space $H$,
	and they have a common essential domain $H_0\subset H$.
	Assume that $A_N\varphi\to A\varphi$ as $N\to +\infty$ for all $\varphi\in H_0$.\footnote{The
	convergence on the common essential domain implies that $A_N\to A$ in the strong resolvent sense.}
	Let $a,b\in \mathbb{R}\cup\{\pm\infty\}$, $a<b$, be such that $a,b$ are not eigenvalues of $A$.
	Then
	\begin{equation*}
		P_{(a,b)}(A_N)\hspace{1pt}\varphi \to P_{(a,b)}(A)\hspace{1pt}\varphi\quad \textnormal{as $N\to+\infty$\quad for all
		$\varphi\in H$},
	\end{equation*}
	where $P_{(a,b)}(A_N)$ denotes the orthogonal spectral projection onto the interval $(a,b)$ corresponding
	to the operator $A_N$, and similarly for $P_{(a,b)}(A)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.888460+00:00","domain":"probability theory","id":"claim_e1c01d2809d631671f9812c3f63dcc2c7e78d84f60a12de1e041ee2082a297a1","kind":"theorem","schema_version":1,"statement":"[Proposition prop:eta-conditional-reduction of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] The process \(\widehat\rho^{N,\eta}\) defined by  (equation eq:eta-hat-rho-conditional of the paper) must satisfy
\begin{equation}
\begin{aligned}
  \mathrm d\widehat\rho_t^{N,\eta}
  &=
  \mathfrak L_N(\widehat\rho_t^{N,\eta})\,\mathrm d t+
  \sqrt{\eta}
  \sum_{k=1}^m\sum_{j=1}^N
  \mathcal C_{L_j^{(k)}}(\widehat\rho_t^{N,\eta})\,\mathrm d Y_t^{k,j},
  \\
  \widehat\rho_0^{N,\eta}
  &=
  \gamma_0^{\otimes N}.
\end{aligned}

\end{equation}
Set
\begin{equation}
  Z_t^{N,\eta}
  :=
  \mathrm{Tr}(\widehat\rho_t^{N,\eta})>0,
  \qquad
  \rho_t^{N,\eta}
  :=
  \frac{\widehat\rho_t^{N,\eta}}{Z_t^{N,\eta}}.

\end{equation}
Then
\begin{equation}
  Z_t^{N,\eta}
  =
  \mathbb E_{\mathbb Q}
  \left[
    M_t^N\mid\mathcal Y_t^N
  \right].

\end{equation}
The measure $\mathbb Q^{N,\eta}$ given by
\begin{equation}
  \frac{\mathrm d\mathbb Q^{N,\eta}}{\mathrm d\mathbb Q}
  \bigg|_{\mathcal Y_T^N}
  :=
  Z_T^{N,\eta}

\end{equation}
is the restriction of \(\mathbb Q^{N,\mathrm{full}}\) to \(\mathcal Y_T^N\), and it holds that
\begin{equation}
  \rho_t^{N,\eta}
  =
  \mathbb E_{\mathbb Q^{N,\mathrm{full}}}
  \left[
    R_t^N\mid\mathcal Y_t^N
  \right].

\end{equation}
Moreover,  the measures \(\mathbb Q^{N,\eta}\) and
\(\mathbb Q\) are equivalent on \(\mathcal Y_T^N\), and the processes
\begin{equation}
  W_t^{N,k,j}
  :=
  Y_t^{k,j}
  -
  \sqrt{\eta}
  \int_0^t
  b_j^{N,k}(\rho_s^{N,\eta})\,\mathrm d s

\end{equation}
form a family of  independent Brownian motions under \(\mathbb Q^{N,\eta}\).  In particular,  
the normalized process solves
\begin{equation}
\begin{aligned}
  \mathrm d\rho_t^{N,\eta}
  &=
  \mathfrak L_N(\rho_t^{N,\eta})\,\mathrm d t+
  \sqrt{\eta}
  \sum_{k=1}^m\sum_{j=1}^N
  \mathcal E_{L_j^{(k)}}(\rho_t^{N,\eta})\,\mathrm d W_t^{N,k,j}.
\end{aligned}

\end{equation}","status":"unverified"}

