{"assumptions":[],"created_at":"2026-10-27T23:20:55.482568+00:00","domain":"probability theory","id":"claim_e1dd5bed4053302c551dc111a3d77c3ca9d7c76f495b121b29c74cc73948bcac","kind":"lemma","schema_version":1,"statement":"[Lem irr of arXiv:2411.07158, 'Markov chains on trees: almost lower and upper directed cases'] [Irreducibility criteria]
  \begin{itemize} \topsep0pt   \itemsep=0pt   \partopsep=0pt   \parsep=0pt \setcounter{c}{0}
  \addtocounter{c}{1}\item[($\roman{c}$)] An {\sf AUD}\xspace transition matrix ${\sf U}$ is irreducible iff, for all $u\neq \varnothing$, ${\sf U}_{u,p(u)}>0$ and, for each node $v\neq \varnothing$, there exists a strict ancestor $u$ of $v$ and an element $w$ in $T_v$ such that ${\sf U}_{u,w}>0$.
\addtocounter{c}{1}\item[($\roman{c}$)] An {\sf ALD}\xspace transition matrix ${\sf D}$ is irreducible iff, for all $u\neq \varnothing$, ${\sf D}_{p(u),u}>0$ and for each node $v$, there exists a descendant $w$ of $v$ and a strict ancestor $u$ of $v$, such that ${\sf D}_{w,u}>0$.~
\addtocounter{c}{1}\item[($\roman{c}$)] The transition matrix of a random walk on $T$ is irreducible iff for each $u\neq \varnothing$, ${\sf M}_{u,p(u)}>0$ and ${\sf M}_{p(u),u}>0$. \end{itemize}\vspace{-2em}~","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:24:20.986108+00:00","domain":"probability theory","id":"claim_e1e3152e703aa78397264051a062a907f2881577c088043a3d0efe3fe27286f8","kind":"concept","schema_version":1,"statement":"[Theorem thm:correction_moments of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] If $d\geq 3\alpha$ and $\alpha<2$  then
