{"assumptions":[],"created_at":"2026-10-26T20:28:53.643833+00:00","domain":"probability theory","id":"claim_e23ca73d4aed0979069db3d09c9a3b67363590546051cb78ee1d4239b0dac475","kind":"lemma","schema_version":1,"statement":"[Lemma 28 of arXiv:2605.13512, '2605.13512'] \leavevmode
