 \begin{align*}
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n}T_n
 \stackrel{\pr}{\to}
 \frac1{\mathsf{v}^\star},
 \qquad
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n}\E T_n
 \to
 \frac1{\mathsf{v}^\star}.
 \end{align*}

