&+\int_0^te^{(t-s)A_n}D_xu_{n}(s,X_n(s,x))\mathcal{G}_ndW(s)\notag\\
&+\int_0^t e^{(t-s)A_n}\mathcal{G}_ndW(s),
\end{align}
where, in analogy with \eqref{expr_h+_h-}, for every $s\in[0,T]$ and every $x\in H_n$, we set 
\begin{align}
& u_n(s,x):=\sum_{k=1}^n \left(u_{n,k}^+(s,x)\Phi_k^{+}+u_{n,k}^-(s,x)\Phi_k^{-}\right), \\
&D_xu_n(s,x)\mathcal{V}_nh:=\sum_{k=1}^n\left( \scal{\mathcal{V}_n^ *\nabla_xu_{n,k}^+(s,x)}{h}_{U}\Phi_k^{+}+\scal{\mathcal{V}_n^*\nabla_xu_{n,k}^-(s,x)}{h}_{U}\Phi_k^{-}\right),\quad h\in U,
\\
