{"assumptions":[],"created_at":"2026-10-27T17:42:08.473714+00:00","domain":"probability theory","id":"claim_e3ddb9b22323a4b181c913b963f8de888460c530c0e17de52771f30db5071c0e","kind":"theorem","schema_version":1,"statement":"[Corollary corollary1 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $\varphi$ be a characteristic satisfying (C1 of the paper)-(C2 of the paper). Then, for $t \in \mathbb{R}$ and $k\in \mathbb{N}_{0}$, we have the following:
\begin{enumerate}[label=(\textbf{\roman*})]
\item For every $u \in \mathcal{I}$, $\varphi_{u}^{(k)}(t-S(u)) \stackrel{a.s.}{=} \mathbb{E}[\varphi_{u}(t-S(u)) \mid \mathcal{A}^{(|u|+ k-1)}]$. 

\item For every $u,v \in \mathcal{I}$ such that $u \neq v$ and $|u| = |v|$,  
\begin{align}
\varphi_{u}^{(k)}(t-S(u)) \varphi_{v}^{(k)}(t-S(v)) \stackrel{a.s.}{=} \mathbb{E}[\varphi_{u}(t-S(u)) \varphi_{v}(t-S(v)) \mid \mathcal{A}^{(|u|+ k-1)}].
\end{align}

\item For every $u \in \mathcal{I}$,  $\varphi^{(k)}_{u}(t-S(u)) \in L^{2}(\Omega, \mathcal{F}, \mathbb{P})$. 

\item For every $u \in \mathcal{I}$, there exists a constant $C>0$ such that, almost surely, 
\begin{align}
\mathbb{E}[ (\varphi_{u}^{(k)}(t-S(u)))^{2} \mid \mathcal{A}^{(|u|-1)}] \leq C
e^{\alpha \max(t-S(u), 2(t-S(u)))}. 
\end{align} 

\item For every $u,v \in \mathcal{I}$ such that $u \neq v$ and $|u| = |v|$ there exists a constant $C>0$ such that, almost surely, 
\begin{align}
& \mathbb{E}[ |\varphi_{u}^{(k)}(t-S(u))| |\varphi_{v}^{(k)}(t-S(v))| \mid \mathcal{A}^{(|u|-1)}]  \leq C \prod_{w=u,v}e^{ \frac{\alpha}{2} \max(t-S(w), 2(t-S(w)))}.
\end{align} 

\item For every $u \in \mathcal{I}$, almost surely, 
\begin{align}
\mathbb{E}[ (\varphi_{u}^{(k)}(t-S(u)) - \varphi_{u}^{(0)}(t-S(u)))^{2} \mid \mathcal{A}^{(|u|-1)} ] \leq 2 {\rm Var}[\varphi](t-S(u)). 
\end{align}

\item For every $u,v \in \mathcal{I}$ such that $u \neq v$ and $|u| = |v|$, 
\begin{align}
\mathbb{E}[ (\varphi_{u}^{(k)}(t-S(u)) - \varphi_{u}^{(0)}(t-S(u))) (\varphi_{v}^{(k)}(t-S(v)) - \varphi_{v}^{(0)}(t-S(v))) \mid \mathcal{A}^{(|u|-1)} ] \stackrel{a.s.}{=} 0. 
\end{align}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.056711+00:00","domain":"probability theory","id":"claim_e3e5e1986beb650dbb1cbc5d1dc2fbff229e094b5c1685ed6bcc3ee700c6547c","kind":"concept","schema_version":1,"statement":"[Lemma 24 of arXiv:2607.01629, 'Quadratic fluctuations of speed-change Kawasaki dynamics'] For test function $f$, we have
