{"assumptions":[],"created_at":"2026-10-26T19:32:38.636278+00:00","domain":"probability theory","id":"claim_e3e9bce976ecb3f5c84c2e3da1488ff319283e0fd9675ceab3b048c42866bf02","kind":"concept","schema_version":1,"statement":"[Lemma 2 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let $\tau$ be an ultrametric, oriented tree with $n$ tips and node depths $x_1, \dots, x_{n-1}\in \{1,\dots, T\}$. The likelihood function of the parameters $(p,r)$ given the outcome $\{\mathbf{T}^{p,r}=\tau\}$ is
   \begin{equation*} 
     \mathcal{L}(p, r \mid  \tau) := \mathbb{P}(\mathbf{T}^{p,r}=\tau)=\mathbb{P}(H>T)\prod_{i=1}^{n-1} \mathbb{P}(H = x_i).
   \end{equation*}
Moreover, the likelihood of $(p,r)$ conditioned on $\{N_T=n\}$ is given by
      \begin{equation*}
      \mathcal{L}(p, r \mid  \tau, n): = \mathbb{P}(\mathbf{T}^{p,r}=\tau \mid N_T = n)=\prod_{i=1}^{n-1} \frac{\mathbb{P}(H = x_i)}{\mathbb{P}(H\le T)}.
   \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.386271+00:00","domain":"probability theory","id":"claim_e3eb8125db5cbc95bac690f48b257a1b30403d5f9edea32d60d8097373abbbae","kind":"concept","schema_version":1,"statement":"[Theorem cas_1 of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Assume ((drift of the paper)) to ((simple of the paper)). Then, the Green's density function $g^{z_0}$ of this process has the following asymptotics as $\alpha \to \alpha_0$ and $r\to\infty$.
\begin{itemize}
\item If $\alpha^* < \alpha_0 < \alpha^{**}$, then
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha \to \alpha_0}{\sim} 
 {c_{\alpha_0}}h_{\alpha_0}(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}}.
  \end{equation}

  \item If $\alpha_0 < \alpha^*$, then
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha \to \alpha_0}{\sim} 
c^*h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x(\alpha^*) + \sin(\alpha)y(\alpha^*))}.
  \end{equation}

  \item If $\alpha_0 > \alpha^{**}$, then
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha \to \alpha_0}{\sim} 
c^{**}h_{\alpha^{**}}(z_0) e^{-r(\cos(\alpha)x(\alpha^{**}) + \sin(\alpha)y(\alpha^{**}))}.
  \end{equation}
\end{itemize}
