{"assumptions":[],"created_at":"2026-10-27T20:38:36.893529+00:00","domain":"probability theory","id":"claim_e400ff1118ce4819b4b2df599f43999a8873893190547bdddd65dcee889f9e09","kind":"lemma","schema_version":1,"statement":"[Lemma firstmoment of arXiv:2606.30475, 'Ancestries in random $d$-DAGs'] For all $n\geq 2$, we have the following:
 \begin{enumerate}[i.]
  \item The expected number of descendants of $n$ in $G_n$ is given by
  \begin{equation}
   \mathbb{E}|D_n| = 2 + \sum_{i=2}^{n-1} \sum_{j=1}^{n-i} \left[1-\bigg(\frac{n-1-j}{n-1}\bigg)^d\,\right]
   \bigg(\frac{i-1}{n-1-j}\bigg)^d \cdot \prod_{k=1}^{j-1} \left[1-\bigg(\frac{i-1}{n-1-k}\bigg)^d\,\right],
  \end{equation}
  or, equivalently,
  \begin{equation}
   \mathbb{E}|D_{n+1}| = 2 + \sum_{i=1}^n \sum_{j=1}^{n-i} \left[1-\bigg(\frac{n-j}{n}\bigg)^d\right] \bigg(\frac{i}{n-j}\bigg)^d \cdot \prod_{k=1}^{j-1} \left[1-\bigg(\frac{i}{n-k}\bigg)^d\right].
  \end{equation}
  \item The expected number of joint descendants of $n+1$ and $n+2$ in $G_{n+2}$ is given by
  \begin{multline}
   \mathbb{E}|D_{n+1}\cap D_{n+2}| = 2 - \bigg(\frac{n}{n+1}\bigg)^d\\
   + \sum_{i=1}^n \sum_{j=1}^{n-i} \left[1-\bigg(\frac{n-j}{n+1}\bigg)^d\right]\cdot \left[1-\bigg(\frac{n-j}{n}\bigg)^d\right] \bigg(\frac{i}{n-j}\bigg)^d \cdot \prod_{k=1}^{j-1} \left[1-\bigg(\frac{i}{n-k}\bigg)^d\right]
  \end{multline}
 \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:22:01.674071+00:00","domain":"probability theory","id":"claim_e402990ec11f90a51f0dddcbe4fa974c889a39dd68eb7409c61f6b1db3d199a0","kind":"lemma","schema_version":1,"statement":"[Lemma quasimorphism of arXiv:2605.02226, 'Finitely Dependent Processes on Subshifts'] If $ (b_v)_{v \in \mathbb{Z}^d}$ is such that $ b_v \in \mathbb{Z}$, $b_\mathbf{0}=0$ and there exists a homomorphism $ \phi :\mathbb{Z}^d \rightarrow \mathbb{Z}$ and $ K < \frac{1}{4}\min\{|\phi(e_i)|: \phi(e_i) \neq 0\}$ such that       
