{"assumptions":[],"created_at":"2026-10-27T23:13:49.899681+00:00","domain":"probability theory","id":"claim_e438a98b5169859c0dee1e7405a693efb0476e11d648f9a653a58548600feffd","kind":"theorem","schema_version":1,"statement":"[Prop weighted-graph of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] For any $d\geq 2, q\in [1, \infty)$, there exist constants $C_{\mathrm{WS}}, C_{\mathrm{LP}}\in (0, \infty)$ that depend at most on $d, q$ such that for any $x\in \mathbb{Z}^d$ the following holds true: 
\begin{enumerate} [(i)]
    \item (Weighted Sobolev inequality on a large scale) 
    For every function $u: \mathbb{Z}^d \to \mathbb{R}$, and every cut-off function $\eta: \mathbb{Z}^d \to [0,1]$  with $\supp{\eta} \subset B(x, n)$,   
    \begin{align*}
        \norm{(\eta u)}^2_{2\rho, B(x, n)} \leq C_{\mathrm{WS}}\frac{n^2}{\abs{B(x,n)}}\norm{\nu}_{q, B(x,n)} \sum_{\{y,y'\}\in E_d}c(y,y')\abs{\eta u(y)- \eta u(y')}^2.
    \end{align*}
    \item (Local Poincar\'{e} inequality on a large scale) For every function $u: \mathbb{Z}^d \to \mathbb{R}$
    \begin{align*}
        & \norm{u-(u)_{B(x, n)}}^2_{2\rho, B(x, n)} \\
        & \qquad  \leq C_{\mathrm{LP}}\frac{n^{2}}{\abs{B(x,n)}}\norm{\nu}_{q, B(x,n)}  \sum_{\substack{ y,y'\in B(x, n) \\ \{y, y'\}\in E_d }}c(y,y')\abs{ u(y)- u(y')}^2.
    \end{align*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:47:32.879813+00:00","domain":"probability theory","id":"claim_e438af2ac8ddc0a113165312f0b8ab6a523c103e4eb1a2d8a77f8178d096c174","kind":"theorem","schema_version":1,"statement":"[Proposition 10 (Anisotropic sampling) of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $p\ge1$ and $L_1,\ldots,L_r\ge1$.  Suppose that
$\boldsymbol x_1,\ldots,\boldsymbol x_M\in\T^r$ are $\delta$-separated with respect to \eqref{eq:anisotropic-metric}.  For each $1\le\nu\le M$, let $f_\nu$ be a trigonometric polynomial satisfying
\begin{equation}
  \Spec(f_\nu)
  \subseteq
  \prod_{j=1}^{r}[-L_j,L_j]\cap\Z^r.
\end{equation}
Then
\begin{equation}
  \sum_{\nu=1}^{M}|f_\nu(\boldsymbol x_\nu)|^p
  \ll_{r,p,\delta}
  \left(\prod_{j=1}^{r}L_j\right)
  \int_{\T^r}
  \sup_{1\le\nu\le M}|f_\nu(\boldsymbol y)|^p
  d\boldsymbol y.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:34:20.778475+00:00","domain":"probability theory","id":"claim_e4392f32ebea434210b4ed83c2e01421009e076a6ddaef57d2eb553d5010eff0","kind":"lemma","schema_version":1,"statement":"[Lemma 2 (Uniform boundary survival and its constant) of arXiv:2609.02257, 'Aperiodic random walks: uniform estimates, local limits and invariance principles'] For some \(c,C>0\), uniformly for all sufficiently large \(N\) and all
\(n\ge0\),
\begin{equation}
 \frac{c}{\sqrt{n+1}}
 \le u_{N,n}^{\rightarrow},u_{N,n}^{\leftarrow}
 \le \frac{C}{\sqrt{n+1}}.

\end{equation}
Moreover the limits
{
\begin{align*}
 \kappa_N^{\rightarrow}
 &:=\lim_{n\to\infty}\sqrt n\,u_{N,n}^{\rightarrow},\\
 \kappa_N^{\leftarrow}
 &:=\lim_{n\to\infty}\sqrt n\,u_{N,n}^{\leftarrow}.
\end{align*}}
exist, are positive, and the convergence is uniform along the array:
\begin{equation}
 \sup_{N\ge N_0}
 \left|\sqrt n\,u_{N,n}^{\rightarrow}-\kappa_N^{\rightarrow}\right|
 +\sup_{N\ge N_0}
 \left|\sqrt n\,u_{N,n}^{\leftarrow}-\kappa_N^{\leftarrow}\right|
 \longrightarrow0.

\end{equation}
Set
\begin{equation*}
 a_N:=\sqrt{\frac\pi2}\frac{\kappa_N^{\rightarrow}}{\sigma_N},
 \qquad
 b_N:=\sqrt{\frac\pi2}\frac{\kappa_N^{\leftarrow}}{\sigma_N}.
\end{equation*}
Then there are \(a,b\in(0,\infty)\) such that
\begin{equation}
 a_N\longrightarrow a,
 \qquad b_N\longrightarrow b.

\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:45.023720+00:00","domain":"probability theory","id":"claim_e44ba747f3debe0934bcc08b1d053c9f8374047f84be764016f64ff1c0ab9a28","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.06489, 'The Missing Central Limit Theorems for Local Functionals of Berry's Random Wave Model'] For any order $q\geq 2$ and space dimension $d\geq 2$, the random variable $\frac{h(q,R)}{\sqrt{\var h(q,R)}}$ converges in total variation and 1-Wasserstein distance
    to a standard Gaussian random variable as $R\to\infty$.

    Moreover, if $F(R)=\int_{B_R}f(u_1(x))dx$ is given by a nontrivial local observable with Hermite decomposition
    \begin{equation*}
        f(x)=\sum_{q\geq 2}\frac{a_q}{q!}H_q(x),
        \qquad
        a_q=\frac1{\sqrt{2\pi}}\int_\R f(z)H_q(z) e^{-z^2/2}dz,
    \end{equation*}
    such that either $d=2$ and $a_4\neq 0$ or $\sum_{q\geq 3}\frac{a_q^2C_{q,d}}{(q!)^2}<\infty$,
    then $\frac{F(R)}{\sqrt{\var F(R)}}$ converges in 1-Wasserstein distance to a standard Gaussian random variable as $R\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.658209+00:00","domain":"probability theory","id":"claim_e44db5aeb47ef0de395c487d040c15db23c8edae8570e346375151fee071768d","kind":"concept","schema_version":1,"statement":"[Theorem 11 (Scaling limit of Sinkhorn-rescaled random matrices) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $(\r_k, \c_k)$ and $\bLambda_k$ satisfy Assumption \ref{assumption: limit_theory}, and for each $k$ let $\X_k$ be a random matrix satisfying Assumption \ref{assump:random_matrix} with mean $\bLambda_k$ and target margin $(\r_k, \c_k)$. Let $\varphi_{\X_k^{\r_k,\c_k}}$ denote the piecewise constant extension of $\X_k^{\r_k,\c_k}$ to $[0,1]^2$ as in Theorem \ref{thm:bound_X^rs-Z}, and let $W^{\r,\c;\bLambda} := d\pi^{\r,\c;\bLambda}/(dx\,dy)$ be the Lebesgue density of the limiting SSB from Theorem \ref{thm:SSB_deterministic_limit}. Assume
		\begin{enumerate}[label=\textup{(\roman*)}]
			\item $\sup_k \sigma_k \le \sigma < \infty$ and $\sup_k R_k \le R < \infty$;
			\item $\liminf_k (m_k/n_k) \wedge (n_k/m_k) \ge \gamma > 0$;
			\item $(m_k \vee n_k)^{3/2} \sqrt{\log(m_k \vee n_k)} = o_{K,\delta,\gamma,\sigma,R}(\|\bLambda_k\|_1)$.
		\end{enumerate}
		Fix $D > 0$. Then for any $g \in L^{\infty}([0,1]^2)$,
		\begin{align}
