				&=(\int_{\frac{t_0}{2}}^{t} + \int_{t_0}^{\frac{t_0}{2}}) [{z^{2}(s,w)}\|\rho(s) \|_{L^2}^{3}\|\nabla \rho(s) \|_{L^2} {e}^{\nu s}]ds \\
				&=I_1+I_2.
			\end{align*}
