    \end{align}
    where the constant $c_{\eqref{equ:large:decoupling}}$ only relies on $p$, $T - t$
    and all the Lipschitz constant in Assumption \ref{coefficient:assume:general},
    and $U_p([t,T])$ and $S_p([t,T])$ are defined as in Theorem \ref{thm:small:decoupling}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:54:15.659783+00:00","domain":"probability theory","id":"claim_e47f3a82dee410e64104e78011044643dc256a4d897dd45fafcad4fd173fa60a","kind":"concept","schema_version":1,"statement":"[Lemma 7 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] We have the following identities (under Assumption 1).
		\begin{enumerate}
			\item For any $n_1,n_2\in\bfN^{d+1}$
			\begin{equation}
			D^{n_1} D^{n_2} = D^{n_1+n_2},  \quad 
			\downarrow^{n_1}\hspace{-1pt} \downarrow^{n_2}\hspace{-0pt} = \downarrow^{n_1+n_2}, \quad 
			\downarrow^{n_1}D^{n_2} = D^{n_2}\downarrow^{n_1}.
		\end{equation}
			\item  For any $\tau\in T \sqcup T^+$,  $\sigma\in\mcB^+$ and $n\in\bfN^{d+1}$
			\begin{equation} 
				\downarrow^n(\tau/\sigma) = (\downarrow^n\tau)/\sigma.
			\end{equation}
			\item  We have the Leibniz rules
			\begin{equation} 
			\begin{aligned}	D^n(\tau_1\tau_2) & = \sum_{n=n_1+n_2} \binom{n}{n_1}  D^{n_1}\tau_1 \, D^{n_2}\tau_2,
			\\
				\downarrow^n\hspace{-2pt}(\tau_1\tau_2) & = \sum_{n=n_1+n_2} \binom{n}{n_1} \downarrow^{n_1}\hspace{-2pt}\tau_1 \, \downarrow^{n_2}\hspace{-2pt}\tau_2.
				\end{aligned}
			\end{equation}
			\item For any $n\in\bfN^{d+1}$ and $\tau\in T$, we have the commutation relations
			\begin{equation*} 
				\Delta D^n\tau = (D^n\otimes\id)\Delta \tau, \quad \text{and}\quad
				\Delta \downarrow^n\tau = (\id \, \otimes \downarrow^n)\Delta \tau.
			\end{equation*}
			The same holds true for $\tau \in \CT^+$ and $\Delta$ replaced by $ \Delta^{\!+} $.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

