{"assumptions":[],"created_at":"2026-10-27T23:06:42.716678+00:00","domain":"probability theory","id":"claim_e49fefae564ca0f39f9a21171482c3d9cbbabf635771cf59ce6677086a016b2b","kind":"concept","schema_version":1,"statement":"[Prop dinh ly 2 of arXiv:2411.04081, 'A Multi-level Monte Carlo simulation for invariant distribution of Markovian switching L\''] Assume that \textbf{C4} holds with  $q=4p_0$;    $\sigma_\Delta, \gamma_\Delta$ satisfy (equation T3T4 of the paper). Moreover, assume that there exist constants $\widetilde{L_0}>0$, $\widetilde{{\zeta_0}} \in \mathbb{R}$ and $\widetilde{{\zeta_1}} \in[0, +\infty)$ such that for all $i \in S, x \in \mathbb{R}^d$,
		\begin{equation}
			|\gamma_{\Delta}(i,x)|\leq \widetilde{L_0}(1+|x|),
		\end{equation}
		and
		\begin{equation} 
			\langle x,b(i,x) \rangle  + \dfrac{p_0-1}{2}  |\sigma_{\Delta}(i,x)|^2 + \dfrac{1}{2\widetilde{L_0}}|\gamma_{\Delta}(i,x)|^2 \int_{\mathbb{R}_{0}^d}|z|\left(\left(1+\widetilde{L_0}|z|\right)^{p_0-1}-1\right) \nu(d z) \leq \widetilde{{\zeta_0}}  |x|^2+\widetilde{{\zeta_1}}.
		\end{equation}
Then, for any positive integer  $k \leq  p_0/2$,  there exists a positive constant $C$, which  depends neither on $t$  nor on $\Delta$, such that
		\begin{align*}
			\mathbb{E} \left[|\widehat{X}_t|^{2k} \right] \vee \mathbb{E} \left[|\widehat{X}_{\underline{t}}|^{2k}\right] \le \left\{ \begin{array}{l l}
				Ce^{{2k\widetilde{{\zeta_0}} t}} \quad &\text{ if \;\;} \widetilde{{\zeta_0}} >0,\\
