{"assumptions":[],"created_at":"2026-10-27T23:07:56.651441+00:00","domain":"probability theory","id":"claim_e54c8363314a9374b43678cc61c934558caf52561bd592c4a74b7f0cd8d220db","kind":"theorem","schema_version":1,"statement":"[Theorem SSRR of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume \((\Omega, \mathcal{F}, \mathbb{P}, \theta)\), \(\frac{1}{3} < \beta \leq \gamma < H\), and let \(\mathbf{B}\) be the delayed \(\gamma\)-rough path cocycle constructed in Theorem (thm:B_delayed_cocycle of the paper). Assume \(\xi \in \mathscr{D}_{\mathbf{B}(\omega)}^{\beta}([-r,0])\) and consider the following equation:
			\begin{align}
				\begin{split}
					\mathrm{d}y_{t} &= A\left(y_t, \int_{-r}^{0} y_{\theta+t} \pi(\mathrm{d}\theta)\right) \mathrm{d}t + G \left(y_{t}, y_{t-r}\right) \mathrm{d}\mathbf{B}_{t}(\omega), \\
					y_{s} &= \xi_{s} \quad \text{for} \quad -r \leq s \leq 0,
				\end{split}
			\end{align}
			with the same conditions as in Theorem (SSS of the paper). Then this equation admits a unique solution globally in time. Assume \((\phi^{t}_{\mathbf{B}(\omega)}(\xi))_{t \geq 0}\) is this solution. For \(m \in \mathbb{N}\), define
			\[
			\varphi^{m}_{\omega}(\xi) := \left(\phi^{(m-1)r+t}_{\mathbf{B}(\omega)}(\xi)\right)_{0 \leq t \leq r}.
			\]
			In this case, we indeed have \(\varphi^{m}_{\omega}(\xi) \in \mathscr{D}_{\mathbf{B}(\theta_{mr}\omega)}^{\beta}([-r,0])\). Moreover, the following map
			\begin{align}
				\begin{split}
					&\varphi^{m}_{\omega}: \mathscr{D}_{\mathbf{B}(\omega)}^{\beta}([-r,0]) \rightarrow \mathscr{D}_{\mathbf{B}(\theta_{mr}\omega)}^{\beta}([-r,0]), \\
					& \xi \longrightarrow \varphi^{m}_{\omega}(\xi),
				\end{split}
			\end{align}
			is continuous and satisfies the cocycle property, i.e.,
			\begin{align}
				\varphi^{p+q}_{\omega} = \varphi^{p}_{\theta_{qr} \omega} \circ \varphi^{q}_{\omega},
			\end{align}
			for all \(p, q \in \mathbb{N}\).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.164768+00:00","domain":"probability theory","id":"claim_e54fa7bcdc7203214864be6834f512ecb2f9ab15d8fc6fa51da9d458f7275ad5","kind":"theorem","schema_version":1,"statement":"[Prop Prop_KerDRD+- of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $(g,[{\mathfrak l}]) \in \mathbf{Met} \times \mathbf{Ram}$ the following hold:
  \begin{enumerate}
  \item

    The kernel of $D_{R_D^\pm,g}^{\mathfrak l}$ consists precisely of the $L^2$ harmonic ${\mathfrak l}$--twisted $1$--forms and self-dual $2$--forms respectively;
    that is:
    \begin{align*}
      \ker D_{R_D^+,g}^{\mathfrak l}
      &=
        \mathscr{H}^1(g,{\mathfrak l})
        \coloneq
        \set[\big]{
        \alpha \in L^2\Omega^1(X{\backslash} Z,{\mathfrak l})
        :
        {\rm d} \alpha = {\rm d}^*\alpha = 0
        } \quad\text{and} \\
      \ker D_{R_D^-,g}^{\mathfrak l}
      &=
        \mathscr{H}^+(g,{\mathfrak l})
        \coloneq
        \set[\big]{
        \beta \in L^2\Omega^+(X{\backslash} Z,{\mathfrak l})
        :
        {\rm d} \beta = {\rm d}^*\beta = 0
        }.
    \end{align*}
  \item

    Pulling back along $\pi \mskip0.5mu\colon\thinspace \tilde X \to X$ induces isomorphisms
    \begin{equation*}
      \mathscr{H}^1(g,{\mathfrak l}) \cong {\rm H}_\mathrm{dR}^1(\tilde X)^-
      \quad\text{and}\quad
      \mathscr{H}^+(g,{\mathfrak l}) \cong {\rm H}_\mathrm{dR}^+(\tilde X)^-.
    \end{equation*}
    Here ${\rm H}_\mathrm{dR}^\bullet(\tilde X)^-$ denotes the subspace of ${\rm H}_\mathrm{dR}^\bullet(\tilde X)$ which is anti-invariant under the sheet-swapping involution $\tau$ and ${\rm H}_\mathrm{dR}^+(\tilde X)^- \subseteq {\rm H}_{\mathrm{dR}}^2(\tilde X)^-$ denotes \emph{a} maximal subspace on which the intersection form is positive-definite.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:05:52.398427+00:00","domain":"probability theory","id":"claim_e5527f6453cdfda487f19ef6c2368e535a27d18d3aea25ec7ee2771f902f84b9","kind":"concept","schema_version":1,"statement":"[Corollary corollaryofthelcd of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $X,Y$ be uniformly sampled from an $(N,N_1,\kappa,\kappa',D_1,D_2,D_3)$ box pair with $N\geq N_1\geq 2$, and let $\alpha>0$ satisfy $\alpha d\geq 4,2^{16}B^2\kappa'Nd^{-1/2}/\alpha \leq 3^d$. Let $t_1=N^{-1}$ and $t_2=N_1^{-1}$. Then whenever $\log N$ is small enough relative to $\alpha$ in the sense that
$
\sqrt{\alpha c_0^2n/8}\geq (\frac{8\sqrt{2}}{\sqrt{\nu p}}+\frac{256\sqrt{2}B^2}{\sqrt{c_0}})\sqrt{\log_+\frac{c_{\rho,\delta}^2c_0^42^{-11}N}{\frac{8\sqrt{2}}{\sqrt{\nu p}}+\frac{256\sqrt{2}B^2}{\sqrt{c_0}}}}
$, the following probability estimate holds true: 
$$\begin{aligned}
\mathbb{P}_{X,Y}(\operatorname{LCD}&^\mathbf{t}_{\frac{8\sqrt{2}}{\sqrt{\nu p}}+\frac{256\sqrt{2}B^2}{\sqrt{c_0}},c_{\rho,\delta}^2c_0^42^{-16}}(r_nX_D,r_nY_D)\leq 2^{11}B^2, \\&|\sin(X_D,Y_D)|\geq c_{\rho,\delta}^2c_0^2/128)\leq (10^{12}\alpha(2+\frac{4\kappa'}{\kappa})^2)^{d/4},
\end{aligned}$$
where we take $r_n=\frac{c_0}{32\sqrt{n}}$ and in the probability we take an intersection with the event where the lower bound on $|\sin(X_D,Y_D)|$ holds. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

