        \end{align}
        Moreover, $\Theta$ satisfies
        \begin{align}
                0=\mu_1(z-E_*)+\mu_2\Theta^2+\mu_3\Theta^3+O(|z-E_*||\Theta|+|z-E_*|^2+|\Theta|^4), 
