{"assumptions":[],"created_at":"2026-10-26T20:46:26.256892+00:00","domain":"probability theory","id":"claim_e6043545a9af684922f90537f0720b0c8072225d90e830e4e43914c79dc50fb4","kind":"concept","schema_version":1,"statement":"[Thm 56 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $x\in F,\;x_n\in F_n,\;\kappa\in [1/2,1],\;t>0$ and $f\in \BL^{\kappa}(M)$ and set
\[
h:=d(x,x_n)+d_{\rm{H}}(F,F_n)^{\kappa}+d_{\BL^{\kappa}}(\mu,\mu_n).
\]
\begin{itemize}
  \item [$\rm{(i)}$]If $(F,R,\mu)$ satisfies the assumption $\rm{(A2)}$, and $h\leq 1/2$,
then it holds that
\begin{align*}
 \Big|E_x[f(X_t)]-E^n_{x_n}[f(X^n_t)]\Big|\lesssim \g{c}{gen,n}\|f\|_{\BL^{\kappa}} h^{E},
\end{align*}
where
\begin{align*}
  E=\frac{\kappa}{\kappa+(1+s_0)(2+\kappa)(\kappa+\theta)},
\end{align*}
and
\begin{align*}
  \g{c}{gen,n}=\frac{1}{1-(1/2)^E}\left[ \g{c}{12q2}
    +\g{c}{sg2,n}\mu(F)^{1/2}\Bigl\{ c_{\rm{A1}} +\g{c}{suffcond1,3}\left(\frac{\alpha_n}{2}\right)^{-(1+\frac{s_1}{2(1+s_0)\theta})(2\kappa-1)}\Bigr\}
    +\g{c}{suffcond1,3}\mu(F)^{1/2} \right],
\end{align*}
and the $p$ in $\g{c}{sg2,n}$ is $2$.
Moreover, the time-dependence of $\g{c}{gen,n}$ is $t+t^{-[\kappa-\frac{s_1}{2(1+s_0)\theta}(2\kappa-1)]},\;t\in (0,1]$.
\item[$\rm{(ii)}$]If $(F,R,\mu)$ satisfies the assumption $\rm{(A3)}$, and $h$ is sufficiently small,
then it holds that
\begin{align*}
 \Big|E_x[f(X_t)]-E^n_{x_n}[f(X^n_t)]\Big|\lesssim \g{C}{gen,n}\|f\|_{\BL^{\kappa}} h^{E_1}(\log(1/h))^{E_2},
\end{align*}
where
\begin{equation*}
  E_1=\frac{\kappa}{\kappa+(1+s_0)(2+\kappa)\Theta},\qquad E_2=\frac{\kappa (2+\kappa)[ (1+s_0)\Theta-1 ]}{\kappa+(1+s_0)(2+\kappa)\Theta},
  \qquad
  \Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)},
\end{equation*}
\begin{equation*}
  \begin{aligned}
    \g{C}{gen,n}=&\left\{ 1+\mu(F)^{1/2}\g{c}{suffcond1,4}+\g{c}{sg2,n}\mu(F)^{1/2}\Bigl[ c_{\rm{A1}}^{1/2} +\g{c}{suffcond1,4}\left(\frac{\alpha_n}{2}\right)^{-(1+\frac{s_1}{2(1+s_0)\Theta})(2\kappa-1)}\Bigr] \right\}\\
  &\times\left\{ 1+\left[\g{c}{summ}^{1/\beta}(1\wedge\frac{1}{2}\diam F)^{1+1/\beta}\left(\frac{\kappa}{\kappa+(1+s_0)(2+\kappa)\Theta}\right)^{-\frac{1}{\beta}}\right]^{-(\kappa+2)}\right\},
  \end{aligned}
\end{equation*}
and $\beta=\frac{1-(2+s_0)(s_0-s_1)}{s_1+2(2+s_0)(s_0-s_1)}$,
and the $p$ in $\g{c}{sg2,n}$ is $2$.
Moreover, the time-dependence of $\g{C}{gen,n}$ is $t+t^{-[\kappa-\frac{s_1}{2(1+s_0)\Theta}(2\kappa-1)]},\;t\in (0,1]$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:50:36.764720+00:00","domain":"probability theory","id":"claim_e608930dbd304d702ba5bea7182b76e0b6f7c6c010737b4321d7b25c5e75019a","kind":"concept","schema_version":1,"statement":"[Lemma 18 (Evaluation of $\mathfrak S_{m, n, p}$) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] }
        We have, 
        \begin{equation}
            \mathfrak S_{m, n, p}=\eps_2(\psi)H(-n^2/4m; p)+ O(1/\sqrt p),
        \end{equation}
        where, $\eps_2(\psi)$ is of absolute value one, defined in the Lemma~\ref{thm:Hasse-Davenport}, and for $\lambda\neq 0$ the character sum $H(\lambda, p)$ is defined by, 
        \begin{equation}
            H(\lambda; p)=
            \begin{cases}
                \hyp(\F_p^2\times\F_p^2; 1, \rho; \bar{\mu}, \bar{\mu}; \lambda) &\text{if $\pi_p$ is of type (a)},\\
                \eta_f(-1)\hyp(\F_p^2\times\F_{p^2}; 1, \rho; \eta_\pi; \lambda) &\text{if $\pi_p$ is of type (b)}.
            \end{cases}
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:07:48.565384+00:00","domain":"probability theory","id":"claim_e60a1ec3943625bc6093fdfc5da92d348ff575fabb0b74ed4c286b889727a737","kind":"theorem","schema_version":1,"statement":"[Proposition 21 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,\|\cdot\|_X)$ and $(Y,\|\cdot\|_Y)$ be finite dimensional normed spaces. Let $c: X \times Y \to \R$ be a continuous cost function that is positively 1-homogeneous in the second variable, meaning $c(x, ty) = tc(x,y)$ for all $t > 0$.

    Suppose a bounded set $K\subset X$ satisfies the non-degeneracy condition:
    \begin{equation}

        \inf_{u \in \mathbb{S}_Y} \sup_{x \in K} -c(x,u) = \epsilon > 0,
    \end{equation}
    where $\mathbb{S}_Y = \{y \in Y \mid \|y\|_Y = 1\}$. Let $L \subset Y$ be a non-empty set and suppose that $-c$ is non-negative on $K\times L$. Set $M(K,L) = \sup_{x\in K, y\in L} -c(x, y)$. Then,
    \begin{enumerate}
        \item If $L$ is unbounded, then $M(K,L)=\infty$.
        \item If $L$ is bounded, then $0\leq M(K,L)<\infty$ and $L\subseteq M(K,L)K^{\circ, c}$. Moreover, if $-c(x,y)=0$ for all $x \in K$ implies $y=o$, then $M(K,L)=0$ implies $L=\{o_Y\}$.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.900805+00:00","domain":"probability theory","id":"claim_e60b3e545ea88fc438d4d5324a23f740b312719a8ab1a154ebf8308e898adafe","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] For all $0<s<t$, $n,k\geq 1$, $x\in E$ and $z\in\mathbb R^d$ we set 
\begin{align*}
\phi_{s,t}^{n,k}(z,x):=\mathbf E_x\big[f_1(\mathbf Z_s^{n,z})\,f_2(\mathbf Z_t^{n,z})\,\mathbf 1_{\{\tau_{k-1}^n<s<t\leq\tau_k^n\}}\big].
\end{align*}
Then, for all $T>0$, $0<s_1<s_2<T$, $t_1<t_2<T$ and $L,M>0$ we have
\begin{align*}
&\lvert\phi_{s_1,t_1}^{n,k}(y,x)-\phi_{s_2,t_2}^{n,k}(y,x)\rvert\\
&\leq\big(\|f_1'\|_\infty\,\|f_2\|_\infty\,(s_2-s_1)+\|f_1\|_\infty\,\|f_2'\|_\infty\,(t_2-t_1)\big)\,\Big(L\,(\lvert z\rvert+TM)\,e^{TL}+M\Big)\\
&+2\,\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(s_2\leq\tau_k^n,L_{s_2}^n>L)+\mathbf P_x(s_2\leq\tau_k^n,M_{s_2}^n>M)\big)\\
&+\|f_1\|_\infty\,\|f_2\|_\infty\,\mathbf P_x(s_1\leq\tau_{k-1}^n<s_2)+\mathbf P_x(t_1\leq\tau_k^n<t_2)+\mathbf P_x(t_2\leq\tau_k^n,L_{t_2}^n>L)\\
&+\mathbf P_x(t_2\leq\tau_k^n,M_{t_2}^n>M)\big)+\mathbf P_x(s_1\leq\tau_{k-1}^n<s_2)+\mathbf P_x(t_1\leq\tau_k^n<t_2)\big).
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:38.359722+00:00","domain":"probability theory","id":"claim_e60bef4488f17783f9cc829043fd13c5e8d67b399bd28820357c0dcc21a1c8f7","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2604.21162, '2604.21162'] Assume that {\bf Assumption (H1)} holds and that $d>3$.
For any $\lambda >0$,  $f\in \mathscr{S}_0^\lambda$ and $\gamma>0$,
there are a constant $C_0>0$
{\rm (}which depends on $f$, $\gamma$ and $\lambda${\rm )}
and a random variable
$k_0(\w)\ge1$ {\rm (}which depends on $\gamma$ and $\lambda$ but is independent of $f${\rm )}
such that for all $k\ge k_0(\w)$,
\begin{equation}
\|
R_\lambda^{(k), \w}f - \bar R_\lambda f
\|_{L^2(\R^d;dx)} \le C_0
(\log k)^{-\frac{1}{2}+\frac{1+\gamma}{2(d-2)}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:48:02.413819+00:00","domain":"probability theory","id":"claim_e60c276af393111c2988bffb66c07dd824a35e96e7f6b6a6a52de0db615ba3f8","kind":"definition","schema_version":1,"statement":"[Definition def:families of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $n, m \geq 1$. The three family types, each with a \emph{base} and \emph{flipped-pair} class, are:
\begin{align*}
	\text{torus-torus:} \quad
	& T^{tor}_n \cup_C \overline{T^{tor}_m}
	&& \bigl(T^{tor}_n\bigr)^{\mathrm{fl}} \cup_C
	\overline{\bigl(T^{tor}_m\bigr)^{\mathrm{fl}}} \\
	\text{twist-torus:} \quad
	& T^{tw}_n \cup_C \overline{\bigl(T^{tor}_m\bigr)^{\mathrm{fl}}}
	&& \bigl(T^{tw}_n\bigr)^{\mathrm{fl}} \cup_C
	\overline{T^{tor}_m} \\
	\text{twist-twist:} \quad
	& T^{tw}_n \cup_C \overline{T^{tw}_m}
	&& \bigl(T^{tw}_n\bigr)^{\mathrm{fl}} \cup_C
	\overline{\bigl(T^{tw}_m\bigr)^{\mathrm{fl}}}
\end{align*}
In each case the first tangle variant occupies the inside ball, the mirrored variant the outside ball, and the boundary Conway spheres are identified as in Figure (fig:families of the paper), matching the strand endpoints so that the union of the four strand arcs is a single circle. In each type, the flipped-pair gluing is obtained from the base gluing by flipping both slots. The resulting knots are the \emph{$(n, m)$ knots} of their type and class, collectively the \emph{family knots}.","status":"unverified"}

