{"assumptions":[],"created_at":"2026-10-26T19:29:23.338400+00:00","domain":"probability theory","id":"claim_e61f73938fb244ff5da9d8b1e25f0f809a68a1f39a92c1cba900b26a42dbc653","kind":"lemma","schema_version":1,"statement":"[Lem 8 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] For functions $F=F(\eta)$ and $G=G(\eta) \in C^2(\R^{2\ell})$, 
if all integrals in the following converge, we have
\begin{align*} 
\int_{\R^{2\ell}} GL_{0,\ell}F d\nu_u^{\otimes 2\ell} 
& = \int_{\R^{2\ell}} FL_{0,\ell}G d\nu_u^{\otimes 2\ell}   \\
& = -\frac12 \int_{\R^{2\ell}} \sum_{x=-\ell+1}^{\ell-1}
 \big( \partial_{\eta(x)} -\partial_{\eta(x-1)} \big) F \cdot
\big( \partial_{\eta(x)} -\partial_{\eta(x-1)} \big) G\, d\nu_u^{\otimes 2\ell}.
\end{align*}
Moreover, for every $m\in \R$ and functions $F$ and $G\in C^2(\mathcal{X}_{\ell,m})$,
if all integrals in the following converge, we have
\begin{align*} 
\int_{\mathcal{X}_{\ell,m}} GL_{0,\ell}F d\mu_{\ell,m} & 
= \int_{\mathcal{X}_{\ell,m}} FL_{0,\ell}G d\mu_{\ell,m}   \\
& = -\frac12 \int_{\mathcal{X}_{\ell,m}} \sum_{x=-\ell+1}^{\ell-1}
 \big( \partial_{\eta(x)} -\partial_{\eta(x-1)} \big) F \cdot
\big( \partial_{\eta(x)} -\partial_{\eta(x-1)} \big) G\, d\mu_{\ell,m} \\
& =: - \mathcal{D}_{\ell,m}(F,G).
\end{align*}
Note again that only the pair $\lan x-1,x\ran \subset \La_\ell=[-\ell,\ell-1]$ appears
in the sum.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:40:26.993936+00:00","domain":"probability theory","id":"claim_e62198e90fce5e9b7c459eb9dbdef34fa8d634ae7d4b1e9bf5709ffe36b97034","kind":"lemma","schema_version":1,"statement":"[Lemma lem-entrident of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] For any box $W\Subset \mathbb{R}^d$ and any $\xi\in{\mathcal M }_1({\mathcal L }_W)$, 
\begin{equation}
\begin{aligned}
H&_{{\mathcal L }_W}\big(\xi\mid \Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q})\big)\\
&=|W|\,H\big((m_k)_k\,\big|\, \smfrac 1{|W|} (q_{k})_k\big)+ H_{{\mathcal L }_W}\Big(\xi\,\Big|\,\bigotimes_{k\in\mathbb{N}} \Pi_{k}(\xi)\Big)\\
&\quad +  \sum_{k\in\mathbb{N}} H_{\mathbb{N}_0}(\Pi_k(\xi)\circ  \mathfrak N_W^{-1}\mid {\rm Poi}_{m_k|W|})\\
&\quad + \sum_{k\in\mathbb{N}}\sum_{n\in\mathbb{N}} \Pi_k(\xi)(\mathfrak N_W=n)\, H\big(\Pi_{k}^{{{\scriptscriptstyle{({n}})}}}(\xi)\circ (\zeta_k\cap W)^{-1}\mid \overline {\rm Leb}_W^{\otimes n}\big)\\
 &\quad + \sum_{k\in\mathbb{N}}\sum_{n\in\mathbb{N}_0}\int \Pi_k^{{{\scriptscriptstyle{({n}})}}}(\xi)(\zeta_k\cap W \in {\rm d} A)\,\Big[ H\Big(\Pi_k^{{{\scriptscriptstyle{({A}})}}}(\xi)\,\Big|\, \bigotimes_{x\in A} \Pi_{k,x}^{{{\scriptscriptstyle{({A}})}}}(\xi)\Big)+ \sum_{x\in A} H\big(\Pi_{k,x}^{{{\scriptscriptstyle{({A}})}}}(\xi) \mid \overline \mu _{x,x}^{\ssup{W,k,{\rm par}}}\big)\Big],
\end{aligned}
\end{equation}
where we  abbreviate $m_k=m_{W,k}(\xi)$ and $q_k=m_{W,k}(\Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q}))$ and denote by $\Pi_k, \Pi_k^{{{\scriptscriptstyle{({n}})}}}, \Pi_k^{{{\scriptscriptstyle{({A}})}}}, \Pi_{k,x}^{{{\scriptscriptstyle{({A}})}}}\colon {\mathcal L }_W\to{\mathcal L }_W^{{{\scriptscriptstyle{({k}})}}}$ the projections on the set of loops of length $k$, respectively on the set of configurations in $W$ with precisely $n$ loops of length $k$ and no loops else, respectively on the set of configurations of loops of length $k$ with set of initial sites equal to $A\subset W$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.595096+00:00","domain":"probability theory","id":"claim_e62535f3739a0b8bc027084afb394c44b42186d725d0ca8fb1b3bbb955e76936","kind":"concept","schema_version":1,"statement":"[Lemma lemma-5.6a of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] For each  $ n+1\ge  k\ge2$ and~$p,q\in\mathbb Z$ let
\begin{equation}

\Gamma_{k,1}(p,q):=\theta_{k-1}^{(p+\alpha)^2}\theta^{-\alpha^2}\gamma_{k-1}( p-q)
\end{equation}
and for  $ n+1\ge k\ge3$ and~$j=2,\dots,k-1$, set
\begin{equation}

\Gamma_{k,j}(p,q):=\sum_{\begin{subarray}{c}
q_1,\dots,q_{j-1}\in\mathbb Z\smallsetminus\{0\}\\ q_0=p,\,q_j= q
\end{subarray}}
\biggl(\,\prod_{i=0}^{j-1}\theta_{k-i-1}^{(q_i+\alpha)^2}\theta^{-\alpha^2}\biggr)\prod_{i=1}^{j}\gamma_{k-i}( q_{i-1}-q_i).
\end{equation}
Then for all  $ n+1\ge k\ge2$ and all $p\in\mathbb Z$, 
\begin{equation}

w_{k}(p) = \sum_{j=1}^{k-1}\Gamma_{k,j}(p,0)\theta^{\alpha^2j}w_{k-j}(0)+\sum_{q\in\mathbb Z\smallsetminus\{0\}}\Gamma_{k,k-1}(p,q)\theta^{\alpha^2(k-1)}w_1(q).
\end{equation}
Moreover, for all~$ n+1\ge k\ge2$,  all  $1\le j< k$ and  all  $p\in\mathbb Z$,
\begin{equation}

\sum_{q\in\mathbb Z}\Gamma_{k,j}(p,q)\le \theta^{-\tilde c+|p|(|p|-1)\sigma^2_{\text{\rm min}}+(1-2|\alpha|)(j-1)}\prod_{i=1}^{j}\sum_{\ell\in\mathbb Z}\gamma_{k-i}(\ell)
\end{equation}
holds with~$\tilde c:=\max\{\alpha^2,(1-|\alpha|)^2\}\sum_{i=0}^n|\sigma_i^2-1|$ and $\sigma^2_{\text{\rm min}}:=\inf_{i=0,\dots,n}\sigma_i^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:58.356481+00:00","domain":"probability theory","id":"claim_e62779d5de62caf70213a6215bce740ed06dcd77cd286c491db5cf9b164ef335","kind":"concept","schema_version":1,"statement":"[Lemma 8 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] Suppose that $(Z_n)$ is a zero mean square-integrable martingale. Let $r_n^2:= \displaystyle\sum_{k=n}^{\infty} \dE[(\Delta Z_k)^2]$. If $\displaystyle\sum_{k=1}^{\infty} \dE[(\Delta Z_k)^2] < +\infty,$
and $\displaystyle\sum_{k=1}^{\infty}\frac{1}{r^2_k} \left[ (\Delta Z_k)^2 - \dE[ (\Delta Z_k)^2 \vert\mathcal{F}_{k-1}]\right] < +\infty ~ \text{ a.s.},$ we have the following:
