{"assumptions":[],"created_at":"2026-10-27T16:26:02.606642+00:00","domain":"probability theory","id":"claim_e649ab30f4858c408a9d0e7a5be9ccff0ad5ab230dba7836e61280a3889110cd","kind":"theorem","schema_version":1,"statement":"[Proposition Bcurv of arXiv:2608.30747, 'Compact homogeneous complex manifolds'] For any $\alpha,\beta\in\Delta_\qg^+$ and $A\in\ag^c$,
\begin{equation}
R^b(A,E_\alpha)E_\beta = g_\ag\left(A,\tfrac{1}{x_{\alpha+\beta}}A_{\alpha+\beta}-\tfrac{1}{x_{\beta}}A_{\beta}\right) \tfrac{N_{\alpha,\beta} \left(x_{\alpha+\beta}-x_\alpha\right)}{x_{\alpha+\beta}}E_{\alpha+\beta}, \qquad  \alpha+\beta\in\Delta_\qg, 
\end{equation}
\begin{equation}
R^b(E_\alpha,E_{-\alpha})E_\beta  = -\left(\la\alpha,\beta\ra+\tfrac{g_\ag(A_\alpha,A_\beta)}{x_\beta}\right)E_\beta, \qquad  \alpha\pm\beta\notin\Delta_\qg, 
\end{equation}
and 
\begin{equation}
R^b(E_\alpha,E_{-\alpha})E_\beta  =
\left(\tfrac{N_{-\alpha,\beta}^2 \left(x_{\beta}-x_\alpha\right)^2}{x_{-\alpha+\beta}x_\beta} 
-\tfrac{N_{\alpha,\beta}^2 \left(x_{\alpha+\beta}-x_\alpha\right)^2}{x_{\alpha+\beta}x_\beta} -\la\alpha,\beta\ra-\tfrac{g_\ag(A_\alpha,A_\beta)}{x_\beta}\right)E_\beta, 
\end{equation}
where in the last line, the term containing $N_{-\alpha,\beta}^2$ appears only if $-\alpha+\beta\in\Delta_\qg^+$ and the term containing $N_{\alpha,\beta}^2$ appears only if $\alpha+\beta\in\Delta_\qg^+$.  

Furthermore, if $\alpha+\beta\in\Delta_\qg$ and $\alpha-\beta\notin\Delta_\qg$, then 
\begin{equation}
R^b(E_{-\alpha},E_\beta)E_\alpha 
= -\tfrac{N_{\alpha,\beta}^2 \left(x_{\alpha+\beta}-x_\beta\right)\left(x_{\alpha+\beta}-x_\alpha\right)}{x_{\alpha+\beta} x_{\beta}} E_\beta. 
\end{equation}","status":"unverified"}

