{"assumptions":[],"created_at":"2026-10-27T19:30:07.875929+00:00","domain":"probability theory","id":"claim_e650220254c3547d8da03467bd4f7cb9781a2f025007e036bc84d21ae2b7da92","kind":"lemma","schema_version":1,"statement":"[Lemma lem_talagrand of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] {janson_luczak_rucinski00}}] 
Let $Z_1,\ldots,Z_n$ be independent random variables taking values in $\mathcal{Z}_1,\ldots,\mathcal{Z}_n$, respectively.
Let $f\colon\mathcal{Z}_1\times\cdots\times\mathcal{Z}_n\to\mathbb{R}$ be a measurable map satisfying the following two assumptions:
\begin{enumerate}[label=\textup{(\roman*)}]
\item  (Lipschitz with respect to Hamming distance) 
For every $j\in\{1,\ldots,n\}$, we have
\eq{ 
|f(z_1,\ldots,z_n) - f(z_1',\ldots,z_n')| \leqslant 1 \quad \text{whenever $z_i = z_i'$ for every $i\ne j$.}
}
\item  (Lower certifiable) 
There exists a map $\psi\colon\mathbb{R}\to[0,\infty)$ with the following property.
If $f(z_1,\ldots,z_n)\geqslant r$, then there exists $I\subseteq\{1,\ldots,n\}$ such that $\#I\leqslant\psi(r)$ and
\eq{
f(z_1',\dots,z_n') \geqslant r \quad \text{whenever $z_i = z_i'$ for every $i\in I$.}
}
\end{enumerate}
Let $Z = f(Z_1,\ldots,Z_n)$.
For every $r\in\mathbb{R}$ and $s\geqslant0$, we have
\eq{
\mathbb{P}(Z\leqslant r-s)\mathbb{P}(Z\geqslant r) \leqslant \exp\Big(\frac{-s^2}{4\psi(r)}\Big).
}
In particular, for any median $m$ of $Z$, we have
\eq{
\mathbb{P}(Z\leqslant m-s) \leqslant 2\exp\Big(\frac{-s^2}{4\psi(m)}\Big) \quad \text{and} \quad
\mathbb{P}(Z\geqslant m+s) \leqslant 2\exp\Big(\frac{-s^2}{4\psi(m+s)}\Big).
}","status":"unverified"}

