{"assumptions":[],"created_at":"2026-10-27T12:15:15.570328+00:00","domain":"probability theory","id":"claim_e66357912a322de5ffad49e9dfdaa9cb17232ba4d8d7f92372c53c8cff176940","kind":"lemma","schema_version":1,"statement":"[Lemma Eigenvector Evolution of arXiv:2507.12502, 'Quantitative Edge Eigenvector Universality for Random Regular Graphs: Berry-Esseen Bounds '] Under the CDBM dynamics (equation eq:cdbm-def of the paper), the eigenvector $\mathbf{u}_i(t)$ satisfies
\begin{equation}
\mathrm{d}\mathbf{u}_i = \sum_{j \neq i} \frac{\langle \mathbf{u}_j, \mathrm{d}\tilde{H}_t\mathbf{u}_i\rangle}{\lambda_i - \lambda_j}\mathbf{u}_j - \frac{1}{2}\mathbf{u}_i\mathrm{d} t + \mathrm{d}\mathbf{u}_i^{\perp}
\end{equation}
where $\mathrm{d}\mathbf{u}_i^{\perp}$ represents second-order corrections orthogonal to the eigenspace. Moreover, $\langle \mathbf{e}, \mathbf{u}_i(t)\rangle = 0$ for all $t \geq 0$ and $i \geq 2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:17:17.063709+00:00","domain":"probability theory","id":"claim_e664dee947787982fa3846415dc23b4dd48ab63f216f248562a9c0ca9f4e2f81","kind":"theorem","schema_version":1,"statement":"[Proposition 18 of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] For every $\beta > 0$, the ground state energy $\lambda(\beta)$ is differentiable with respect to $\beta$, and
\begin{equation}
\lambda'(\beta) = \int_{\mathbb{R}^d} \de x \, Q(x) \phi_{\beta}(x)^2  =: \theta_{\beta}.

\end{equation}
Let 
\[\mathcal{D}_{\beta,0} = \{g \in \mathcal{D} : g \text{ is real-valued and } \langle g, \phi_{\beta}\rangle = 0\}\]
and define on this real Hilbert space the coercive form $b_{\beta}[f,g] = h_{\beta}[f,g] - \lambda(\beta)\langle f,g\rangle$ and the bounded linear functional $L_{\beta}(g) = \int_{\mathbb{R}^d} \de x \, (Q(x) - \theta_{\beta})\phi_{\beta}(x)g(x) $.
Then, there exists a unique $u_{\beta} \in \mathcal{D}_{\beta,0}$ satisfying
\begin{equation}
b_{\beta}[u_{\beta}, g] = L_{\beta}(g) \quad \text{for all } g \in \mathcal{D}_{\beta,0}.

\end{equation}
Furthermore, $\beta \mapsto \phi_{\beta}$ is differentiable in the form norm $\|\cdot\|_{\mathcal{D}}$ with $\partial_{\beta}\phi_{\beta} = -u_{\beta}$, and $\lambda(\beta)$ is twice differentiable with
\begin{equation}
\lambda''(\beta) = -2 b_{\beta}[u_{\beta}, u_{\beta}] < 0.
\nonumber
\end{equation}
In particular, $\beta \mapsto \theta_{\beta}$ is strictly decreasing, $\sigma_{\beta}^2 = -\lambda''(\beta) > 0$, and $I_{\beta} = \frac{1}{2} \int_{\mathbb{R}^d} \de x \, |\nabla\phi_{\beta}(x)|^2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.498478+00:00","domain":"probability theory","id":"claim_e66d8e33f068b0ae3b35d38e0a991059eb1d18049c3446616260a9dd88739576","kind":"theorem","schema_version":1,"statement":"[Cor lem:lipschitz-f-g of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] The following statements hold:
\begin{enumerate}[label=(\roman*)]
    \item $\tilde F: [0,\infty) \times B \times \Theta \to B$ is locally Lipschitz.
    \item $\tilde G: [0,\infty) \times B \times \Theta \to \gamma(\mathcal{U},\mathcal{B}_{\beta,\rho})$ is locally Lipschitz for all $\rho \in [2,\infty)$, where $\beta$ is as in (SPDE-G-lem of the paper)(i).
    \item For all $M,p > 0$ there is some constant $C > 0$ such that
    \begin{equation}
        R+\|x\|_B \leq M \implies \|\tilde F_u(R,x,\theta)\|_{L^p} \leq C\|x_u\|_{L^p} \,.
    \end{equation}
    \item For any $r \geq 0$, $\theta \in \Theta$, and any $x$
    \begin{equation} 
        |\tilde \sigma_u(\cdot,r,x,\theta)| \lesssim |x_u| \,.
    \end{equation}
    \item There is some $k > 0$ such that, for $\rho \in [2,\infty)$ and $\beta$ as in (SPDE-G-lem of the paper):
    \begin{equation}
    \begin{aligned}
         \|\tilde G_u(R,x,\theta)\|_{\beta,\rho} &\lesssim \|x_u\|_{L^\rho} &\quad &\text{and} &\quad \|\tilde G(R,x,\theta)\|_{\beta,\rho} &\lesssim (1+R)\|x\|_{L^\rho}\\
         |\tilde F^+(R,x,\theta)| &\lesssim 1 + (1+R)|x| &\quad &\text{and} &\quad |\tilde F(R,x,\theta)| &\lesssim (1+R)^k|x|^k
         \,.
    \end{aligned}
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.074799+00:00","domain":"probability theory","id":"claim_e66dbaec733926c3e790a1d0c1fd0cc5d534ad07c6bfcc3aba197debb716046f","kind":"theorem","schema_version":1,"statement":"[Theorem 4 of arXiv:2606.02036, 'Self-intersection local times for Volterra Gaussian processes in stochastic flows with int'] Let $\{u(t) \equiv (u_1(t),\ldots,u_d(t)):  t\in[0,1]\}$ be a centred Gaussian process in $\mathbb{R}^d$ with indepdendent and identically distributed (i.i.d.) components and $\rho:\mathbb{R}^d\to\mathbb{R}$ be a weight function satisfying \eqref{eq:condition_on_weight_function}. Let $p\ge 2$.  If
 \begin{align}

 \int_{\Delta^p_k}\frac{1}{G(u_1(t_1),\ldots,u_1(t_{pk}))^{\frac{d}{2}}}\differential{t_1}\cdots\differential{t_{pk}}<\infty,
\end{align}
then there exists a random variable $T^{u}_k(\rho)$ such that 
the family  
$\{T^u_{\varepsilon,k}(\rho) : \ve >0 \}$ converges to $T^{u}_k(\rho)$ in $L^p(\Omega,\cF,\prob)$ as $\ve\to0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.608032+00:00","domain":"probability theory","id":"claim_e66e3bb9f93f30531ae762636e637558d69f3a5ef8f3b279e52d24785ac02022","kind":"lemma","schema_version":1,"statement":"[Lem 19 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\chi\in\Pi(G_1)$ and recall $\lambda_{\mathrm{C}}(s,z)$ from \eqref{eq:def-lambda-cont}.
		\begin{enumerate}
			\item Let $\chi^2\neq\1_1$ and $\varphi\in\1_{n-2}\boxplus\chi\boxplus\chi^{-1}$. Then $\Eis(\bar{\varphi},\lambda_{\mathrm{C}}(s,z))$ is holomorphic in the region $\Re\left(\tfrac{n}{2}s\right)\ge \Re(z)\ge 0$.
			\item Let $\chi^2=\1_1\neq \chi$ and $\varphi\in\1_{n-2}\boxplus\chi\boxplus\chi^{-1}$. Then $\Eis(\bar{\varphi},\lambda_{\mathrm{C}}(s,z))$ is meromorphic in the region $\Re\left(\tfrac{n}{2}s\right)\ge \Re(z)\ge 0$ with a simple polar divisor only at $z=\tfrac{1}{2}$.
			\item Let $\chi=\1_1$ and $\varphi\in\1_{n-2}\boxplus\chi\boxplus\chi^{-1}$. Then $\Eis(\bar{\varphi},\lambda_{\mathrm{C}}(s,z))$ is meromorphic in the region $\Re\left(\tfrac{n}{2}s\right)\ge \Re(z)\ge 0$ with simple polar divisors only at $z=\tfrac{1}{2}$ and $z=\pm\left(\tfrac{n}{2}s-\tfrac{n-1}{2}\right)$.
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:56:37.648217+00:00","domain":"probability theory","id":"claim_e675a20ec21a83024af79448ad36da6cf95e6899f784d8c3505d5e8da15eee23","kind":"concept","schema_version":1,"statement":"[Prop lebowitz of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Fix a finite graph $G = (V,E)$. Consider two sets of coupling constants $\{J_{xy}\}_{xy\in E}$ and $\{J'_{xy}\}_{xy\in E}$ satisfying $|J'_{xy}| \le J_{xy}$ for every $xy\in E$, and two external magnetic fields $\mathsf{h}$ and $\mathsf{h}'$ satisfying $|\mathsf{h}'_x|\le \mathsf{h}_x$ for every $x\in V$. Consider a family of single-site measures $(\rho_x)_{x\in V}$ such that for every $x\in V$, $\rho_x$ is either an even measure over $\mathbb{R}$ or $\rho_x$ is supported on $\mathbb{R}^+$. For every pair of moment functions $A, B:V\to\mathbb{N}$, one has
\begin{equation}
\langle \tau_A \tau_B \rangle - \langle \tau_A \tau_B \rangle' \ge |\langle \tau_A \rangle \langle\tau_B \rangle' - \langle \tau_A \rangle' \langle \tau_B \rangle|,
\end{equation}
where $\langle \cdot \rangle$ and $\langle \cdot \rangle'$ stand for the expectations under the measures $\nu_{G,\rho,J, \mathsf{h}}$ and $\nu_{G,\rho,J',\mathsf{h}'}$ respectively\footnote{Note that $\beta$ has been chosen equal to $1$ here which explains why it disappeared from the notation.}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:07:17.256588+00:00","domain":"probability theory","id":"claim_e67a60598fe13cda757dfb6f93d49097b7ae14294b9ef76a2d164afe6ce43839","kind":"definition","schema_version":1,"statement":"[Definition attractor of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] A random compact set $\mathcal{A} = \{ \mathcal{A}(\omega^-) \}_{\omega^- \in \mathcal{B}}$ is called a \(\mathrm{P}\)-pullback attractor for the SDS \(\varphi\) if the following conditions are satisfied.
	\begin{enumerate}
		\item For every $\omega^-, \omega^+ \in \mathcal{B}$, we have
		\[
		\Phi^{t}_{(\omega^-,\omega^+)}(\mathcal{A}(\omega^-)) = \mathcal{A}(P_t(\omega^-,\omega^+)).
		\]

		\item For every compact set 
		\( K \subset \mathbb{R}^d \)
		\[
		\lim_{t \to \infty} \sup_{x \in K} d(\varphi^{t}_{\omega^-}(x), {\mathcal{A}}(\omega^-)) = 0 \quad \mathbf{P}\text{-a.s.}
		\]
	\end{enumerate}
	\begin{comment}
		\textcolor{red}{
			This statement must not be difficult to show:
			The Weak \(\mathrm{P}\)-pullback attractor  is unique up to set with full measure.
		}
	\end{comment}","status":"unverified"}

