{"assumptions":[],"created_at":"2026-10-26T20:43:04.733507+00:00","domain":"probability theory","id":"claim_e6aaf6a658e9c916666ddede992dd5704b1d4fbe6b9dc152d477be49d8c0b6d3","kind":"concept","schema_version":1,"statement":"[Proposition 14 (Upward and downward one-sided exit problem) of arXiv:2605.18136, 'L\'evy processes with partially stochastic resetting'] Let  $q,\lambda > 0$,. Then,  the following limit cases, in terms of the resolvents $\overline{r}^{(q+\lambda)}$ and  $\underline{r}^{(q+\lambda)}$ defined in \textnormal{\textbf{(S1)}}, hold 
	\begin{itemize}
		\item[\upshape{(i)}] For $a,b \in \R_+$, 
		\begin{align}
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{a,U}^+} \1_{\{\tau_{a,U}^+ < \infty\}} \Bigr) &= \ee^{-\Phi_{q+\lambda}(a-x)} + \ee^{-\Phi_{q+\lambda}a} \cdot\frac{\lambda \int^{a}_{-\infty} \overline{r}^{(q+\lambda)}(x,y) \dd y}{1- \lambda \int^{a}_{-\infty} \overline{r}^{(q+\lambda)}(0,y) \dd y}, \quad x \in (-\infty,a], \notag \\
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{b,U}^-} \1_{\{\tau_{b,U}^- < \infty\}} \Bigr) &= {Z}^{(q+\lambda)}(x-b) - \frac{q+\lambda}{\Phi_{q+\lambda}} W^{(q+\lambda)}(x-b) + \lambda \int^\infty_b \underline{r}^{(q+\lambda)}(x,y) \dd y, \quad x \in [b,\infty). \notag
		\end{align}

		\item[\upshape{(ii)}] For $a,b \in \R_-$,
		\begin{align}
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{a,U}^+} \1_{\{\tau_{a,U}^+ < \infty\}} \Bigr) &= \ee^{-\Phi_{q+\lambda}(a-x)} + \lambda \int^{a}_{-\infty} \overline{r}^{(q+\lambda)}(x,y) \dd y, \quad x \in (-\infty,a], \notag \\
			\lim\limits_{p \rightarrow 0} \E_x \Bigl( \ee^{-q \tau_{b,U}^-} \1_{\{\tau_{b,U}^- < \infty\}} \Bigr) &= {Z}^{(q+\lambda)}(x-b) - \frac{q+\lambda}{\Phi_{q+\lambda}} W^{(q+\lambda)}(x-b) \notag \\
			&\quad \quad + Z^{(q+\lambda)}(-b) \cdot \frac{ \lambda \int^\infty_b \underline{r}^{(q+\lambda)}(x,y) \dd y}{\lambda \int^\infty_b \underline{r}^{(q+\lambda)}(0,y) \dd y}, \quad x \in [b,\infty). \notag
		\end{align} 
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:42:55.313946+00:00","domain":"probability theory","id":"claim_e6abb5d80e693f72773193c2d4c335b7c2426df2f9fa2e96a91ae0a48374dc87","kind":"theorem","schema_version":1,"statement":"[Prop 11 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $\sigma, \alpha > 0$,
