 \qquad
 \operatorname{Dom} a_{\tau,f}=V_\mu.

\end{equation}
For every $T>0$, the form norms
\[
 \left\|u\right\|_{\tau,f}^2
 :=a_{\tau,f}(u,u)+\left\|u\right\|_{L^2(\mu)}^2
