{"assumptions":[],"created_at":"2026-10-27T19:51:00.239751+00:00","domain":"probability theory","id":"claim_e7176eac5c897a7dde9cb7ecea4ad34b3729d3cb5ce7b97415c50ea7e6d586ac","kind":"theorem","schema_version":1,"statement":"[Theorem thm:ou_semigroup of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] The $\bm{\kappa}$-Ornstein--Uhlenbeck semigroup operator of the Brownian signature is given by
\begin{equation}
    {\bf T}^{\bm{\kappa}}_\vartheta\sigW 
    = \exp\!\left(\sum_{i=1}^d\frac{1 - e^{-\kappa_i\vartheta}}{2}\,{{\bf\Psi}}^{{\color{NavyBlue}{\mathbf{0}}}}_{{\color{NavyBlue}{\mathbf{ii}}}}\right)
      \left(\prod_{i=1}^d{\bf J}_{{\color{NavyBlue}{\mathbf{i}}}}^{\kappa_i\vartheta}\right)\sigW.
\end{equation}
Moreover, we have $\sigW \in \mathrm{Dom}({\bf L}^{\bm{\kappa}})$ and
\begin{equation}
    {\bf L}^{\bm{\kappa}}\sigW = 
    \sum_{i=1}^d\kappa_i\bigl({{\bf\Psi}}^{{\color{NavyBlue}{\mathbf{0}}}}_{{\color{NavyBlue}{\mathbf{ii}}}} - {\bf \Lambda}_{{\color{NavyBlue}{\mathbf{i}}}}\bigr)\sigW.
\end{equation}
Their adjoint operators are
\begin{equation}
    ({\bf T}_\vartheta^{\bm{\kappa}})^* 
    = \left(\prod_{i=1}^d{\bf J}_{{\color{NavyBlue}{\mathbf{i}}}}^{\kappa_i\vartheta} \right)
      \exp\!\left(\frac{1 - e^{-2\kappa_i\vartheta}}{2}\,{{\bf\Psi}}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{0}}}}\right),
    \qquad 
    ({\bf L}^{\bm{\kappa}})^* 
    = \sum_{i=1}^d\kappa_i({{\bf\Psi}}^{{\color{NavyBlue}{\mathbf{ii}}}}_{{\color{NavyBlue}{\mathbf{0}}}} - {\bf \Lambda}_{{\color{NavyBlue}{\mathbf{i}}}}).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:00.614021+00:00","domain":"probability theory","id":"claim_e717c34e17377375a0c2bd4e15f4006f68aa347e0209da96dfb876cf0a3fc710","kind":"concept","schema_version":1,"statement":"[Proposition 15 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] Fix $\beta'\in (0,1/2)$ and $\delta\in (0,1/6)$. For all $\ell\leq n$ and all $m\in [\![\beta'n, (1-\beta')n]\!]$, 
consider the event $\TP_{\ell,m}$ defined by
  \begin{equation}

    \TP_{\ell,m}=\{\exists x:
|x-\Gamma_{\0}^{\n}(m)|\geq \ell^{2/3-\delta}, |T_\0^\n-Z_{\0}^{\n,\bullet}(x,m)|\leq
\ell^{\delta}\}.
\end{equation}
Then there exists a constant $C$ such that for all $n$ large enough and all $\ell,m$ as above, we have
  \begin{equation}

      \PP(\TP_{\ell,m})\leq C \ell^{-1/3+2\delta}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.576670+00:00","domain":"probability theory","id":"claim_e71801720f8ebb387c40b2b70c8e8bfe6c7dff896726161b9502f52da3b78efa","kind":"lemma","schema_version":1,"statement":"[Lemma L:ipv_balan of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $\eta \in \mathbb{R}$. For any $\theta > 0$, denote by
  \begin{align*}
    F_{\eta} (\theta, \tau) \coloneqq \int_0^{\theta} \ensuremath{\mathrm{d} } s \; e^{i s \tau} \sin (s  + \eta) .
  \end{align*}
  Then, for all $\tau\in\mathbb{R}\setminus\{\pm1\}$,
  \begin{align}
    |F_{\eta} (\theta, \tau)|^2 = \frac{1}{\left(1 - \tau^2\right)^2}                                                            
    & \left( \left(\cos(\eta) \sin(\tau \theta) + \tau \sin(\eta) \cos(\tau \theta) - \tau \sin(\theta + \eta) \right)^2 \right. \nonumber \\
    & \left.+ \left(\cos(\eta) \cos(\tau \theta) - \tau \sin(\eta) \sin(\tau \theta) - \cos(\theta + \eta) \right)^2\right).
  \end{align}
  Moreover, the identity extends to $\tau=\pm1$ by continuity.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:03:39.763115+00:00","domain":"probability theory","id":"claim_e7192b89d7834e3b70e305575b8ad2e1f7c919ead250c7ba765e853b14f92a50","kind":"concept","schema_version":1,"statement":"[Prop eq:greedy.path.u of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{prop:greedy.path}
   Let
   $(0,0)_0=(r_0,s_0)_0\to(r_1,s_1)_1\to\cdots$ be the
   $k$-greedy infection path. There exist constants $C,c$
   depending only on $\lambda$ and $k$ such that for all $n$ and all $t\geq 5$,
   \begin{align}
     \mathbf{P}\Biggl(\abs[\bigg]{r_n-\frac{\crist[k]n^2}{2}}\geq tn^{3/2}\Biggr) &\leq C\exp\biggl(-\frac{ct^2}{1+\frac{t}{\sqrt{n}}}\biggr),\\\intertext{and}
