{"assumptions":[],"created_at":"2026-10-27T12:10:07.473808+00:00","domain":"probability theory","id":"claim_e748d30a842be05754a0cdd8dc305ba29a49280ed165e22753049f597a39fb3a","kind":"lemma","schema_version":1,"statement":"[Lemma eq:dI-budget of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:aggregate-jet-budget}
Uniformly in \(O\in\mathcal O_{N,L}\),
\begin{equation}
 \sum_{I\in[N]^p}\mathfrak d_I\le C N,
 \qquad
 \max_{I\in[N]^p}\mathfrak d_I\le Cq_N^2.
\end{equation}
Writing \(\alpha_I(J)=\partial_I\Psi_O(J)\), one also has
\begin{equation}
 \max_I\left\lvert\alpha_I(J)\right\rvert\le Cq_N,
 \qquad
 \sum_I\left\lvert\alpha_I(J)\right\rvert^2\le CN,
\end{equation}
and, for \(2\le k\le m+1\),
\begin{equation}
 \left\lvert\partial_I^k\Psi_O(J)\right\rvert
 \le C_k\mathfrak d_Iq_N^{k-2}.
\end{equation}
Consequently, for \(2\le k\le m+1\),
\begin{align}
 \left\lvert\partial_I^kF_O(J)\right\rvert
 &\le C_kF_O(J)
 \left(\left\lvert\alpha_I(J)\right\rvert^k+
       \mathfrak d_Iq_N^{k-2}\right),
 \\
