{"assumptions":[],"created_at":"2026-10-27T17:42:08.473963+00:00","domain":"probability theory","id":"claim_e7766eb9915744e26196f711dc1f7b9d14ddefccdb47dd40e2b77981f28a81cc","kind":"lemma","schema_version":1,"statement":"[Lemma GeneralLemma of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C3 of the paper). Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$. Fix $t \in \mathbb{R}$ and for $k=1,\dots h+1$, define $M_{0}^{(k)}(t) \coloneqq 0$, and for $n \in \mathbb{N}$,
\begin{align} 
M_{n}^{(k)}(t) & \coloneqq \sum_{i=1}^{n} (\varphi_{u_{i}}^{(k)}(t-S(u_{i})) - \mathbb{E}[\varphi_{u_{i}}^{(k)}(t-S(u_{i})) \mid \mathcal{G}^{(k-1)}_{i-1}]).
\end{align}
\noindent Then:
\begin{enumerate}[label=(\textbf{\roman*})]
\item $(M_{n}^{(k)}(t))_{n \in \mathbb{N}_{0}}$ is a well-defined centred martingale with respect to $(\mathcal{G}_{n}^{(k-1)})_{n \in \mathbb{N}_{0}}$. Moreover, for $n \in \mathbb{N}$, 
\begin{align} 
M^{(k)}_{n}(t) &  \stackrel{a.s.}{=}  (\varphi_{u_{1}}^{(k-1)}(t) - \varphi_{u_{1}}^{(0)}(t)) + \sum_{i=1}^{n} (\varphi_{u_{i}}^{(k)}(t-S(u_{i})) - \varphi_{u_{i}}^{(k-1)}(t-S(u_{i}))).  
\end{align}

\item The increments of $(M_{n}^{(k)}(t))_{n \in \mathbb{N}_{0}}$ are uncorrelated. 
\item $(M_{n}^{(k)}(t))_{n \in \mathbb{N}_{0}}$ is bounded in $L^{2}(\Omega, \mathcal{F}, \mathbb{P})$, that is, $\sup_{n \in \mathbb{N}_{0}} \mathbb{E}[(M_{n}^{(k)}(t))^{2}] < \infty$. 
\item The series 
\begin{align} 
M^{(k)}(t) \coloneqq (\varphi_{\varnothing}^{(k-1)}(t) - \varphi_{\varnothing}^{(0)}(t)) + \sum_{u \in \mathcal{I}} (\varphi_{u}^{(k)}(t-S(u)) - \varphi_{u}^{(k-1)}(t-S(u))).
\end{align}
\noindent converges unconditionally in $L^{2}(\Omega, \mathcal{F}, \mathbb{P})$ and it is also the almost sure limit  of $(M_{n}^{(k)}(t))_{n \in \mathbb{N}_{0}}$, as $n \rightarrow \infty$. Furthermore, for any deterministic sequence $(\mathcal{I}_{n})_{n \in \mathbb{N}}$ such that $\mathcal{I}_{n} \uparrow \mathcal{I}$, as $n \rightarrow \infty$, we have that 
\begin{align}
M^{(k)}_{\mathcal{I}_{n}}(t) \coloneqq (\varphi_{\varnothing}^{(k-1)}(t) - \varphi_{\varnothing}^{(0)}(t)) + \sum_{u \in \mathcal{I}_{n}} (\varphi_{u_{i}}^{(k)}(t-S(u_{i})) - \varphi_{u_{i}}^{(k-1)}(t-S(u_{i})))
\end{align}
\noindent converges in $L^{2}(\Omega, \mathcal{F}, \mathbb{P})$ towards $M^{(k)}(t)$, as $n \rightarrow \infty$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.231759+00:00","domain":"probability theory","id":"claim_e777525c945ff991ab9bc5dcb15ead177d45fd139345f2d8e84ceba6484ea82b","kind":"concept","schema_version":1,"statement":"[Proposition 31 of arXiv:2607.18104, '2607.18104'] There exist constants $C,c>0$ such that for all $\delta>0$ and $N$ large enough
