{"assumptions":[],"created_at":"2026-10-27T21:54:18.300814+00:00","domain":"probability theory","id":"claim_e797778c60a34d0c928743fe92042b1b46551613e98080bb55ac26b790945313","kind":"theorem","schema_version":1,"statement":"[Prop 3476 of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ c, q \in (0,\infty) $, $ \beta \in [ \nicefrac{ 1 }{ 2 }, 1 ) $,
let $ \mathcal V \subseteq {\mathbb R}^d $ be measurable, and
let $ ( X, U ) $ be $ ( c, q ) $-regular on $ \mathcal V $ in the sense of (def:regular of the paper).
Consider the stopping time
\bas{
  \bar\tau =
  \inf\bigl\{
    n \in {\mathbb N}_0 \colon \theta_n\not\in \mathcal V
  \bigr\}
  \qquad
  \text{and}
  \qquad
  \sigma^{ (i) } =
  \inf\bigl\{
    n \in {\mathbb N} \colon v_n^{ (i) } \ge \tfrac{ c ( 1 - e^{ - 1 / 2 } ) }{ 2 }
  \bigr\} .
}
Then for all $ n \in {\mathbb N} $ one has
\bas{
  {\mathbb P}\bigl(
    \bar \tau \ge n, \sigma^{(i)} > n
  \bigr)
  \le
  \exp\Bigl(
    - \frac{ q n ( 1 - e^{ - 1 / 2 } ) }{ 4 }
  \Bigr)
  .
}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:31.958419+00:00","domain":"probability theory","id":"claim_e79861df87b4aeff4a77515f897a181b7060790d0b5a30fe7345067845c67ae6","kind":"lemma","schema_version":1,"statement":"[Lm 13 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] The functions defined by \eqref{eq:Q-kernel},\eqref{eq:p-kernel} and \eqref{eq:R-kernel} satisfy the following recurrence relations
	\begin{align}
        \begin{split}
    		Q_{i+1,j}(x_{i},x_{j}) & = \sum_{y_i\geq x_i} Q_{i,j}(y_i,x_j), \\
    		Q_{i,j+1}(x_{i},x_{j}) & = \sum_{y_j\geq x_j} Q_{i,j}(x_i,y_j), \\
    		U_{k+1}(z) & = \sum_{y\geq z} U_{k}(y), \\
    		p_{k+1}(z) & = \sum_{y\geq z} p_k(y).
        \end{split}
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:45:27.972937+00:00","domain":"probability theory","id":"claim_e798c83f4eeec0dcec9487911243180fa6ed04f63830c7767a3633613dda2740","kind":"lemma","schema_version":1,"statement":"[Lemma lem:limiting-bridge-identity of arXiv:2607.04264, 'Macroscopic Feynman Cycles and Poisson--Kingman Universality in Bose Condensation'] Let \(h\in\mathcal H\).  Assume that \(T^{(\kappa)}\) and
\(T_h^{(\kappa)}\) have densities \(f_0^{(\kappa)}\) and
\(f_h^{(\kappa)}\), respectively.  Then
\begin{equation}
        \mathbf E
        \left[
            e^{-\langle h,\Pi^{(\kappa)}\rangle};
            T^{(\kappa)}\in da
        \right]
        =
        e^{-A^{(\kappa)}(h)}
        f_h^{(\kappa)}(a)\,da .
\end{equation}
Consequently, for every \(a>0\) such that \(f_0^{(\kappa)}(a)>0\),
\begin{equation}
        \mathbf E
        \exp\left\{
            -\langle h,\Pi_a^{\mathrm{br}}\rangle
        \right\}
        =
        e^{-A^{(\kappa)}(h)}
        \frac{
            f_h^{(\kappa)}(a)
        }{
            f_0^{(\kappa)}(a)
        } .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:33.748044+00:00","domain":"probability theory","id":"claim_e7a1bb916e0b96ef2ce1794c0963435a3e3e6499f0d300dd63c81ea74801e880","kind":"lemma","schema_version":1,"statement":"[Lem 12 of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let $\rho_1<\rho_2$ be consecutive pivot nodes and set $j:=\rho_2-\rho_1$.
The following statements hold.
\begin{enumeratei}
\item If $j\le 2\ell-2$, then $T(\rho_1,\rho_2)<2a$, where $a$ is the fixed constant satisfying Condition~\textnormal{B.\ref{ass:B1}}.
\item If $j\ge 2\ell-1$, then there exist $\lc=\ell(\ell+1)/2$ paths from $0$ to $j$ such that, after deleting their first and last edges, the remaining edge sets are pairwise disjoint. Moreover, each such truncated path uses at most $j$ edges.
\end{enumeratei}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.275735+00:00","domain":"probability theory","id":"claim_e7a21d7ad3d894545ba129e83ea8345e0a1656e7678efabdb62baaf75bde7433","kind":"concept","schema_version":1,"statement":"[Lemma lemma3.9 of arXiv:2412.06246, 'The smallest singular value for rectangular random matrices with Lévy entries'] Fix some $d,r>0$. Let $(g_{i1},g_{i2},\cdots g_{in})$ be a random vector of i.i.d. coordinates. Consider $H\subset\mathbb{R}$ a Borel subset with $H=H_1\cup H_2$ for two Borel sets $H_1,H_2$, where $\operatorname{dist}(H_1,H_2)\geq d$, and $\min(\mathbb{P}(g_{ij}\in H_1),\mathbb{P}(g_{ij}\in H_2))\geq r$. Given any $t>0$ we define 
    $$
h_{(equation lemma3.9 of the paper)}=\frac{1-\delta^{-1/4}}{C_{(equation theorem3.2 of the paper)}}\sqrt{
\frac{r}{16}
}td,
    $$ and let $y\in\mathbb{R}^n$ be a vector which satisfy $\|y\|_2\geq t$, $\|y\|_\infty\leq \frac{2h_{(equation lemma3.9 of the paper)}}{d}$. Let $(g_{i1}',g_{i2}',\cdots,g_{in}')$ be an i.i.d. copy of $(g_{i1},\cdots,g_{in})$. Then 
    \begin{equation}
\mathbb{P}\left\{\left|\sum_{j=1}^n \psi_{ij}(g_{ij}-g_{ij}')y_j\right|\leq h_{(equation lemma3.9 of the paper)}\right\}
  \leq 1-\delta^{-1/4}.\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.275777+00:00","domain":"probability theory","id":"claim_e7a458df7b8e0e60ea7d8b8aa8509c21bc509f394f6b70dd6523d4b14b947045","kind":"concept","schema_version":1,"statement":"[Lem 10 ({Penrose~\cite[Theorem~2.3) of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] {Penrose.2003}}]
    Let $(I, \sim)$ be a finite simple graph and, $(\xi_i)_{i \in I}$ be a collection of Bernoulli variables such that $\xi_i$ is independent from $\xi_j$ whenever $i \nsim j$.
    That is, assume $(I, \sim)$ is a dependency graph for $(\xi_i)_{i \in I}$.
    Let $\{I(j)\}_{j=1}^{\ell}$ be a partition of $I$ and for $1 \leq j \leq \ell$, set $W_j := \sum_{i \in I(j)} \xi_i$.
    Let $(Z_i)_{i=1}^{\ell}$ be a set of independent Poisson variables with $E[Z_j] = E[W_j]$.
    Then, for $p_i := E[\xi_i]$ and $p_{ij} := E[\xi_i \xi_j]$,
    \begin{equation*}
        d_{\text{TV}}\left((W_j)_{1 \leq j \leq \ell}, (Z_j)_{1 \leq j \leq \ell}\right) \leq 3\left(\sum_{i \in I} \sum_{j \in \CN_i \setminus \{i\}}p_{ij} + \sum_{i \in I} \sum_{j \in \CN_i} p_i p_j\right),
    \end{equation*}
    where $\CN_i := \{i\} \cup \{j \in I : j \sim i\}$ is the neighborhood of $i$ with respect to the adjacency relation $\sim$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:21:56.726915+00:00","domain":"probability theory","id":"claim_e7a8e32a6cab2bf9be169a7bd779d03f870b96e5459c12d166363fec9f1d0001","kind":"lemma","schema_version":1,"statement":"[Lemma le:tightness_loop_chain of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] There exists $\zeta > 0$ such that the following is true. For each $a_1 > 0$ and $b>0$, there exists $N \in \mathbf{N}$ such that the following holds. Fix $0<r<1$. For $z \in B(0,r)$ and $\delta > 0$, let $G_{z,\delta}$ be the event that there is a set of at most $N$ points $x_1,x_2,\ldots \in A(z,\delta,\delta^{1-a_1})$ with $\abs{x_{i}-x_{i'}} \ge \delta$ for each $i \neq i'$ and such that
\begin{itemize}
 \item The set $\{x_1,x_2,\ldots\}$ separates $\Upsilon_\Gamma \cap B(z,\delta)$ from $\partial B(z,\delta^{1-a_1})$.
 \item Let $K'$ be any connected component of $\Upsilon_\Gamma \setminus \{x_1,x_2,\ldots\}$ containing some point in $B(z,\delta)$, and let $i,i'$ so that $x_{i},x_{i'} \in \partial K'$. Let $V \in \metregions$ be such that $\overline{V}$ contains all \emph{simple} admissible paths within $K'$ from $x_{i}$ to $x_{i'}$. Then
 \[ \median{\epsilon}^{-1}\metapproxacres{\epsilon}{V}{x_{i}}{x_{i'}}{\Gamma} \le \delta^\zeta+\epsilon^{a_0} . \]
\end{itemize}
Then $\mathbf{P}[G_{z,\delta}^c] = O(\delta^b)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.340558+00:00","domain":"probability theory","id":"claim_e7a9e895c903792fc089b88fc652aa001776ceff6f1174d876cb466e14f041e9","kind":"definition","schema_version":1,"statement":"[Definition def: CharacterizedPhi of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] The \emph{bivariate characteristic polynomial} of the pair $(\bM,\zeta)$ is defined as 
    \begin{align}
        \Phi_{\bM,\zeta}(\lambda, t) \de \det\bigl(\lambda \bI - \bM - t \zeta \zeta^{\T}\bigr),
    \end{align}
    where $\bI$ is the identity.
    The pair $(\bM,\zeta)$ is said to be \emph{characterized by $\Phi$-spectrum} if every $(\bN,\eta)$ with $\Phi_{\bM,\zeta} = \Phi_{\bN, \eta}$ is isomorphic up to signed permutation.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.058430+00:00","domain":"probability theory","id":"claim_e7aa5c6209503c5800e2649a6fa787698068025b87d723f0eb4a7d0bb2c191a8","kind":"definition","schema_version":1,"statement":"[Definition 42 (Balanced comparison structure) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] We say that $\xi$ is \textbf{balanced} with respect to $\lambda$ if there exists a one-species covariance function $\xi_\star:\R_+\to\R$ such that, for every $r\in\R_+$,
\begin{equation}

    \xi(r\lambda)=\xi_\star(r),
\end{equation}
and, for every $a=(a_s)_{s\in\sS}\in\R_+^\sS$,
\begin{equation}

    \xi(a)\leq \sum_{s\in\sS}\lambda_s\xi_\star\left(\frac{a_s}{\lambda_s}\right).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.355568+00:00","domain":"probability theory","id":"claim_e7acda3f820a404b16e155474ba95b2d360fc012cd74a1dc9f9024ee30960196","kind":"concept","schema_version":1,"statement":"[Lemma eq:auxiliary-control-problem:verification of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Fix $p \in [2,\infty)$ and $\delta > 0$, and let $\lambda$ and $\gamma$ be as defined in (equation eq:primal-optimizers-finite-p:def-lambda of the paper) and (equation def.gammalambda of the paper). Define a function $u : [0,1] \times {\mathbb R} \to {\mathbb R}$ via
    \begin{align*}
    u(t_0,x_0) = \inf_{\beta} {\mathbb E}\bigg[ \int_{t_0}^1 \frac{1}{2 \lambda(t)} \beta(t)^2 \, dt + \gamma |X(1)|^p \bigg],
\end{align*}
where the infimum is taken over all progressively measurable processes $\beta$ satisfying
\begin{align*}
    {\mathbb E}\bigg[ \int_{t_0}^1 \frac{1}{\lambda(t)} \beta(t)^2 \, dt  \bigg] < \infty,
\end{align*}
and
\begin{align*}
    X(t) = x_0 + \int_{t_0}^t \beta(s) \, ds + (B(t)  - B(t_0)).
\end{align*}
Then, the following assertions hold:
\begin{enumerate}
    \item $u$ is convex and even in $x$, and there is a constant $C$ such that
    \begin{align*}
        |u(t,x)| \leq C(1 + |x|^p)
    \end{align*}
    for all $(t,x) \in [0,1] \times {\mathbb R}$.
    \item $u$ is a classical solution to (equation eq:auxiliary-control-problem:hjb of the paper).
    \item the unique optimizer for the problem (equation eq:auxiliary-control-problem:def of the paper)  (and hence for the problem $V_{p,\delta}^{\infty}$, thanks to Lemma (lemma:auxiliary-control-problem:optimality of the paper)) is give in feedback form by
    \begin{align*}
