{"assumptions":[],"created_at":"2026-10-27T20:17:04.328233+00:00","domain":"probability theory","id":"claim_e7e98e102b1fa79d010a554a5e01e2ff4a77e856d228c2b27b4484c081182f40","kind":"concept","schema_version":1,"statement":"[Theorem thm:main2 of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Assume that $\alpha_e=0$, and for any $t\in [0,T]$, $\varphi\in\mathscr{S}(\mathbb{R} )$ define
    \begin{equation*}
        \mathcal{Z}_t^{N ,1}(\varphi ) = \mathcal{Y}_t^{p,N}(T_{v_1N^{a-1}t}\varphi) - \frac{\rho}{\mathcal{E}}\mathcal{Y}_t^{e,N}(T_{v_1N^{a-1}t}\varphi) \qquad \mbox{ and }\qquad  \mathcal{Z}_t^{N ,2}(\varphi ) = \mathcal{Y}_t^{p,N}(T_{v_2N^{a-1}t}\varphi)
    \end{equation*}
    where $v_1 = \frac{\alpha_p (\kappa -1)(1-\rho )}{N^\gamma}$ and $v_2 = \frac{\alpha_p(\kappa -1)(1-2\rho )}{N^\gamma}$. Then, in the diffusive timescale $a=2$ and with a weak asymmetry given by $\gamma =\frac12$, the couple of processes $(\mathcal{Z}^{N,1},\mathcal{Z}^{N,2})_{N\ge 1}$ converges in distribution, as $N\to\infty$ to a pair of independent processes $(\mathcal{Z}^1,\mathcal{Z}^2)$ starting from independent spatial white noises with respective variances $\sigma_1$ and $\sigma_2$, where $\mathcal{Z}^1$ is a solution to the Ornstein-Uhlenbeck equation 
    \begin{equation*}
        \partial_t\mathcal{Z}_t^1 = (\kappa -1)\Delta \mathcal{Z}_t^1 +\sqrt{\smash[b]{2(\kappa -1)\sigma_1^2}}\nabla\dot{\mathcal{W}}_t^1
    \end{equation*}
    in the sense of (defin:OUsolution of the paper), while $\mathcal{Z}^2$ is an energy solution to the SBE
    \begin{equation*}
        \partial_t\mathcal{Z}_t^2 = (\kappa -1)\Delta\mathcal{Z}_t^2 + \mathfrak{g}_2\nabla (\mathcal{Z}_t^2)^2 + \sqrt{\smash[b]{2(\kappa -1)\sigma_2^2}} \nabla\dot{\mathcal{W}}_t^2
    \end{equation*}
    in the sense of (defin:energysolution of the paper). Above, $(\mathcal{W}^1,\mathcal{W}^2)$ are two independent $\mathscr{S}'(\mathbb{R} )$-valued Brownian motions, and the parameters are given by
    \begin{equation*}
        \mathfrak{g}_2 = -\alpha_p(\kappa -1) ,\qquad \sigma_1^2 = \frac{\rho \big( 1-\frac{\rho}{\mathcal{E}}\big) \big(\kappa\frac{\rho}{\mathcal{E}} -1\big)}{\kappa -1} \qquad \mbox{ and }\qquad \sigma_2^2 = \rho (1-\rho ).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:09:34.495010+00:00","domain":"probability theory","id":"claim_e7eb1ad2bf2bf7c924cd0d316747befc5eaea1933b0adfd0649f09821c7e67ea","kind":"definition","schema_version":1,"statement":"[Defn ${\rm SLE}(0,\boldsymbol{\rho})$ of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Let $w$ be the growth point on $\partial \mathbb{D}$ and $\boldsymbol{\rho}=\sum_{i=1}^{n} \rho_j \delta_{u_j} + \sigma_0 \cdot 0 + \sigma_{\infty} \cdot \infty$ be a divisor on $\widehat{\mathbb{C}}$ that is symmetric under involution, i.e. $\boldsymbol{\rho}(z)=\boldsymbol{\rho}(\frac{z}{|z|^2})$ for all $z$ and $\int \boldsymbol{\rho}= -6$. Define the radial $\operatorname{SLE}(0,w, \boldsymbol{\rho})$ Loewner chain by
\begin{equation}
\partial_t g_t(z)=g_t(z)\frac{w(t)+g_t(z)}{w(t)-g_t(z)}, \quad g_0(z)=z,
\end{equation}
where the driving function $w(t)$ evolves as

\begin{equation}
\dot{w}(t)=w(t)\sum_j \rho_j\frac{g_t(u_j)+w(t)}{g_t(u_j)-w(t)}, \quad z(0)=z_0.
\end{equation}

In the angular coordinate, $w(t)=e^{i\theta(t)}$ and $u_j(t)= e^{i q_j(t)}$, let $h_t(z)$ be the covering conformal map of $g_t(z)$ (i.e. $e^{ih_t(z)}=g_t(e^{iz}))$.

Then the Loewner differential equation for $h_t(z)$ is 

\begin{equation}
\partial_t h_t(z)=\cot(\frac{h_t(z)-\theta_t}{2}), \quad h_0(z)=z,     z\in{\overline{\mathbb{H}}},
\end{equation}

where the driving function $\theta_t$ evolves as
\begin{equation}
\dot{\theta}_t=\sum_j \rho_j \cot( \frac{\theta_t-q_j(t)}{2}), \quad x(0)=x_0.
\end{equation}","status":"unverified"}

