{"assumptions":[],"created_at":"2026-10-27T17:42:08.474425+00:00","domain":"probability theory","id":"claim_e812b63fea52b9d226d63a7450c7f83c657817e9cd8af7e1ae1e28000f638651","kind":"lemma","schema_version":1,"statement":"[Lemma lemma6 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and  let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, we have the following:
\begin{enumerate}[label=(\textbf{\roman*})]
\item  For every $t \in \mathbb{R}$, $\chi^{(\varphi, h)}(t) \in L^{2}(\Omega, \mathcal{F}, \mathbb{P})$. 
\setcounter{Cond3}{\value{enumi}}
\end{enumerate}

\noindent Assume further that (C4 of the paper)-(C5 of the paper) holds. Then, we also have the following:
\begin{enumerate}[label=(\textbf{\roman*})]
\setcounter{enumi}{\value{Cond3}}
\item $\chi^{(\varphi,h)}$ almost surely has c\`adl\`ag paths. 

\item $\chi^{(\varphi,h)}$  satisfies (C1 of the paper)-(C3 of the paper).  

\item  Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$ and recall that $\mathcal{I}_{n} = \{u_{1}, \dots, u_{n}\}$, for $n \in \mathbb{N}$. For $n \in \mathbb{N}$ and $t \in \mathbb{R}$, define
\begin{align} 
Y_{n}^{\varphi}(t) \coloneqq \sum_{u \in \mathcal{I}_{n}} \chi^{(\varphi,h)}_{u}(t-S(u)) = \sum_{i=1}^{n} \chi^{(\varphi,h)}_{u_{i}}(t-S(u_{i})). 
\end{align}
\noindent Then, for every $t \in \mathbb{R}$, as $n \rightarrow \infty$, $Y_{n}^{\varphi}(t) \rightarrow  \mathcal{Z}_{t}^{\chi^{(\varphi,h)}}$, in $L^{1}(\Omega, \mathcal{F}, \mathbb{P})$.

\item For every $t \in \mathbb{R}$,  $\mathbb{E}[\mathcal{Z}_{t}^{(\chi^{(\varphi,h)})^{2}}] < \infty$.

\item For all $t \in \mathbb{R}$ and any admissible order $(u_{n})_{n \in \mathbb{N}}$ of $\mathcal{I}$, as $n \rightarrow \infty$, 
\begin{align} 
\sum_{i=n+1}^{\infty} (\chi^{(\varphi,h)}_{u_{i}}(t-S(u_{i})))^{2} \rightarrow 0, \quad \text{in} \quad L^{1}(\Omega, \mathcal{F}, \mathbb{P}).
\end{align}

\item For $t \in \mathbb{R}$, 
\begin{align} 
\mathcal{Z}_{t}^{\varphi - \mathbb{E}[\varphi]} \stackrel{a.s.}{=} \mathcal{Z}_{t}^{\chi^{(\varphi,h)}} +  \sum_{0 \leq |u| \leq h-1}  ( \varphi_{u}^{(h-|u|)}(t-S(u)) - \varphi_{u}^{(0)}(t-S(u))).
\end{align}
\noindent (If $h=0$, the sum  $\sum_{0 \leq |u| \leq h-1}$ on the right-hand side of (equation eq82 of the paper) is defined to be $0$.) 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.373210+00:00","domain":"probability theory","id":"claim_e81525040fcc5f5627f5b30f02151132e633f395edfc3aaffba578dea86ed082","kind":"concept","schema_version":1,"statement":"[Proposition of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] $\mathsf{acc}$ is strictly proper iff there is a convex function $\varphi$ (with values $\mathsf{acc}_v(v)$) where:
