{"assumptions":[],"created_at":"2026-10-27T12:52:05.705634+00:00","domain":"probability theory","id":"claim_e8769c9a71de5d581bb1c54949ac30ddf3f4d278df7b59b0c1169c0414042d42","kind":"concept","schema_version":1,"statement":"[Lem compound of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $n \in \mathbb{N}$, $p,q \in (0,1]$ and $\lambda,\mu > 0$ be fixed parameters. Then:
\begin{itemize}
\item [\rm{i.}] If $S \sim \Bigeo(n,p;q)$, then $\begin{cases}\mathbb{P}( S \leq \theta ) \leq {\rm e}^{-(\sqrt{np}-\sqrt{\theta q})^2}  \quad \text{ if $\theta \leq \frac{np}{q}$,} \\ \\ \mathbb{P}(  S  \geq \theta ) \leq {\rm e}^{-(\sqrt{\theta q}-\sqrt{np})^2} \quad \text{ if $\theta \geq \frac{np}{q}$}.\end{cases}$ 
\item [\rm{ii.}] If $S \sim \Biexp(n,p;\lambda)$, then $\begin{cases}
\mathbb{P}( S \leq \theta ) \leq {\rm e}^{-(\sqrt{np}-\sqrt{\theta \lambda})^2} \quad \text{ if $\theta \leq \frac{np}{\lambda}$,}\\ \\
\mathbb{P}(  S  \geq \theta ) \leq {\rm e}^{-(\sqrt{\theta \lambda}-\sqrt{np})^2} \quad \text{ if $\theta \geq \frac{np}{\lambda}$}.\end{cases}$
\item[\rm{iii.}] If $S \sim \Poigeo(\mu;q)$, then $\begin{cases}
\mathbb{P}(S \leq \theta) \leq {\rm e}^{-(\sqrt{\mu}-\sqrt{\theta p})^2} \quad \text{ if $\theta \leq \frac{\mu}{p}$,} \\ \\ 
\mathbb{P}(S \geq \theta) \leq {\rm e}^{-(\sqrt{\mu}-\sqrt{\theta p})^2} \quad \text{ if $\theta \geq \frac{\mu}{p}$}.\end{cases}$
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:22:59.714258+00:00","domain":"probability theory","id":"claim_e878990abd4426c21a36cb547d6409f91477157604d4982c29cf8c453977288e","kind":"concept","schema_version":1,"statement":"[Lemma lem:saturation of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] Let $L \supseteq \textbf{FIK}$ and let $(\Gamma, \Delta)$ be a maximal $L$-consistent theory.
  \begin{enumerate}[label=(\arabic*)]
    \item $\varphi \in \Gamma$ if there is a finite $\Gamma_0 \subseteq \Gamma$ such that $L \vdash \bigwedge \Gamma_0 \to \varphi$.
    \item If $\varphi \lor \psi \in \Gamma$, then either $\varphi \in \Gamma$ or $\psi \in \Gamma$.
  \end{enumerate}
  \begin{proof}
    (1) Suppose towards a contradiction that there is such $\Gamma_0 \subseteq \Gamma$ but $\varphi \notin \Gamma$, then $\varphi \in \Delta$ by maximality, so $(\Gamma, \Delta)$ is $L$-inconsistent.
    (2) Suppose $\varphi \lor \psi \in \Gamma$, then $L \vdash (\varphi \lor \psi) \to (\varphi \lor \psi)$ implies either $\varphi \notin \Delta$ or $\psi \notin \Delta$ by $L$-consistency. By maximality, this means either $\varphi \in \Gamma$ or $\psi \in \Gamma$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:15:15.556417+00:00","domain":"probability theory","id":"claim_e87ce1def7b6a44c4c914b9e9c1fb60c4a2dcee9878ef49b3035f43e0b261b36","kind":"theorem","schema_version":1,"statement":"[Corollary AA-d of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \textbf{ }Let $n_{k}\rightarrow \infty $ be a subsequence such
that 
\begin{equation}
\sup_{x\in \lbrack 0,1]^{d}}|L_{n_{k}}(x)-L^{\ast }(x)|\rightarrow 0.

\end{equation}
Then, for each $i\in \{1,\ldots ,d\}$, 
\begin{equation}
\sup_{x\in \lbrack 0,1]}|L_{i}^{n_{k}}(x)-L_{i}^{\ast }(x)|\rightarrow 0,

\end{equation}
where 
\begin{equation}
L_{i}^{\ast }(x)=L^{\ast }(1,\ldots ,1,x,1,\ldots ,1).  
\end{equation}
If, in addition, $L_{i}^{\ast }$ is strictly increasing, then 
\begin{equation}
T_{i}^{n_{k}}=L_{i}^{n_{k},-1}\rightarrow T_{i}^{\ast }=L_{i}^{\ast ,-1}

\end{equation}
uniformly on $[0,1]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:35:57.130081+00:00","domain":"probability theory","id":"claim_e885eb6a42341a11efb81496b47dc4dc24a126f19465cf04849f10ea2a77874c","kind":"concept","schema_version":1,"statement":"[Corollary nonamentran of arXiv:2604.07227, 'Transition probabilities of step-reinforced random walks'] Suppose $G$ is a group generated by a finite symmetric set $\Gamma$ such that $G_{\Gamma}$ is nonamenable. \\
   (i) Let $S$ be an irreducible generalized SRRW on $G$ with parameter $\alpha \in [0,1)$ and step distribution $\mu$ whose support is $\Gamma$. Then, there exists a constant $\kappa=\kappa(G,\mu,\alpha) \in (0,1)$ such that 
    \begin{equation}

         \sup_{x\in G} \mathbb{P}(S_n=x) \leq \kappa^n, \quad \forall n\geq 1.
    \end{equation}
    In particular, $\liminf_n d(e_G,S_n)/n >0$ a.s. where $d(\cdot,\cdot)$ denotes the graph distance in $G_{\Gamma}$. \\
    (ii). Assume $G_{\Gamma}$ is the infinite d-regular tree $\mathbb{T}_d$ with $d\geq 3$. Let $S$ be an ERW on $G_{\Gamma}$ with memory parameter $p \in [0,1]$. Then for any $p \in [0,1)$ and $d\geq 3$, there exists a positive constant $\rho = \rho(G,p,d) \in (0,1)$ such that
    $$
\sup_{x\in G} \mathbb{P}(S_n=x) \leq \rho^n, \quad \forall n\geq 1.
    $$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

