         \,    [{\color{purp}g}]_{\mathcal{R}^{\gamma, \beta}}= [g^{\bullet}]_{\mathcal{C}^\gamma}+ [g^{\circ}]_{\mathcal{C}^\beta}+[\mathbb{g}^{\bullet \bullet}]_{\mathcal{C}^{2\gamma}_2}+[\mathbb{g}^{\circ  \bullet}]_{\mathcal{C}^{\gamma+ \beta}_2}+[\mathbb{g}^{\bullet \circ}]_{\mathcal{C}^{\gamma+ \beta}_2}.
