{"assumptions":[],"created_at":"2026-10-26T20:24:59.505887+00:00","domain":"probability theory","id":"claim_ea1e82d3ed9a580035998e336a863c2a9eeb57a5df6b006c75fc4eb72b34f40f","kind":"definition","schema_version":1,"statement":"[Definition 102 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\xi \in W$ be arbitrary. An $W$-valued continuous, adapted process $Y = (Y_t)_{t \in [0,T_0]}$ for some $T_0 \in (0,T]$ is called a \emph{local mild solution} to the SPDE \eqref{SPDE-Wiener} with $Y_0 = \xi$ if
\begin{align*}
Y_t = S_t \xi + \int_0^t S_{t-s} f_0(s,Y_s) ds + \int_0^t S_{t-s} f(s,Y_s) dX_s, \quad t \in [0,T_0].
\end{align*}
If we can choose $T_0 = T$, then we also call $Y$ a \emph{(global) solution} to the SPDE \eqref{SPDE-Wiener} with $Y_0 = \xi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.462655+00:00","domain":"probability theory","id":"claim_ea1e929a61acb2ed7de7ce248e50894d3e84008360dd54f64744419b016dad54","kind":"definition","schema_version":1,"statement":"[Defn 21 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] A pair $(u^h,\nu^h)$ is called a kinetic solution of \eqref{eq:skeleton-obstacle-problem} with initial data $u^0$ and obstacle $\psi$ if the following conditions hold.
\begin{enumerate}[label=\textbf{\arabic*}.]
  \item For every $p\geq1$, $u^h\in L^\infty(0,T;L^p(\mathbb T^N))$ and
\begin{align*}
\underset{0\leq t\leq T}{{\rm{ess\,sup}}}\ \Vert u^h(t)\Vert ^p_{L^p(\mathbb{T}^N)} \leq C(p,\Vert h\Vert_{L^2(0,T;U)},T,D_0),
\end{align*}
\item  We have 
\begin{equation*}
u^h(x,t)\geq\psi(x,t),\qquad\text{for } \dd x\otimes\dd t\text{-a.e. } (x,t),
\end{equation*}
and $\nu^h$ is a nonnegative finite Radon measure on $\mathbb{T}^N\times[0,T)$.
\item  The function $u^h$ satisfies the weak initial trace condition
\begin{equation*}
\lim_{\tau\downarrow0}\frac{1}{\tau}\int_0^\tau\Vert u^h(t)-u^0\Vert _{L^1(\mathbb{T}^N)}\dd t=0.
\end{equation*}
\item There exists a (deterministic) kinetic measure $q^h$ such that, with $f:= \one_{\{u^h>\xi\}}$ and $\mu^h:=\delta_{u^h}$, for all $\varphi\in C^1_c(\mathbb{T}^N\times [0,T)\times \mathbb{R})$,
\begin{align}\notag
&\int^T_0\langle f(t), \partial_t \varphi(t)\rangle \dd t+\langle f^0, \varphi(0)\rangle +\int^T_0\langle f(t), a(\xi)\cdot \nabla \varphi (t)\rangle \dd t\\
&= -\sum_{k\geq 1}\int^T_0\int_{\mathbb{T}^N} \int_{\mathbb{R}}g_k(x,\xi)\varphi (x,t,\xi)h_k(t)\dd \mu^h_{x,t}(\xi)\dd x\dd t \\
&\quad + q^h(\partial_{\xi} \varphi)-\int_0^T\int_{\mathbb{T}^N}\varphi(x,t,\psi(x,t))\dd\nu^h(x,t),\nonumber
\end{align}
 where  $\mu^h_{x,t}(\dd\xi)=\delta_{u^h(x,t)}(\dd\xi)$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.780421+00:00","domain":"probability theory","id":"claim_ea20b3afc61c3997543acd3226a5770944e614b0c25af7e52c969829ea53c65a","kind":"concept","schema_version":1,"statement":"[Thm smasympexUN of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] There is a universal constant $C>0$, and a compactly supported 
distribution $\mu_k$ for every $k\in\mathbb{Z}_+$, such that the following 
hold. Fix any $h\in C^\infty(\mathbb{R})$, and let
$f(\theta):= h(K\cos\theta)$. Then
$$
	\left| \mathbf{E}[\mathop{\textnormal{tr}} h(X^N)]- \sum_{k=0}^{m-1} \frac{\mu_k(h)}{N^k} 
	\right| \leq 
	\frac{(C\tilde q_0)^m}{u^mN^m}
	\|f^{(m'+1)}\|_{[0,2\pi]} 
