				Let $0 \le \rho_0 \in L^1 \cap H^{1-\frac{2}{q}}_q\left(\mathbb{T}^d\right)$, with $\Arrowvert \rho_0 \Arrowvert_{1}=1$. For each $\kappa>0$, there exists a $T>0$ depending on $\kappa,\lambda, q, C_K, L, M$ and $d$ such that if $\Arrowvert \rho_0 \Arrowvert_{q} = \kappa$,  the SPDE ((SPDE_Ito of the paper)) admits a unique nonnegative solution in
				\begin{align*}
					\mathbb{M} \doteq L_{\mathcal{F}^B}^q\left([0, T]; H_q^{1}\left(\mathbb{T}^d\right)\right) \cap S_{\mathcal{F}^B}^{\infty}\left([0, T] ; L^1 \cap L^q\left(\mathbb{T}^d\right)\right).
				\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:26.257881+00:00","domain":"probability theory","id":"claim_ea5bbdd148e4e6b665a90902de18ffc18a29537d13de183fb487b970f9b847ab","kind":"theorem","schema_version":1,"statement":"[Prp 70 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $f\in C_c^{+}(\R_{\ge 0})$ and set 
  \begin{align*}
    \omega(h):=\sup_{\substack{s,t\in [0,\sigma_f]\\|s-t|\le h}}|f(s)-f(t)|,\;h\ge 0,\qquad
  \omega^{-1}(r):=\sup\{h>0:\omega(h)<r\},\;r>0.
  \end{align*}
  \begin{itemize}
    \item [$\rm{(i)}$]For any $x\in T^f$ and $r>0$, we have
    \begin{align*}
      \omega^{-1}\left(\frac{r}{2}\right)\wedge\frac{\sigma_f}{2}\le m^f(B(x,r)).
    \end{align*}
    \item [$\rm{(ii)}$]For any $t\in [0,\sigma_f]$ and $r>0$, let $I(t,r)$ be the connected component of $\{s\in[0,\sigma_f]:f(s)>f(t)-r\}$ containing $t$.
    Suppose that there exists a function $V:[0,\infty)\to[0,\infty)$ such that
    \begin{align*}
      \rm{Leb}(I(t,r)\cap \{|f-f(t)|<r\})\le V(r),\qquad\forall t\in [0,\sigma_f],\;r>0,
    \end{align*}
where $\rm{Leb}$ is the one dimensional Lebesgue measure.
    Then it holds that 
    \begin{align*}
      m^f(B(x,r))\le V(r),\qquad \forall x\in T^f,\;r>0.
    \end{align*}
  \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.366971+00:00","domain":"probability theory","id":"claim_ea60b3ea3922e0611ac061a962ce489e724f51e11917ac8cc99ab93bbfaeef7f","kind":"concept","schema_version":1,"statement":"[Proposition p: uniform linear combination of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d, \infty], \varepsilon>0$. Suppose that $\Phi$ and $\Psi$ are locally absolutely square-integrable invariant random complex measures, which can be correlated, and let $a,b\in\C$. Assume that $\Phi$ and $\Psi$ are both (beyond) $p$-uniform (with radius $\varepsilon$). Then $a\Phi+b\Psi$ is also (beyond)\linebreak $p$-uniform (with radius $\varepsilon$).

    Further, if $\Phi$ is (beyond) $p$-uniform (with radius $\varepsilon$), $\Psi$ is not, and $b\neq 0$, then $a\Phi+b\Psi$ is not (beyond) $p$-uniform (with radius $\varepsilon$). In this case, if $p<\infty$, if either of the following limits exist, we have
        \begin{equation}
            \lim_{r\to\infty} \frac{\BV[(a\Phi+b\Psi)(f_r)]}{r^{d-p}} = \lim_{r\to\infty} b^2\frac{\BV[\Psi(f_r)]}{r^{d-p}},
        \end{equation}
        where $f$ is chosen as in Theorem~(t:asymptotic variance test function of the paper).
    \begin{proof}
        Let $p\in[-d, \infty)$, and suppose that $f\in\C_c^\infty(\R^d, [0,\infty))$ and $f\neq0$. Then, by the Cauchy-Schwarz inequality,
        \begin{align*}
            \Big(\sqrt{b\BV[\Psi(f_r)]} - \sqrt{a\BV[\Phi(f_r)]}\Big)^2 &\leq \BV[(a\Phi+b\Psi)(f_r)]\\ &\leq \Big(\sqrt{b\BV[\Psi(f_r)]} + \sqrt{a\BV[\Phi(f_r)]}\Big)^2
        \end{align*}
        for $r>0$. Now, the second inequality yields the first assertion, the first inequality yields the second assertion, and together they yield~(equation e:lin comb limit of the paper) with an application of Theorem~(t:asymptotic variance test function of the paper). For $p=\infty$, the assertions follow similarly from Theorem~(t: stealthy characterization of the paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:53:30.611992+00:00","domain":"probability theory","id":"claim_ea60d7450ff72c924bf660231f63556c3c270b291eae1bd22fce4c76971c45ba","kind":"concept","schema_version":1,"statement":"[Theorem thm-regular conditional expectation with parameters of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that    $(\mathbf{Z},\mathscr{B}_\mathbf{Z})$, $(\mathbf{X},\mathscr{B}_\mathbf{X})$ and $(\mathbf{Y},\mathscr{B}_\mathbf{Y})$ are three  measurable spaces.
Assume further that   $(\mathbf{Z},\mathscr{B}_\mathbf{Z})$ is a standard  measurable space and that $m$ is a non-negative measure on it. \\
Assume that a map
\begin{align*}
\theta\colon & \mathbf{Y} \times \mathbf{Z} \to \mathbf{X}
\end{align*}
is $\mathscr{B}_\mathbf{Y}\otimes \mathscr{B}_\mathbf{Z}/\mathscr{B}_\mathbf{X}$-measurable. For each  $y\in \mathbf{Y}$ let us put \footnote{Let us observe that $\theta_y$ is $ \mathscr{B}_\mathbf{Z}/\mathscr{B}_\mathbf{X}$-measurable.} $\theta_y\coloneqq\theta(y,\cdot)\colon \mathbf{Z} \to \mathbf{X}$ and let us assume that  $q(y,\cdot)$ is equal to the image of the measure $m$ via $\theta_y$:
\begin{equation}

q(y,B) = m (\theta_y^{-1}(B)), \;\; B \in \mathbf{X}.
\end{equation}
We finally assume that for every $B \in \mathbf{X}$ the map
\begin{align}
   \mathbf{Y}  \ni y \mapsto q(y,B) \in [0,\infty]
\end{align}
is $\mathscr{B}_\mathbf{Y}$-measurable.

Then, there exists a function
\begin{align*}
Q\colon & \mathbf{Y} \times \mathbf{X} \times \mathscr{B}_{\mathbf{Z}} \to [0,\infty]
\end{align*}
such that the following three conditions are satisfied.
\begin{trivlist}
\item[(i)] for all $y \in \mathbf{Y}$ and $x \in \mathbf{X}$, the map
\begin{align*}
Q(y,x,\cdot)\colon & \mathscr{B}_Z \to [0,\infty]
\end{align*}
is a measure;
 \item[(ii)] for every $A\in \mathscr{B}_{\mathbf{Z}}$ the map
\begin{align*}
Q(\cdot,\cdot,A)\colon & \mathbf{Y} \times \mathbf{X}  \to [0,\infty]
\end{align*}
 is $\mathscr{B}_{\mathbf{x}} \otimes \mathscr{B}_{\mathbf{Y}}$-measurable,
 \item[(iii)] for all $y \in \mathbf{Y}$, $A\in \mathscr{B}_{\mathbf{Z}}$ and $B\in \mathscr{B}_{\mathbf{X}}$, the following equality holds:
\begin{align}
m (A \cap \theta_y^{-1}(B))
=\int_{\mathbf{X}}  \1_{B}(x) Q(y,x,A)\, q(y,\mathrm{d} x).
\end{align}
\end{trivlist} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

