{"assumptions":[],"created_at":"2026-10-26T19:29:52.228711+00:00","domain":"probability theory","id":"claim_ea89d346662372d45d0edebc6aa875e5d1fd10805cb05445c5f055e07f4fbaea","kind":"lemma","schema_version":1,"statement":"[Lemma 26 (Negligibility of the integrals along $S_{x,\alpha}^\pm$ and $S_{y,\alpha}^\pm$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $z_0 \in \R^2$. For $(a,b) \in \R \times (0,+\infty)$, let $\alpha(a,b) \in (0,\pi)$ be the angle such that $\cos (\alpha) = \frac{ a }{ \sqrt{a^2+b^2}}$ and $\sin(\alpha) = \frac{ b }{\sqrt{a^2+ b^2}}$.
\begin{itemize}
\item Suppose $\alpha_0 \in (0, \pi)$. Then, for $\eta > 0$ small enough, there exist $r_0 > 0$ and $D > 0$ such that for all $(a,b)$ satisfying $\sqrt{a^2+b^2} > r_0$ and $|\alpha(a,b) - \alpha_0| < \eta$, we have:
\begin{equation}

\left| \int\limits_{S^{+}_{x, \alpha}} \phi^{z_0}(x)\frac{\gamma(x,Y^+(x),Z^+(x))}{\partial_y\gamma_+(x,Y^+(x))} e^{-ax - bY^+(x)} \, dx \right| \leq \frac{D}{b} e^{-a x(\alpha) - b y(\alpha) - \epsilon^2 \sqrt{a^2+b^2}}.
\end{equation}
If $b > b_0$, then the following estimate also holds:
\begin{equation}

\left| \int\limits_{S^{+}_{x, \alpha}}  
\frac{e^{(a_0-a)x} \left(
e^{(b_0-b)Y^+(x)}\fc_{b_0>0} 
+ e^{b_0Z^+(x) - bY^+(x)}\fc_{b_0 < 0}
\right)}{\partial_y\gamma_+(x,Y^+(x))} \, dx \right| \leq  
  \frac{D}{b - b_0} e^{-a x(\alpha) - b y(\alpha) - \epsilon^2 \sqrt{a^2 + (b - b_0)^2}}.
\end{equation}  

\item Suppose ${\M} = x^{+}_{\max}$ and let $\alpha_0 = 0$. Then, for $\eta > 0$ small enough, there exist $r_0 > 0$ and $D > 0$ such that for all $(a,b)$ satisfying $\sqrt{a^2 + b^2} > r_0$ and $0 < \alpha(a,b) \leq \eta$, we have:
\begin{equation}

\left| \int\limits_{S^{+}_{x, \alpha}} \phi^{z_0}(x) \frac{\gamma(x,Y^+(x),Z^+(x))}{\partial_y\gamma_+(x,Y^+(x))} e^{-ax - bY^+(x)} \, dx \right| \leq D e^{-a x(\alpha) - b y(\alpha) - \epsilon^2 \sqrt{a^2 + b^2}},
\end{equation}

\begin{equation}

\left| \int\limits_{S^{+}_{y, \alpha}}
\frac{e^{(a_0 - a)X^+(y) + (b_0 - b)y}}{\partial_x\gamma_+(X^+(y),y)} \, dy \right| \leq \frac{D}{a} e^{-a x(\alpha) - b y(\alpha) - \epsilon^2 \sqrt{a^2 + b^2}}.
\end{equation}

\item Symmetric estimates hold for $\alpha_0 = \pi$ when ${\m} = x^{+}_{\min}$.
\end{itemize}
The same estimates hold for $S^{-}_{x, \alpha}$ and $S^{-}_{y, \alpha}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.720554+00:00","domain":"probability theory","id":"claim_ea8a56ece2756653c102bb9b952fd13349877b6c30a6a038128970096e7e9cfe","kind":"concept","schema_version":1,"statement":"[Thm tailsmat of arXiv:2605.31054, 'On the empirical spectral distribution of matrix perpetuities'] Assume that $N\geq 2$ and
    \begin{enumerate}
    \item[(i)] ${\mathbf A},{\mathbf B}\in\mathrm{Sym}_{\geq0}(N)$ a.s.,
        \item[(ii)] $({\mathbf u}{\mathbf A} {\mathbf u}^\top, {\mathbf u} {\mathbf B} {\mathbf u}^\top)\stackrel{d}{=}({\mathbf A},{\mathbf B})$ for any orthogonal matrix ${\mathbf u}$,
        \item[(iii)] there exists $\eta>0$ such that 
        \begin{enumerate}
            \item ${\mathbb E}[{\mathbf A}_{11}^\eta]=1$,
             \item ${\mathbb E}[{\mathbf A}_{11}^\eta \log^+({\mathbf A}_{11})]<\infty$,
             \item ${\mathbb E}[{\mathbf B}_{11}^\eta]<\infty$,
             \item ${\mathbb E}[ \det( {\mathbf A}^{[2]})^{\eta/2}]<1$,
        \end{enumerate}
        \item[(iv)] the conditional law of $\log {\mathbf A}_{11}$ given $\{{\mathbf A}_{11}\neq 0\}$ is non-arithmetic,
        \item[(v)] ${\mathbb P}({\mathbf A}_{11}x+{\mathbf B}_{11}=x)<1$ for $x\in{\mathbb R}$.
    \end{enumerate}
   Then, there exists a unique solution ${\mathbf X}$ to
\begin{align}
{\mathbf X}\stackrel{d}{=}{\mathbf A}^{1/2} {\mathbf X} {\mathbf A}^{1/2} +{\mathbf B},\qquad ({\mathbf A},{\mathbf B})\mbox{ and }{\mathbf X}\mbox{ are independent},
\end{align} 
which satisfies 
\[
\mu_{\mathbf X}\big( (t,\infty)\big) \sim \frac{1}{N}{\mathbb P}(\lambda_{\max}({\mathbf X}) > t) \sim \frac1N \frac{\sqrt{\pi}\, \Gamma\left(\eta+\dfrac{N}{2}\right)}{\Gamma\left(\dfrac{N}{2}\right)\, \Gamma\left(\eta+\tfrac12\right)} {\mathbb P}({\mathbf X}_{11}>t)
\]
and
    \begin{align}
\lim_{t\to+\infty} t^\eta\, {\mathbb P}({\mathbf X}_{11}>t) = \frac{ {\mathbb E}\left[ ({\mathbf A}_{11}{\mathbf X}_{11}+{\mathbf B}_{11})^\eta - ({\mathbf A}_{11}{\mathbf X}_{11})^\eta \right]}{\eta \,{\mathbb E}[{\mathbf A}_{11}^\eta \log{\mathbf A}_{11} ]}\in(0,+\infty).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:11:11.699040+00:00","domain":"probability theory","id":"claim_ea8aa9a96ee04ba34ba7d05aa2e0f72cd1ac170510d55d1c6733b61cc8896ed3","kind":"lemma","schema_version":1,"statement":"[Lemma lem:pairvectors of arXiv:2609.00668, 'Rigidity of Euclidean Minimal Hypersurfaces under Nonuniform Diagonal Dilations'] Along $\Sigma$, every $V_{ij}$ is tangent and
\begin{equation}
C_{ij}[F]=\operatorname{Hess}F(V_{ij},V_{ij})=|\nabla F|\,II(V_{ij},V_{ij}),
\end{equation}
