(-1)^{\mathds 1[\mathbf p^0(x)<\mathbf p^0(x-)]}\mathbf I_0(y-x;\mathbf H(x)-\mathbf H(y)) , & (x,y) \in \Xi_3, \\
(-1)^{\mathds 1[\mathbf p^0(x)<\mathbf p^0(x-)]} \mathbf I(y-x;\mathbf H(x)-\mathbf p^0(x), \mathbf H(y)-\mathbf p^0(y_-) ), & (x,y) \in \Xi_4.
