Furthermore, in the case $\alpha \in (-1,0)$, there exists $C>0$ such that for every $t>0$,
\begin{equation}
|\dot{C}^M_t(x,y)| \leq C \frac{\langle t\rangle ^{\alpha-1} \log\left( 1 + \frac{|x-y|^2}{(x_1-y_1)^2} \right)}{|x-y|^{1-\alpha}}, \qquad \forall x,y\in M.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.368024+00:00","domain":"probability theory","id":"claim_eb658b70a6ddfd1c802ace2ca8275ee278e838861723480f974819c056247359","kind":"theorem","schema_version":1,"statement":"[Proposition 6 of arXiv:2606.03122, 'Propagation of support for super-Brownian motion with general branching mechanism'] Suppose that $\Psi$ satisfies Condition \ref{con_localize}. Then for any $0<R_1<R$, we have
\begin{align}
u_\theta^\Psi(x,t)\leq u_{R,\Phi_R}(R_1)P_x(\sigma_{R_1}<t),\quad \forall x\in B(0,R_1),\ t>0,
\end{align}
where $P_x$ denotes the law of a $d$-dimensional Brownian motion $W$ starting from $x$ and $\sigma_{R_1}:=\inf\{s>0:|W_s|=R_1\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:49:17.499074+00:00","domain":"probability theory","id":"claim_eb667ff3a50d9781ca8692a57c56e3356de5cf54b5d82e93d502b3945c309241","kind":"concept","schema_version":1,"statement":"[Corollary 7 (\cite{Gross1975document}, Theorem 3 and \cite{Diaconis1996}, Example 3.2) of arXiv:2605.29608, '2605.29608'] Let $(Y_{k})_{k\in\mathbb{Z}^{+}}$ and $\mu_{N}$ be defined as in Theorem \ref{thm: transitionmatrix}. At infinite temperature (i.e., $\hat{J}=0$), the Wolff dynamics reduces to the simple random walk on the hypercube $\Omega=\{-1,+1\}^{N}$, where at each step a single spin is chosen uniformly at random and flipped. Applying Theorem~\ref{thm:logsobolev} to the Markov chain with transition probability~\eqref{eq:transition0}, the log-Sobolev inequality
	\begin{align} 
		E_{\mu_{N}}[f^{2}\log f^{2}]-E_{\mu_{N}}[f^{2}]\log E_{\mu_{N}}[f^{2}]\leq&N	\mathcal{E}^{\text{W},0}_{\mu_{N}}(f),
	\end{align}
	holds for all functions $f:\Omega\to\mathbb{R}$, where
	\begin{align*}	
		\mathcal{E}^{\text{W},0}_{\mu_{N}}(f):=\frac{1}{2N}\sum_{i=1}^{N}E_{\mu_{N}}\big[(f(\sigma)-f(\sigma^{i}))^{2}\big]=\frac{1}{2N}\sum_{i=1}^{N}(f(\sigma)-f(\sigma^{i}))^{2}\frac{1}{2^{N}}.
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:53:54.854975+00:00","domain":"probability theory","id":"claim_eb6ff359dad802ad751dacb0b47e1f0aa5cfe0ff5fe3bbb69ae938a92fec6658","kind":"concept","schema_version":1,"statement":"[Lemma 5 of arXiv:2607.16954, 'Repeated differentiation of deterministic polynomials with asymptotically radial root dist'] The coefficients of $\pp$ and $\qq$ as defined in Notation \ref{not:setting.derivatives} are related as follows.
\begin{equation}

\coef{k}{\qq}=\falling{mn-mk}{ml}\, \coef{k}{\pp},\qquad \text{for } 0\leq k\leq n.    
\end{equation}
Furthermore, the ratio of consecutive coefficients satisfies
\begin{equation}

\frac{\coef{k}{\qq}}{\coef{k-1}{\qq}}=\frac{\coef{k}{\pp}}{\coef{k-1}{\pp}} \prod_{i=1}^{m} \frac{ n-k-l+\frac{i}{m}}{n-k+\frac{i}{m}},\qquad \text{for } 1\leq k\leq n-c_\qq,
\end{equation}
where $c_\qq$ is the multiplicity of the root 0 of $\qq$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:35:04.211570+00:00","domain":"probability theory","id":"claim_eb7392366f569741fe303aee40f61b09a501e2afa1e80edee15a220b91704eec","kind":"lemma","schema_version":1,"statement":"[Lem 1 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Define an infinite sub-triangular array $\tau$ by
\begin{align}
\tau_{n,j} \triangleq \T_{n + 3, j + 3} \notag
\end{align}
for every $n \geq 0$ and $1 \leq j \leq n +1$. Then, $\tau_{n,*}$ is a strictly-positive log-concave sequence for every $n\geq 2$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.161074+00:00","domain":"probability theory","id":"claim_eb77ed06c304c789bc606ef524f4ed05d1b3e358162871c607f01921a7aa7bff","kind":"definition","schema_version":1,"statement":"[Definition Def_SmoothingOperatorProperty of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] A graded Fréchet space $\paren{F,\paren{\Abs{-}_k}_{k \in {\mathbf{N}}_0}}$ is \defined{tame} if it has the \defined{smoothing operator property};

  that is:
  there is a family of smoothing operators $\paren{ S_\varepsilon : \varepsilon \in (0,1) }$ on $F$ such that:
  \begin{enumerate}[label=\rm{(S\arabic*)},ref=S\arabic*]
  \item

    For every $\varepsilon \in (0,1)$, $k,\ell \in {\mathbf{N}}_0$ with $k \geqslant \ell$, and $x \in F$
    \begin{equation*}
      \Abs{S_\varepsilon x}_k \lesssim \varepsilon^{\ell-k}\Abs{x}_\ell.
    \end{equation*}
  \item

    For every $\varepsilon \in (0,1)$, $k,\ell \in {\mathbf{N}}_0$ with $k \leqslant \ell$, and $x \in F$
    \begin{equation*}
      \Abs{\paren{S_\varepsilon-\mathbf{1}} x}_k \lesssim \varepsilon^{\ell-k}\Abs{x}_\ell.
    \end{equation*}
  \item

    For every $\varepsilon \in (0,1)$, $k,\ell \in {\mathbf{N}}_0$, and $x \in F$
    \begin{equation*}
      \varepsilon\Abs{\partial_\varepsilon S_\varepsilon x}_k \lesssim \varepsilon^{\ell-k}\Abs{x}_\ell.
      \qedhere
    \end{equation*}
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.243519+00:00","domain":"probability theory","id":"claim_eb787a30f3c534d7d6517c9635a8c22a39ee6a8e6e6e63528a029e458b7a3f51","kind":"theorem","schema_version":1,"statement":"[Theorem thm:phi of arXiv:2604.23791, 'Finite-sample Borel--Cantelli inequalities under mixing conditions'] Let $N\ge1$ and let $(A_{k})_{1\le k\le N}$ be events, with
$\varphi(\cdot)$ fixed by one coefficient convention of
Section~(sec:prelim of the paper). For each integer $L\ge0$,
\begin{equation}
  \mathbb{P}\Bigl(\,\bigcup_{k=1}^{N}A_{k}\,\Bigr)
  \;\ge\; 1-\exp\!\Biggl(-\frac{1}{L+1}
  \sum_{k=1}^{N}\bigl(\mathbb{P}(A_{k})-\varphi(L+1)\bigr)_{+}\Biggr).
\end{equation}
In particular, if $\varphi(L+1)\le\min_{1\le k\le N}\mathbb{P}(A_{k})$,
\begin{equation}
  \mathbb{P}\Bigl(\,\bigcup_{k=1}^{N}A_{k}\,\Bigr)
  \;\ge\; 1-\exp\!\Bigl(-\tfrac{1}{L+1}\bigl(S_{N}-N\varphi(L+1)\bigr)\Bigr).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:31:49.906180+00:00","domain":"probability theory","id":"claim_eb7e757be31dcad0095380976b91fb22ebba367f8b23441eeb0d3ec27f4d1897","kind":"theorem","schema_version":1,"statement":"[Theorem thm:flat-diagonal of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] Let $Q$ be a real symmetric positive-semidefinite $N\times N$ matrix and set $T=\operatorname{tr} Q>0.$ Suppose that, for some $r\geq1$,
\begin{equation}
 \max_{1\leq i\leq N}q_{ii}\leq\frac{T}{r}.
\end{equation}
Let $\varepsilon\in\{-1,1\}^N$ be a uniform sign vector.
There exist absolute constants $C,c>0$ such that, for every $D\geq2$ and $H\geq1$,
\begin{equation}
 \mathbb{E}\min\!\left\{
   \log_{+}\frac{T}{\varepsilon^{\mathsf T}Q\varepsilon},H
 \right\}
 \leq
 C+CH\left(
   \frac{D^{7/4}}{\sqrt r}+e^{-cD}
 \right).
\end{equation}
