\overline{\sigma}({\bf 1}_{\{\tau_{k+1}  < T+1\}}) \leq
\left(\frac{a-c}{b-c} \right)^{k+1} ~\overline{\sigma}({\bf 1}_{\{\rho_{0}  < T+1\}}) \leq
\left(\frac{a-c}{b-c}\right)^{k+1}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.094777+00:00","domain":"probability theory","id":"claim_ec0529c630045e8751460bfeb892e2a28d690b709c777d501867ddf0d4912dce","kind":"lemma","schema_version":1,"statement":"[Lemma lem:app-distance-stability of arXiv:2609.02710, 'Asymptotic Mean Value Laplacian\\ on equiregular sub-Riemannian manifolds'] Let $C,C' \subset \mathbb{R}^n$ be compact sets such that
$0\in C\subset\operatorname{int}C'\Subset U_0$.  Suppose $Y^\lambda$ is
jointly smooth and uniformly two-generating on $\overline{U_1}$, and that
for some $R<\infty$ and every $\lambda\in\Theta$,
\begin{equation}
 d_{Y^\lambda}(0,q)\le R\quad(q\in C'),
 \qquad
 \gamma_{0,u}^\lambda([0,1])\subset U_0
 \quad\text{if }\|u\|_{L^2}\le R+1.
\end{equation}
Then there is $L$ such that
\begin{equation}
  |d_{Y^\lambda}(0,q)^2-d_{Y^\lambda}(0,q')^2|
  \le L|q-q'|
\end{equation}
for all $q,q'\in C$ and $\lambda\in\Theta$.
Moreover, if $Z^\lambda$ is a second family with the same properties and the same
bound $R$, then there are $\varepsilon_0,L'>0$ such that
\begin{equation}
  \sup_{q\in C}
  |d_{Y^\lambda}(0,q)^2-d_{Z^\lambda}(0,q)^2|
  \le L'\max_i\|Y_i^\lambda-Z_i^\lambda\|_{C^1(\overline{U_1})}
\end{equation}
whenever the norm on the right is at most $\varepsilon_0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.044796+00:00","domain":"probability theory","id":"claim_ec071ba98ea0bf443ed14bfff671ad0bf4e2eb1a4c5ee395adc3f1f6448f8739","kind":"definition","schema_version":1,"statement":"[Definition 89 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] We say that $X$ is a {\em regular
diffusion process 
\index{$D$@Processes!regular
diffusion process}
corresponding to
$\cL$ or to $a,b$\/} if



(i)  for any $(t,x)\in\bR^{d+1}$
there exists a $d$-dimensional Wiener process $w_{t}$, $t\geq0$,
which is a Wiener process relative to $\bar \cN_{t}$,
where $\bar \cN_{t}$ is the completion of $\cN_{t}$
with respect to all $P_{s,y}$, and such that with    
$P_{t,x}$-probability one, for
all $s\geq 0$, $\sft_{s}=t+s$ and
\begin{equation} 

x_{s}=x+\int_{0}^{s}\sigma(t+u,x_{u})\,dw_{u}
+\int_{0}^{s}b(t+u,x_{u})\,du.
\end{equation}

(ii) there exists $\rho_{b}\in(0,\infty)$ such that
\begin{equation}

  \bar b_{\rho_{b}}=\sup_{r\leq\rho_{b}}r^{-1}
\sup_{(t,x)\in\bR^{d+1}}\sup_{C\in\bC_{r}}
E_{t,x}\int_{0}^{\tau_{C}}|b(\sft_{s},x_{s})|\,ds \leq \sfb_{0},
\end{equation}
where $\tau_{C}$ is the first exit time of 
$(\sft_{s},x_{s})$ from $C$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:00.617392+00:00","domain":"probability theory","id":"claim_ec0812c71c02774141da0a5c8d393a148d7a11a4a442a827af1820a23ba4d927","kind":"lemma","schema_version":1,"statement":"[Lemma 62 ({\cite[Lemma 3.4) of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] {Dau23}}]

Fix $\delta>0$. For every $k\in \NN$, there exists a $C_k,c_k$ such that for all $s\in (-n^{1/3}/4,n^{1/3}/4)$, $r\in (0,n^{1/3})$ and $a$ satisfying $n^{2/3}/4>a>c_kr^2$, we have
  \begin{equation}

