{"assumptions":[],"created_at":"2026-10-28T02:56:14.331934+00:00","domain":"probability theory","id":"claim_ec2a2eb4bdf3a69b9c68ab04fcb3ab118ab876b7414f299b0b078465a23dcf3c","kind":"definition","schema_version":1,"statement":"[Defi def:Markovinified of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Let us consider an interval $T \subset \mathbb{R}$, $d \geq 1$  and a measure $P \in \mathcal{P}( (\mathbb{R}^d )^T )$.
		\begin{enumerate}
			\item We say that $P$ admits a weak local Markov transform if there exists a Markov measure $P'$ such that \[\forall s<t \in T^2, \exists (R_n)_{n \geq 1} \in {\left(\mathcal{S}_{[s,t]} \right)}^{\mathbb{N}^*}, \accol{\lim_{n \to +\infty} P_{\{R_n\}}^{s,t} = P'^{s,t} \\  \lim_{n \to + \infty} \sigma_{R_n} = 0}.\] In this case, we say that $P'$ is a weak local Markov transform of $P.$
			\item We say that $P$ admits a strong local Markov transform if there exists a Markov measure $P'$ such that   \[ \forall s<t \in T^2, \forall (R_n)_{n \geq 1} \in {\left(\mathcal{S}_{[s,t]} \right)}^{\mathbb{N}^*} :  \lim_{n \to +\infty} \sigma_{R_n} = 0 \implies \lim_{n \to + \infty} P_{\{R_n\}}^{s,t} = P'^{s,t}.\] In this case, we say that $P'$ is a strong Markov transform of $P.$
			\item Given two $\mathbb{R}^d$-valued stochastic processes $(X_t)_{t \in T}$ and $(Y_t)_{t \in T}$, we say that $(Y_t)_{t \in T}$ is a weak (resp. strong) local Markov transform of $(X_t)_{t \in T}$ if the law of $(Y_t)_{t \in T}$ is a weak (resp. strong) Markov transform of the law of $(X_t)_{t \in T}.$
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.422837+00:00","domain":"probability theory","id":"claim_ec2a39cf4671e8b351d691aff7a7df542401ee9c94b1cf159891fe628cf95812","kind":"concept","schema_version":1,"statement":"[Theorem eq:array-assumptions of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:bulk-universality}
Fix \(p\ge3\), \(m\ge2\), \(L>0\), \(\varepsilon>0\),
\(V\in\mathcal V_m\), and either \(f\in\mathcal F_m\) or
\(f=\ell_\eta\) for fixed \(\eta>0\).  For each \(N\), let
\(J=(J_{I,N})_{I\in[N]^p}\) have independent, not necessarily
identically distributed coordinates satisfying
\begin{equation}
 \sup_{N,I}\mathbb E e^{\abs{J_{I,N}}/K}\le2,
 \qquad
 \mathbb E J_{I,N}^r=\mathbb E G^r,\quad 1\le r\le m,
\end{equation}
where \(G\sim\mathcal N(0,1)\).  Let \((G_I)\) be independent standard Gaussians.  Then there is a constant
\[
 C=C(p,m,L,K,\varepsilon,V,f)<\infty
\]
such that, for all sufficiently large \(N\),
\begin{equation}
 \left|\log\frac{\mathbb E\mathcal Z_{N,L}^J(V,\varepsilon,f)}
 {\mathbb E\mathcal Z_{N,L}^G(V,\varepsilon,f)}\right|
 \le C Nq_N^{m-1}.
\end{equation}
Consequently, for every \(p\ge3\) and every \(m\ge2\),
\begin{equation}
 \Phi_{N,L}^J(V,\varepsilon,f)-\Phi_{N,L}^G(V,\varepsilon,f)\longrightarrow0.
\end{equation}
Assume additionally that
\begin{equation}
 (m-1)(p-2)>2.
\end{equation}
Then
\begin{equation}
 \frac{\mathbb E\mathcal Z_{N,L}^J(V,\varepsilon,f)}
 {\mathbb E\mathcal Z_{N,L}^G(V,\varepsilon,f)}\longrightarrow1,
\end{equation}
and
\begin{equation}
 \Phi_{N,L}^J(V,\varepsilon,f)-\Phi_{N,L}^G(V,\varepsilon,f)=o(N^{-1}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:24:45.940770+00:00","domain":"probability theory","id":"claim_ec2a50cca2b65bb53aa4463e22835c797f04e7b01a5a9d5ef327093b05b3b01d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:exponential_moment of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Let $Y_0^m = \mu+m\delta_{x_0}$, where $\mu \in \mathcal{M}_F^+$, $x_0 \in\mathbb{R}$ and $m \in \mathbb{N} \cup \{ \infty\}$. Let $Y(\nu)$ be the process constructed above with measure $\nu$. Then, for every $\gamma \in \mathbb{R}$ and $K>0$, there exists $T_0>0$ such that for all $t\leq T_0$ we have 
