	Hereby, $T_0>0$ and $C>0$ depend only on $\langle \mu,1\rangle$, $K$ and $\gamma$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:52:32.333609+00:00","domain":"probability theory","id":"claim_ec2e4b849037a6390f19c27c15ba96da87b5db06cdacf4810c148b6ccec0783f","kind":"concept","schema_version":1,"statement":"[Proposition prop:patching of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] Let $(\Omega,\Omega_w,\Omega_h)$ be a Lipschitz interface triple with interface $\gamma$. Let $\pi\in L^2(\Omega)$ be a patching of $w,h$, i.e., $\pi|_{\Omega_w} = w, \pi|_{\Omega_h }=h$.
    \begin{enumerate}
        \item Assume $w\in H^1(\Omega_w), h\in H^1(\Omega_h)$, then $w,h$ have matching trace $${\operatorname{tr}}^{\gamma}(w) ={\operatorname{tr}}^{\gamma}(h)$$ if and only if $\pi$ is an element of $ H^1(\Omega)$.
        \item Assume $w\in H^{\operatorname{div}}(\Omega_w), h\in H^{\operatorname{div}}(\Omega_h)$, then $w,h$ have matching normal trace $${\operatorname{tr}}^{\gamma}_N(w) = -{\operatorname{tr}}^{\gamma}_N(h)$$ if and only if $\pi$ is an element of $ H^{\operatorname{div}}(\Omega)$.

        \item Assume $w\in H^\Delta(\Omega_w)$, $h\in H^\Delta(\Omega_h)$, then $w,h$ have matching boundary trace and normal derivative, i.e., $${\operatorname{tr}}^{\gamma}(w) ={\operatorname{tr}}^{\gamma}(h)~~\textnormal{and} ~~ {\operatorname{tr}}^{\gamma}_N(\nabla w) = -{\operatorname{tr}}^{\gamma}_N(\nabla h),$$ if and only if $\pi$ is an element of $ H^\Delta(\Omega)$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.924496+00:00","domain":"probability theory","id":"claim_ec2f3ea82bf4f8198bf335da9d9d5cf237900575b076e1a1b95f1e1390906b17","kind":"concept","schema_version":1,"statement":"[Lemma lemma_revise_2.3 of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] {cai2024high}}]
