{"assumptions":[],"created_at":"2026-10-26T20:58:53.188371+00:00","domain":"probability theory","id":"claim_ec32499cfa9c08f405404a5bc8782797e1168a197257731c394bd90deeef7e8c","kind":"concept","schema_version":1,"statement":"[Lemma 2 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] Let $0 \leq b \leq a$, $q \geq 0$ and $0 < \lambda < \infty$. Then the following identities hold:
			\begin{enumerate}
				\item[\upshape{(i)}] For $ x \in [b,a]$ and $ y \in [b,\infty)$,
				\begin{equation}
					\E_x\Bigl( \int^\infty_0 e^{-q t} \1_{\{Y_t \in \dd y, \; t < T_{a,Y}^{+,\lambda} \wedge \tau_{b,Y}^- \}} \dd t \Bigr) = \Bigl( \frac{\W^{(q)}(x-b)}{\Z^{(q)}(a-b, \varphi_{q+\lambda})} \Z^{(q)}(a-y, \varphi_{q+\lambda}) - \W^{(q)}(x-y)\Bigr) \dd y, 
				\end{equation}
				and, consequently, for $ y \in (a,\infty)$,	
				\begin{equation}
					\E_x\bigl( \ee^{-q T_{a,Y}^{+,\lambda}} \1_{\{Y_{T_{a,Y}^{+,\lambda}} \in \dd y, \; T_{a,Y}^{+,\lambda} < \tau_{b,Y}^-\}} \bigr) = \lambda \frac{\W^{(q)}(x-b)}{\Z^{(q)}(a-b,\varphi_{q+\lambda})} \ee^{\varphi_{q+\lambda}(a-y)} \dd y.  
				\end{equation}

				\item [\upshape{(ii)}] For $ x,y \in [b,\infty)$,	
				\begin{equation}
					\E_x \Bigl( \int^\infty_0 \ee^{-q t} \1_{\{Y_t \in \dd y, \; t < T_{a,Y}^{-,\lambda} \wedge \tau_{b,Y}^- \}} \dd t \Bigr) = \Bigl(\frac{\Z^{(q+\lambda)}(a-y, \varphi_{q})}{\Z^{(q+\lambda)}(a-b, \varphi_{q})} \W^{(q+\lambda)}(x-b) - \W^{(q+\lambda)}(x-y) \Bigr) \dd y, 
				\end{equation}
				and consequently, for $y \in (b,a)$,
				\begin{equation}
					\E_x \Bigl( \ee^{-q T_{a,Y}^{-,\lambda}} \1_{\{Y_{T_{a,Y}^{-,\lambda}} \in \dd y,\; T_{a,Y}^{-,\lambda} < \tau_{b,Y}^- \}} \Bigr) = \lambda \Bigl(\frac{\Z^{(q+\lambda)}(a-y, \varphi_{q})}{\Z^{(q+\lambda)}(a-b, \varphi_{q})} \W^{(q+\lambda)}(x-b) - \W^{(q+\lambda)}(x-y) \Bigr) \dd y. 
