{"assumptions":[],"created_at":"2026-10-27T21:59:24.050890+00:00","domain":"probability theory","id":"claim_ec3617b789f335e9d72b66549d5ba5ddd6f9860daf60dfacc1d6ddea432d3a58","kind":"theorem","schema_version":1,"statement":"[Proposition prop:coordinate-crossing of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] For $N\ge3$, the first three Ritz levels are
\begin{equation}
 \Lambda_1(N)=2N,
 \qquad
 \Lambda_2(N)=3N-\sqrt{N^2+8N-8}.
\end{equation}
Set
\begin{equation}
 R_N:=\sqrt{N^2+11N-20},
 \qquad
 \phi_N:=\frac13\arccos\!\left(
 \frac{3\sqrt3\,N(7N-16)}{2R_N^3}\right).
\end{equation}
Then
\begin{equation}
 \Lambda_3(N)
 =4N+\frac{4R_N}{\sqrt3}
 \cos\!\left(\phi_N+\frac{2\pi}{3}\right).
\end{equation}
Equivalently, $\Lambda_3(N)$ is the smallest zero of
\begin{equation}
 \lambda^3-12N\lambda^2
 +(44N^2-44N+80)\lambda
 -48N^3+120N^2-192N=0.
\end{equation}
Moreover,
\begin{equation}
 \Lambda_2(N)<2N\qquad(N\ge3),
\end{equation}
and the first crossings of the continuum coefficient along this ladder are
\begin{align}
 \Lambda_1(N)&<A_N &&(N\ge12),\\
 \Lambda_2(10)&>A_{10},\qquad
 \Lambda_2(N)<A_N &&(N\ge11),\\
 \Lambda_3(10)&<A_{10}.
\end{align}
Consequently,
\begin{equation}
 C(N)\le\Lambda_2(N)<\min\{A_N,2N\}
 \qquad(N\ge11),
\end{equation}
and $C(10)<A_{10}$ follows from the third level.  Finally,
\begin{equation}
 \Lambda_3(N)
 =2N-4-\frac6N+\frac{51}{N^2}+O(N^{-3})
 \qquad(N\to\infty).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.591723+00:00","domain":"probability theory","id":"claim_ec3ff9b22bf81b42376eb3bba2ad6ff1f3653e8c7faaed0153bacd8729ec4cfe","kind":"concept","schema_version":1,"statement":"[Prop pro:colour_position_symmetry of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Let $\textup{id}:\mathbb{Z} \to \mathbb{Z}$ be the identity bijection and denote by $\textup{inv}$ the map that takes the inverse of a permutation. Then, for any $k \in \mathbb{N}$ and integers $z_1, \dots, z_k \in \mathbb{Z}$, it holds 
