{"assumptions":[],"created_at":"2026-10-27T15:07:17.265101+00:00","domain":"probability theory","id":"claim_ec60cd269cb71aa8ae06f0171f86159a7cd8d1cfee0221b836ac3e1542a045b4","kind":"definition","schema_version":1,"statement":"[Definition def:sigmas-single of arXiv:2603.14906, 'Four Levels of Thermodynamic Convergence of Singularly Perturbed Markov Semigroups'] Let $X$ denote the underlying state space (either $X=E$ or $X=\bar E$), and let $(P_t,\pi,\mathcal L)$ be as in
Eq.~(equation eq:generator-eps of the paper) on $X$.
Fix a nonnegative initial datum $f$ and write $u(t,\zeta)=P_t f$. 
Whenever we specialize to the diffusion form (equation eq:backward-eps1 of the paper), we use the associated coefficients $(A,\gamma)$ via (lem:dict-diffusion of the paper).
For each $t\ge 0$ we define:

\begin{enumerate}
\item \emph{Free energy:}
\[
  \mathcal{F}(t)
  :=\int_X P_t f \log (P_t f)\,d\pi
  =\int_X u(t,\zeta)\,\log u(t,\zeta)\,d\pi(\zeta)\ge 0,
\]
with the convention $0\log0:=0$.

\item \emph{Free energy dissipation rate:}
\begin{equation}

  \mathcal{I}(t) :=4\int_X \Gamma(\sqrt{P_t f})\,d\pi
  =4\int_X \Gamma(\sqrt{u(t,\zeta)})\,d\pi(\zeta) \ge 0.
\end{equation}

\item \emph{Housekeeping (adiabatic) entropy production rate:}
\begin{equation}
  \sigma_{\mathrm{hk}}(t)
  :=\int_X P_t f\,
        (L_a \mathrm{id})^\top \Gamma(\mathrm{id})^{-1}L_a \mathrm{id}\,d\pi
  =\int_X u(t,\zeta)\,\gamma(\zeta)^\top A(\zeta)^{-1}\gamma(\zeta)\,d\pi(\zeta)\ge 0,
\end{equation}
where $L_a:=\tfrac12(\mathcal L-\mathcal L^\dagger)$ and $\mathcal L^\dagger$ is the $\pi$-adjoint of $\mathcal L$ in $L^2(\pi)$.
Let $\mathrm{id}:X\to\mathbb{R}^d$ denote the coordinate embedding $\mathrm{id}(\zeta)=\zeta$, with components $\mathrm{id}_i(\zeta)=\zeta_i$.
Let $\Gamma(\mathrm{id})$ be the $d\times d$ matrix field with entries $\Gamma(\mathrm{id}_i,\mathrm{id}_j)$.
For diffusion generators of the form in Eq.~(equation eq:backward-eps1 of the paper), one has $\Gamma(\mathrm{id})=A$ and $L_a\,\mathrm{id}=-\gamma$.

We also set the steady-state housekeeping entropy production rates by
\begin{equation}
\sigma_{\mathrm{hk,ss}}:= \int_X(L_a \mathrm{id})^\top \Gamma(\mathrm{id})^{-1}L_a \mathrm{id}\,d\pi=\int_X \gamma(\zeta)^\top A(\zeta)^{-1}\gamma(\zeta)\,d\pi(\zeta).

\end{equation}

\item \emph{Excess (nonadiabatic) entropy production rate:}
\begin{equation}
  \sigma_{\mathrm{ex}}(t):= \mathcal{I}(t)\ge 0.
\end{equation}

\item \emph{Total entropy production rate:}
\begin{equation}
  \sigma(t):= \sigma_{\mathrm{hk}}(t) + \sigma_{\mathrm{ex}}(t)\ge 0.
\end{equation}
\end{enumerate}","status":"unverified"}

