    \end{equation}
    where $X_t := \int_0^t\,Y_s\,ds\,$. Additionally, $\sup_{t \leq T} \,\mathbb E \left[Y_t^p \right]$ is finite for all $p \geq 2\,$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.726329+00:00","domain":"probability theory","id":"claim_ec8f2ebeb8822374178f4f8112ba4962d4276eba908429fd76b8215ea4edf43c","kind":"concept","schema_version":1,"statement":"[Lemma of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Let $L:C^{0,1}(\Omega_T)\to\mathbb{R}$ be any linear functional and recall 
    \begin{equation*}
    \mathfrak{M}(H):=\int_0^T\int_0^1\sigma(\rho_t)|\nabla H_t|^2\;dx\;dt+\int_0^T\Psi(t,H_t(0),H_t(1))\;dt.
\end{equation*}
Then 
\begin{equation*}
    \sup_{C^{0,1}(\Omega_T)}\{L_0(H)-\mathfrak{M}(H)\}=S_1+S_2,
\end{equation*}
where
\begin{equation*}
    S_1=\sup_{C^{0,1}_0(\Omega_T)}\{L_0(G)-\int_0^T\int_0^1\sigma(\rho_t)|\nabla G_t|^2\;dx\;dt\}
