{"assumptions":[],"created_at":"2026-10-28T01:29:08.521438+00:00","domain":"probability theory","id":"claim_ecf7e93af636d415eea7a96474d572cb88e855bd0d6dea1fd5c3d757fb9f04ef","kind":"definition","schema_version":1,"statement":"[Definition def:lf-insertion of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $(\alpha_i,z_i)\in\mathbb{R}\times\mathbb{H}$ and $(\beta_j,s_j)\in\mathbb{R}\times\partial\mathbb{H}$ for $i=1,...,m$ and $j = 1,...,n$ and the $z_i$'s and $s_j$'s are pairwise distinct. Set 
	\begin{equation*}
	\begin{split}
	&C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j} =\\ &\prod_{i=1}^m\prod_{j=1}^n(2\mathrm{Im}z_i)^{-\frac{\alpha_i^2}{2}}|z_i|_+^{-2\alpha_i(Q-\alpha_i)}|s_j|_+^{-\beta_i(Q-\frac{\beta_i}{2})}e^{\frac{\alpha_i\beta_j}{2}G_\mathbb{H}(z_i,s_j)+\sum_{i'=i+1}^{m}\alpha_i\alpha_{i'}G_\mathbb{H}(z_i,z_{i'})+\sum_{j'=j+1}^{n}\frac{\beta_j\beta_{j'}}{4}G_\mathbb{H}(s_j,s_{j'}) }.   
	\end{split}
	\end{equation*}
	Let $(h,\mathbf{c})$ be sampled from $C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j}P_\mathbb{H}\times [e^{(\sum_i\alpha_i+\frac{1}{2}\sum_j\beta_j-Q)c}dc]$, and 
	\begin{equation*}
	    \phi(z) = h(z)-2Q\log|z|_++\sum_{i=1}^m\alpha_iG_\mathbb{H}(z,z_j)+\sum_{j=1}^n\frac{\beta_j}{2}G_\mathbb{H}(z,s_j)+\mathbf{c}.
	\end{equation*}
	We write $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j}$ for the law of $\phi$ and call a sample from $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j}$ the Liouville field on $\mathbb{H}$ with insertions $(\alpha_i,z_i)_{1\le i\le m}, (\beta_j,s_j)_{1\le j\le n}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:48:24.316352+00:00","domain":"probability theory","id":"claim_ecfcbf694a8499451e259c3878261a9dafa7e07b022a434132d022ca9a62e0c0","kind":"definition","schema_version":1,"statement":"[Definition def:finite boxtimes of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $p_n$ and $q_n$ be degree $n$ monic polynomials with corresponding unique polynomials  $P_n$ and $Q_{n}$ such that $p_n(z)=P_n(z\partial_{z})(z-1)^{n}$ and $q_{n}(z)=Q_n(\partial_{z})(z-1)^n$, respectively.

	Then, the finite free multiplicative convolution  of $p_n$ and $q_n$ is the unique degree $n$ polynomial $p_n\boxtimes_{n}q_n$ such that \begin{equation*}
		p_n\boxtimes_{n}q_{n}(z)=Q_n(z\partial_{z})P_n(z\partial_{z})(z-1)^n.
	\end{equation*} Equivalently, if $p_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(p_n)\binom{n}{k}z^{n-k}$ and $q_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(q_n)\binom{n}{k}z^{n-k}$, then \begin{equation*}
	p_n\boxtimes_{n}q_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(p_n)e_{k}(q_n)\binom{n}{k}z^{n-k}. 
	\end{equation*}","status":"unverified"}

