{"assumptions":[],"created_at":"2026-10-27T12:52:05.699603+00:00","domain":"probability theory","id":"claim_ed1bf31fbf2892d5192e4ac26189b79feab97c4bf9d8c4db1a6a43ebcd97975a","kind":"concept","schema_version":1,"statement":"[Lem resampling of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Given $n \geq k \geq 1$, $u \geq 0$ and $i \in \mathbb N_{\geq 2}$, consider a nonempty Borel subset $M^{i}_{k,n} \subseteq \mathcal N_k$ and a family $(f^{i}_{n,u,y,v} :  y \in \mathbb{X}_{k+(i-2)k^\gamma},v \in \mathcal N_k)$ of measurable functions $f^{i}_{n,u,y,v}: \mathbb{R}^{\overline{{\rm B}^+[y;i-1]}} \to \mathbb{R}$. Then, if for each  $z \in {\mathbf W}_n(u)$ we define
\begin{equation}
\mathbb{Y}^i_n(u;z):=\Big\{	y \in \mathbb{X}_{k+(i-2)k^\gamma} :\: {\rm W}_n(u) \cap {\rm Q}(z;n-r_n) \subseteq {\rm B}^-[y;i-1] \,,\, 
 \sqrt{\widehat{N}_{t}[y;i]} \in M^i_{k,n}\Big\},
\end{equation}
the quantity $\mathbb{Z}^i_n(u)$ given by  
\begin{equation}
\mathbb{Z}_n^i(u):= \sum_{z \in {\mathbf W}_n(u) \atop \mathbb{Y}^i_n(u;z) \neq \emptyset}  \max_{y \in \mathbb{Y}^i_n(u;z)} f^i_{n,u,y,\sqrt{\widehat{N}_t[y;i]}} \big(L_t\big(\overline{{\rm B}^+[y;i-1]}\big)\big).	
\end{equation} satisfies, for any $\kappa,t > 0$ and all $k$ large enough (depending only on $\gamma$),
\begin{equation}
\mathbb{P}( |\mathbb{Z}^i_n(u)| > \kappa |{\mathbf W}_n(u)|) \leq C \kappa^{-1}{\rm e}^{4k^\gamma}b_{k,n}^{(i)}(u),	
\end{equation}where $C > 0$ is some universal constant and  
\begin{equation}
b_{k,n}^{(i)}(u):= \sup_{y,\rho} \mathbb E \left( \Big|f^i_{n,u,y,v}\big(L_t\big(\overline{{\rm B}^+[y;i-1]}\big)\big)\Big|\,\Big|\,  Z_{t^A_n}[y;i]=\rho\,,{\rm W}_n(u) \cap {\rm B}^-[y;i-1] \neq \emptyset \right),
\end{equation} with the supremum being over the set of all $y \in \mathbb{X}_{k+(i-2)k^\gamma}$ with $\overline{{\rm B}^+[y;i]} \subseteq {\rm D}_n$ (so that $N_{t}[y;i]$ is well-defined) and all $\rho:=(v,\overline{z}) \in \mathcal Z_k(i)$ with $v \in M^i_{k,n}$ (with the convention that $b_{n,k}^{(i)}(u):=0$ if this set is empty, in which case $\mathbb{Z}_n^i(u) = 0$ since the sum in (equation eq:sumz of the paper) is also over an empty set). 
In particular, given a nonempty subset $\mathcal C_{k,n} \subseteq \mathbb{N}_{\geq 2}$ of indices and $\eta \in (0,\frac{1}{2}-\gamma)$, if 
\begin{equation}
 \limsup_{k \to \infty} \limsup_{n \to \infty} \left[\sup_{i \in \mathcal C_{k,n}} b_{k,n}^{(i)}(u) {\rm e}^{2(k+ik^\gamma)^{\frac{1}{2}-\eta}}\right] \leq 1,	
\end{equation} then 
\begin{equation}
	\lim_{k \to \infty} \limsup_{n \to \infty} \mathbb{P}\left( \exists i \in \mathcal C_{k,n} : |\mathbb{Z}^{i}_{n}(u)| > {\rm e}^{-(k+ik^\gamma)^{\frac{1}{2}-\eta}}\right) = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

