{"assumptions":[],"created_at":"2026-10-27T13:12:09.001043+00:00","domain":"probability theory","id":"claim_ed2a54983c7f40d821d121f0b01e477eef224225f60a935763d215e66320810b","kind":"theorem","schema_version":1,"statement":"[Theorem thm:tikhonov-trace of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] In the setting of Theorem~(thm:pseudoinverse-covering of the paper), let $\Phi: \Omega \times [0,T] \to L_2(U, H)$ be the time-fibre realisation of $\mathcal{T} = DF$ obtained from the canonical isometry
\[
  L_2\!\bigl(L^2([0,T]; U),\; H\bigr) \;\simeq\; L^2\!\bigl([0,T]; L_2(U, H)\bigr), \qquad \mathcal{T} u \;=\; \int_0^T \Phi_r\,u(r)\,\mathrm{d}r,
\]
so that $\norm{\mathcal{T}}^2_{L_2(H_W, H)} = \int_0^T \lVert \Phi_r \rVert^2_{L_2(U, H)}\,\mathrm{d}r$ a.s. Suppose, in addition to (hyp:i-F of the paper)--(hyp:ii-F of the paper):
\begin{enumerate}[leftmargin=3em]
  \item[\textup{(iii$_F'$)}]\hyplabel{hyp:iii-F-prime}{\textup{(iii$_F'$)}} \textup{(Fixed-Tikhonov substitution regularity.)} For every $\varepsilon > 0$,
  \begin{equation}
    u_h^{(\varepsilon)} \;:=\; \mathcal{T}^{*}\,(\gamma_F + \varepsilon I)^{-1}\,h \;\in\; \mathbb{D}^{1,2}(H_W) \;\subset\; \operatorname{Dom}(\delta_U),
  \end{equation}
  and the corresponding fixed-$\varepsilon$ substitution identity is well-defined. Alternatively, for the purpose of the substitution identity, the direct assumption~(equation eq:uheps-D12 of the paper) may be replaced by the following basis-wise sufficient conditions:
  \begin{equation}
    G^{(\varepsilon)} := (\gamma_F + \varepsilon I)^{-1}h \;\in\; \mathbb{D}^{1,2}(H), \qquad \varepsilon > 0,
  \end{equation}
  together with the H\"older-pair joint integrability~(equation eq:linear-sub-Holder of the paper) of $(\mathcal{T}, G^{(\varepsilon)})$ (the basis-wise route via Theorem~(thm:linear-sub-D12 of the paper)). Sufficient conditions for either form, and the relation between them, are catalogued in Remark~(rem:iii-F-status of the paper).
  \item[\textup{(iv$_F$)}]\hyplabel{hyp:iv-F}{\textup{(iv$_F$)}} \textup{(Cameron--Martin compatibility)} The covariance, viewed as an $L_2(H,H)$-valued random variable, belongs to $\mathbb{D}^{1,2}(L_2(H,H))$, and the Tikhonov-regularised trace integrand
  \[
    \mathcal{I}^{(\varepsilon)}_r(F) \;:=\; \operatorname{Tr}_U\!\Bigl[\,\Phi_r^{*}\,(\gamma_F + \varepsilon I)^{-1}\,[D_r\gamma_F]\,(\gamma_F + \varepsilon I)^{-1}\,h\,\Bigr], \qquad \varepsilon > 0,
  \]
  converges a.s.\ for a.e.\ $r$, as $\varepsilon \downarrow 0$, to a measurable limit $\mathcal{I}^{(0)}_r(F)$, and admits a measurable dominator $\Psi_r$, exactly as in (equation eq:CM-compat-limit of the paper)--(equation eq:CM-compat-dominator of the paper) with $[0,t]$ replaced by $[0,T]$ and $\mathbb{E}[(\int_0^T\Psi_r\,\mathrm{d}r)^2] < \infty$.
\end{enumerate}
Then $u_h \in \operatorname{Dom}(\delta_U)$, and the Skorokhod integral admits the explicit decomposition
\begin{equation}
  \delta_U(u_h) \;=\; M_h \;+\; C_h,
\end{equation}
where the \emph{main term} $M_h$ is the Hilbert--Schmidt kernel evaluation at the random point $\gamma_F^{\dagger}h$: by Lemma~(lemma:HS-kernel of the paper), the map $z \mapsto \delta_U(\mathcal{T}^{*}z)$ is Hilbert--Schmidt from $H$ to $L^2(\Omega)$ with kernel $\mathcal{K} \in L^2(\Omega; H)$, and
\begin{equation}
  M_h \;:=\; \langle \gamma_F^{\dagger}h,\,\mathcal{K}\rangle_H \;=\; \lim_{\varepsilon\downarrow 0}\,\langle (\gamma_F+\varepsilon I)^{-1}h,\,\mathcal{K}\rangle_H \quad \text{in } L^2(\Omega),
\end{equation}
and the \emph{correction term} $C_h$ is the trace-integral limit
\begin{equation}
  C_h \;:=\; \int_0^T \mathcal{I}^{(0)}_r(F)\,\mathrm{d}r \;=\; \lim_{\varepsilon \downarrow 0}\,\int_0^T \mathcal{I}^{(\varepsilon)}_r(F)\,\mathrm{d}r \quad \text{in } L^2(\Omega),
\end{equation}
existing under~(hyp:iii-F-prime of the paper)--(hyp:iv-F of the paper).
Both limits are independent of any regularising sequence $\varepsilon_n \downarrow 0$.","status":"unverified"}

