{"assumptions":[],"created_at":"2026-10-27T13:41:28.180837+00:00","domain":"probability theory","id":"claim_ed6a291630c71cdcb5b3b8cca82d15ae7679972a0b28690ec842a64cc78b9beb","kind":"concept","schema_version":1,"statement":"[Proposition pro:CheegerPoincareBounds of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $D \geqslant 2$ be an integer and $U$ be a doubly stochastic irreducible $D \times D$ transition matrix. Let $U^+$ be the additive symmetrisation of $U$. Then
    \begin{enumerate}[label=(\alph*)]
        \item The Cheeger constant $\Phi_{\ast}(U)$ of $U$ is equal to that of $U^T$ as well as to that of $U^+$.

        \item The spectral gap $\gamma^+$ of $U^+$, also known as the \emph{Poincar\'e constant} of $U$, satisfies $\gamma^+ \asymp \Phi_{\ast}(U)$.

        \item The following \emph{Poincar\'e inequality} holds: For any distribution $\nu$ on $[D]$, writing $\pi$ for the uniform distribution on $[D]$, we have that for all $t \geqslant 0$,
        \begin{equation*}
            \normtp{\nu \mathrm{e}^{t(U-I)} - \pi} \leqslant \mathrm{e}^{-\gamma^+ t} \left\lVert\nu - \pi\right\rVert_{2, \pi} = \mathrm{e}^{-\gamma^+ t} \Big( \sum_{x \in [D]} \Big( \frac{\nu(x)}{\pi(x)}-1\Big)^2 \pi(x)\Big)^{\frac{1}{2}}.
        \end{equation*}

        \item In the notation of (c), uniformly in $t \geqslant D$, we have that
        \begin{equation*}
            \normtp{\nu \mathrm{e}^{t(U-I)} - \pi} \lesssim (1+t^D)  \mathrm{e}^{-\gamma (t-D)} \left\lVert\nu - \pi\right\rVert_{2, \pi}.
        \end{equation*}

        \item The worst-case total variation distance from $\pi$ at time $t$, defined as
        \begin{equation*}
            \mathrm{d}_{\mathrm{TV}}(t) \coloneqq \max_{x \in [D]} \normTV{\delta_x \mathrm{e}^{t(U-I)} - \pi},
        \end{equation*}
        where $\delta_x$ is the Dirac measure on $x$, satisfies uniformly in $t \geqslant D$ that
        \begin{equation*}
