{"assumptions":[],"created_at":"2026-10-27T13:12:08.981903+00:00","domain":"probability theory","id":"claim_ed886f63a9e90f135006a6de02d4371b42b0894dca3a17d74c75e0b882f05867","kind":"concept","schema_version":1,"statement":"[Lem lem_MetricSupEstimate of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let $(X_\eta)_{\eta\in\mathfrak{M}}$ be a centred Gaussian field on a compact metric space $\mathfrak{M}$ with \emph{canonical} metric $d_X(\eta,\zeta) := \mathbb{E}\left[(X_\eta-X_\zeta)^2\right]^{1/2}$.
    Let $N_X(x)$ be the smallest number of canonical balls of radius $x$ that cover $\mathfrak{M}$. Then
    \begin{align*}
        \expec{\sup_{\eta\in\mathfrak{M}} X_\eta} \leq K \int_0^{\diam_X(\mathfrak{M})/2} \sqrt{\log N_X(x)} ~\textup{d} x,
    \end{align*}
    where $K$ is a universal constant and $\diam_X(\mathfrak{M}):=\sup_{\eta,\zeta\in \mathfrak{M}} d_X(\eta,\zeta)$ is the diameter with respect to the canonical metric. Moreover, if there is an $\varepsilon_0 >0$ so that
    \begin{align}
        \int_0^{\varepsilon_0} \sqrt{\log N_X(x)} ~\textup{d} x < \infty
    \end{align}
    then $(X_\eta)_{\eta\in\mathfrak{M}}$ is a.s.\ continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:19.216976+00:00","domain":"probability theory","id":"claim_ed88fe2b35818bd70b285b75d7eef0d2642ce185483ccf65a78aa20ea033b837","kind":"theorem","schema_version":1,"statement":"[Proposition 2602021049 of arXiv:2609.02626, 'Comparison principles and symmetry for subquadratic fractional $p$-Laplacian equations'] Let $N\ge 1$, $s\in (0, 1)$, $1<p<2$, $U\subset  \mathbb{R}_+^N$ be a bounded open set and $$u\in \widetilde{W}^{s,p}(U)\cap \widetilde{W}^{s,p}(\mathcal{T}(U))\cap L^\infty(\mathbb{R}^N).$$  If  $w=u-u^*\ge 0$ a.e. in $\mathbb{R}^N_+\backslash U$, then we have
\begin{align}
\begin{split}
& \quad -\int_{\mathbb{R}^{2N}}\frac{(J_{u}(x, y)-J_{u^*}(x, y))\left(w_-(x){\mathbbm 1}_{U}(x)-w_-(y){\mathbbm 1}_{U}(y)\right)}{|x-y|^{N+sp}}{\rm d}x{\rm d}y\\
& \ge C \|u\|_{L^{\infty}(\mathbb{R}^N)}^{p-2}\|w_-{\mathbbm 1}_{U}\|_{W_0^{\frac{sp}{2},2}(U)}^2,
\end{split}
\end{align}
where $C$ depends only on $p$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:31.999422+00:00","domain":"probability theory","id":"claim_ed8de24fce42620e22ae0548d91dd0541217ee515a981b347f7869dc3bdcc4e0","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] There exist absolute constants $\delta_0,c>0$ such that the following holds for $\delta \leq \delta_0$.
	For every $x_0\in D$, measurable $E\subseteq D$, and $t \geq c\min\{ 1/\kappa^2, 1/\lambda_{\max}^2,\rho^2 \}$,
	\begin{equation}
		\bbP\bigl(X_t \in E \mid X_0 = x_0\bigr)
		\geq
		\frac{1}{2}
		\sup_{u}\inf_{x_0' \in \cD(\delta)}\bbP\bigl(X_{u} \in E \mid X_0 = x_0'\bigr)
		.

	\end{equation}
	Here, the supremum runs over $u \leq  t - c\min\{ 1/\kappa^2, 1/\lambda_{\max}^2,\rho^2\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:16:46.780305+00:00","domain":"probability theory","id":"claim_ed8ee78aabd5ba2e9d1a09590315a10e832570eaf74aefb37a3ebb812c7239ea","kind":"concept","schema_version":1,"statement":"[Theo thm:ConvergenceSemiGroup of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] \begin{enumerate}
