{"assumptions":[],"created_at":"2026-10-27T19:33:43.753255+00:00","domain":"probability theory","id":"claim_edd1f22ebc8ea487c41cbeef9aded23876df0081d71f051830034c66473c8254","kind":"theorem","schema_version":1,"statement":"[Theorem thm:embedding_theorems of arXiv:2609.01984, 'Instantaneous shrinking of supports for stochastic PDEs\footnote{JY was supported by a KIA'] Let $\tau\le T$ be a bounded stopping time. 
\begin{enumerate}[(i)]
\item

For every $p\ge2$, $\mathcal H_p^\eta(\tau)$ is a Banach space with the norm $\|\cdot\|_{\mathcal H_p^\eta(\tau)}$.
\item  
If $\eta\in\mathbb{R}$, $p>2$, and $1/p<\mathbb{a}<\mathbb{b}<1/2$, then for every $u\in\mathcal{H}_p^\eta(\tau)$, we have 
\[ u\in C^{\mathbb{a}-1/p}([0,\tau];H_p^{\eta-2\mathbb{b}}) \quad a.s.\]
and
\begin{equation}

\mathbb{E}\| u \|_{C^{\mathbb{a}-1/p}([0,\tau];H_p^{\eta-2\mathbb{b}})}^p \leq N(\mathbb{a},\mathbb{b},p,T)\| u \|_{\mathcal{H}_p^\eta(\tau)}^p.
\end{equation}
\item

If $p=2$, then (equation holder_embedding of the paper) holds with
$\mathbb{a}=\mathbb{b}=1/2$, i.e., $u\in C([0,\tau];H_2^{\eta-1})$ a.s. 
and
\begin{equation*}

    \mathbb{E}\sup_{t\le\tau}
    \|u(t)\|_{H_2^{\eta-1}}^2
    \le
    N(T)
    \|u\|_{\mathcal H_2^\eta(\tau)}^2 .
\end{equation*}

\item  
If $\eta>0$, $p>2$, $\mathbb{a},\mathbb{b}\in(0,\infty)$ satisfy
\begin{equation*}
\frac{1}{p} < \mathbb{a} < \mathbb{b} < \frac{1}{2}\left( \eta - \frac{1}{p} \right),
\end{equation*}
then for every $u\in\mathcal{H}_p^\eta(\tau)$, we have $u\in C^{\mathbb{a}-1/p}([0,\tau];C^{\eta-2\mathbb{b}-1/p})$ a.s. and 
\begin{equation*}
\mathbb{E}\| u \|_{C^{\mathbb{a}-1/p}([0,\tau];C^{\eta-2\mathbb{b}-1/p})}^p \leq N(\mathbb{a},\mathbb{b},p,T)\| u \|_{\mathcal{H}_p^\eta(\tau)}^p.
\end{equation*}

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.736060+00:00","domain":"probability theory","id":"claim_edd94c236528a384cf2fb462f2a4064de93eca98baf3e6146d007f6dd2eb5ffc","kind":"lemma","schema_version":1,"statement":"[Lemm 19 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Assume that the FBSDE \eqref{fbsde:equ} satisfies all the condition of Theorem \ref{theorem:path-regularity} with $p \geq 2$,
