				-\kappa^{-2}(1+q)\hspace{1pt} q^{-1-2\Delta x}, & \tfrac{1}{2}(\mathsf{S}+\mathsf{t}-\mathsf{N})<\mathsf{x}<\tfrac{1}{2}(\mathsf{S}+\mathsf{t});\\
				\dfrac{-\kappa^2 (1+q) \hspace{1pt} q^{2\Delta x+1}}{(1-\kappa^2 q^{2 \Delta x})(1-\kappa^2 q^{2\Delta x+2})}, & \mathsf{x}=\tfrac12(\mathsf{S}+\mathsf{t}),\ \lfloor L\hspace{1pt} \mathsf{x}\rfloor=\tfrac{1}{2}(S+t);\\
				-\kappa^2(1+q) \hspace{1pt} q^{2\Delta x+1}, & \tfrac{1}{2}(\mathsf{S}+\mathsf{t})<\mathsf{x}<\tfrac{1}{2}(\mathsf{S}+\mathsf{t}+\mathsf{N});\\
				-1-\kappa^2(1+q) \hspace{1pt} q^{2\Delta x+1}, & \mathsf{x}= \tfrac12(\mathsf{S}+\mathsf{t}+\mathsf{N}) ,\ \lfloor L\hspace{1pt} \mathsf{x}\rfloor=\tfrac{1}{2}(S+t+N);
