{"assumptions":[],"created_at":"2026-10-28T01:29:08.682232+00:00","domain":"probability theory","id":"claim_ee9491a98e765770a8c55ecdaea346b9e3853acaf98994a1235461ef6eecaaa7","kind":"definition","schema_version":1,"statement":"[Definition def:predictable of arXiv:2412.00279, 'Optimal local storage policy based on stochastic intensities and its large scale behavior'] Let $\{\mathcal{F}_t\}_{t\in\mathbb{R}}$ be a filtration on $(\Omega,\mathcal{F})$. The \emph{predictable} $\sigma-$algebra $\mathcal{P}(\mathcal{F}.)$ associated to $\mathcal{F}_t$ is the $\sigma-$algebra on $\mathbb{R}\times \Omega$ generated by the sets of the form:
    \begin{equation*}
      (a,b] \times A, \; a<b, \; A\in\mathcal{F}_a.
    \end{equation*}
    A stochastic process $X(t, \omega)$ taking values on a measurable space $(E,\mathcal{E})$ is $\mathcal{F}_t$-\emph{predictable} if the mapping $(t,\omega) \mapsto X(t,\omega)$ is $\mathcal{P}(\mathcal{F}.)$-measurable.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.771874+00:00","domain":"probability theory","id":"claim_ee98f504f022dbe24c0afe7b58b58df9f588dfa16bac53b433b3d38267e75d00","kind":"lemma","schema_version":1,"statement":"[Lemma 50 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definitions \ref{Def.ParametersEdge} and \ref{Def.ScalingEdge}. In addition, fix parameters $\theta_{\kappa_1}, \dots, \theta_{\kappa_m} \in (\pi/4, \pi/2)$, $R_{\kappa_1}, \dots, R_{\kappa_m} > q^{-1}$, and the contours
\begin{equation}
\begin{split}
&\Gamma_{\kappa, N} = C\left(c,\theta_{\kappa}, R_\kappa, \sec(\theta_{\kappa}) N^{-1/2}\right), \hspace{2mm} \gamma_{\kappa, N} = C_{\zc(\kappa) + N^{-1/2}}\mbox{ for } \kappa \in \mathcal{T}, \mbox{ and } \\
& \tilde{\gamma}_N = C\left(c, \pi/2, \sqrt{c^2 + N^{-1/6}}, 0 \right),
\end{split}
\end{equation}
as in Definition \ref{Def.ContoursEdge}. Let $M^N$ be the point process on $\mathbb{R}^2$, formed by $\{(\kappa_j, Y_i^{j,N}): i \geq 1, j \in \llbracket 1, m\rrbracket \}$. Then for all large $N$ (depending on $q, c, \mathcal{T}$ and $\{\theta_{\kappa}: \kappa \in \mathcal{T}\}$), $M^N$ is a Pfaffian point process with reference measure $\mu_{\mathcal{T},\nu(N)}$ and correlation kernel $K^N$ that are defined as follows. 

The measure $\mu_{\mathcal{T},\nu(N)}$ is as in Definition \ref{Def.ScaledLatticeMeasures} for $\nu(N) = (\nu_{\kappa_1}(N), \dots, \nu_{\kappa_m}(N))$, where $\nu_{\kappa}(N)$ is $\sigmap^{-1} N^{-1/2}$ times the counting measure on $\Lambda_{\kappa}(N)$. 

The correlation kernel $K^N: (\mathcal{T} \times \mathbb{R}) \times (\mathcal{T} \times \mathbb{R}) \rightarrow\operatorname{Mat}_2(\mathbb{C})$ takes the form
\begin{equation}
\begin{split}
&K^N(s,x; t,y) = \begin{bmatrix}
    K^N_{11}(s,x;t,y) & K^N_{12}(s,x;t,y)\\
    K^N_{21}(s,x;t,y) & K^N_{22}(s,x;t,y) 
\end{bmatrix} \\
&= \begin{bmatrix}
    I^N_{11}(s,x;t,y) & I^N_{12}(s,x;t,y) + R^N_{12}(s,x;t,y) \\
    -I^N_{12}(t,y;s,x) - R^N_{12}(t,y;s,x) & I^N_{22}(s,x;t,y) + R^N_{22}(s,x;t,y)
\end{bmatrix},
\end{split}
\end{equation}
where $I^N_{ij}(s,x;t,y), R^N_{ij}(s,x;t,y)$ are defined as follows. The kernels $I^N_{ij}$ are given by
\begin{equation}
\begin{split}
&I^N_{11}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\Gamma_{s, N}} dz \oint_{\Gamma_{t, N}} dw F_{11}^N(z,w) H_{11}^N(z,w) \mbox{, where }\\
& F^N_{11}(z,w) = e^{N\bar{\SFt}(z;s) + N\bar{\SFt}(w;t)} \cdot e^{-  \sigmap x N^{1/2} \log (z/c) -  \sigmap y N^{1/2} \log(w/c)  }, \\
&H^N_{11}(z,w) = \sigmap N^{1/2} \cdot  \frac{(z-w)( 1 - c/z) (1 - c/w)(1-q/z)^{\lfloor s N \rfloor - sN}(1-q/w)^{ \lfloor t N \rfloor - tN} }{(z^{2}-1)(w^{2}-1)(zw-1)(1-q/c)^{ \lfloor s N \rfloor - sN}(1-q/c)^{\lfloor t N \rfloor - tN} };
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&I^N_{12}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\Gamma_{s, N}} dz \oint_{\gamma_{t,N}} dw F_{12}^N(z,w) H_{12}^N(z,w) \mbox{, where }\\
& F^N_{12}(z,w) = e^{N\bar{\SFt}(z;s) - N\bar{\SFt}(w;t)}\cdot e^{-  \sigmap x N^{1/2} \log (z/c) +  \sigmap y N^{1/2} \log(w/c)  }, \\
&H^N_{12}(z,w) =   \sigmap N^{1/2} \cdot \frac{(zw - 1)(z-c)(1-q/z)^{\lfloor s N \rfloor - sN}(1-q/c)^{ \lfloor t N \rfloor - tN}}{z (z-w)(z^2 - 1) (w-c)(1-q/w)^{ \lfloor t N \rfloor - tN}(1-q/c)^{ \lfloor s N \rfloor - sN}};
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&I^N_{22}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\gamma_{s,N}} dz \oint_{\gamma_{t, N}} dw F_{22}^N(z,w) H_{22}^N(z,w) \mbox{, where }\\
& F^N_{22}(z,w) = e^{-N\bar{\SFt}(z;s) - N\bar{\SFt}(w;t)}\cdot e^{  \sigmap x N^{1/2} \log (z/c) +  \sigmap y N^{1/2} \log(w/c)  }, \\
&H^N_{22}(z,w) =  \sigmap N^{1/2}\cdot \frac{(z-w)(1-q/c)^{\lfloor s N \rfloor - sN}(1-q/c)^{\lfloor t N \rfloor - tN}}{(zw - 1)(z- c)(w - c)(1-q/z)^{\lfloor s N \rfloor - sN }(1-q/w)^{\lfloor t N \rfloor - tN}}.
\end{split}
\end{equation}
The kernels $R^N_{ij}$ are given by
\begin{equation}
\begin{split}
&R^N_{12}(s,x;t,y) = \frac{-{\bf 1}\{s < t \}   \sigmap N^{1/2} }{2 \pi \im}  \oint_{\tilde{\gamma}_N} dz e^{(s-t)N \bar{\GFt}(z)} \cdot e^{\sigmap (-  x +  y) N^{1/2} \log(z/c)  } \\
&\times \frac{(1-q/z)^{\lfloor sN \rfloor - sN}(1-q/c)^{\lfloor tN \rfloor - tN}}{z(1-q/z)^{\lfloor tN \rfloor - tN}(1-q/c)^{\lfloor sN \rfloor -s","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:38:37.419082+00:00","domain":"probability theory","id":"claim_ee99a20b861193423678fc86d4cf0064edd6db37799a3fabc5d67798ee7a4f02","kind":"definition","schema_version":1,"statement":"[Definition 19 (Likelihood ratio dominance order $\leq_{\textnormal{lrd}}$) of arXiv:2605.16560, 'Seasonal Statistics of Shannon Rate in a Dynamical Poisson-Voronoi Cellular Network'] We say that two non-negative random variables $X,Y$ satisfy  likelihood ratio dominance order ({\em lrd order}), 

