{"assumptions":[],"created_at":"2026-10-26T19:36:44.526267+00:00","domain":"probability theory","id":"claim_ef210699f0499eaa7fa765b1411ea1d82f8c05ef4f8aec206217e76bed736b67","kind":"concept","schema_version":1,"statement":"[Lemma 12 of arXiv:2604.01701, '\bf Chung-type laws of the iterated logarithm for $m$-fold weighted integrated fractional '] Let $  X(t)$ be a continuous, centered, self-similar Gaussian process of index $\tau>0$.
Suppose that
\begin{equation}-\log \pr\Big(\sup_{a\le t\le b} \left|  X(t)\right|<\epsilon\Big)\preccurlyeq \; (\text{resp.} \ll)\; \epsilon^{-\beta}\Big(\log\frac{1}{\epsilon}\Big)^{\nu },   
\end{equation} 
with $0<\beta<\infty$, $0\le \nu <\infty$, $0\le a<b<\infty$. Then for all $0\le c<d<\infty$,
\begin{equation}-\log \pr\left(\sup_{c\le t\le d} \left | X(t)\right |<\epsilon\right)\preccurlyeq \; (\text{resp.} \ll)\; \epsilon^{-\beta}\Big(\log\frac{1}{\epsilon}\Big)^{\nu }.
\end{equation}

As corollaries, we have  
\begin{itemize}
\item[(i)] For all $\alpha<\tau$,
$$ -\log \pr\left(\sup_{0\le t\le 1} t^{-\alpha}\left | X(t)\right |<\epsilon\right)\preccurlyeq \; (\text{resp.} \ll)\; \epsilon^{-\beta}\Big(\log\frac{1}{\epsilon}\Big)^{\nu }; $$
  \item[(ii)] For all $\alpha<\tau+1$ and $\alpha_1<\tau+1$,  
\begin{equation}-\log \pr\Big(\sup_{0\le t\le 1}|t^{-(\alpha-\alpha_1)}J_{\alpha_1}(X)(t)|< \epsilon\Big)
\preccurlyeq \; (\text{resp.} \ll)\;\epsilon^{- \beta/(\beta+1)}\Big(\log\frac{1}{ \epsilon}\Big)^{\nu /(\beta+1)}, 
\end{equation}
\begin{equation}-\log \pr\left(\sup_{0\le t\le 1} \left |J_{\alpha}(X)(t)\right |<\epsilon\right)\preccurlyeq \; (\text{resp.} \ll)\; \epsilon^{-\beta/(\beta+1)}\Big(\log\frac{1}{\epsilon}\Big)^{\nu /(\beta+1)},  
\end{equation}
\begin{equation}-\log \pr\left(\sup_{0\le t\le 1} \left|t^{-\alpha}I(X)(t) \right |<\epsilon\right)\preccurlyeq \; (\text{resp.} \ll)\; \epsilon^{-\beta/(\beta+1)}\Big(\log\frac{1}{\epsilon}\Big)^{\nu /(\beta+1)};   
\end{equation} 
\item[(iii)] 
For all $m\ge 1$, $\alpha_1+\cdots+\alpha_i<\tau+i$, $i=1,\ldots,m$, and $\alpha<\tau+m$,   
\begin{align} 
-\log \pr& \left(\sup_{0\le t\le 1} \left|t^{-(\alpha-\alpha_1-\cdots-\alpha_m)} J_{m,\bm\alpha}(X)(t)-t^{-\alpha}  I_{m}(X)(t) \right|<\epsilon\right)\nonumber\\
&\preccurlyeq \; (\text{resp.} \ll)\; \epsilon^{-\beta/((m+1)\beta+1)}\Big(\log\frac{1}{\epsilon}\Big)^{\nu /((m+1)\beta+1)}.
\end{align} 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:06:42.683989+00:00","domain":"probability theory","id":"claim_ef23514146bdb86fd01d40e81ab50e6c3270a3b11f9b6a226ce09933ae475295","kind":"concept","schema_version":1,"statement":"[Lemma lem1 of arXiv:2411.03942, 'Asymptotic expansions relating to the distribution of the product of correlated normal ran'] (i) Let $a>0$ and $b,m\in\mathbb{R}$ and suppose that the function $g:(0,\infty)\rightarrow\mathbb{R}$ has the following asymptotic expansion:
\begin{equation*}
g(x)\sim x^m\mathrm{e}^{-ax+b\sqrt{x}}\sum_{\ell=0}^\infty\frac{u_\ell}{x^{\ell/2}}, \quad x\rightarrow\infty,   
\end{equation*}
where $u_0,u_1,\ldots$ are real-valued constants. Then, as $x\rightarrow\infty$,
\begin{equation}\int_x^\infty g(t)\,\mathrm{d}t\sim\frac{x^m}{a}\mathrm{e}^{-ax+b\sqrt{x}}\sum_{p=0}^\infty\frac{U_p}{x^{p/2}},
\end{equation}
where, for $p\geq0$,
\begin{align*}
U_p=\sum_{\substack{i,j,k,\ell\geq0 \\ i+2j+k+\ell=p}}(-1)^{j+i}u_\ell \binom{2m+1-\ell}{k}\binom{2m-\ell-k-2j}{i}\frac{((\ell+k)/2-m)_j}{a^j}\bigg(\frac{b}{2a}\bigg)^{k+i}.   
\end{align*}
\noindent (ii) Suppose now that $a>0$ and $m\in\mathbb{R}$ and suppose that the function $h:(0,\infty)\rightarrow\mathbb{R}$ has the following asymptotic expansion:
\begin{equation*}
h(x)\sim x^m\mathrm{e}^{-ax}\sum_{j=0}^\infty\frac{v_j}{x^{j}}, \quad x\rightarrow\infty, 
\end{equation*}
where $v_0,v_1,\ldots$ are real-valued constants. Then, as $x\rightarrow\infty$,
\begin{equation}\int_x^\infty h(t)\,\mathrm{d}t\sim\frac{1}{a}x^m\mathrm{e}^{-ax}\sum_{k=0}^\infty\frac{V_k}{x^k},
\end{equation}
where, for $k\geq0$,
\begin{equation*}
V_k=\sum_{j=0}^kv_j\frac{(k-m)_{k-j}}{(-a)^{k-j}}.    
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.290691+00:00","domain":"probability theory","id":"claim_ef26b5958001fdf74fdee104e161379338bcaeb226022ccc20e07246a92e74aa","kind":"theorem","schema_version":1,"statement":"[Theorem thm:ergodicity of upper v.s. invariant functions of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] Let $(\Omega,\mathcal{F},V,T)$ be an UPPS. Then the following three statements are equivalent:
	\begin{enumerate}
		\item [(i)] $V$ is of finite ergodic components;
		\medskip
		\item [(ii)]there exists a measurable partition $\{A_1,\ldots,A_n\}$ of $\Omega$ with  $V(A_i)=1$, $i=1,2,\ldots,n$ such that for any $T$-invariant function $f$, i.e., $f\circ T=f$, there exists $c_1,\ldots,c_n\in\mathbb{C}$ such that 
		\[f=\sum_{j=1}^nc_j1_{A_j},\text{ }V\text{-a.s.};\]

		\item [(iii)] there exists a measurable partition $\{A_1,\ldots,A_n\}$ of $\Omega$ with  $V(A_i)=1$, $i=1,2,\ldots,n$ such that the eigenspace of the Koopman operator $U_T$ corresponding to eigenvalue $1$ is spanned by $\{1_{A_i}:i=1,2,\ldots,n\}$ and  the eigenvalue $1$ of $U_T$ is of multiplicity $n$.
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:30.016022+00:00","domain":"probability theory","id":"claim_ef2718ecf5fff2126b0278491880fa75bc99a10b42060df43fcf8516d3ff6d61","kind":"theorem","schema_version":1,"statement":"[Proposition 3 of arXiv:2605.05864, 'Classification and Metrization of Classes of Smooth measures'] We assume that \(1_K \mu \in \mathcal{T}\) for any \(\mu \in \mathcal{T}\) and compact set \(K\). Then the following holds.
