{"assumptions":[],"created_at":"2026-10-27T21:05:37.771942+00:00","domain":"probability theory","id":"claim_ef4d2acfb05f35d3e654f5de008e764cc957249becb60eb37cfb62ff6616119d","kind":"theorem","schema_version":1,"statement":"[Proposition comp_pena of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] Let be $\{\sigma_{q,i}\}_{i=0,1,\cdots,k_q+1}$ be a finite sequence of arrays stopping times such that $0=\sigma_{q,0} <\sigma_{q,1}<\sigma_{q,2}<\cdots<\sigma_{q,k_q+1}=T$ for $q \in \{1,2\}$. Let $\{(Y^q,M^q)\}_{q=1,2}$ be a solution of the following GBSDE associated with $(B,\xi_T,\mathfrak{f}_q)$:
		\begin{equation}
			\begin{split}
				Y^q_t=\xi_T&+\int_{t}^{T} \mathfrak{f}_q(s,Y^q_{s-})dB_s
				-\int_{t}^{T} dM^q_s +\sum_{t \leq \sigma_{q,i} < T} \left(Y^q_{\sigma_{q,i}+}-\xi_{\sigma_{q,i}}\right)^{-},\qquad t \in [0,T].
			\end{split}
		\end{equation}
		Suppose that
		$$
		\xi^1_T\geq \xi^2_T,
		\quad \mathbb{P}\text{-a.s.},
		$$
		and that the following conditions hold:
		\begin{itemize}
			\item[\textnormal{(i)}] $\mathfrak{f}_1(\omega,t,y)\geq \mathfrak{f}_2(\omega,t,y)$ for every $(\omega,t,y)\in\Omega\times[0,T]\times\mathbb{R}$;
			\item[\textnormal{(ii)}] for every $(\omega,t)\in\Omega\times[0,T]$, the mapping $y\mapsto \mathfrak{f}_1(\omega,t,y)$ is nonincreasing;
			\item[\textnormal{(iii)}] $\bigcup_i \llbracket \sigma_{2,i}  \rrbracket \subset \bigcup_i \llbracket \sigma_{1,i}  \rrbracket$
		\end{itemize}
		Then
		$$
		Y^1_t\geq Y^2_t,
		\qquad \forall t\in[0,T],
		\quad \mathbb{P}\text{-a.s.}
		$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.350925+00:00","domain":"probability theory","id":"claim_ef50f19e9234cf5c81a06c7bd2409327ed12c583c4c8e58319bf045f10505db9","kind":"concept","schema_version":1,"statement":"[Proposition eq:Breg of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] If $\mathsf{acc}$ is proper, then $\varphi_\mathsf{acc}$ is convex and if it is differentiable, then:
		\begin{align}
		&\mathrm{Exp}_p\mathsf{acc}(p)-\mathrm{Exp}_p\mathsf{acc}(x)=\varphi_\mathsf{acc}(p)-\varphi_\mathsf{acc}(x)-(p-x)\varphi_\mathsf{acc}'(x)
		\end{align}
			If it is not differentiable, then we have the same form, but with $\varphi_\mathsf{acc}'$ as some sub-gradient. 

		Also for $v\in\set{0,1}$,
		\begin{align}
		&\mathsf{acc}_v(x)=\mathsf{acc}_v(v)-\br*{\varphi_\mathsf{acc}(v)-\varphi_\mathsf{acc}(x)-(v-x)\varphi_\mathsf{acc}'(x)}
		\end{align}
		And in fact
		\begin{align}
		&\mathsf{acc}_v(x)=\varphi_\mathsf{acc}(x)+(v-x)\varphi_\mathsf{acc}'(x)
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:06:18.059193+00:00","domain":"probability theory","id":"claim_ef535bdfbffb7c001dc10ac34af3335495ca3e0cfa0de0cdd4c373151498b452","kind":"lemma","schema_version":1,"statement":"[Lemma 43 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Assume $A>A_c(N)$ and let $\beta_{A,N}\in(0,N)$ be the exponent from
  \cref{lem:nd-gaussian-cramer-exponent}. Fix $\alpha\in(0,2)$ and set
  $h(t):=\min\{1,e^{-Nt}\}$. Then there exists $C<\infty$ such that
  \begin{equation}
    \sum_{k\in\Z}
    \sup_{t\in[k,k+1]} e^{\beta_{A,N}t}h(t)<\infty
  \end{equation}
  and, for every $0<r\leq\sqrt N$ and every $t\in\R$,
  \begin{equation}
    \left\|
      \Ee\left[
        \one_{\{\norm{\tanh(rU)}_2<re^{-t}\}}
        \delta_{\widehat{\tanh(rU)}}
      \right]
      -
      \Ee\left[
        \one_{\{\norm U_2<e^{-t}\}}\delta_{\hat U}
      \right]
    \right\|_{\mathrm{TV}}
    \leq
    C r^\alpha h(t),
  \end{equation}
  where $\delta_z$ denotes the Dirac mass at $z$, $U=(A/\sqrt N)G$, and
  $G\sim\mathcal N(0,I_N)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:25.041143+00:00","domain":"probability theory","id":"claim_ef53f768b4129c7e523e6e7778bac52908bfe65c88c4ab523317230e0ffd7eac","kind":"theorem","schema_version":1,"statement":"[Proposition 12 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] The weight of the set $\mathcal T_{x_1}$ of arborescences of $K_{n+1}$ and the reduced weight of the set $\hat{\mathcal T}_{x_1}$ of arborescences of $\hat K_{n}$ are related by:
\begin{equation} 
	r\left(\mathcal{T}_{x_1}\right) \,=\, r^\textup{out}(s)\,\ \hat{r}\left(\hat{\mathcal{T}}_{x_1}\right) \,.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:01.898760+00:00","domain":"probability theory","id":"claim_ef5525b290520dfd2ed19813c0b0d6eda7b84d68037ed19ae60063ea21b95689","kind":"lemma","schema_version":1,"statement":"[Lemma dennear of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Let $w\left(x\right)$ be the density function of the reference measure of $H_n\left(x|q\right)$, supported on $\left[-1,1\right]$. For fixed $q \in [0,1)$, we have 
    \begin{equation}
        \lim_{\epsilon \to 0} \sqrt{\epsilon}w\left( 1 - \epsilon\right) = \frac{\sqrt{2} \left(q;q\right)_{\infty}}{\pi}. 
    \end{equation}
    In addition, $\sqrt{1-x}w\left( x\right)$ has a uniform upper bound for $x \in [0,1]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:31:20.609627+00:00","domain":"probability theory","id":"claim_ef561462a0d7376917162ed91cd3c00730d4c7e3b8f8db21d6143969edf61e85","kind":"concept","schema_version":1,"statement":"[Proposition 13 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Let $E$ be a Polish space and $\mu,\nu\in\mathcal{P}(E)$ be two Borel probability measures on $E$. Suppose that $f:E\to E$ is a continuous map. Then we have
    \begin{equation}
        H(f_{\ast}\mu|f_{\ast}\nu)\leq H(\mu|\nu).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.598575+00:00","domain":"probability theory","id":"claim_ef57b6bda39fb5b63f18ea1da10ba8cecf9bd051f224a9938b177ce268b85484","kind":"concept","schema_version":1,"statement":"[Lemma L:basic-stationary-est of arXiv:2604.10020, 'The directed landscape in half-space'] Fix $\alpha_0 \in (0, 1/2)$. There is $c>0$ depending only on $\alpha_0$ such that the following is true. Take parameters $\alpha, \beta$ such that $\alpha > \alpha_0$, $\beta \in (2(1/2 - \alpha)\vee 0, 1/2 - \alpha_0)$. Set
$$
\bar Z^+(i) =\begin{cases}
	Z^+(i) - \frac{i}{1/2 - \beta}, \qquad i \ge 0 \\
	Z^+(i) - \frac{|i|}{1/2 + \beta}, \qquad i < 0.
\end{cases}
$$
 Then for any $i < j \in \mathbb{Z}$ and $m > 0$ we have that
\begin{equation}

\mathbb{P}\Big(\max_{r < s \in \llbracketi,j \rrbracket} |\bar Z^+(s) - \bar Z^+(r)| \ge m\Big) \le 2\exp \left(-\frac{cm^2}{m + (j - i)} \right).
\end{equation}
Moreover, for any $j_0 \in \mathbb{Z}, \delta > 0,$ and $m > 0$ we have that
\begin{equation}

	\mathbb{P}(|\bar Z^+(j_0 + i) - \bar Z^+(j_0)| \le m + \delta i^2 \text{ for all } i \in \mathbb{Z}) \ge 1 - 2\exp \left(-\frac{cm^2}{m + \sqrt{m/\delta}} \right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.581169+00:00","domain":"probability theory","id":"claim_ef5929b70a244e9b205a239364bd4d710be71de74f448177f681d24b1158d8e0","kind":"lemma","schema_version":1,"statement":"[Lemma Fn of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $F(\cdot)$ be defined in (equation F-Euler of the paper). There exists a sequence of locally Lipschitz functions $\{F_n:\mathbb H^s\to \mathbb H^s\}_{n\ge1}$ with $s>\frac{d}{2}+1$ such that the following properties hold:
		\begin{itemize}[leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item If $s>\frac{d}{2}+1$ and $\theta\in(\frac{d}{2},s-1)$, $\{X_n,X\}_{n\ge1}\subset \mathbb H^s$ is bounded, and $\lim_{n\to\infty}X_n=X$ in $\mathbb H^\theta$, then
			$$\lim_{n\to\infty} F_n(X_n)=F(X)\quad \text{in}\quad \mathbb H^{\theta-1}.$$
			\item If (Constant Sound of the paper) holds, then 
			\begin{equation*}
				\sup_{n\ge1}\Abs{\left\langleF_n(X), X\right\rangle _{\mathbb H^s}}\lesssim  \big(\|\nabla u\|_{L^\infty}+\|\nabla \varrho\|_{L^\infty}\big)\|X\|_{\mathbb H^s}^2,\quad X=(\varrho,u)^T\in \mathbb H^{s},\quad s>\frac{d}{2}+1.
			\end{equation*}
			Moreover, if $s>\frac{d}{2}+2$ and $\theta\in(\frac{d}{2}+1,s-1)$, then 
			\begin{align*}
				\left\langleF_n(X)-F_m(Y),X-Y\right\rangle _{\mathbb H^\theta} 
				\lesssim \Big(1+\|X\|^4_{\mathbb H^s}+\|Y\|^4_{\mathbb H^s}\Big)
				\left((n\wedge m)^{-2(s-1-\theta)}+\|X-Y\|^2_{\mathbb H^\theta}\right), \quad X,Y\in\mathbb H^s.
			\end{align*}

			\item If (General Sound of the paper) holds, then 
			\begin{equation*}
				\sup_{n\ge1}\Abs{\left\langleF_n(X), X\right\rangle _{\mathbb H^s}}\lesssim \big(1+\Phi_\Lambda(\|\varrho\|_{L^\infty})\big)\big(\|\nabla u\|_{L^\infty}+\|\nabla \varrho\|_{L^\infty}\big)\|X\|_{\mathbb H^s}^2,\quad X=(\varrho,u)^T\in \mathbb H^{s}.
			\end{equation*}
			Additionally, if $s>\frac{d}{2}+2$ and $\theta\in\left(\frac{d}{2}+1,s-1\right)$, then for all $m,n\ge1$,
			\begin{align*}
				&\left\langleF_n(X)-F_m(Y),X-Y\right\rangle _{\mathbb H^\theta} \\
				\lesssim\ &  \Big(1+ \Phi^2_{\Lambda}\big(\|X\|_{\mathbb H^{s}}+\|Y\|_{\mathbb H^{s}}\big)+\|X\|^4_{\mathbb H^s}+\|Y\|^4_{\mathbb H^s}\Big)
				\left((n\wedge m)^{-2(s-1-\theta)}+\|X-Y\|^2_{\mathbb H^\theta}\right),\quad X,Y\in\mathbb H^s.
			\end{align*}

		\end{itemize}","status":"unverified"}

