\[\textup{(item:triangle_cancellation of the paper)}\ \big|N_{\triangle}(H)\big|\leq K^{\mathcal{D}} n^{3/2}p^{3/2},\quad \textup{(item:c4_cancellation of the paper)}\ \big|N_{\square}(H)\big|\leq K^{\mathcal{D}} n^{2}p^{2},\quad \textup{(item:diamond_cancellation of the paper)}\ \big|N_{\diamond}(H)\big|\leq K^{\mathcal{D}} n^{2}p^{5/2}.\]
