{"assumptions":[],"created_at":"2026-10-27T12:13:31.955602+00:00","domain":"probability theory","id":"claim_ef6b75bf3dde4f1588b234f3eb2ae8459a3aae2ce0f3ee38100a7dd1a04eb61c","kind":"lemma","schema_version":1,"statement":"[Lemma lem:intermediate_recursion of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] For all ${n < N-1}$,
    \begin{align*}
        (\mathtt d^\mathsf{sh}_{n+1})^2
        &\leqslant L_n^2 \,(\mathtt d^\mathsf{sh}_n)^2 + O\bigl((\mathtt E^{\rm w}_n + \zeta_n \mathtt E^{\rm s}_n)\,\mathtt d^\mathsf{sh}_n + (\mathtt E^{\rm s}_n)^2\bigr)\,,
    \end{align*}
    where:
    \begin{itemize}
        \item $L_n$ is the effective contraction constant at iteration $n$ for the ``diffuse then shift'' process given in Lemma~(lem:discrete_contraction of the paper), i.e.,
            \begin{align*}
                L_n = \exp\Bigl(-c\int_{nh}^{(n+1)h} (\omega_+ + \eta_t^\mathsf{p})\,\mathrm{d} t\Bigr)\,.
            \end{align*}
        \item $\mathtt E$ denotes the local errors in the twisted coordinates. Namely, introducing a third process $\tilde\psi$ which starts at $\psi_n^\mathsf{alg}$ and evolves by the diffusion $\boldsymbol{P}$, we define
            \begin{align*}
                \mathtt E_n^{\rm w} \coloneqq \sqrt{\mathbb{E}[\norm{\mathbb{E}[\uppsi^\mathsf{alg}_{n+1} - \tilde \uppsi_{n+1} \mid \mathscr{F}_n]}^2]}\,, \qquad
                \mathtt E_n^{\rm s} \coloneqq \sqrt{\mathbb{E}[\norm{\uppsi^\mathsf{alg}_{n+1}- \tilde \uppsi_{n+1}}^2]}\,,
            \end{align*} 
            where the inner expectations are conditional on the filtration $\mathscr{F}_n$ at iteration $n$.
        \item $\zeta_n$ is the ``coupling constant'', defined in~(equation eq:zeta of the paper) below.
    \end{itemize}","status":"unverified"}

