            \begin{equation}

                \mathbb E\left[\left|\{j>i:s_j=s_i \}\right|\big\vert \mathbf a_i\right] \leq C(\mu,\chi)N(\lambda_{s_i})^{1-o_{\chi}(1)}\cdot N^{O(\chi)}.
            \end{equation}
            on the event $F_i$.
            \item

            There exists $C(\mu,\chi)>0$ such that if $s_i \in \mathsf S^\p _{\for}$, we have that for all $x \in \mathsf S^\p_{\for}$ and $x>_{\lex} s_i$, 
            \begin{equation} 
                \mathbb E\left[\left|E(G_{B_x}) \right|\big\vert \mathbf a_i\right] 
                \leq C(\mu,\chi)N^{2-\frac{K-M}{\log N}\sum_{1 \leq i \leq z} h_i\psi_{\bp^{(i)}}(2)+o_\chi(1)} \cdot(\lambda_{x})^{2-o_\chi(1)} 
            \end{equation}
            on the event $F_i$,
            where $M$ is the length of prefix $x$.
            \item 
             For any prefix $x$ such that $\lambda_x \geq N^{-1+\xi}$, we have 
            \begin{equation}
                \P \lt( \big|\,|\cI(B_x)|-N \lambda_x \big| \leq (N \lambda_x)^{\frac{4}{5}} \big|\mathbf a_i \rt)\geq 1-\exp(-N^{\xi/2})
            \end{equation}
            on the event $F_i$.
            \item 

            For any prefix $x$ such that $\lambda_x \geq N^{-1+\xi}$, we have 
            \begin{equation}
                \P \Big(\Big|n^{(t),x}_{ l}-N \lambda_x \cdot \frac{n^{(t)}_{ l}}{N}\Big| \leq (N \lambda_x)^{\frac{4}{5}} \mbox{  for all $(t,l) \in \mathsf{P}$ and $ M<t\leq K$}\big|\mathbf a_i \Big)\geq 1-\exp(-N^{\xi/2})
            \end{equation}
            on the event $F_i$, where $M$ is the length of prefix $x$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

