{"assumptions":[],"created_at":"2026-10-27T07:10:05.759224+00:00","domain":"probability theory","id":"claim_efe399c65998594ae3b81183cab087b46588d65cbdd47b2dda41c4c2ea1bf0a6","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $\lambda>0$, $f$ be a Bernstein function as in \eqref{definizioneFunzioneBernstein} with $ \bar \nu_f\not=0$ and
	\begin{equation}
		a_k = a_{\lambda,f,k} = \frac{1}{f(\lambda)} \frac{\lambda^k}{k!}\int_0^\infty e^{-\lambda w} w^k \bar \nu_f(\dif w),\ \ \ k\ge1.
	\end{equation}
	\begin{itemize}
		\item[($i$)] $\displaystyle \sum_{k\ge1} a_k = 1-(a+b\lambda)/f(\lambda)$.
		\item[($ii$)] $ \displaystyle f\big(\lambda(1-x)\big) = f(\lambda) \Bigg(1- \sum_{k\ge 1}a_k x^k\Bigg) - b\lambda x ,\ \ \ x\le1. $
		\item[($iii$)] Let  $a'_1 = a_1 + b\lambda/f(\lambda)$ and $a'_k = a_k,\ k\ge2$. Let $F$ be a distribution function and $p$ be a suitable function. $f$ has $a=0$ if and only if
		\begin{equation}
			f\Big(\lambda\big(I-C_F\big)\Big) p= f(\lambda)\big(I-C_{ F_f}\big) p
		\end{equation}
		with $F_f$ being the distribution
		\begin{equation}

		F_f = \sum_{k\ge1} a'_k F^{(k)} = \sum_{k\ge1} a'_k\, \conv_{h=1}^k F, \ \ \ x\in \mathbb{R}.
		\end{equation}
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:25:55.462549+00:00","domain":"probability theory","id":"claim_efe48ed41920297f3a57a7aba69844e7b7763b0b95f31d2dacfc628f5f7d3b67","kind":"concept","schema_version":1,"statement":"[Thm 20 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] If $\{\mathcal{G}^{\varepsilon}\}$ satisfies {Condition A}, then $X^{\varepsilon}$ satisfies the large deviation principle on $\mathcal{E}$ with the
following good rate function $I$ defined by
\begin{equation}
I(f)=\inf_{\{h\in L^2([0,T];U): f= \mathcal{G}^0(\int^{\cdot}_{0}h(s)\dd s)\}}\Big\{\frac{1}{2}\int^T_0|h(s)|^2_{U}\dd s\Big\},\ \ \forall f\in\mathcal{E}.
