{"assumptions":[],"created_at":"2026-10-27T20:14:57.721145+00:00","domain":"probability theory","id":"claim_f07df23aa04cf8cbb2f8ab26fb2ec1fa2d30250fa497e6a63575dfa9139a175e","kind":"theorem","schema_version":1,"statement":"[Thm matmodel of arXiv:2605.31054, 'On the empirical spectral distribution of matrix perpetuities'] Fix ${\mathbb A},{\mathbb B}$ in a $W^*$ probability space $(\mathcal{A},\tau)$. Assume that for each $N\in\mathbb{N}$,
\begin{enumerate}
\item[(i)] ${\mathbf A}^{(N)}, {\mathbf B}^{(N)}\in\mathrm{Sym}_{\geq0}(N)$,
\item[(ii)] $({\mathbf u}_N{\mathbf A}^{(N)} {\mathbf u}_N^\top, {\mathbf u}_N {\mathbf B}^{(N)} {\mathbf u}_N^\top)\stackrel{d}{=}({\mathbf A}^{(N)},{\mathbf B}^{(N)})$ for any orthogonal matrix ${\mathbf u}_N$, 
\item[(iii)] Assume that for any fixed $L\geq 1$ families 
\[
\left\{\left(\left({\mathbf A}^{(N)}_1\right)^{1/2},{\mathbf B}^{(N)}_1\right),\ldots,\left(\left({\mathbf A}^{(N)}_L\right)^{1/2},{\mathbf B}^{(N)}_L\right)\right\}
\]
of independent copies of $({\mathbf A}^{(N)},{\mathbf B}^{(N)})$ are asymptotically free, i.e., converge in noncommutative distribution to the family
\[\left\{({\mathbb A}_1^{1/2},{\mathbb B}_1),\ldots,({\mathbb A}_L^{1/2},{\mathbb B}_L)\right\}\]
of free copies of $({\mathbb A}^{1/2},{\mathbb B})$.
\item[(iv)]  $\tau({\mathbb A})<1$. 
\end{enumerate}
Then, for sufficiently large $N$, there exists a unique solution to 
    \begin{align}
{\mathbf X}^{(N)}\stackrel{d}{=}({\mathbf A}^{(N)})^{1/2} {\mathbf X}^{(N)} ({\mathbf A}^{(N)})^{1/2} +{\mathbf B}^{(N)},\quad ({\mathbf A}^{(N)},{\mathbf B}^{(N)})\mbox{ and }{\mathbf X}^{(N)}\mbox{ are independent},
\end{align}
Moreover,  the expected spectral distribution of ${\mathbf X}^{(N)}$ converges weakly to the distribution of ${\mathbb X}$, which is a unique solution to
    \begin{align}
     {\mathbb X}\stackrel{d}{=}{\mathbb A}^{1/2} {\mathbb X} {\mathbb A}^{1/2}+{\mathbb B},\qquad ({\mathbb A},{\mathbb B})\mbox{ and }{\mathbb X}\mbox{ are *-free.}    
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:45:10.128480+00:00","domain":"probability theory","id":"claim_f07e420cd1ed8fe7ec34af7051202973ad76efdfacac39415bfdd3eae4314c15","kind":"lemma","schema_version":1,"statement":"[Lemma l.growth of arXiv:2505.07145, 'Nonamenable Poisson zoo'] Consider an $\mathbb{N}$-valued stochastic process $(Z_n)_{n\ge 0}$, with increments $Y_{n+1}=Z_{n+1}-Z_n \ge 0$. Define the events, for some $b>0$ and $a>1$,
\begin{equation}
	\mathcal{E}_0 := \left\{ Z_0 \ge b \right\} \qquad \text{and} \qquad \mathcal{E}_{n} := \left\{ Z_n \ge a \cdot  Z_{n-1}  \right\}, \, n \geq 1.
\end{equation}
Let $\mathcal{F}_n$ be the sigma-algebra generated by $\{Z_0,Z_1,\dots, Z_n\}$, and $\mathcal{F}_n^{\mathcal{E}}$ be its restriction on the event $\mathcal{E}_0\cap\dots\cap \mathcal{E}_n$.  Assume that $\mathbb{P} ( \mathcal{E}_0 ) > 0$ and that, for every $n\ge 0$,
\begin{equation}
	\mathbb{E}[Y_{n+1} \,|\, \mathcal{F}_n^\mathcal{E} ] \ge 2a \cdot Z_n
\end{equation}
and
\begin{equation}
	\mathrm{Var}[Y_{n+1} \,|\, \mathcal{F}_n^\mathcal{E} ] \leq C \cdot \mathbb{E}[Y_{n+1} \,|\, \mathcal{F}_n^\mathcal{E} ],
\end{equation}
where we assume that $C<b/2$. Then 
\begin{equation}
	\mathbb{P}\big(Z_n > 0 \text{ for all }n\ge 0\big) \ge \mathbb{P}\left( \bigcap_{n=0}^\infty \mathcal{E}_n \right) > 0\,.
\end{equation}","status":"unverified"}

