			&\big|{\mathbb E}[\mathcal{X}_{s,r}(x,\mu)^ q]- x^ q\big|\leq C_q(1+x^ q)(t-s)\\
			&{\mathbb E}[|\mathcal{X}_{s,r}(x,\mu)-x|^q]\leq C_q(1+x^ q)(t-s)
		\end{align}
		where $C_q$ depends on $q$, the drift $b$, $J$ and $\|f\|_\infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:54:12.434411+00:00","domain":"probability theory","id":"claim_f0b568f758dcb86583c96e1f03e73a6f11c823428d93c063f707a0ffe2864766","kind":"theorem","schema_version":1,"statement":"[Theorem thm: MainHaarDisc of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Let $\bM\sim \operatorname{SymHaar}(\widehat{R}^{n\times n})$. 
     Then, for every fixed prime $p$, 
     \begin{align}
        &\lim_{n\to \infty}\bbP\Bigl(\coker(\bM - x\bI ) \textnormal{ satisfies condition }\cD_p^1 \Bigr) = \Bigl( 1 - \frac{1}{p}\Bigr) \prod_{i=1}^\infty\Bigl(1 - \frac{1}{p^{2i}}\Bigr) , \\
        &\lim_{n\to \infty}\bbP\Bigl(\coker(\bM - x\bI ) \textnormal{ satisfies condition } \cD_p^1 \textnormal{ or }\cD_p^2 \Bigr)= \Bigl(1 - \frac{1}{p^2} \frac{3p-1}{p+1}\Bigr)\prod_{i=1}^\infty\Bigl(1 - \frac{1}{p^{2i}}\Bigr).  
