{"assumptions":[],"created_at":"2026-10-27T08:26:47.197066+00:00","domain":"probability theory","id":"claim_f0d346a96f46e4afe787d2b6c558d8169849c8eb68da08c7aefbe5079acd19f4","kind":"concept","schema_version":1,"statement":"[Lem 116 (temporal smoothing of domain constraint) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $\tvvv^N$ and $\tuuu^N$ be the temporally smoothed quantities from Definition~\ref{d:t.smooth}. Let $J^N\equiv J(p^N,\tep,\lambda)$ be as defined by \eqref{e:bad.times.J}. Then, analogously to 
\eqref{e:domain.plus.coarse} and the bound from Lemma~\ref{l:sp.smooth.domain}, with high probability we have
	\[
	\Tvvv^N(t,y)
	\ge
	\Tuuu^N(t,y)^2
	-\frac{\eta^2}{2}\]
for all $(t,y)\in[q_*,1]\times\R$. We have additionally
	\[\max\left\{
	\begin{array}{c}
	|\tbbb^N(t,y)^2
		-\Tbbb^N(t,y)^2|,\\
	|\tvvv^N(t,y)-\Tvvv^N(t,y)|,\\
	|\tuuu^N(t,y)^2-\Tuuu^N(t,y)^2|
	\end{array}
	\right\}
	\le \bar{\lambda}_N
	\equiv \bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N)^2 \lambda\,.
	\]
for all $(t,y)\in ([q_*,1]  \setminus J^N)\times \bbR$.

\begin{proof}
As discussed in Definition~\ref{d:t.smooth}, 
the coefficients $\tuuu^N$, $\tvvv^N$,  $\Tuuu$, $\Tvvv$, etc.\ are well-defined for all times $t\in[q_*,1]$. The first conclusion follows from Lemma~\ref{l:sp.smooth.domain}: for all $t\in[q_*,1]$,
    \begin{align*}
    \Tvvv^N(t,y)
    &=\tE\bigg[ \frac{\sV^N(t-\sss,y)}
        {p^N(t-\sss)}\bigg]
    \ge
    \tE\bigg[ 
    \frac{\sU^N(t-\sss,y)^2}
        {p^N(t-\sss)
        \cdot (t-\sss)
        (p^N)'(t-\sss)
        }
        \bigg]
         - \frac{\eta^2}{2}\\
    &= \tE[ \suuu^N(t-\sss,y)^2]
    - \frac{\eta^2}{2}
    \ge (\tE[\suuu^N(t-\sss,y)])^2
    - \frac{\eta^2}{2}
    = \Tuuu^N(t,y)^2 -\frac{\eta^2}{2}
    \,.
    \end{align*} 
From Definition~\ref{d:t.smooth}, we have 
	\[\tvvv^N(t,y)
	= \frac{\tV^N(t,y)}{p^N(t)}
	= \frac{\tE[\sV^N(t-\sss,y)]}{p^N(t)}\]
Since $(p^N)'\le L^2$ by \eqref{e:sdelimits.pprime},
the difference between
$p^N(t)$ and $p^N(t-\sss)$ is at most
$L^2\tep$. Moreover, since we restrict to $t\ge q_*$ as defined by \eqref{e:qbar.and.qstar}, it follows by recalling \eqref{e:breve.q.bounds} that 
\beq
p^N(t)\ge \brep=\frac1{L^{\breve{c}}}\,.\eeq
Combining with the bound on $\sV^N$ from Lemma~\ref{l:sp.smooth.reg} gives, for $t\in [q_*,1]$, 
	\[
	\Big|\tvvv^N(t,y)
	-\Tvvv^N(t,y)\Big|
	=\bigg|
	\frac{\tE[\sV^N(t-\sss,y)]}
		{p^N(t)}
	-\tE\bigg[ \frac{\sV^N(t-\sss,y)}
		{p^N(t-\sss)}\bigg]\bigg|
	\le \bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N)^2 \tep\,.\]
Now applying Lemma~\ref{l:sp.smooth.domain} gives, for all $t\in[q_*,1]$,
	\[
	\frac{\sU^N(t,y)^2}
		{p^N(t)
		\cdot t
		(p^N)'(t)
		} - \frac{\eta^2}{2}
	\le \frac{\sV^N(t,y)}
		{p^N(t)}
	\le \bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N)^2\,,
	\]
which also implies a bound on $\sU^N$. 
Finally we note that if $t\in [q_*,1]  \setminus J^N$, then
	\begin{align*}
	\Big|\tuuu^N(t,y)
	-\Tuuu^N(t,y)\Big|
	&=\bigg|
	\frac{\tE[\sU^N(t-\sss,y)]}
		{p^N(t) \cdot t (p^N)'(t)}
	-\tE\bigg[\frac{\sU^N(t-\sss,y)}
		{p^N(t-\sss) \cdot
		(t-\sss) (p^N)'(t-\sss)}
		\bigg]
	\bigg| \\
	&\le
	\bigg(\frac{ \trK L}{\sep}\bigg)^{O(1)} 
	(\MAX_N) \lambda\,,
	\end{align*}
using the bound on $\sU^N$ noted above. It follows that
for $t\in [q_*,1] \setminus J^N$ we have
	\[
	\Big|\tuuu^N(t,y)^2
	-\Tuuu^N(t,y)^2\Big|
	\le
	\Big|\tuuu^N(t,y)
	-\Tuuu^N(t,y)\Big|
	\Big|\tuuu^N(t,y)^2
