\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:39:18.537166+00:00","domain":"probability theory","id":"claim_f10eea2559368e06560f284c7d51c758de8cb144e8be47889325ada68c62ac2a","kind":"theorem","schema_version":1,"statement":"[Proposition 25 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] For every measurable positive function $f: \R^d \to [0,\infty)$, the following holds. 
\begin{enumerate}
    \item If
    \begin{equation}

    \begin{split}
        \left(\frac{2(k+1)}{dk-\alpha-1}\right)^{\frac{k+1}{(d+2)k-\alpha+1}}  \left( \frac{w_d k}{k - (\alpha + 1)} \right)^{-\frac{k}{(d+2)k + 1 - \alpha}} \cdot \\ \cdot\left( \int f^{k+1} |xb| dx \right)^{- \frac{1} {(d+2)k + 1-\alpha}} E^{\frac{k+1}{(d+2)k + 1 - \alpha}}\le \bar\rho
        \end{split}
    \end{equation}
    then
    \begin{equation*}
    \begin{split}
        \|f\|_1 &\le C(k,d,\alpha)\left( \int f^{k+1} |xb| dx \right)^{\frac{2}{(2+d)k + 1 - \alpha}} E^{\frac{dk - \alpha - 1}{(d+2)k + 1 - \alpha}}
     \end{split}
    \end{equation*}
    \item If
    \begin{equation}

    \begin{split}
        \left(\frac{1}{\beta\bar\rho}\right)^{-\frac{\alpha(k+1)}{((d+2)k+1)k}} \left(\frac{2(k+1)}{dk-1}\right)^{\frac{k+1}{(d+2)k+1}}\left( \frac{w_d k}{k -  1} \right)^{-\frac{k}{(d+2)k + 1 }} \cdot \\ \cdot\left( \int f^{k+1} |xb| dx \right)^{- \frac{1} {(d+2)k + 1}} E^{\frac{k+1}{(d+2)k + 1}} \geq \bar \rho,
        \end{split}
    \end{equation}
    then 
    \begin{equation*}
    \begin{split}
        \|f\|_1 &\le C(k,d,\alpha)\left(\frac{1}{\beta\bar\rho}\right)^{\frac{2\alpha(k+1)}{((d+2)k+1)k}}\left( \int f^{k+1} |xb| dx \right)^{\frac{2}{(2+d)k + 1 }} E^{\frac{dk - 1}{(d+2)k + 1 }}.
     \end{split}
    \end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.872570+00:00","domain":"probability theory","id":"claim_f11060539c804c2129abfe90d5e3c6857ee67f0935cc25737aec9d961a3d91f6","kind":"theorem","schema_version":1,"statement":"[Prop martingalep of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] Let $\eta(t)$ be from (prop11112 of the paper) with $a=2$. Define $\eta(t)=0$ if $t\le 0$. On the full binary tree $\mathbb{T}$ and with $\Theta_v$ as in (equation agedef of the paper), 
define
\begin{equation} 
\mathscr{X}_n(t)=\sum_{|v|=n-1}2\eta(\alpha^n(t-\Theta_v)),\ \ \ \ \forall\,n\ge 1.
\end{equation}
 Then
\begin{enumerate}[(i)]
\item The sequence $\{\mathscr{X}_n(t)\}$ satisfies the stochastic Picard iterations (equation pant_bin_iter of the paper) for the binary pantograph 
process  with ground state $\mathscr{X}_0(t)=\eta(t)$, corresponding to $a=2$ and $w_0=0$, i.e.
\begin{equation}
{{\mathscr{X}}_{n}}(t)=\left\{ \begin{array}{*{35}{l}}
   0 & \text{if} & T_\theta\ge t,  \\
   \mathscr{\mathscr{X}}_{n-1}^{(1)}(\alpha (t-T_\theta))+\mathscr{X}_{n-1}^{(2)}(\alpha (t-T_\theta)) & \text{if} & T_\theta<t.  \\
\end{array} \right.
