\item For each $t>0$, $\{\mathscr{X}_n(t)\}$ is a martingale with respect to the filtration $\mathcal{F}_n=\sigma(T_v:\,|v|\le n)$.
\item The limit $\mathscr{X}(t)=\lim_{n\to\infty}\mathscr{X}_n(t)$ exists. Moreover, $\mathbb{E}(\mathscr{X}(t))=\eta(t)$, and
for any $\delta\in(1,1/\gamma)$, $\mathbb{E}(\mathscr{X}^\delta(t))\le \frac{\eta_\delta(t)}{2^{\delta}}$, where $\eta_\delta$ 
is given in (exampleone of the paper).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:33:06.540508+00:00","domain":"probability theory","id":"claim_f11077b64ecb16c3abf43156701db7a494576b98b35d9dd25bcb0bb7f83d1bca","kind":"concept","schema_version":1,"statement":"[Lemma 2 of arXiv:2608.25887, '\bf Efficient Estimation of High Information Projections using Nearest Neighbours'] Let $X_1, X_2, ...$ be i.i.d. random variables with density $f_X$ satisfying Conditions C1--C4. Let $0 < a \leq b$ and let $\{k(n)\}_{n\in \mathbb{N}}$ satisfy $\lim_{n \to \infty} k(n) = \infty$ and $\lim_{n\to\infty} k(n)/n = 0$. Then
    \begin{align*}
        \lim_{n \to \infty} \sup_{\x \in Supp(X)} \Bigg(E\left[\frac{\nnnd{\x,n}{k(n)+1}^b}{\nnnd{\x,n}{k(n)}^a}\right] - E\left[\nnnd{\x,n}{k(n)+1}^{b-a}\right]\Bigg) &= 0.
