		\end{equation}
		As a consequence,
		\begin{equation}
			C_d = 		\frac{1}{2^{d-1}\sqrt{\pi}(d-1)!}\frac{\Gamma\left(\frac{d}{2}\right)^{d}}{\Gamma\left(\frac{d+1}{2}\right)^{d-1}}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.534305+00:00","domain":"probability theory","id":"claim_f1253e3029ecf8ce399341e0011b1b53675566ce62285860963d014407e33bd0","kind":"concept","schema_version":1,"statement":"[Prop pr:key_estimate of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $i,j\in \mathbb{N}$ and $\alpha \geqslant 0$, then for every $\mathsf{r} \in (\frac{50}{27}, 2)$, and every $N,k \in \mathbb{N}$ satisfying
