{"assumptions":[],"created_at":"2026-10-27T13:49:06.337572+00:00","domain":"probability theory","id":"claim_f12ce40759b8e20a58eaf953d0fd9a78173f1d07dd58c0caabafb7f5e6435b22","kind":"lemma","schema_version":1,"statement":"[Lemma lem:RiemannSums of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] Let $f: \xi \in \mathbb{R}^{2} \to f(\xi) \in [0, \infty)$ be smooth, radial, decreasing in $|\xi|$, and integrable.  Then it holds that
\begin{equation}
\left(\frac{2\pi}{L} \right)^{2}\sum_{\xi \in \Lambda_{L}^{*}}f(\xi) \geq \frac{1}{4}\int_{\mathbb{R}^{2}}f(\xi)d\xi. 
\end{equation}
Furthermore, the following bound holds
\begin{equation}
\bigg |\int_{\mathbb{R}^{2}}f(\xi)d\xi -\left(\frac{2\pi}{L} \right)^{2}\sum_{\xi \in \Lambda_{L}^{*}}f(\xi) \bigg | \leq 3 \cdot \left(\frac{2\pi}{L} \right)^{2}f(0)+4 \cdot\left(\frac{2\pi}{L} \right) \int_{0}^{\infty} f(\eta_{1},0)d \eta_{1}. 
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:38:13.637359+00:00","domain":"probability theory","id":"claim_f12d2b1f8a2dd174f2e208e7010525fccbc241b3d8efe902e7749095b9ef3cda","kind":"lemma","schema_version":1,"statement":"[Lemma 10 of arXiv:2609.00680, 'Sharp embeddings between quasi-Banach Besov spaces and shallow ReLU Variation spaces'] Fix $A>0$ and an integer $R_0>k+d+2$. Let $0<h\leq1$,
$x_0\in\mathbb R^d$, and $\psi\in C_c^\infty(\R^d)$ satisfy
$\supp\psi\subset B(0,A)$. Set
\begin{equation}

\psi_h(x):=\psi\left(\frac{x-x_0}{h}\right).
\end{equation}
The following estimate holds:
\begin{equation}
\|\psi_h\|_{\mathcal{L}_1(\mathcal{D})}
\lesssim h^{-k}
\max_{|\alpha|\leq R_0}\|D^\alpha\psi\|_{L^\infty(\mathbb R^d)}.
\end{equation}
The implicit constant may depend on $d$, $k$, $A$, $R_0$, and $\Omega$,
but is independent of $h$, $x_0$, and $\psi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:49:15.415656+00:00","domain":"probability theory","id":"claim_f12e4101bdd970d23e5eb268a40a37c1cf75591e00914d401e97d3fdf28bddfc","kind":"concept","schema_version":1,"statement":"[Lemma component-epsilon of arXiv:2608.27904, 'Instantons, indefinite 4-manifolds, and Dehn surgery'] If $W: (Y, \mathfrak a) \to (Y', \mathfrak a')$ is a nice cobordism, and $\theta \in \mathfrak Z(Y) \cong H^1(Y;\mathbb F_2)$, the map $\varepsilon_0$ is given by 
