{"assumptions":[],"created_at":"2026-10-26T20:46:26.256337+00:00","domain":"probability theory","id":"claim_f1335ac7b55399daef14fb652b7b07bd49d2476350f2bca1398bf2d859cd6cf8","kind":"concept","schema_version":1,"statement":"[Cor 48 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that $F$ is compact.
\begin{itemize}
  \item [$\rm{(i)}$]The condition $1_{\kappa,2}$ holds for $\kappa\in \left[ \frac{1}{2},\frac{2}{3}\right)$ with 
    \begin{align*}
      c_1(t,\kappa,2)=\g{c}{suffcond2,1}t^{-(3\kappa-1)},\quad t\in (0,1],
    \end{align*}
    and $2_{\kappa,p,q}$ holds for $p,q=1,2,$ and $\kappa\in [1/2,1]$ with the following constants:
    \begin{align*}
      c_2(\alpha,t,\kappa,1)=\g{c}{suffcond1,1}t^{-3},\quad c_2(\alpha,t,\kappa,2)=(\g{c}{suffcond1,1})^{1/2}t^{-5/2},
    \end{align*}
     \begin{align*}
       c_3(\alpha,t,\kappa,1)= \g{c}{suffcond1,2} \alpha^{-(2\kappa-1)}t^{-(\kappa+2)},
      \quad c_3(\alpha,t,\kappa,2)= (\g{c}{suffcond1,1})^{1/2}\g{c}{suffcond1,2} \alpha^{-(2\kappa-1)}t^{-(\kappa+5/2)}.
     \end{align*}

  \item [$\rm{(ii)}$]Assume that the assumption $\rm{(A1)}$ is satisfied. 
  Then the condition $1_{\kappa,p}$ holds for $p=1,2$ with the following constants:
   \begin{align*}
    c_1(t,\kappa,1)=\g{c}{c_1,1}t^{-\frac{2\kappa s_0+3\kappa-1}{1+s_0}},\quad t\in (0,1],\kappa\in \left[\frac{1}{2},\frac{s_0+1}{2s_0+3}\right),
   \end{align*}
      \begin{align*}
    c_1(t,\kappa,2)=\g{c}{suffcond2,2}t^{-(3\kappa-1)},\quad t\in (0,1],\kappa\in \left[\frac{1}{2},\frac{2}{3}\right).
   \end{align*}
   Also, the condition $2_{\kappa,p,q}$ is satisfied for $p,q=1,2,$ and $\kappa\in [1/2,1]$ with the following.
     \begin{equation*}
     c_2(\alpha,t,\kappa,1)=c_{\rm{A1}}t^{-\left(2+\frac{s_0}{1+s_0}\right)},\quad 
    c_2(\alpha,t,\kappa,2)=c_{\rm{A1}}^{1/2}t^{-\left(2+\frac{s_0}{2(1+s_0)}\right)},
  \end{equation*}
  \begin{equation*}
  c_3(\alpha,t,\kappa,1)= c_{\rm{A1}}^{1/2}\g{c}{suffcond1,2}\alpha^{-( 2\kappa-1 )} t^{-(\kappa+2+\frac{s_0}{2(1+s_0)})}.
  \end{equation*}
  The constant $c_3(\alpha,t,\kappa,2)$ is same as in $\mathrm{(i)}$.

  \item [$\rm{(iii)}$]
  Assume that the assumption $\rm{(A2)}$ is satisfied. 
  Then the condition $1_{\kappa,p}$ holds for $p=1,2$ with the following constants:
   \begin{align*}
    c_1(t,\kappa,1)=\g{c}{c_1,2}t^{-\frac{2[(1+s_0)\theta-s_1]\kappa+s_0\theta+s_1}{2(1+s_0)\theta}},\quad t\in (0,1],\kappa\in \left[\frac{1}{2},  \frac{(2+s_0)\theta-s_1}{2[(1+s_0)\theta-s_1]}\right),
   \end{align*}

   \begin{align*}
    c_1(t,\kappa,2)=\g{c}{suffcond1,3} t^{-[\kappa-\frac{s_1}{2(1+s_0)\theta}(2\kappa-1)]} \quad t\in (0,1],\kappa\in\left[\frac{1}{2},1\right].
   \end{align*}
   Also, the condition $2_{\kappa,p,q}$ is satisfied for $p,q=1,2$ and $\kappa\in [1/2,1]$ with the following.
     \begin{equation*}
     c_3(\alpha,t,\kappa,1)=c_{\rm{A1}}^{\kappa}\g{c}{suffcond1,3}\alpha^{-(1+\frac{s_1}{2(1+s_0)\theta})( 2\kappa-1 )} t^{-(\kappa+2+\frac{s_0}{2(1+s_0)})},
  \end{equation*}
  \begin{equation*}
    c_3(\alpha,t,\kappa,2)=\g{c}{suffcond1,3}\alpha^{-(1+\frac{s_1}{2(1+s_0)\theta})(2\kappa-1)}t^{-(\kappa+2)}.
  \end{equation*}
  The constants $c_2(\alpha,t,\kappa,1)$ and $c_2(\alpha,t,\kappa,2)$ are same as in $\rm{(ii)}$.

  \item [$\rm{(iv)}$]
    Assume that the assumption $\rm{(A3)}$ is satisfied. 
  Then the condition $1_{\kappa,p}$ holds for $p=1,2$ with the following constants:
   \begin{align*}
    c_1(t,\kappa,1)=\g{c}{c_1,3}t^{-\frac{2[(1+s_0)\Theta-s_1]\kappa+s_0\Theta+s_1}{2(1+s_0)\Theta}},\quad t\in (0,1],\kappa\in \left[\frac{1}{2},  \frac{(2+s_0)\Theta-s_1}{2[(1+s_0)\Theta-s_1]}\right),
   \end{align*}

   \begin{align*}
    c_1(t,\kappa,2)=\g{c}{suffcond1,4} t^{-[\kappa-\frac{s_1}{2(1+s_0)\Theta}(2\kappa-1)]} \quad t\in (0,1],\kappa\in\left[\frac{1}{2},1\right].
   \end{align*}
   Also, the condition $2_{\kappa,p,q}$ is satisfied for $p,q=1,2$ and $\kappa\in [1/2,1]$ with the following constants:  
     \begin{equation*}
     c_3(\alpha,t,\kappa,1)=c_{\rm{A1}}^{\kappa}\g{c}{suffcond1,4}\alpha^{-(1+\frac{s_1}{2(1+s_0)\Theta})( 2\kappa-1 )} t^{-(\kappa+2+\frac{s_0}{2(1+s_0)})},
  \end{equation*}
  \begin{equation*}
    c_3(\alpha,t,\kappa,2)=\g{c}{suffcond1,4}\alpha^{-(1+\frac{s_1}{2(1+s_0)\Theta})(2\kappa-1)}t^{-(\kappa+2)} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:55.645379+00:00","domain":"probability theory","id":"claim_f1342a21387d898d358f106feede4f4398bc9f844a43ca2165e0c4521d4728c6","kind":"concept","schema_version":1,"statement":"[Theorem 10 (TV local-error bound for tRLMC) of arXiv:2605.24937, '2605.24937'] Assume \hyperref[ass:PJG]{\textup{(A1)}}--\hyperref[ass:D]{\textup{(A4)}} and let \(\lambda\in(0,\lambda_{\max}^{\mathrm{tRLMC}}]\). Then there exist constants \(C_1,C>0\), independent of \(N\) and \(\lambda\), such that for all \(\mu,\nu\in\mathcal P_2(\R^d)\) and all \(N\in\mathbb N\) with \(N\ge3\),
\begin{equation}
  TV\!\bigl(\mu\,\widetilde P^{N}\,\big\|\,\nu\,P^{N}\bigr)
  \;\le\;
  C_1\,\frac{1}{\sqrt{\lambda}}\,\W(\mu,\nu)
  \;+\;
  C\lambda \sqrt{\,\bigl((N\lambda)\vee \log N\bigr)} .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.645242+00:00","domain":"probability theory","id":"claim_f13a8602ad0011989887b35f650c7cb630d2e7904edae3fa043a15d2bb5d76a6","kind":"concept","schema_version":1,"statement":"[Thm discrete-conv of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\tau_\delta$ be a critical XOR-Ising model in the setup of Theorem (thm:ES-XOR of the paper). As $\delta\to 0$, 
    \begin{equation}
        \big(\delta^{-1/4}\tau_\delta,\ (\delta^{-1/4}\mu_k^\delta)_{k\geq1},\ (C_k^\delta)_{k\geq1},\ (\xi_k^\delta)_{k\geq1}\big) \overset{(d)}{\longrightarrow} \big(\tau,\ (\mu_k)_{k\geq1},\ (C_k)_{k\geq1},\ (\xi_k)_{k\geq1}\big),
    \end{equation}
    where the limiting law is that of Theorem (thm:cont-XOR of the paper). Under the obvious modifications, the same statement holds for $+/+$ boundary conditions. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:38:13.645184+00:00","domain":"probability theory","id":"claim_f13b5395c40141931bc7ea55016880c166822f673ba21063447e8d9fe2cf7545","kind":"theorem","schema_version":1,"statement":"[Prop 5 of arXiv:2609.00719, 'On the Aleksandrov--Bakelman--Pucci estimates for the weighted $1$-Laplacian'] Let $u\in C(\R^n)$ have compact support, and let $\Gamma$ be the quasiconcave envelope of $u^+$.
Then the following properties hold.
\begin{enumerate}
\renewcommand{\labelenumi}{(\roman{enumi})}
\item For every $a>0$,
\begin{equation}
\operatorname{Conv}(\{u^+\geq a\})=\{\Gamma\geq a\}.
\end{equation}
Moreover, for every $a\geq0$,
\begin{equation}
\operatorname{Conv}(\{u^+>a\})=\{\Gamma>a\}.
\end{equation}
\item Every modulus of continuity of $u^+$ is also a modulus of continuity of $\Gamma$.
In particular, if $u$ is $L$-Lipschitz, then $\Gamma$ is $L$-Lipschitz.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:47:40.729670+00:00","domain":"probability theory","id":"claim_f13c200ae6689f89ae573e74704da5a701b66bfcf55335ea86b563f789ae7f67","kind":"lemma","schema_version":1,"statement":"[Lemma lem:tildeH-convex of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] The modified Hamiltonian $\tilde H^+$ is concave in $\mathcal{D}_+$, and
    \begin{align*}
        -\nabla^2_{\mathsf{Sp}} \tilde H^+ +\frac1\beta \mathrm{Ric}\succeq \kappa_\textsc{be} I.
    \end{align*}
    for a constant $\kappa_{\textsc{be}} >0$. The same holds for $\tilde H^-$ on $\mathcal D_-$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.364404+00:00","domain":"probability theory","id":"claim_f13ef1b858974e7881d105a17c0b722a3694d32d801df92db4228b72aa9f8aac","kind":"lemma","schema_version":1,"statement":"[Lemma lem:bounds_for_J_sigma(phi) of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $F \in \mathcal{C}^2$. There exists a random variable $\Psi$ such that for all $s \in [0, 1], x \in {\mathbb{R}}^d$, we have 
    \begin{equs}
        \| \blue{F (\phi^{s,x})}\|_{\mathcal{D}^{2H_-}_B([s, 1])}& + \| \blue{J^{s,x}}\|_{\mathcal{D}^{2H_-}_B([s, 1])} + \| \blue{(J^{s,x})^{-1}}\|_{\mathcal{D}^{2H_-}_B([s, 1])}
        \\
        & + \| \blue{\nabla J^{s,x}}\|_{\mathcal{D}^{2H_-}_B([s, 1])} + \|  \blue{\nabla(J^{s,x})^{-1}}\|_{\mathcal{D}^{2H_-}_B([s, 1])}\leq \Psi.
    \end{equs}
    Moreover, for any $p \geq 1$, there exists a constant $C=C( H_-, p, \| \sigma\|_{\mathcal{C}^4}, \| F\|_{\mathcal{C}^2})$ such that $\| \Psi \|_{L_p(\Omega)} \leq C$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.304991+00:00","domain":"probability theory","id":"claim_f1400217eb576f3538c7f3765da0204f25512ee5e5cdf5868b3e368d9ab38a77","kind":"concept","schema_version":1,"statement":"[Theorem MainRes of arXiv:2411.06089, '{\Large \bf Averaging principle for semilinear slow-fast rough partial differential equati'] Assume that $(\mathbf{H1})$-$(\mathbf{H5})$ hold. Then for each initial values $x\in \mathcal{H}_\eta$ and $y \in \mathcal{H}$ with $\eta \in (\gamma-1/4,\gamma) $, we have
	\begin{equation}
		\lim_{\varepsilon\rightarrow 0}  \mathbb E\big[\|X^\varepsilon-\bar{X}\|_{\eta, 0}^{2}\big]=0,
	\end{equation}
	where $\bar{X}_t$ is the unique solution of the corresponding averaged equation
	\begin{equation*}
		\left\{ \begin{aligned}
			d\bar{X}_t&=\big[ A \bar{X}_t+\bar{F}_1 (\bar{X}_t)\big]dt+G_1(\bar{X}_t)d \mathbf B_t,\\
			\bar{X}_0&=x,
		\end{aligned} \right.
	\end{equation*}
	with the averaged coefficient $\bar{F}_1 (x):=\displaystyle \int_{\mathcal{H}} F_1 (x,y) \mu^x (dy)$ for $x\in\mathcal{H}$, where $\mu^x$ is the unique invariant measure with respect to the Markov semigroup of frozen equation
 \begin{equation}\nonumber
\left\{ \begin{aligned}
	d Y_t&=\big[A Y_t+F_2(x,Y_t)\big]dt+G_2(x,Y_t) d \widetilde{W}_t,\\
	Y_0&= y.
\end{aligned} \right.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.225328+00:00","domain":"probability theory","id":"claim_f1425fb1cf70aec5d3ccac9734167b6193fadc07b871b4fcc33f3febf1443874","kind":"lemma","schema_version":1,"statement":"[Lemma apx_lemma: random_walk_expected_hitting_size of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $G$ be a quasi-transitive graph of superlinear polynomial growth.

    For any $K_1, K_2 \ge 1$, there exist constants $c = c(G, K_1, K_2)$ and $C = C(G)$, such that for any $a \ge 2$, $x \in V$, and $D \subseteq B_x(K_1 a)$ with $|D| \ge |B_x(a)|/K_2$, we have



    \begin{align}
        c \cdot \theta(a) \leq \sum_{y \in D} \mathbb P_x \left( \tau_y \le a^2 \right) \leq C \cdot \theta(a) \, ,
    \end{align}
    where $\theta(a)$ is defined as 
    \begin{align*}
        \theta(a) := \begin{cases}
            a^2 & \text{if } d \geq 3, \\
            a^2 / \log a & \text{if } d = 2.
        \end{cases}
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:47:04.947907+00:00","domain":"probability theory","id":"claim_f1454b92ed2ee9f289a6d33197337bd0d0b8b3e2228c46d7113066c8b10e2e6a","kind":"concept","schema_version":1,"statement":"[Theorem bmdirexists of arXiv:2412.03067, 'Geodesic Trees and Exceptional Directions in FPP on Hyperbolic Groups'] [BM19]

	Consider FPP on $\Gamma$ under Assumption (assume-subexp of the paper). For $o\in \Gamma$, and for $\mathbb{P}$- a.e. $\omega \in \Omega$,  $\omega$-geodesic rays starting at $o$ have a direction $\xi\in {\partial G}$.

	Fix $\xi \in \partial G$ and $x_{n}\in {\Gamma}$ such that $x_{n}\to \xi$. For $\mathbb{P}$-a.e.\ $\omega \in \Omega$ the sequence of $\omega-$geodesics $[o,x_n]_\omega$ from $o$ to $x_n$ converges (up to extracting a subsequence) to an $\omega-$geodesic ray $[o,\xi)_\omega$ having direction $\xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:49.204303+00:00","domain":"probability theory","id":"claim_f14864d149287a3cfcdddcefb1931f664e963aff600501a3e48d09194bb037aa","kind":"concept","schema_version":1,"statement":"[Theorem 4 (Graph sparsification~\protect{\cite[Thm.~1) of arXiv:2604.27119, '\Large Applied Random Matrix Theory\relatedversion'] {SS11:Graph-Sparsification}}]
Let $\mtx{L}$ be the Laplacian~\eqref{eqn:graph-laplacian} of a weighted graph
on $n$ vertices, and let $\widehat{\mtx{L}}$ be the Laplacian~\eqref{eqn:sparse-graph}
of a random sparse graph with at most $q$ edges.  With probability at least $1 - \delta$,
the random matrix $\widehat{\mtx{L}}$ is an $\eps$-approximation of $\mtx{L}$ in the sense~\eqref{eqn:graph-spectral-equiv}
