{"assumptions":[],"created_at":"2026-10-27T06:21:45.321292+00:00","domain":"probability theory","id":"claim_f17b935053b6f9062e343719abe7d699f259693077fd30d32af0ad8de51d3bd9","kind":"theorem","schema_version":1,"statement":"[Theorem 5 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Let $\mathcal{X}(t)$, $t \geq0$, be a stochastic process in $\RR^d$ with $\mathcal{X}(0) =0$, with stationary and independent increments. Assume that for some linear operator $E$ one has $\mathcal{X}(ct)\stackrel{\text{d}}{=} c^E\mathcal{X}(t)$, for all $t>0$, and that the law of $\mathcal{X}(1)$ is full. Let $X_n$, $n\in\NN$, be a sequence of r.v.'s in $\mathbb{R}^d$, in the domain of attraction of some full operator stable law as in \eqref{defopstable}, with $b_n=0$, $n\in \NN$, and with $Y \stackrel{\text{d}}{=}\mathcal{X}(1)$. Then there exists a regularly varying function $B$ with operator $-E$ such that
		\begin{align}
			B(n) \sum_{i=1}^n X_i \to \mathcal{X}(1),\quad \text{as $n\to+\infty,$}  
		\end{align}
		in distribution.
		Furthermore, as $c \to +\infty$,
		\begin{align}
			B([c]) \sum_{i=1}^{[ct]} X_i \to  \mathcal{X}(t)
		\end{align}
		and the convergence holds both in the sense of all finite-dimensional distributions and weakly on $D([0, +\infty), \mathbb{R}^d)$ with the $J$ topology.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.452068+00:00","domain":"probability theory","id":"claim_f17c3cbe9bfa4f06cdaa1cdbe68e0f7fbef8d4a55b53b4159dd35ff4a0393145","kind":"concept","schema_version":1,"statement":"[Theorem thm : PointPoint of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] There exists a function $J_{\mathrm{pp}}  : \mathcal{X} \rightarrow \intervallefo0\infty$, such that for all $x,y\in X$ and $\zeta > a \norme[1]{x-y}$,
    \begin{equation}

        \lim_{n\to\infty}-\frac1n \log\Pb{ \vphantom{\BoxPT} \mathbf T\p{\!\mathopen{}\mathclose\bgroup\originalleft\lfloor nx \aftergroup\egroup\originalright\rfloor\!, \!\mathopen{}\mathclose\bgroup\originalleft\lfloor ny \aftergroup\egroup\originalright\rfloor\!} \le n \zeta } =  \lim_{n\to\infty} -\frac1n \log\Pb{ \BoxPT\p{\!\mathopen{}\mathclose\bgroup\originalleft\lfloor nx \aftergroup\egroup\originalright\rfloor\! ,\!\mathopen{}\mathclose\bgroup\originalleft\lfloor ny \aftergroup\egroup\originalright\rfloor\! } \le n\zeta } = J_{\mathrm{pp}} (x-y, \zeta),
    \end{equation}
    where $\floor\cdot$ denotes the componentwise floor function. Moreover:
    \begin{enumerate}[(i)]
        \item

         $J_{\mathrm{pp}} $ is convex and absolutely homogeneous.
        \item

         For all $(x,\zeta)\in \mathcal{X}$,
        \begin{equation}
            J_{\mathrm{pp}} \mathopen{}\mathclose\bgroup\originalleft( x, \zeta \aftergroup\egroup\originalright) = J_{\mathrm{pp}} \mathopen{}\mathclose\bgroup\originalleft( \module x,\zeta \aftergroup\egroup\originalright),
        \end{equation}
        where $\module x$ denotes the vector of $\mathbb{R}^d$ whose components are the modules of $x$'s components. 

        \item 

        For all $(x_1,\zeta_1), (x_2,\zeta_2)\in \mathcal{X}$, if $0\le x_1 \le x_2$ for the componentwise order and $\zeta_1 \ge \zeta_2$, then
        \begin{equation}
            J_{\mathrm{pp}} (x_1, \zeta_1) \le J_{\mathrm{pp}} (x_2, \zeta_2).
        \end{equation}

        \item 

        For all $(x,\zeta) \in \mathcal{X}$, $J_{\mathrm{pp}} (x,\zeta)=0$ if and only if $\zeta \ge \mu(x)$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.764660+00:00","domain":"probability theory","id":"claim_f180fde27389b04b152086d9242aa5e553ede754f0b8a8f529f94d45ea47c942","kind":"lemma","schema_version":1,"statement":"[Lem thm:1+eps of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $(X_{j,\tau})_{j\in\mathds{N}_0,\tau\in\mathds{N}}$ be a family of non-negative i.i.d.\ random variables, $d\in\mathds{N}$, $\eps\in (0,\infty)$, and $\sigma\in [1,\infty)$.
Suppose that
\begin{equation*}
\mathds{E}[X_{j,\tau}^{\sigma(1+\eps)}]<\infty.
\end{equation*}
Let
\begin{align*}
M_j&\mathrel{\mathop:}= \#\setcond{m\in\mathds{Z}^d}{\left\lVertm\right\rVert_{\infty}\leq 2^j}=(2^{j+1}+1)^d,\\
N_j&\mathrel{\mathop:}=\#\setcond{m\in\mathds{Z}^d}{2^j<\left\lVertm\right\rVert_\infty\leq 2^{j+1}}=M_{j+1}-M_j
\end{align*}
for $j\in\mathds{N}_0$.
Then, for
\begin{equation*}
\Xi\mathrel{\mathop:}= \sup_{j \in \mathds{N}_0} \lr{\frac{1}{M_j} \sum_{\tau=1}^{M_j} X_{j,\tau}+\sup_{\ell\geq j} \frac{1}{N_\ell} \sum_{\tau=M_\ell + 1}^{M_{\ell+1}} X_{j,\tau}},
\end{equation*} 
we have $\mathds{E}[\Xi^\sigma]<\infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.237497+00:00","domain":"probability theory","id":"claim_f1826b598c2d74ba3591b8a2c80af756d41f1072c8f4a501750e3af5efef288b","kind":"theorem","schema_version":1,"statement":"[Corollary 40 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(k\) be a perfect field and let
