{"assumptions":[],"created_at":"2026-10-26T19:47:01.662478+00:00","domain":"probability theory","id":"claim_f195513ea6848aa8378ad901ccdc3e98bb7b491d92daf67c570054ae60fe0b25","kind":"concept","schema_version":1,"statement":"[Theorem 6 of arXiv:2604.23610, 'Scaling limits of Lévy walks with random velocities'] Let $\{W_V\left(t\right)\}_{t\ge0}$ be the continuous LW with random velocities generated by the sequence $\left\{V_i, \, T_i, \, \mathbf{J}_i\right\}_{i\in \mathbb{N}}$. Then,
\begin{enumerate}
    \item if $\alpha<\beta$, we have
    \begin{equation}
        \frac{1}{n}W(nt) \xrightarrow[n \to \infty]{U} L_{V, \alpha}(t) = 
        \begin{cases}
            \big(\mathbf{L}_{\alpha}^-(S_{\alpha}^{-1}(t))\big)^+, & t\in\mathcal{R}(S_{\alpha}),\\[1ex]
            \begin{aligned}
                &\big(\mathbf{L}_{\alpha}^-(S_{\alpha}^{-1}(t))\big)^+ + \frac{t-G(t)}{H(t) - G(t)}\\
                &\quad \times \big(\mathbf{L}_{\alpha}(S_{\alpha}^{-1}(t)) - \big(\mathbf{L}_{\alpha}^-(S_{\alpha}^{-1}(t))\big)^+\big),
            \end{aligned} & t\notin \mathcal{R}(S_{\alpha}).
        \end{cases}
    \end{equation}

    \item if $\alpha>\beta$, we have
    \begin{equation}
        \frac{1}{n}W(nt) \xrightarrow[n \to \infty]{U} L_{V, \beta}(t) = 
        \begin{cases}
            \big(\mathbf{L}_{\beta}^-(S_{\alpha}^{-1}(t))\big)^+, & t\in\mathcal{R}(S_{\alpha}),\\[1ex]
            \begin{aligned}
                &\big(\mathbf{L}_{\beta}^-(S_{\alpha}^{-1}(t))\big)^+ + \frac{t-G(t)}{H(t) - G(t)}\\
                &\quad \times \big(\mathbf{L}_{\beta}(S_{\alpha}^{-1}(t)) - \big(\mathbf{L}_{\beta}^-(S_{\alpha}^{-1}(t))\big)^+\big),
            \end{aligned} & t\notin \mathcal{R}(S_{\alpha}).
        \end{cases}
    \end{equation}

    \item if $\alpha=\beta$, we have
    \begin{equation}
        \frac{1}{n}W(nt) \xrightarrow[n \to \infty]{U} L_{V, \alpha}^{\text{log}}(t) = 
        \begin{cases}
            \big(\mathbf{L}_{\alpha}^{\text{log}-}(S_{\alpha}^{-1}(t))\big)^+, & t\in\mathcal{R}(S_{\alpha}),\\[1ex]
            \begin{aligned}
                &\big(\mathbf{L}_{\alpha}^{\text{log}-}(S_{\alpha}^{-1}(t))\big)^+ + \frac{t-G(t)}{H(t) - G(t)}\\
                &\quad \times \big(\mathbf{L}_{\alpha}^{\text{log}}(S_{\alpha}^{-1}(t)) - \big(\mathbf{L}_{\alpha}^{\text{log}-}(S_{\alpha}^{-1}(t))\big)^+\big),
            \end{aligned} & t\notin \mathcal{R}(S_{\alpha}),
        \end{cases}
    \end{equation}
    where the processes 
        where $\mathcal{R}\left(S_{\alpha}\right) = \left\{S_{\alpha}\left(t\right):\, t\geq0\right\} \subset\left[0, \infty\right)$, $G\left(t\right) = S_{\alpha}^{-}\left(S_{\alpha}^{-1+}\left(t\right)\right)$, $H\left(t\right) = S_{\alpha}\left(S_{\alpha}^{-1+}\left(t\right)\right)$ and $\overunderset{U}{n \to \infty}{\to }$ means uniform convergence.
\end{enumerate}
    \begin{proof}
        According to Lemma \ref{vectorconv}, we have the convergence of the underlying joint vector of jumps and waiting times. Then, by Theorem 4.11 in \cite{Magdziarz2015b} for part 1 and 3, we have that the process
        \begin{equation}
            n^{-1/\alpha}W\left(n^{1/\alpha}t\right)
        \end{equation}
    converges weakly to $\left\{L_{V, \alpha}\left(t\right)\right\}_{t\geq0}$ in Skorokhod $\mathbb{M}_1$ topology. Because the sample paths of the limiting process $\left\{L_{V, \alpha}\left(t\right)\right\}_{t\geq0}$ are continuous according to Lemma 4.4 in \cite{Magdziarz2015b}, thus convergence also holds in the stronger uniform topology $U$. Since $b^{-1}\left(n\right) = n^{-1/\alpha}$ is regularly varying with index $1/\alpha$ there exists a function $\overset{\sim}{b}\left(n\right)$ regularly varying with index $\alpha$ such that $b\left(\overset{\sim}{b}\left(n\right)\right)^{-1} \sim n$ as $n\to\infty$. Replacing $n$ by $\overset{\sim}{b}\left(n\right)$ in Eq. \eqref{scaledw} we obtain the thesis. The proofs of the parts 2 and 3 are analogous. The form of the L\'evy triplets of the limiting processes follows directly from Lemma \ref{vectorconv}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.563363+00:00","domain":"probability theory","id":"claim_f19aebc149a96b762df9a553ebd56743f1cbeaa797556fa99ce467ee472c3f4c","kind":"theorem","schema_version":1,"statement":"[Proposition pro.ak-inputs of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Fix any $\beta_h\in(0,1/8]$. There exist deterministic constants $C=C(d,\Lambda,r_0,\beta_h)<\infty$ and $c=c(d,\Lambda,r_0,\beta_h)>0$, a deterministic exponent $\sigma=\sigma(d,\Lambda,r_0,\beta_h)\in(0,1)$, and a random scale $\mathcal{X}_{\beta_h}\colon\Omega\to[0,\infty)$ with the following properties. First, the random scale has a stretched-exponential tail:
		\begin{equation}
			\mathbb{Q}\bigl(\mathcal{X}_{\beta_h}\ge M\bigr)\le C\exp\bigl(-c M^\sigma\bigr)\qquad\text{for every }M\ge 0\, .
		\end{equation}
		Second, on a $\mathbb{Q}$-full-probability event, the following estimates hold for every integer $M\ge \mathcal{X}_{\beta_h}(\omega)$.
		\begin{itemize}
			\item Let $k\in\{1,d\}$, let $u\in H^1(\square_M;\mathbb{R}^k)$, and let $f\in H^{1/6}(\square_M;\mathbb{R}^k\otimes\mathbb{R}^d)$ satisfy $-\nabla\cdot(\mathbf{a}\nabla u)=\nabla\cdot f$ componentwise in $\square_M$. Then
			\begin{equation}
				3^{-M/6}\|(\mathbf{a}-\bar{\mathbf{a}})\nabla u\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-1/6}(\square_M)}\le C 3^{-\beta_h M}\bigl(\|\nabla u\|_{\underline L^2(\square_M)}+3^{M/6}[f]_{\underline H^{1/6}(\square_M)}\bigr)\, .
			\end{equation}
			\item For every $j$ with $1\le j\le d$,
			\begin{equation}
			\begin{aligned}
				&3^{-M}\|w_{j,M}-x_j\|_{\underline L^2(\square_M)}
				+3^{-M/6}\|\nabla w_{j,M}-e_j\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-1/6}(\square_M)}\\
				&\qquad
				+3^{-M/6}\|\mathbf{a}\nabla w_{j,M}-\bar{\mathbf{a}} e_j\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-1/6}(\square_M)}
				\le C 3^{-\beta_h M}\, .
			\end{aligned}
			\end{equation}
		\end{itemize}","status":"unverified"}

