{"assumptions":[],"created_at":"2026-10-28T00:45:32.093363+00:00","domain":"probability theory","id":"claim_f1e0c2a28f506df6acc2d777d876a8e5eaa4147633167e6181a7691f8f649fdc","kind":"concept","schema_version":1,"statement":"[Theorem theorem 1 of arXiv:2411.14350, 'Randomized Geodesic Flow on Hyperbolic Groups'] There exists a measure $\Theta$ on $\partial^2 G$ satisfying 
\begin{equation}
\frac{{\rm{d}}\Theta}{{\rm{d}} (\nu_o\otimes\nu_o)} (\xi,\eta)\asymp {\rm e} ^{2(\xi,\eta)_o^{{\mathcal G}}} \qquad\forall (\xi,\eta)\in \partial^2 G, 
\end{equation}
which can be constructed explicitly in the following three measure-equivalent ways:
\begin{enumerate}
\item As the measure $\Theta_1$ given by
\begin{equation}
\Theta_1(A) = \int_{A} \lim_{n\to\infty} \sum_{z=-n}^n\bigg[\frac{1}{2n+1} \, \frac{{\rm{d}}(\nu_{p_z}\otimes \nu_{p_z})}{{\rm{d}}(\nu_{o}\otimes \nu_{o})}(\xi,\eta)\bigg]\;{\rm{d}}(\nu_{o}\otimes \nu_{o})(\xi,\eta)
\end{equation}
for $A\subset \partial^2 G$, where $(p_z)_{z\in\mathbb{Z}}=(p_z(\xi,\eta))_{z\in\mathbb{Z}}$ is a fixed quasi-geodesic between $\xi$ and $\eta$. 
\vspace{2mm}
\item As a disintegrated version $\Theta_2$ of $\Theta_1$, defined by
\begin{equation}
\Theta_2(A) = \int_{A} \lim_{n\to\infty} \sum_{z=-n}^n \bigg[\frac{1}{2n+1} \,\frac{{\rm{d}}(\nu_{x_z}\otimes \nu_{x_z})}{{\rm{d}}(\nu_{o}\otimes \nu_{o})}(\xi,\eta)\bigg]\;{\rm{d}}\bar\mathbb{P}_o\big((x_n)_{n\in\mathbb{N}}\big),
\end{equation}
for all $A\subset\partial^2 G$, where $\xi={\rm bd} (x_n)_{n\in\mathbb{N}}$ and $\eta={\rm bd} (x_{-n})_{n\in\mathbb{N}}$.
\vspace{2mm}
\item  As the push forward $\Theta_3(\cdot)= \widehat\mathbb{Q}({\rm bd} ^{-1}(\cdot))$ of the measure $\widehat\mathbb{Q}$ (defined in (equation def QZ int of the paper)) under the boundary map ${\rm bd} : G^{\mathbb{Z}}\to \partial^2 G$. The measure $\Theta_3$ is invariant under the action of $G$ on $\partial^2G$. 
\end{enumerate}
Finally, the measure $\Theta$ on $\partial^2 G$ is 
\begin{itemize}
    \item quasi-invariant under the $G$-action with uniformly bounded Radon-Nikodym derivatives $\frac{{\rm{d}} g_{\ast}\Theta}{d\Theta}$, and
    \item ergodic under the action of $G$ on $\partial^2 G$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:46.471418+00:00","domain":"probability theory","id":"claim_f1e22a0481553183994331f8992f4dce84c72ce8121bd4ab45fa50858d248685","kind":"definition","schema_version":1,"statement":"[Definition 100 (Geometric $L^{\infty}$ norms) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] For scalar functions or $\ell_{t,u}$-tangent tensorfields $\upxi$, we define 
	the following $L^{\infty}$ norm on the double-null tori $\doublenulltoritwoarg{\ubar}{u}$:
	\begin{align} 
		\| \upxi \|_{L^{\infty}\left(\doublenulltoritwoarg{\ubar}{u}\right)}
		& 
		\eqdef 
		\mbox{ess sup}_{(x^2,x^3) \in \mathbb{T}^2}
		|\upxi|_{\gtorus}(\ubar,u,x^2,x^3),
	\end{align}
	where on RHS\,\eqref{E:GEOLINFINITYDOUBLENULLTORUS}, we are viewing
