{"assumptions":[],"created_at":"2026-10-27T12:43:43.359451+00:00","domain":"probability theory","id":"claim_f34a375e95767d3d14c26cc86c6e7974082bfc77e2a6aee59da0220a8bec6082","kind":"concept","schema_version":1,"statement":"[Proposition of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] The following estimates hold.
\begin{enumerate}
\item[(i)] \textbf{Duality.} Let $s \in \mathbb R$ and $p_1,p_2,q_1,q_2 \in [1,\infty]$ such that $\frac 1{p_1} + \frac 1{p_2} = \frac 1{q_1} + \frac 1{q_2} = 1$. Then
	\begin{equation}
	\left| \int_{\mathbb T^d} f g dx  \right| \leq
	\| f \|_{B^{-s}_{p_1,q_1}} \|g \|_{B^s_{p_2,q_2}}, \qquad \forall f,g \in C^\infty(\mathbb T^d). 
	\end{equation}
\item[(ii)] \textbf{Fractional Leibniz.} Let $s \in \mathbb R$, $p,p_1,p_2,p_3,p_4,q \in [1,\infty]$ satisfy $\frac 1p = \frac 1{p_1} + \frac 1{p_2} = \frac 1{p_3} + \frac 1{p_4}$. Then there exists $C>0$ such that
	\begin{equation}
	\| fg \|_{B^s_{p,q}} \leq C\| f \|_{B^s_{p_1,q}} \| g \|_{L^{p_2}} + \| f \|_{L^{p_3}} \|g \|_{B^s_{p_4,q}}, \qquad \forall f,g \in C^\infty(\mathbb T^d).
	\end{equation}
\item[(iii)] \textbf{Interpolation.} Let $s,s_1,s_2 \in \mathbb R$ such that $s_1 < s < s_2$, $p,p_1,p_2,q,q_1,q_2 \in [1,\infty]$ and $\theta \in (0,1)$ satisfy
	\begin{equation}
	s= \theta s_1 + (1-\theta)s_2, \quad \frac 1p = \frac \theta {p_1} + \frac{1-\theta}{p_2}, \quad \frac 1q=\frac \theta {q_1} + \frac{1-\theta}{q_2}.
	\end{equation}
	Then there exists $C>0$ such that 
	\begin{equation}
	\| f \|_{B^s_{p,q}}\leq C\| f \|_{B^{s_1}_{p_1,q_1}}^\theta \| f \|_{B^{s_2}_{p_2,q_2}}^{1-\theta}.
	\end{equation}
\item[(iv)] \textit{Bernstein inequalities.} Let $R>0$ and let $B_{\mathbb Z^d}(R) = \{ n \in \mathbb Z^d : |n| \leq R \}$. Let $s_1, s_2 \in \mathbb R$ such that $s_1 < s_2$, $p,q \in [1,\infty]$. There exists $C>0$ such that 
\begin{equation}
\| f \|_{B^{s_2}_{p,q}}\leq C R^{s_2 - s_1} \| f \|_{B^{s_1}_{p,q}}, \qquad \forall f,g \in C^\infty(\mathbb T^d)
\end{equation}
and
\begin{equation}
\| g \|_{B^{s_1}_{p,q}}\leq CR^{s_1 - s_2}\| g \|_{B^{s_2}_{p,q}},	
\end{equation}
for $f,g \in C^\infty(\mathbb T^d)$ such that $\mathrm{supp} (\mathcal F f) \subset B_{\mathbb Z^d}(R)$ and $\mathrm{supp} (\mathcal F g) \subset \mathbb Z^d \setminus B_f(R)$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

