{"assumptions":[],"created_at":"2026-10-27T19:45:17.707606+00:00","domain":"probability theory","id":"claim_f374a4485962c794578c52e9075681da6a7e0b82f3739ed3845f6f276b84c5fc","kind":"lemma","schema_version":1,"statement":"[Lemma lem:condi_hold of arXiv:2604.10214, 'Large deviations for maximum local time of simple random walk in dimensions \texorpdfstrin'] Let $(\gamma_i:i\ge 1)$ be i.i.d.\ $\mathrm{Exp}(1)$ random variables. Conditionally on $\big\{\xi(\widehat n,x):x\in\mathbb{Z}^d\big\}$, $\mathcal{N}$, $\big(Y_{\tau_j}:1\le j\le \mathcal{N}\big)$ and $\big(\mathcal{M}_j:1\le j\le \mathcal{N}\big)$, the following hold: 
        \begin{itemize}
            \item The holding times $\Big\{\sigma(i,x),\,\sigma_1(x)\mathbf{1}_{x\in \{Y_{\tau_j}\}},\, \sigma_2(x)\mathbf{1}_{x\in \{Y_{\tau_j}\}}:1\le i\le \xi(\widehat n,x)\Big\}$ are independent across different $x\in\mathbb{Z}^d$;
            \item For any $x\in \mathbb{Z}^d\setminus\{Y_{\tau_j}\}$, 
            \[\Big(\sigma(i,x):1\le i\le \xi(\widehat n,x)\Big)\overset{d}{=} \Big(\big(\gamma_i:1\le i\le \xi(\widehat n,x)\big)\,\Big|\,\sum_{i=1}^{\xi(\widehat n,x)}\gamma_i<\Lambda_n\Big);\]
            \item For any $x\in \{Y_{\tau_j}\}$,
            \begin{align*}
                &\Big(\sigma_1(x),\,\sigma(i,x):1\le i\le \mathcal{R}_j-1\Big)\overset{d}{=} \Big(\big(\gamma_i:1\le i\le \mathcal{R}_j\big)\,\Big|\,\sum_{i=1}^{\mathcal{R}_j}\gamma_i=\Lambda_n\Big),\\
                &\Big(\sigma_2(x),\sigma(i,x):\mathcal{R}_j+1\le i\le \xi(\widehat n,x)\Big)\overset{d}{=}\big(\gamma_i:1\le i\le \xi(\widehat n,x)-\mathcal{R}_j\big),
            \end{align*}
            and these two collections of holding times are mutually independent.
        \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:45:01.784426+00:00","domain":"probability theory","id":"claim_f37594131ec372122e16b369ea4656789ab619f497162792c861e45a3a749dec","kind":"theorem","schema_version":1,"statement":"[Proposition prop:OU of arXiv:2512.17736, 'Pathwise uniqueness by noise for singular stochastic PDEs'] Assume (H0 of the paper), (H1 of the paper), (H2_0 of the paper), (H3_0 of the paper) and let $t>0$. 
    Then, for every $n\in\mathbb N_+$ it holds
    \[
    R_{n,t}(C^0_b(H_n))\subseteq C_b^{\infty}(H_n)\,.
    \]
    Moreover, for every $\gamma\geq-\delta$ there exist 
    $M_{\gamma,\delta}>0$ and 
    $M_\gamma>0$
    such that
    for every and $n\in\mathbb N_+$ it holds
    \begin{alignat*}{2}
        \norm{A_n^\gamma D(R_{n,t}\varphi)}_{C^0_b(H_n; H_n)}
        &\leq \frac{M_{\gamma,\delta}}{t^{\frac12+\gamma+\delta}}
        {\left\|\varphi\right\|}_{C^0_b(H_n)}
        \qquad&&\forall\,\varphi\in C^0_b(H_n)\,,\\
        \norm{A_n^\gamma D(R_{n,t}\varphi)}_{C^0_b(H_n; H_n)}
        &\leq \frac{M_{\gamma}}{t^{\max\{0,\gamma\}}}
        {\left\|\varphi\right\|}_{C^1_b(H_n)}
        \qquad&&\forall\,\varphi\in C^1_b(H_n)\,,\\
        \norm{D(A_n^{\gamma}D(R_{n,t}\varphi))}_{C^0_b(H_n; {\mathscr L}(H_n))}
        &\leq\frac{M_{\gamma,\delta}}{t^{1+\gamma+2\delta}}\|\varphi\|_{C^0_b(H_n)}
        \qquad&&\forall\,\varphi\in C^0_b(H_n)\,,\\
        \norm{D(A_n^{\gamma}D(R_{n,t}\varphi))}_{C^0_b(H_n; {\mathscr L}(H_n))}
        &\leq\frac{M_{\gamma,\delta}}{t^{\frac12+\gamma+\delta}}\|\varphi\|_{C^1_b(H_n)}
