{"assumptions":[],"created_at":"2026-10-28T00:59:45.548348+00:00","domain":"probability theory","id":"claim_f3869a2780168d743b368664b9b131ecb83b56729849bb0ab76b72570558adc0","kind":"lemma","schema_version":1,"statement":"[Lemma le:estforpsi of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] Let $\gamma_*:=\exp\left(-\dfrac{\pi}{e}\bigl(e^{\frac16}-1\bigr)\right)\approx 0.811$. 
For each $\alpha>0$, $\alpha\neq1$ and each $\gamma\in(\gamma_*,1)$, we define
\begin{equation*}
    D(\alpha,\gamma):=\left(\frac{\pi|\alpha-1|}{-e\alpha\log\gamma}\right) ^{\frac{|\alpha-1|}{2}}.
\end{equation*}
Then
\begin{enumerate}[label=\arabic*)]
    \item for $\alpha\in(0,1)$,
    \begin{equation*}

        \psi(\alpha,\lambda) < C_1(\alpha,\gamma)e^{-\alpha\lambda}E_\alpha\left(\Bigl(\dfrac{\alpha}{\gamma}\lambda\Bigr)^{\alpha } \right), \quad\lambda>0,
    \end{equation*}
where
    \begin{equation*}

        C_1(\alpha,\gamma):=\sqrt{\alpha}e^{\frac{1}{12\alpha}} D(\alpha,\gamma);
    \end{equation*}
\item for $\alpha>1$, 
\begin{equation*}    
    \psi(\alpha,\lambda)> 
C_2(\alpha,\gamma)e^{-\alpha\lambda}E_\alpha\left(\bigl(\alpha\gamma\lambda\bigr)^{\alpha } \right),    
\end{equation*}
where
    \begin{equation*}

        C_2(\alpha,\gamma) := \sqrt{\alpha} e^{-\frac{\alpha }{12}}\frac{1}{D(\alpha,\gamma)}.
    \end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:04:39.787749+00:00","domain":"probability theory","id":"claim_f38aa0748ab163f4faf0f76e3d5c59797784e7b7d4f9906bdbcbc4ba0fa84f6e","kind":"theorem","schema_version":1,"statement":"[Proposition prop:harmonic-grad-c3 of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] Under (lem:tailrl-regularity of the paper), for every $T\geq1$,
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}^{(T)}(\theta;x)
=
\sum_{k=1}^{T}
\frac{1}{k}
\nabla_\theta\text{Best-of-}k(\theta;x).

\end{equation}
Equivalently,
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}^{(T)}(\theta;x)
=
\int_0^1
\frac{1-\left(1-p_\theta(x,\tau)\right)^T}
{p_\theta(x,\tau)}
\nabla_\theta p_\theta(x,\tau)
\,d\tau,

\end{equation}
where the ratio is interpreted by continuity as $T$ when $p_\theta(x,\tau)=0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.225216+00:00","domain":"probability theory","id":"claim_f38ae4dd2a954770cd9efe514e0ae4100ce3d5446a563c65216b37000fdab233","kind":"lemma","schema_version":1,"statement":"[Lemma sub-gaussian_cts_quasi of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $G$ be a quasi-transitive graph of polynomial growth. Then, there exist constants $c_{1},c_{2},C_{1},C_{2}>0$ depending on $G$ such that
\begin{equation}
  \frac{c_{1}}{t^{d/2}} e^{-d_{G}^{2}(x,y)/c_{2}t} \leq p_{t}(x,y) \leq \frac{C_{1}}{t^{d/2}} e^{-d_{G}^{2}(x,y)/C_{2}t}
\end{equation}
for all $x,y \in V, t\geq 1$ with $d_{G}(x,y) \leq t$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.555501+00:00","domain":"probability theory","id":"claim_f38f16aad763e4041e3f392a28bceb89ffd9f86765e8b473546c23fd58e5dbb1","kind":"theorem","schema_version":1,"statement":"[Proposition prop:asymptotic_order of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] \begin{compactitem}
