{"assumptions":[],"created_at":"2026-10-26T19:20:15.486858+00:00","domain":"probability theory","id":"claim_f3b941fce8f708ce67d4fd065cdfd48620707089074a03df62ea1393a95555c5","kind":"theorem","schema_version":1,"statement":"[Thm 85 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For the generation $m=0$ and $n\geq 1$ odd,
\begin{displaymath}
\psi^{\rm gen}_{n,m=0} = 
\sum_{j=0}^{+\infty}
\Big(
\sigma_{m=0,j}
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big),
\end{displaymath}
where the infinite sum in $j$ converges in $L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.
Moreover,
\begin{displaymath}
\E\Big[\Vert \psi^{\rm gen}_{n,m=0}\Vert_{H^{-\eta}(\C)}^{2}\Big] = 
\sum_{j=0}^{+\infty}
\E\Big[
\Big\Vert
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big].
\end{displaymath}
For $n\geq 2$ even,
\begin{multline*}
\psi^{\rm gen}_{n,m=0} =
\\
\sum_{j=0}^{+\infty}
\Big(
\Big(
\sum_{0\leq k < \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{0}}^{k}\psi_{n-2k,m=0,j}
\Big)
+
(-1)^{n/2} \dfrac{n!}{2^{n/2} (n/2)! }
\ind_{\inter(\Gamma_{m=0,j})}
V_{A^{\rm gen}_{0}}^{n/2}
\Big).
\end{multline*}
For the generations $m\geq 1$ and $n\geq 1$ odd,
\begin{multline*}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
=
\\
\sum_{j=0}^{+\infty}
\Big(
\sigma_{m,j}
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,m,j}
\Big),
\end{multline*}
and
\begin{multline*}
\E\Big[
\Big\Vert
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
=
\\
\sum_{j=0}^{+\infty}
\E\Big[
\Big\Vert
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,m,j}
\Big)
\Big\Vert_{H^{-\eta}(\C)}^{2}
\Big].
\end{multline*}
For $n\geq 2$ even,
\begin{multline*}
\sum_{0\leq k <\lfloor n/2\rfloor}
(-1)^{k}\dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen, +}_{m-1}}^{k}
\psi^{\rm gen}_{n-2k,m}
=
\\
\sum_{j=0}^{+\infty}
\Big(
\Big(
\sum_{0\leq k< \lfloor n/2\rfloor}
(-1)^{k} \dfrac{n!}{2^{k} k! (n-2k)!}
V_{A^{\rm gen}_{m}}^{k}\psi_{n-2k,j}
\Big)
+
\ind_{\inter(\Gamma_{m,j})}
(-1)^{n/2} \dfrac{n!}{2^{n/2} (n/2)! }
(V_{A^{\rm gen}_{m}}^{n/2} - V_{A^{\rm gen, +}_{m-1}}^{n/2})
\Big)
.
\end{multline*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:51:52.062287+00:00","domain":"probability theory","id":"claim_f3bb5cd67a355199c9b030d37bbb228b2abeeb82cbfefff99090211d7578f7bc","kind":"concept","schema_version":1,"statement":"[Lemma eq:lem-4.6 of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $G = (V, E)$ be a finite graph containing $0$, and $\mu$ a monotonic measure on $\{0, 1\}^E$. Then, for any $n \in \mathbb N^*:=\{1,2,\ldots\}$, we have
  \begin{equation}
    \sum\limits_{e \in E} \mathrm{Cov}(\mathbf 1_{(0 \leftrightarrow \partial \Lambda_n)}, \omega(e)) \geqslant \frac n {4 \max\limits_{x \in \Lambda_n} \sum\limits_{k=0}^{n-1} \mu(x \leftrightarrow \partial \Lambda_k(x))} \mu(0 \leftrightarrow \partial \Lambda_n) (1 - \mu(0 \leftrightarrow \partial\Lambda_n)).

  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:25:35.747840+00:00","domain":"probability theory","id":"claim_f3bb5f2eabbb7ffee59cf0a23692cba2c8495a6561793ad0f02a59e6afe13e81","kind":"theorem","schema_version":1,"statement":"[Proposition prop convergence of deterministic of arXiv:2603.09008, 'On the statistics of random-to-top shuffles'] Let $\pi$ be a uniformly random permutation of $[n]$ and let $0<a\leq 1$ be a constant. Then, we have
    \begin{equation}

    L_{a,n}:=n-\max_{1\leq i\leq \lfloor an \rfloor} (\pi(i))+\sum_{i=1}^{\lfloor an \rfloor} \1(\pi(i)=i)\Rightarrow_d X+Y
    \end{equation}
    where $X$ and $Y$ are independent random variables with $X\sim\operatorname{Poisson}(a)$ and $Y$ is a geometric random variable with parameter equal to $a$ and $P(Y=k)=a(1-a)^k$. If $a_n\in(0,1]$ is a sequence with $a_n\to a\in(0,1]$ as $n\to\infty$ such that for some $\alpha>0$, we have $a_n>\alpha>0$ for all $n$, then $L_{a_n,n}$ has the same limiting distribution as $L_{a,n}$ in equation $(equation convergence of deterministic model of the paper)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:17:34.001856+00:00","domain":"probability theory","id":"claim_f3bb88c1f696722d27e167ab02abf378ebac71ccd90466245feaf899f36130c8","kind":"lemma","schema_version":1,"statement":"[Lemma 56 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $A\in\mathbb C^{N\times N}$ and let $X(z)$ and $Y(z)$ be respectively $\mathbb C^{N\times m}$-valued and $\mathbb C^{m\times m}$-valued, and analytic on the spectrum
  of $A$. Then, for $a\in\sigma(A)$,
  \begin{equation}
    {\rm Res}_{z=a}(zI_N-A)^{-1}
    X(z)Y(z)={\rm Res}_{z=a}(zI_N-A)^{-1}PY(z)
\end{equation}
