\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Poincare-type-Boolean}}}(p)=2^{1-p}/\Beta(\frac{1}{2};\frac{p}{2},\frac{p}{2})$, where $\Beta(x;a,b) := \int_0^x t^{a-1} \left(1-t\right)^{b-1} \dif t$ is the incomplete Beta function. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.897619+00:00","domain":"probability theory","id":"claim_f3c595bf58a91d14aa9fba90ab74c070b7d22cee07f0614a4baae3201a7808bb","kind":"lemma","schema_version":1,"statement":"[Lemma lem:bessympt of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] For any $u\in \mathbb{R}^n$, we have
\begin{equation} 
K_{\mathbdx{h};n}(
u)=\fint_{\mathbbm{B}^{n}} e^{i\langle u , \xi \rangle} \dd \xi=\frac{(2\pi)^{\frac{n}2}}{b_{n}}\frac{J_{\frac{n}{2}}(|u|)}{|u|^{\frac n 2}},\quad  \text{and} \quad |\nabla_u^\alpha K_{\mathbdx{h};n}(u)|\le C(1+|u|)^{-\frac{n+1}{2}},\ \forall \alpha\in \mathbb{N}^n;
\end{equation}    
\begin{equation} 
K_{\mathbdx{b};n}(
u)=\fint_{\mathbbm{S}^{n-1}} e^{i\langle u , \xi \rangle} \dd \xi=\frac{(2\pi)^{\frac{n}2}}{s_{n-1}}\frac{J_{\frac{n-2}{2}}(|u|)}{|u|^{\frac{n -2} 2}},\quad  \text{and} \quad |\nabla_u^\alpha K_{\mathbdx{b};n}(u)|\le C(1+|u|)^{-\frac{n-1}{2}},\ \forall \alpha\in \mathbb{N}^n;
