\end{multline*}
and
\begin{multline*}
\mathbb E_r\sum_{y\in \mathbb Z^d} \sum_{x\in K} \sum_{z\in K_y} \mathbbm{1}(0\nleftrightarrow y, \|x-z\| \leq r) |K||K_y|^2 P(y)
