        \mathbb{P}_n\big(\cX_{j-1} = \{x^{j-1}_{k_1},\ldots, x^{j-1}_{k_{m_2}}\}\,\big|\,\mathcal{G}_j\big)=\binom{q_n(j-1)}{m_2}^{-1} \p_n\big(\#\{\kp(u^{j}_i):1\le i\le m_1\}=m_2\big).
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.360595+00:00","domain":"probability theory","id":"claim_f477d257779b3f719efa2041f2e18db932b101acbb61f457d7c8eb997f0232e0","kind":"definition","schema_version":1,"statement":"[Definition 38 (Sampled vertex sets) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Fix $h_* \le j \le h^*$.  Conditionally on the tree $\mathscr{T}^n$, we define the sampled vertex set $\widetilde{\cX}_j$ as follows:
