{"assumptions":[],"created_at":"2026-10-27T13:52:23.571915+00:00","domain":"probability theory","id":"claim_f536e2d1a11e32e5a29cc8fe7466e9eba2247bfb9bda034392bb9576868fad62","kind":"concept","schema_version":1,"statement":"[Theorem T:Infinity of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] For $\alpha>0$, $\beta\in (0, 2)$ and $\gamma\ge 0$, the fundamental solution
  $G(1,x)$ has the following asymptotic expansions:
  \begin{enumerate}[\rm (i)]

    \item If $\alpha\not\in 2 \mathbb{N}$, then, as $|x|\to+\infty$,
          \begin{align*}
            G(1,x) = \Theta_1\: |x|^{-(d+\alpha)} + o\left(|x|^{-(d+\alpha)}\right),
          \end{align*}
          with
          \begin{align*}
            \Theta_1 \coloneqq 2^{d (1-1/\alpha)+\alpha-1}\nu^{1+d/\alpha}\pi^{-(1+d/2)} \frac{\Gamma\left((d+\alpha)/2\right) \Gamma\left(1+\alpha/2\right)}{\Gamma(2\beta+\gamma)} \sin\left(\pi\alpha /2\right).
          \end{align*}

    \item If $\alpha = 2$, then, as $|x|\to+\infty$,
          \begin{align*}
            G(1,x)
             & = \Theta_{2,1}\: |x|^{\frac{\alpha(d/2+1-(\beta+\gamma))}{2-\beta}-d} \exp\left( - \Theta_{2,2} |x|^{\alpha/(2-\beta)} \right) \left(1+O\left(|x|^{-\alpha/(2-\beta)}\right)\right),
          \end{align*}
          with
          \begin{align*}
            \Theta_{2,1} & = 2^{d\left(1-\frac{1}{\alpha}\right) + \frac{(1-\alpha)\left(d/2+1-(\beta+\gamma)\right)}{2-\beta}} \pi^{-d/2} \nu^{\frac{d}{\alpha} -\frac{d/2+1-(\beta+\gamma)}{2-\beta}}
            (2-\beta)^{-1/2} \beta^{\frac{-4\gamma+\beta (d-3)+2}{4-2\beta}}>0,                                                                                                                         \\
            \Theta_{2,2} & = 2^{(1-\alpha)/(2-\beta)} \nu^{-1/(2-\beta)} (2-\beta) \beta^{\beta / (2-\beta)} > 0.
          \end{align*}

    \item If $\alpha \in 2\mathbb{N}+2$, then, as $|x|\to+\infty$, write
          $\ell\coloneqq \alpha/2\in\mathbb{N}$ (so $\ell\ge 2$) and
          \begin{align*}
            G(1,x) & = \Theta_{3,1}\: |x|^{\frac{\alpha(d/2+1-(\beta+\gamma))}{\alpha-\beta}-d}
            \cos\left(\Theta_{3,2} - \Theta_{3,3}\cos\left(\theta_{\alpha,\beta}\right)\: |x|^{\alpha/(\alpha-\beta)}\right)                                                                     \\
                   & \quad \times \exp\left(- \Theta_{3,3}\sin\left(\theta_{\alpha,\beta}\right)\: |x|^{\alpha/(\alpha-\beta)}\right) \left(1+O\left(|x|^{-\alpha/(\alpha-\beta)}\right)\right),
          \end{align*}
          where $\theta_{\alpha,\beta}\in (0, \pi/2)$ is defined in~(equation E:theta of the paper)
          and
          \begin{align*}
            \Theta_{3,1} & = 2^{\frac{\alpha ^3+\alpha ^2 (2 d-\beta )-2 \alpha  (2 (\beta +\gamma -1)+(\beta +1) d)+4 \beta  d}{4 \alpha  (\alpha -\beta)}}
            \pi^{(\alpha/2-d-1)/2}
            \nu^{\frac{d}{\alpha} -\frac{d/2+1-(\beta+\gamma)}{\alpha-\beta}}                                                                                \\
                         & \quad \times \alpha^{\frac{\beta(1-d)+2\ell(2\beta+2\gamma-3)}{4\ell-2\beta}}
            \left(\alpha-\beta\right)^{-1/2}
            \beta^{\frac{\beta(1+d)-2 \ell(2\beta +2\gamma-1)}{4\ell-2\beta}},                                                                               \\
            \Theta_{3,2} & = \pi\left(\frac{\alpha}{2}-1\right)\left(\frac{d}{2}+1-(\beta+\gamma)\right)(\alpha-\beta)^{-1},                                 \\
            \Theta_{3,3} & = 2^{1/(\alpha-\beta)} \nu^{-1/(\alpha-\beta)} \alpha^{\alpha/(\beta-\alpha)} (\alpha-\beta) \beta^{\beta/(\alpha-\beta)} >0.
          \end{align*}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:22:08.537257+00:00","domain":"probability theory","id":"claim_f53771787da49fb6f13f62566639b984e4c8570906082b3fc72eda42696d53fd","kind":"theorem","schema_version":1,"statement":"[Corollary cor:RGP-scalar of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The one-point Fredholm determinant
