\item For any $V$-valued $({\mathcal F}_t)_{t\in [0,T]}$-progressively measurable $\mathrm{d} t\otimes \mathbb{P}$-version $\overline{X}$ of $\widehat{X}$ it holds that
\begin{equation*}
X_t=x+\int_0^t A(\overline{X}_s)\,\mathrm{d} s+B \,W_t,\quad t\in [0,T],\quad\mathbb{P}\text{-a.s.}
\end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.323033+00:00","domain":"probability theory","id":"claim_f53efa11079c5af974695657f30cfdba2c28cb9847a5acc52ff402d6b1c86f99","kind":"theorem","schema_version":1,"statement":"[Proposition 2 (Compressibility plus Malliavin regularity) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $S>\tfrac{1}{2}$ and $s>0$. Assume that $X \in \mathcal{H}_T^2(\mathbb{R}^{d})$ is compressible with compressibility constant $C_{X}$; see Definition \ref{defn:compressibility}. Suppose, in addition, that $X \in \mathbb{D}_T^{s,2:d}$. Then, for every $N \in \mathbb{N}_{+}$ and every $P \in \mathbb{N}$, we have
\begin{equation}

    \inf_{
        \underset{
            \mathfrak{m}^{(1)},\dots,\mathfrak{m}^{(N)}\in \bigcup_{m=0}^{P} \mathfrak{C}_m
        }{
            \beta_1,\ldots,\beta_N\in \mathbb{R}^d
        }
    }
    \Big\|
        X
        -
        \sum_{n=1}^N
            \beta_n
            \mathfrak{m}^{(n)}
    \Big\|_{\mathcal{H}_T^2(\mathbb{R}^{d})}
    \lesssim_X
    N^{-(S-\frac12)}
    +
    (1+P)^{-s/2},
\end{equation}
where the symbol $``\lesssim_X"$ indicates that the bounding constant depends on $X$, but not on the approximation parameters $N$ and $P$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:06:39.270948+00:00","domain":"probability theory","id":"claim_f53f5fd37ee4dcac8f64042f8e671e55997cae77016d1595b49de2df2e998464","kind":"definition","schema_version":1,"statement":"[Definition def:GU of arXiv:2607.08914, 'Linear spreading speed in non-monotone population models'] Let $G^U \subseteq [0,1]^{\mathtt{Block}(0,0)}$ be the set of all $U$'s which satisfy
