        = \inf_{\substack{f\in \langle \1 \rangle^{\perp_\zeta} \\ \|f\|_\zeta=1}}\mathscr{E}_\zeta(f)
        = \inf_{\substack{f\in \langle \1 \rangle^\perp \\ \|f\|=1}} 
        \frac{\mathscr{E}_\zeta(f)}{\operatorname{var}_\zeta(f)}  
        .
     \end{align}
    In addition, for any $\mathcal{P}_+(\ensuremath{\mathbb{Z}}) \ni \zeta_\varepsilon \to \zeta$ and any $0 < \delta_\varepsilon \to 0$ as $\varepsilon \to 0$, we have
    \begin{align}
