\end{equation}
\item for every $m<r$ there exists a finite family
\begin{equation}
I^{(m)}=\{(y_j^{(m)},a_j^{(m)}):1\le j\le s_m\}
\end{equation}
of visible state--appended-edge pairs at depth $m$ such that, with
