{"assumptions":[],"created_at":"2026-10-28T02:28:34.981624+00:00","domain":"probability theory","id":"claim_f66d3b72a19255cbbdc8bd1cd81982f47322c78ffeb8091a609c002cae2321ec","kind":"theorem","schema_version":1,"statement":"[Cor thm:joint distribution of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $t=1/q$, and $n\ge 1$ be an integer.
\begin{enumerate}[left=0pt]
\item (Alternating case) Let $A\in\Alt_{2n}(\mathfrak{o})$ be the same as in (thm:The Hall-Littlewood measure of i.i.d entries of the paper), and $B_1,\ldots,B_k\in M_{2n\times 2n}(\mathfrak{o})$ be i.i.d random matrices with i.i.d entries distributed by the additive Haar measure on $\mathfrak{o}$. Then, the joint distribution  
$$\mathbf{P}(\SN^{\alt}(A)=\lambda,\SN^{\alt}(B_1^tAB_1)=\lambda^{(1)},\ldots,\SN^{\alt}(B_k^t\cdots B_1^tAB_1\cdots B_k)=\lambda^{(k)})$$
is given by

\begin{equation}
\frac{Q_{\lambda}(t,t^3,\ldots;t^2)Q_{\lambda^{(1)}/\lambda}(t,t^2,\ldots;t^2)\cdots Q_{\lambda^{(k)}/\lambda^{(k-1)}}(t,t^2,\ldots;t^2)P_{\lambda^{(k)}}(1,t^2,\ldots,t^{2n-2};t^2)}{\Pi_{t^2}(1,t^2,\ldots,t^{2n-2};t,t^3,\ldots)\Pi_{t^2}(1,t^2,\ldots,t^{2n-2};t,t^2,\ldots)^k}
\end{equation}

\item (Hermitian case) Let $A\in\Her_n(\mathfrak{o})$ be the same as in (thm:The Hall-Littlewood measure of i.i.d entries of the paper), and $B_1,\ldots,B_k\in M_{n\times n}(\mathfrak{o})$ be i.i.d random matrices with i.i.d entries distributed by the additive Haar measure on $\mathfrak{o}$. Then, the joint distribution  
$$\mathbf{P}(\SN^{\her}(A)=\lambda,\SN^{\her}(B_1^*AB_1)=\lambda^{(1)},\ldots,\SN^{\her}(B_k^*\cdots B_1^*AB_1\cdots B_k)=\lambda^{(k)})$$
is given by

\begin{equation}
\frac{Q_{\lambda}(t,-t^2,\ldots;-t)Q_{\lambda^{(1)}/\lambda}(t,-t,\ldots;-t)\cdots Q_{\lambda^{(k)}/\lambda^{(k-1)}}(t,-t,\ldots;-t)P_{\lambda^{(k)}}(1,\ldots,(-t)^{n-1};-t)}{\Pi_{-t}(1,-t,\ldots,(-t)^{n-1};t,-t^2,\ldots)\Pi_{-t}(1,-t,\ldots,(-t)^{n-1};t,-t,\ldots)^k}
\end{equation}
Here $t,-t,\ldots$ is the abbreviation of $t,-t,t^2,-t^2,t^3,-t^3,\ldots$, and $t,-t^2,\ldots$ is the abbreviation of $t,-t^2,t^3,-t^4,t^5,\ldots$.
\end{enumerate}","status":"unverified"}

