{"assumptions":[],"created_at":"2026-10-26T20:47:22.239452+00:00","domain":"probability theory","id":"claim_f6acfabd809ffe0b617e6dd01a33d93a3a78e350f305e6b6f1088ad8408635d9","kind":"definition","schema_version":1,"statement":"[Defn 2 of arXiv:2605.25715, '2605.25715'] Let $\widetilde{\mathbf{G}} \in L^2_{loc}(\mathbb{R}^d, \mathbb{R}^d)$. 

\begin{itemize}
\item[(i)]
We say that $\widetilde{\mathbf{G}} $ admits a Helmholtz--Hodge decomposition (in short: {\bf HHD}), if there exist $\Phi \in H^{1,2}_{loc}(\mathbb{R}^d) \cap L^{\infty}_{loc}(\mathbb{R}^d)$ and $\mathbf{B} \in L^2_{loc}(\mathbb{R}^d, \mathbb{R}^d)$, such that 
\begin{equation} 
\int_{\mathbb{R}^d} \langle \mathbf{B}, \nabla f \rangle \,dx = 0 \quad \forall f \in C_0^{\infty}(\mathbb{R}^d) \quad \text{(in short: $\mathrm{div}_{dx }(\mathbf{B})=0$)}
\end{equation}
 and
\begin{equation} 
\widetilde{\mathbf{G}} = \nabla \Phi + \mathbf{B}\quad (\text{a.e. on } \  \mathbb{R}^d).
\end{equation}
\item[(ii)]
We say that $\widetilde{\mathbf{G}} $ admits an orthogonal Helmholtz--Hodge decomposition (in short: {\bf OHHD}), 
if $\widetilde{\mathbf{G}} $ admits a HHD as in (i), and in addition,
\begin{equation} 
\langle \nabla \Phi, \mathbf{B} \rangle = 0 \quad (\text{a.e. on } \  \mathbb{R}^d).
\end{equation}
\item[(iii)]
We say that $\widetilde{\mathbf{G}} $ admits a weighted Helmholtz--Hodge decomposition (in short: {\bf WHHD}), if   there exist $\Phi \in H^{1,2}_{loc}(\mathbb{R}^d) \cap L^{\infty}_{loc}(\mathbb{R}^d)$ and $\mathbf{B} \in L^2_{loc}(\mathbb{R}^d, \mathbb{R}^d)$ such that
\eqref{mathbfbolb} holds and
$$
\int_{\mathbb{R}^d} \langle \mathbf{B}, \nabla f \rangle \,d\mu = 0 \quad \forall f \in C_0^{\infty}(\mathbb{R}^d) \quad \text{(in short: $\mathrm{div}_{\mu }(\mathbf{B})=0$)},
$$
where $\mu=\exp(2\Phi)\,dx$.
\end{itemize}
If $\widetilde{\mathbf{G}} $ is a continuous vector field admitting an OHHD, and  $\Phi$ as well as  $\mathbf{B}$ are continuously differentiable, then we say that $\widetilde{\mathbf{G}} $ admits a strictly orthogonal Helmholtz--Hodge decomposition (in short: {\bf SOHHD}). Note that in this case, \eqref{mathbfbolb}, \eqref{BorthnablaPhi}, and $\mathrm{div}\mathbf{B}=0$ hold everywhere on $\R^d$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:09:15.292237+00:00","domain":"probability theory","id":"claim_f6ad9869967c47d5706b8d4e0640a4cc7494f52330dea3d3125814547a2b292e","kind":"lemma","schema_version":1,"statement":"[Lemma 0-1 of arXiv:2411.05204, '\Large\bf Sample Path Properties of the Fractional Wiener--Weierstrass Bridge'] Let $(G(t))_{t\in[0,1]}$ be a centered Gaussian process for which $d(t,s):={\mathbb E}[(G(t)-G(s))^2]$ is continuous. Let furthermore   $\omega,\rho:[0,1)\to[0,\infty)$ be continuous  functions with $\omega(0)=\rho(0)=0$, and $K\in[0,1]$ be a compact set. Then 
    $$\lim_{h\to 0}\sup_{\substack{t,s\in K\\ |t-s|<h}}\frac{G(t)-G(s)}{\omega(|t-s|)}\leq L\quad\text{ a.s. }\implies ~\lim_{h\to 0}\sup_{\substack{t,s\in K\\ |t-s|<h}}\frac{G(t)-G(s)}{\omega(|t-s|)}=L'\quad\text{ a.s. }$$
    for some $L'\geq 0$. Similarly, for each $s\in[0,1]$,
   $$\limsup_{t\in[0,1],\,t\to s}\frac{G(t)-G(s)}{\rho(|t-s|)}\leq L_s\quad\text{ a.s. }\implies ~\limsup_{t\in[0,1],\,t\to s}\frac{G(t)-G(s)}{\rho(|t-s|)}=L_s'\quad\text{ a.s. }$$
    for some $L_s'\geq 0$.","status":"unverified"}

