  \le C\eps^\delta
  \norm{\widetilde{\mathcal P}_\eps\phi}_{C^{0,\alpha}_{\delta-4}}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:38:11.839940+00:00","domain":"probability theory","id":"claim_f6b4e3a3625f137aa6f6f09985cb962c01c1c6c6a5ad6bdd1ef14e44aeda7df8","kind":"concept","schema_version":1,"statement":"[Theorem thm:SmoothnessRegularityFBM of arXiv:2504.04860, 'Stochastic differential equations driven by fractional Brownian motion: dependence on the '] Let $k \in \mathbb{N}$ and $T >0$. Then, there exists a process $B^{H,k} = (B_t^{H,k})_{t \in [0,T]}$  such that:
	\begin{itemize}
		\item[(i)] For all $\omega \in \Omega$ the sample paths $(0,1) \times [0,T] \ni (H,t) \mapsto B_t^{H,k}(\omega) \in \mathbb{R}$ are continuous.
		\item[(ii)] For all $\omega \in \Omega$ and for any fixed $H \in (0,1)$ and $\lambda \in (0,H)$ the sample paths  $ [0,T] \ni t \mapsto B_t^{H,k}(\omega) \in \mathbb{R}$ are $ \lambda$-H\"older continuous. We even have, for all $0<a< b<1$ and $0<\gamma <a$, that there exists a non-negative random variable $K_{\gamma, a,b,k,T}>0$  such that
		\begin{align*}
			\sup_{H \in [a,b]} \big|B^{H,k}_t(\omega) - B^{H,k}_s(\omega)\big| \leq K_{\gamma, a,b,k,T}(\omega) |t-s|^\gamma, \qquad s,t \in [0,T].
		\end{align*}
		\item[(iii)]  For all $0<a< b <1$, $t \in [0,T]$ there exists $\Omega_{a,b,k,t} \in \mathcal{A}$ such that $\mathbf{P}(\Omega_{a,b,k,t})=1$ and
		\begin{align*}
			\frac{\partial^k}{\partial H^k} B_t^H(\omega) = B^{H,k}_t(\omega), \qquad H \in [a,b], \,\, \omega \in \Omega_{a,b,k,t}.
		\end{align*}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:23:37.802188+00:00","domain":"probability theory","id":"claim_f6b7debcc1a1d7db5403141bfe7dcd4f5ee8e39948aefff4f78564c4a4a9ab7c","kind":"theorem","schema_version":1,"statement":"[Theorem 5 (Sobolev estimates) of arXiv:2609.03558, 'Local well-posedness of the higher-order nonlinear Schr\"{o}dinger equation on the half-li'] Let $s\in\mathbb R$, $b\in \{0,1\}$. The unique solution of the Cauchy problem \eqref{cauchy1}, denoted by $y=S[y_0;0]$, belongs to $C(\mathbb{R}_t;H_x^s(\mathbb{R}))$ and satisfies the conservation law
	\begin{equation}
		\left\| y(\cdot ,t) \right\|_{H_x^s(\mathbb{R})}= \left\| y_0 \right\|_{H_x^s(\mathbb{R})},\quad t\in\mathbb{R}.
	\end{equation}
	Moreover, if  $\alpha^2+3\beta\delta\ge 0$, then $\partial_x^by\in C(\mathbb{R}_x;H_t^{\frac{s+1-b}{3}}(-T,T))$ for any $T>0$ and there exists a constant $c=c(s,T\alpha,\beta,\delta)\geq 0$ 

    such that
\begin{equation}
		\sup_{x\in\mathbb{R}}\left\|\partial_x^by(x,\cdot)\right\|_{H_t^{\frac{s+1-b}{3}}(-T,T)}\leq 
        c \left\|y_0\right\|_{H_x^s(\mathbb{R})},
	\end{equation}
	while if $\alpha^2+3\beta\delta<0,$ then $\partial_x^by\in C(\mathbb{R}_x;H_t^{\frac{s+1-b}{3}}(\mathbb{R}))$ and there is a constant $c=c(s,\alpha,\beta,\delta)\geq 0$ such that
	\begin{equation}
		\sup_{x\in\mathbb{R}}\left\|\partial_x^by(x,\cdot)\right\|_{H_t^{\frac{s+1-b}{3}}(\mathbb{R})}\leq c \left\|y_0\right\|_{H_x^s(\mathbb{R})}.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:41:03.268121+00:00","domain":"probability theory","id":"claim_f6bb2be19c8f6dba57ccae53c727b8605dce240de5c5c1f50eeba32ccf78cf2d","kind":"concept","schema_version":1,"statement":"[Mylem l2 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] For any random variable $\xi \in \operatorname{Sub}_{\varphi}(\Omega)$, 
		\begin{equation}
			\textsf{E} \exp \{\lambda \xi\} \leq \exp \left\{\varphi\left(\lambda \tau_{\varphi}(\xi)\right)\right\}, \quad \lambda \in \mathbb{R}
		\end{equation}
		holds, where $$
		\tau_{\varphi}(\xi):=\sup _{\lambda \neq 0} \frac{\varphi^{(-1)}(\log \textsf{E} \exp \{\lambda \xi\})}{|\lambda|},
		$$
		and  $\varphi^{(-1)}(\cdot)$ denotes the inverse function of $\varphi(\cdot)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:47:04.952960+00:00","domain":"probability theory","id":"claim_f6bc4ed5a8bea6bc28472e31bfe9d4994266bd608e2685e6f59fdbe3b22d2d32","kind":"definition","schema_version":1,"statement":"[Defn def-accessible of arXiv:2412.03067, 'Geodesic Trees and Exceptional Directions in FPP on Hyperbolic Groups'] We say that a finitely generated group $G$ is \emph{accessible} if there exists a simplicial tree ${\mathcal T}$ and a $G-$action on ${\mathcal T}$ such that
 \begin{enumerate}
 \item $G_e$ is finite for each edge $e \in {\mathcal E}({\mathcal T})$,
 \item $G_v$ has at most one end for each vertex $v \in {\mathcal V}({\mathcal T})$.
 \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.184401+00:00","domain":"probability theory","id":"claim_f6bdfa91273e963fb421267fa444a99d7d79d2469a6cd72d96bc7a2e0a3bd2a5","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2606.30080, 'Ergodicity of reflected stochastic reaction-diffusion equations driven by space-time white'] Assume that (S1)--(S3) and (H3) hold. Let $p>2$. Define
  \begin{align*}
    h_{-}(u):=
  \begin{cases}
        -\gamma u + \inf_{0\leq v\leq u}\big(b(v) - b(0) - C_{b,\theta}\big), & u\geq 0, \\
        - C_{b,\theta}, & u\leq 0,\\
  \end{cases}
  \end{align*}
where $\gamma$ satisfies \eqref{260621.1621} with $p$ replaced by $p\nu$. Let $v_{-}$ be the unique solution to (\ref{260603.1828}) with $\tilde{b}=h_{-}$. If 
$m$ satisfies \eqref{260621.1647}, 
then
\begin{align*}
  \sup_{t\geq 0}\mathbb{E}\Big[ \sup_{x\in [0,1]}|v_{-}(t,x)|^p \Big] <\infty.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:40:21.311922+00:00","domain":"probability theory","id":"claim_f6bffcd38bca46f3d4421a23e82a3cec6b6940a84be88e3f1d8b0fd1a70288b0","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$. Given $t_0 = 0$ and $t_1 , t_2 , \dots , t_m > 0$, let $\sigma \in S_m$ be a permutation such that $t_{\sigma(1)} \le t_{\sigma(2)} \le \dots \le t_{\sigma(m)}$ and set $\sigma(0) = 0$. For any $k < d$,
    \begin{equation}
        \mathbb{E} \left[ \prod_{i=1}^m |W(t_i) - W(t_{i-1})|^{-k} \right] \le C^m \prod_{i=1}^m |t_{\sigma(i)} - t_{\sigma(i-1)}|^{-k/2}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:57:59.889175+00:00","domain":"probability theory","id":"claim_f6c5012337790ca62784e3d100a891c8f093ff37d2a4d9ac4a1c8ffd234b98be","kind":"theorem","schema_version":1,"statement":"[Proposition prop:addendum of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] In the context of (thm:scasca of the paper) or (cor:scaberry of the paper) we have the following additional relations.
\begin{enumerate}
\item There exists $r_*>0$ such that
\begin{equation} 
0<\liminf_\ell\inf_{\dist xy \le \frac{r_*}{\lambda_\ell}}\|\sigma_\ell^{-2}j^{1,1}_{x,y}E_\ell\|_{g^{\lambda_\ell}}, \quad  \quad 
\limsup_\ell\sup_{\dist xy \le \rho}\|\sigma_\ell^{-2}j^{1,1}_{x,y}E_\ell\|_{g^{\lambda_\ell}}<+\infty.
\end{equation}
\item
\begin{equation} 
\lambda_\ell^{-n}\le \mathrm{O}(1)\int_{\substack{x,y\in M,
\\
\mathrm{dist}(x,y)\le 
\frac{r_\ell}{\lambda_\ell}}}
\|\sigma_\ell^{-2}j^{1,1}_{x,y}E_\ell\|^4_{g^{\lambda_\ell}}
\dd x \dd y\le \mathrm{O}(1)r_\ell^n \lambda_\ell^{-n}.
\end{equation}
\item If $r_\ell$ is constant, then the conclusion can be equivalently stated as
 \begin{gather}
{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_{\phi_\ell}(M)}{\lambda_\ell}\right\}\le 
{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_{\phi_\ell}(M)[2]}{\lambda_\ell}\right\}
+\mathrm{O}(1)\Bigg(\int_{M\times M}
\|\sigma_\ell^{-2}j^{1,1}_{x,y}E_\ell\|^4_{g^{\lambda_\ell}} \dd x \dd y 
\Bigg).
\end{gather} 
\item An implied weaker bound is
\begin{equation} 
{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_{\phi_\ell}(M)}{\lambda_\ell}\right\}
\le 
\mathrm{O}(1)\Bigg(
\int_{M\times M}\|\sigma^{-2}j^{1,1}_{x,y}E_\ell\|^2_{g^{\lambda_\ell}} \dd x \dd y 
\Bigg).
\end{equation}
\item The actual variance, frequency and eccentricity of the field $\phi_\ell$ satisfy
\begin{equation} 
\|\frac{\sigma(\phi_\ell)}{\sigma_\ell\sigma(F)}-1\|\le \delta_\ell,\quad \|\frac{\lambda(\phi_\ell)}{\lambda_\ell\lambda(F)}-1\|\le \delta_\ell, \quad \varepsilon(\phi_\ell)\le 8\delta_\ell.
\end{equation}
The latter holds for any scaling bound, not necessarily a scaling limit.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T21:02:38.601654+00:00","domain":"probability theory","id":"claim_f6c7254b1e347b58a34c72271a75269f8d0555449f6df1112a55e6370fc539c3","kind":"theorem","schema_version":1,"statement":"[Proposition 32 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Under the preceding spectral assumptions, let $\alpha$ be a continuous linear functional on $\mathcal B$ and let $f\in\mathcal B$. Put

\begin{equation*}
g_n(k)=(2\pi)^{-d/2}\det(\Gamma)^{-1/2}
\exp\left\{-\frac{1}{2n}(k-nm)^T\Gamma^{-1}(k-nm)\right\}.
\end{equation*}

For every $M<\infty$,

\begin{equation*}
\sup_{|k-nm|_1\leq M\sqrt n}
\left|n^{d/2}\alpha(q_k^{(n)}f)-\alpha(\one)\pi(f)g_n(k)\right|
\xrightarrow[n\to\infty]{}0.
\end{equation*}

Moreover, there exist finite positive constants $C$ and $c$, depending on $\alpha$ and $f$, such that

\begin{equation*}
|\alpha(q_k^{(n)}f)|
\leq Cn^{-d/2}\exp\left\{-c\frac{|k-nm|_1^2}{n}\right\}+Ce^{-cn},
\qquad n\geq1,
\quad k\in\N^d.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.932547+00:00","domain":"probability theory","id":"claim_f6ca10027bf89e50195b5e35908ee1295bc3a8bd487e26d256ddc8a65b3758bf","kind":"concept","schema_version":1,"statement":"[Lem 32 of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] There exists a constant $c\in (0,1)$ such that the following three properties hold:
\begin{enumerate}
\item  
For any $\ell\in\mathrm{GoodScales}$ and $m>7\ell$,
\[
\Ppsq{B_m\in \intervalleentier{6\ell}{7\ell} 
}{B_m\leq 7\ell} \geq c.
\]

\item   For any  $\ell\in\mathrm{GoodScales}$ and $k\in \intervalleentier{6\ell}{7\ell}$,
\begin{align*}
	\Ppp{k}{\DMC(\stt_{4\ell}-1) \in \intervalleentier{5\ell}{7\ell}\,,\, \DMC(\stt_{4\ell}) \in \intervalleentier{\ell}{4\ell} }\geq c.
\end{align*}

\item  For any $\ell\in \mathrm{GoodScales}$, we can couple the golden instructions $(G_m)_{5\ell \leq m \leq 7\ell}$, with law given by \eqref{eq:red-law}, in such a way that 
	\begin{align*}
		\Pp{\forall a,a' \in \intervalleentier{5\ell}{7\ell}, \ G_a = G_{a'} }\geq c.
	\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:19:47.203530+00:00","domain":"probability theory","id":"claim_f6d6937a94015c824102d8c50864fa78b1dbff2843098abd0ea7b88cd430c237","kind":"concept","schema_version":1,"statement":"[Theorem mainsharpness of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $\vec{G} = (V, \vec{E})$ be a directed vertex-transitive graph. The following statements hold:
    \begin{itemize}[nosep,left=5pt]
        \item[1.] For every $t > 0$, there exists a constant $K_{1}(\lambda_{\mathrm{c}}(t))$ such that for any $\lambda$ in $[\lambda_{\mathrm{c}}(t),2\lambda_{\mathrm{c}}(t)],$ we have
        \begin{align}
            \mathbb P_{\lambda, t}(\mathbf{0} \rightarrow \infty) \geq K _{1}(\lambda - \lambda_{\mathrm{c}}).
        \end{align} 
        \item[2.] For every $\lambda > 0$, there exists a constant $K_{2}(t_{\mathrm{c}}(\lambda)) $ such that for any $t$ in $[t_{\mathrm{c}}(\lambda),2t_{\mathrm{c}}(\lambda)],$ we have
        \begin{align}
            \mathbb P_{\lambda, t}(\mathbf{0} \rightarrow \infty) \geq K_{2} (t - t_{\mathrm{c}}).
        \end{align} 
        \item[3.] For fixed $t>0,$ and $\lambda < \lambda_{\mathrm{c}}(t),$ there exist constants $C,c>0,$ such that
        \begin{equation}
            \mathbb P_{\lambda,t}\left(|\mathcal{C}_{\mathbf{0}}| \geq n\right) \leq Ce^{-cn}, \text{ for every $n\geq0$}. 
        \end{equation}
        \item[4.] For fixed $\lambda > 0,$ and $t < t_{\mathrm{c}}(\lambda),$ there exist constants $C,c>0,$ such that
        \begin{equation}
            \mathbb P_{\lambda,t}\left(|\mathcal{C}_{\mathbf{0}}| \geq n\right) \leq Ce^{-cn}, \text{ for every $n\geq0$}. 
        \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.466689+00:00","domain":"probability theory","id":"claim_f6d6e3f3708d36f6560af9885fde1f0a3bbc1166abcc300158073412c6455e44","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $f \in \mathcal{B}^n$. For $U \subset \mathbb{R}^n$ measurable, 
