{"assumptions":[],"created_at":"2026-10-28T00:59:45.503444+00:00","domain":"probability theory","id":"claim_f6e447746953bbafd39b174f218144c4e4af778355ac554862fb6e245b624229","kind":"lemma","schema_version":1,"statement":"[Lemma z1lm of arXiv:2411.16647, 'The stochastic evolution of an infinite population with logistic-type interaction'] For some $\alpha_0$ and  all $\sigma \in (0,1]$, let $\mu_0$ and $\mu^\sigma_0$ be in $\mathcal{P}^{\alpha_0}_{\rm exp}$. Assume also that   
\begin{equation}

  \forall G \in \mathcal{G}_{{\alpha}_0} \qquad \langle\! \langle k_{\mu^\sigma_0}, G \rangle \! \rangle \to \langle\! \langle k_{\mu_0}, G \rangle \! \rangle  \qquad {\rm as} \ \ \sigma \to 0.
\end{equation}
Next, for these $\mu^\sigma_0$ and $\mu_0$, let $\mu^\sigma_t$ and $\mu_t$ be the unique solutions of the Fokker-Planck equation for $(L_\sigma, \mathcal{F}, \mu_0^\sigma)$ and $(L, \mathcal{F}, \mu_0)$, respectively. Then for each $t>0$, one finds $\tilde{\alpha}_t \geq \alpha_t$ such that the  following holds
\begin{equation}

 \forall G \in \mathcal{G}_{\tilde{\alpha}_t} \qquad \langle\! \langle k_{\mu^\sigma_t}, G \rangle \! \rangle \to \langle\! \langle k_{\mu_t}, G \rangle \! \rangle  \qquad {\rm as} \ \ \sigma \to 0. 
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:08.845917+00:00","domain":"probability theory","id":"claim_f6e4eae66bd1f2b4c1a47de1cc964ebb5cfae979e65cec0cba52debd3e248a0a","kind":"concept","schema_version":1,"statement":"[Prop 21 (Schwinger--Dyson Equations) of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] Let $Q\in \PP_d$ and $1\le j\le d$.
    \begin{enumerate}
        \item[(a)]
        If $\bs{X}^N = (X^N_1,\ldots,X^N_d)$ is a $d$-tuple of independent GUE random matrices in $\M_N(\C)$, then 
        \begin{equation}    
            \E\left[\ts_N(X_j^N Q(\bs{X}^N))\right] = \E\left[\ts_N\otimes\ts_N\left((\partial_jQ)(\bs{X}^N)\right)\right],
        \end{equation}
        where we recall $\ts_N$ is the normalized trace. 
        \item[(b)]
        If $\bs{x}=(x_1,\dots, x_d)$ is a $d$-tuple of freely independent semicircular random variables, 
        \begin{equation}    
            \tau(x_j Q(\bs{x})) = \tau\otimes\tau\left((\partial_jQ)(\bs{x})\right).
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:51:26.749709+00:00","domain":"probability theory","id":"claim_f6e60df274e1410604e153e1fe1aa51bf17aeb835216cccbc65cf481cb95c99a","kind":"concept","schema_version":1,"statement":"[Lemma ungreedy_depth_only_one_vertex_connections_set of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Let $\mathbf x$ be a choice sequence that satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper) is satisfied. We have
\begin{equation} 
\mathbb{P}(u_n(v)\leq u,\ell_n(v)\geq\ell\,|\,\deg_n(v)\geq d)\leq \mathbb{P}(\widetilde{u}_n(v)\leq u,\ell_n(v)\geq\ell\,|\,\deg_n(v)\geq d).
\end{equation} 
Now, fix $b\in(0,m+1)$, and let $d,\ell,u=d(n),\ell(n),u(n)\in\mathbb{N}$ such that $d< bh_n^+$ for $n\in\mathbb{N}$. Suppose that, additionally, the choice sequence $\mathbf x$ satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:hI of the paper) with $\varepsilon<1-b/(m+1)$ and Part~(item:lb of the paper). Let $(c_n)_{n\in\mathbb{N}}$ be any sequence such that $c_n=\omega(I_{\hyperref[ass:A]{\mathbf{x}}})$. Then, 
\begin{equation}
\mathbb{P}(u_n(v)\leq u,\ell_n(v)\geq\ell\,|\,\deg_n(v)\geq d)\geq \mathbb{P}(\widetilde{u}_n(v)\leq u-c_n,\ell_n(v)\geq\ell\,|\,\deg_n(v)\geq d)+o(1).  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:47.658388+00:00","domain":"probability theory","id":"claim_f6e62c209ca524fece1d73a26710110c6465319e3c007a0f512c34f0dcaa7a55","kind":"theorem","schema_version":1,"statement":"[Proposition 5 (Local MDP) of arXiv:2605.08629, 'Moderate deviations for the Maki--Thompson rumour model'] Let $I=(a,b)$ be a non-empty bounded open interval. Assume \eqref{bn-weak}, then
    \begin{align}
        \liminf_{n\to\infty}\frac1{b_n^2}\log \mathbb{P}(Z_n\in I)
        &\ge -\inf_{z\in I} \frac{z^2}{2\sigma^2}, \\
        \limsup_{n\to\infty}\frac1{b_n^2}\log \mathbb{P}(Z_n\in I)
        &\le -\inf_{z\in \overline I} \frac{z^2}{2\sigma^2}. 
    \end{align}
    In particular, for any $x\in\mathbb{R}$,
    \begin{equation}
        \lim_{\delta\downarrow 0}\lim_{n\to\infty}
        \frac{1}{b_n^2}\log \mathbb{P}\bigl(Z_n \in (x-\delta, x+\delta)\bigr) = -\frac{x^2}{2\sigma^2}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:08.956139+00:00","domain":"probability theory","id":"claim_f6e90bddfd812f29996293e97a31dc192bdb2b9c28174a62321f27969fccc5aa","kind":"theorem","schema_version":1,"statement":"[Proposition prop:sample_mean of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let the assumptions of Theorems~(thm:explicit_density of the paper),~(thm:explicit_current_1 of the paper)
and~(thm:explicit_current_2 of the paper) hold, with the corresponding sub-gamma parameters
$\tilde\sigma_A^2$ and $c_A$ established there for $\overline{A}_t \in
\{\overline{\rho}_t(V), \overline{J}_t(U)\}$. Then for every $n \geq 1$, $t>0$, and
$a>0$, the sample mean $\widehat{A}_{n,t}$ satisfies the one-sided bound
\begin{align}
  \mathbb{P}^\nu\left(\widehat{A}_{n,t} - \E^\mu[\overline{A}_t] \geq a\right)
  \leq
  N_\nu^{n}
  \exp\left[-nt\frac{\tilde\sigma_A^2}{c_A^2}
  h\left(\frac{c_A a}{\tilde\sigma_A^2}\right)\right],

\end{align}
and the corresponding two-sided bound
\begin{align}
  \mathbb{P}^\nu\left(\left|\widehat{A}_{n,t} 
  - \E^\mu[\overline{A}_t]\right| \geq a\right)
  \leq
  2 N_\nu^{n}
  \exp\left[-nt\frac{\tilde\sigma_A^2}{c_A^2}
  h\left(\frac{c_A a}{\tilde\sigma_A^2}\right)\right].

\end{align}
Here, $\mathbb{P}^\nu$ now denotes the underlying initial law of the $n$ independent trajectories. 
In particular, $\widehat{A}_{n,t}$ obeys the single-trajectory bounds
($n=1$) of Section~(sec:conc_poincare of the paper)
and also Eq.~(equation eq:uq_general of the paper) by replacing $t \to nt$ and $N_\nu \to N_\nu^n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.553681+00:00","domain":"probability theory","id":"claim_f6ea90e33ea9bee920f68030879eca9275a1df4d26542c8fb8473cece61f432c","kind":"concept","schema_version":1,"statement":"[Lemma noninttreeleaves of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] For all $x,y\in[n]$ with $x\neq y$ and uniformly over $u\in [0,1]$, we have
\begin{align}
 \mathbb E\bigl[u^{d(x)+d(y)} \mathbf{1}_{x,y\in\mathcal{Q}_n\cap \mathcal{T}_n}\mathbf{1}_{B_{\omega}(x)\cap B_{\omega}(y)= \varnothing}\bigr] = g_k(u\eta_k)^2 - \frac{c_{\textrm{approx}}^2(w,u)}{n}+ O\Big(\frac{1}{n^2}\Big),
\end{align}
where
\begin{align}
c_{\textrm{approx}}^2(w,u):=  \frac{1}{2} \mathbb E_{\scriptscriptstyle BGW}^2\Bigl[u^{Z_{k}^{(1)}+Z_{k}^{(2)}}\bigl(({Z}^{(1)}+{Z}^{(2)}-2)({Z}^{(1)}+{Z}^{(2)}+1)+\overline{Z}^a+\overline{Z}^b\bigr)\mathbf{1}_{Z_{2k}^{(1)}=Z_{2k}^{(2)}=0}\Bigr].
\end{align}
	 Here we recall the definition of the sets $A^+, A^-, B^+,B^-$ from Section~(subsec:probaleaf of the paper), and for a letter $c\in \{a,b\}$ of respective capital version $C\in \{A,B\}$, we let $\overline{Z}^c = \overline{Z}_{C^-}(\overline{Z}_{C^-}-2\overline{Z}_{C^+})$ with $\overline{Z}_U=Z^{(1)}_U+Z^{(2)}_U$ for every $U\subseteq \mathbb{N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.591443+00:00","domain":"probability theory","id":"claim_f6ee421f4b8f57fab59a18c55350201c589890f5bdb75f1ef831f2075af1c109","kind":"theorem","schema_version":1,"statement":"[Theorem th2NL of arXiv:2412.04973, 'On the Laplace equation with non-local dynamical boundary conditions'] Let $\Lambda=0$, $l > 0$, $k \in \mathbb{R}$ and $\alpha \in (0,1]$.  Let assume  $\lambda_1 + \Lambda \geq 0.$
