{"assumptions":[],"created_at":"2026-10-27T07:41:29.041240+00:00","domain":"probability theory","id":"claim_f6fffd6d5817acdbf0d2e59adcd401afd4eb4122fa8f35c207a7b97072de5f1e","kind":"lemma","schema_version":1,"statement":"[Lemma 4 of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Let $n\ge6$ and $S\in\CPIC\cap\CB(\mathbb R^n)$. Then, for every orthonormal frame
    $\{e_1,\dots,e_n\}$:
    \begin{enumerate}
        \item $S_{ijij}+S_{klkl}\ge0$ whenever $\{i,j\}\cap\{k,l\}=\emptyset$;
        \item $\Scal(S)-2\Ric_{kk}=\sum_{i\ne k}\sum_{j\ne k}S_{ijij}\ge0$ for every $k$;
        \item $\sum_{p\ge3}(S_{1p1p}+S_{2p2p})\ge0$; equivalently
        $\Ric_{11}+\Ric_{22}\ge2S_{1212}$;
        \item $\Ric_{11}+\Ric_{22}+\Ric_{33}+\Ric_{44}\ge2(S_{1212}+S_{3434})\ge0$;
        \item $(n^2-7n+14)S_{1212}+(n-5)(\Ric_{11}+\Ric_{22})+\Scal(S)\ge0$; for $n=8$ this reads
        $22S_{1212}+3(\Ric_{11}+\Ric_{22})+\Scal(S)\ge0$, and together with (3) it gives
        $\Ric_{11}+\Ric_{22}\ge-\frac1{14}\Scal(S)$;
        \item for every $\lambda\in[0,1]$ and every $p\ge5$,
        $S_{1313}+\lambda^2S_{1414}+S_{2323}+\lambda^2S_{2424}-2\lambda S_{1234}
        +(1-\lambda^2)(S_{1p1p}+S_{2p2p})\ge0$;
        \item if $\Scal(S)=0$ then $S=0$; equivalently every nonzero
        $S\in\CPIC\cap\CB(\mathbb R^n)$ has positive scalar curvature.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:01:15.335450+00:00","domain":"probability theory","id":"claim_f70088c9421e000c944d4b940777298fee1de9a18753e6c54bf955da42cb21e4","kind":"theorem","schema_version":1,"statement":"[Corollary 13 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=\left(V,E\right)$ be a locally finite weighted graph satisfying the $CD\psi\left(n,-K\right)$ condition with $K\geq0$, where $\psi\in C^{1}\left(0,+\infty\right)$ is a concave function with $\psi^{\prime}(1)>0$ and $H_{\psi}<\infty$. Then for any $0<t<s$ and any $x,y,z\in V$, 
\begin{equation*}
    p\left(t,x,y\right)\leq p\left(s,x,z\right)\left(\frac{s}{t}\right)^{\frac{n}{2\psi^\prime \left(1\right)}}\exp\left(\frac{Kn(s-t)}{4\psi^{\prime}(1)}+\frac{\psi^\prime \left(1\right)H_{\psi}\mu_{\max}\left(3+2Ks\right)d^2\left(y,z\right)}{3w_{\min}\left(s-t\right)} \right).
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:44:28.086263+00:00","domain":"probability theory","id":"claim_f700aefee2412c32f1bb8d842c2e2b3c19245157b74cf94f8b2f7c1ee4004e0b","kind":"concept","schema_version":1,"statement":"[Prop 16 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] For $\delta >0$, 
let $(X_t, \mathscr{J}_t)_{0 \le t \le T}$ be a weak limit in $\mathcal{C}([0,T], \mathcal{H}^{-1}_{\mathrm{Sym}}(\mathbb{S})\times \mathcal{H}^{-(3+\delta)}_{\mathrm{Sym}}(\mathbb{S}))$  of the couple of processes $\{(X_t^{(h)},\mathscr{J}_t(X^{(h)}))_{0 \le t \le T}\}_{ h \in T/{\mathbb N}^*}$ when $h\searrow 0$. 
Let $\phi\in \mathcal{H}^{(3+\delta)}_{\mathrm{Sym}}(\mathbb{S})\cap \mathcal{U}^2(\mathbb{S})$

and $\varepsilon >0$. 
Then, 
with probability one, 
for all $0\leq s<t\leq T$, 
\begin{align}
	\langle \phi, \mathscr{J}_{t}- \mathscr{J}_{s}\rangle \geq  \frac{1}{2}\int_s^t\int_{\mathbb{S}}\frac{\phi'(\mathbf{x})}{E_{\varepsilon}(\mathbf{x})+ D_{\mathbf{x}}{X}_{r}(\mathbf{x})}\mathrm{d}\mathbf{x}\mathrm{d}r,
\end{align}
where $E_\varepsilon(\mathbf{x})$ is given by \eqref{eq:varepsilon}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:59:53.159318+00:00","domain":"probability theory","id":"claim_f705527a5c33e9c2942064971b070cfbd1804b1b92b3d45d40f8a859b96eea84","kind":"theorem","schema_version":1,"statement":"[Proposition 13 of arXiv:2607.02406, 'On the range of competing random walks'] Under assumptions \ref{Assumption A1},\ref{Assumption A2}, we have
