{"assumptions":[],"created_at":"2026-10-27T08:26:47.190756+00:00","domain":"probability theory","id":"claim_f74e3eb3ff49acfa51f61c8a09f97a22e448ad6e8510dff25992d3445913ada0","kind":"concept","schema_version":1,"statement":"[Lem 108 (spatial smoothing of budget constraint) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Analogously to \eqref{e:budget.Ising.plus.eps}, with high probability we have
	\begin{align*}\nonumber
	&\tilde{C}^N(t)
	\equiv
	\int_{\R}
	\Cost_{t,2\bar{\lambda}}(\sPsi^N(t,y)) \,
		\overline{\varrho_{\vY,N,t}*\sphi}(y)\,dy\\ 
	&\qquad\le
	\frac{1}{\alpha}
	\bigg(
	\int_{\R} \swww(t,y)^{1/2} 
		\,\varsigma_{\vY,N,t}*\sphi(y)\,dy
	\bigg)^2
	+ 3\epsilon^\circ
	\equiv \frac{\tilde{W}^N(t)^2}{\alpha}+ 3\epsilon^\circ
	\end{align*}
for all $q_0\le t\le 1$. 

\begin{proof}
We continue to use the abbreviations introduced above.\smallskip

\noindent\textbf{Relation between $\tilde{C}^N(t)$ and $C^N(t)$.}
 As in Definition~\ref{d:sp.smooth}, let $\sPsi\equiv(\sB,\sV,\sU)$. The function $\Cost_{t,2\bar{\lambda}}$ is convex on the  expanded domain 
	\[\bigg\{(B,V,U)
	: \frac{V}{p(t)}
	\ge \frac{U^2}{p(t) \cdot t p'(t)} 
	-  \frac{2\bar\lambda}{p(t)}\bigg\}\,.\]
It follows from Lemma~\ref{l:sp.smooth.domain}
that $\sPsi$ lies in this expanded domain with high probability. 
Recall from Definition~\ref{d:disc.rescaled.coeffs} that we can regard $\Psi=(B,V,U)$ as functions of $(t,\vy)$ with $\vy\in\R^3$.
It then follows by Jensen's inequality that 
	\begin{align*}
	&\Cost_{t,2\bar{\lambda}}\Big(\sPsi(t,y)\Big)
	= \Cost_{t,2\bar{\lambda}}
	\Big( \sE_{t,y} \Psi(t,\xxx)\Big)
	\le \sE_{t,y}
	\bigg[ \Cost_{t,2\bar{\lambda}}
		\Big(\Psi(t,\xxx)\Big)\bigg] \\
	&\qquad
	\stackrel{\eqref{e:tilde.bP}}{=}
	\int_{H(y)}\int_{\R^3}
	\Cost_{t,2\bar{\lambda}} (\Psi(t,\vx))
	\frac{\varrho_t*\sphi(\vy)}
		{\overline{\varrho_t*\sphi}(y)}
		\cdot \frac{\sphi(\vy-\vx)\,\varrho_t(d\vx)}
			{\varrho_t*\sphi(\vy)} \,d\vy\,.
	\end{align*}
Integrating the above bound with respect to $\overline{\varrho_t * \sphi}(y)\,dy$ gives
	\begin{align*}
	\tilde{C}^N(t) &=
	\int_{\R} \Cost_{t,2\bar{\lambda}}\Big(\sPsi(t,y)\Big)
		\overline{\varrho_t * \sphi}(y)\,dy
	\le
	\int_{\R^3}
	\Cost_{t,2\bar{\lambda}} (\Psi(t,\vx)) \bigg[
	\int_{\R^3}
	\sphi(\vy-\vx) \,d\vy\bigg] \,\varrho_t(d\vx) \\
	&= \int_{\R^3}
	\Cost_{t,2\bar{\lambda}} (\Psi(t,\vx))\, \varrho_t(d\vx) = C^N(t)\,,
	\end{align*}
having used that $\sphi$ integrates to one.\smallskip

\noindent\textbf{Relation between $\tilde{W}^N(t)$ and $W^N(t)$.}
Similarly, recall from Definition~\ref{d:disc.rescaled.coeffs} that we can regard $\www^\frozen$ as a function of $(t,y^4)\in\R^2$. We can then express
$\swww(t,y) = \sE_{t,y,\Ising} \www^\frozen(t,\xxx)$ where $\sE_{t,y,\Ising}$ denotes expectation with respect to the law of $(\vy,\xxx)\sim\tilde{\bP}_{t,y,\Ising}$ defined by
	\[
	\tilde{\bP}_{t,y,\Ising}(dy\,dx)
	= \frac{\sphi(y-x)\,\varsigma_t(dx)}
			{\varsigma_t*\sphi(y)} \, dy\,.
	\]
for $x,y\in\R$.
Then, since $w\mapsto w^{1/2}$ is concave in $w\ge0$, we have
	\begin{align*}
	&\swww(t,y)^{1/2}
	=\Big( \sE_{t,y,\Ising} 
	\www^\frozen(t,\xxx) \Big)^{1/2}
	\ge\sE_{t,y,\Ising} 
	\Big[\www^\frozen(t,\xxx)^{1/2}\Big] \\
	&\qquad\stackrel{\eqref{e:tilde.bP}}{=}\int_{\R}\int_{\R}
		\www^\frozen(t,x)^{1/2}
	\frac{\sphi(y-x)\,\varsigma_t(dx)}
		{\varsigma_t*\sphi(y)} \,dy
	\,.
	\end{align*}
Integrating the above bound with respect to $\varsigma_t * \sphi(y)\,dy$ gives
	\begin{align*}
	\tilde{W}^N(t)
	&=
	\int_{\R} \swww(t,y)^{1/2} 
		\varsigma_t * \sphi(y)\,dy
	\ge
	\int_{\R} \www^\frozen(t,x)^{1/2}
	\bigg[\int_{\R}\sphi(y-x)\,dy\bigg] \, \varsigma_t(dx)\\
	&=\int_{\R} 
	\www^\frozen(t,x)^{1/2}\, \varsigma_t(d\vx)
	= W^N(t)\,.
	\end{align*}
Combining with \eqref{e:budget.Ising.plus.eps} gives
	\[
	\tilde{C}^N(t)
	\le C^N(t)
	\stackrel{\eqref{e:budget.Ising.plus.eps}}{\le}
	\frac{W^N(t)^2}{\alpha}+ 3\epsilon^\circ
	\le
	\frac{\tilde{W}^N(t)^2}{\alpha}+ 3\epsilon^\circ\,,
	\]
as claimed.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

