{"assumptions":[],"created_at":"2026-10-27T06:25:55.317109+00:00","domain":"probability theory","id":"claim_f7aaeaf38c02dcb819b68f96c109822218653580c36cd06b69c6f999bc88f09b","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $\kappa\in (0,4]$ and $\ell\in\Z$. 
\begin{itemize}
\item Transience: the process $\gamma$ driven by the driving function~\eqref{eqn::annuluSLEkappa} with $\LZ=\LFcro{1}^{(\kappa;\ell)}(r;\alpha,\beta)$ is a continuous curve that almost surely terminates at the target point $\ee^{\ii \beta-r}$ as $t \to r$ and it has winding $\ell$, i.e. $q^{-1}(\gamma)$ connects $\alpha$ to $\beta+2\pi\ell+\ii r$.

\item Boundary perturbation (in simply connected domain): for any simply connected test domain $\Omega\subset \A_r$ that agrees with $\A_r$ in neighborhoods of $\ee^{\ii \alpha}$ and $\ee^{\ii \beta-r}$, we denote by $\Ptwo^{(\kappa)}(\Omega;\ee^{\ii \alpha},\ee^{\ii \beta-r})$ the law of chordal $\SLE_{\kappa}$ in $(\Omega;\ee^{\ii \alpha};\ee^{\ii \beta-r})$, then 
	\begin{equation} 
		\frac{\ud \Ptwo^{(\kappa)}(\Omega;\ee^{\ii \alpha},\ee^{\ii \beta-r})}{\ud \Pcro{1}^{(\kappa;\ell)}(\A_r;\ee^{\ii \alpha},\ee^{\ii \beta-r})}(\gamma)=\frac{\LFcro{1}^{(\kappa;\ell)}(r;\alpha,\beta)}{\LZtwo(\Omega;\ee^{\ii \alpha},\ee^{\ii \beta-r})}  \one\{ \gamma\subset \Omega\} \exp\left(\frac{\mathfrak{c}}{2} \blm(\A_r;\gamma,\A_r\setminus \Omega)\right). 
\end{equation}
\item Boundary perturbation (in doubly connected domain): 
	for any doubly connected test domain $D \subset \A_r$ that agrees with $\A_r$ in neighborhoods of $\ee^{\ii \alpha}$ and $\ee^{\ii \beta-r}$, then
	\begin{equation}
		\frac{\ud \Pcro{1}^{(\kappa; \ell)}(D;\ee^{\ii \alpha},\ee^{\ii \beta-r})}{\ud \Pcro{1}^{(\kappa;\ell)}(\A_r;\ee^{\ii \alpha},\ee^{\ii \beta-r})}(\gamma)=
		\frac{\LFcro{1}^{(\kappa;\ell)}(r;\alpha,\beta)}{\LFcro{1}^{(\kappa;\ell)}(D;\ee^{\ii \alpha},\ee^{\ii \beta-r})}
		\one\{\gamma\subset D\}
		\exp\left(\frac{\mathfrak{c}}{2}\blm(\A_r;\gamma,\A_r \setminus D)\right).
	\end{equation}
\end{itemize}","status":"unverified"}

