{"assumptions":[],"created_at":"2026-10-28T01:16:46.726830+00:00","domain":"probability theory","id":"claim_f7ca7e9461aa52b4acd238084f2d08eb062cf3bf12b38823df0f7f85b43c804f","kind":"lemma","schema_version":1,"statement":"[Lemma lm:AffentrangerWieacker of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] Fix $m\in\mathbb{N}$, $m\geq 1$, and let $\alpha\geq 0$, $a_1\geq a_2\geq\ldots\geq a_m>0$ and $c\in(0,1]$. 
    \begin{itemize}
        \item[(1)] Suppose that $a_{m-1}-a_m>0$. Then
    \begin{equation*}
        \int_{0}^1\ldots\int_{0}^1 (1-cx_1\cdots x_m)^{n-\alpha} x_1^{a_1}\cdots x_m^{a_m} \, \textup{d} x_m\ldots\textup{d} x_1
        = \frac{\Gamma(a_m+1) (cn)^{-(a_m+1)}}{(a_1-a_m)\cdots(a_{m-1}-a_m)} (1+ o_n(1)),
    \end{equation*}

        \item[(2)] Suppose that $\ell\in\{1,\ldots,m-1\}$ is the smallest index such that $a_\ell=\ldots=a_m$. Then
        \begin{equation*}
        \int_{0}^1\ldots\int_{0}^1 (1-cx_1\cdots x_m)^{n-\alpha} x_1^{a_1}\cdots x_m^{a_m} \, \textup{d} x_m\ldots\textup{d} x_1
        = {\Gamma(a_\ell+1)(cn)^{-(a_\ell+1)}(\log n)^{m-\ell}\over(a_1-a_\ell)\cdots(a_{\ell-1}-a_\ell)}(1+o_n(1)).
        \end{equation*}
    \end{itemize}","status":"unverified"}

