{"assumptions":[],"created_at":"2026-10-27T12:10:07.391753+00:00","domain":"probability theory","id":"claim_f8313fb707c0be345696026a1a41edab5784fe479d7be7606746db8b89d0e85d","kind":"concept","schema_version":1,"statement":"[Theorem th:near-critical-scaling of arXiv:2606.11503, 'Percolation on hierarchical lattices'] For any $\lambda \in \mathbb{R}$,
  \begin{equation}

    f_{k} \Big( p_\star + \frac{\lambda}{\zeta^k} \Big) \to h^{-1}(\lambda),
  \end{equation}
  where the diffeomorphism $h: (0, 1) \to \mathbb{R}$ is characterized as the unique linear conjugation of $f$ (that is, $h \circ f = \zeta \cdot h$) such that $h'(p_\star) = 1$.

  \nc{c:tail_h_1}
  \nc{c:tail_h_2}
  Moreover, there exist constants $\uc{c:tail_h_1}, \uc{c:tail_h_2} > 0$ such that
  \begin{equation}

    \exp \Big( -\uc{c:tail_h_1} |\lambda|^\nu \Big)
    \leq h^{-1}(\lambda)
    \leq \exp \Big( -\uc{c:tail_h_1}^{-1} |\lambda|^\nu \Big),
    \text{ as $\lambda \to -\infty$}
  \end{equation}
  and
  \begin{equation}

    1 - \exp \Big( -\uc{c:tail_h_2} \lambda^\mu \Big)
    \leq h^{-1}(\lambda)
    \leq 1 - \exp \Big( -\uc{c:tail_h_2}^{-1} \lambda^\mu \Big),
    \text{ as $\lambda \to \infty$},
  \end{equation}
  where the exponents $\mu$ and $\nu$ are the ones appearing in (th:off-critical-decay of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:09.866324+00:00","domain":"probability theory","id":"claim_f8320f87d93659d4749e8359c282ff5aaf6fe95e85ef1a16a4556f11713777a7","kind":"lemma","schema_version":1,"statement":"[Lem 25 of arXiv:2605.21638, 'Markov renewal theory for transfer operators and point processes on the line'] Let $k<n,\,f\colon \mathbb{R}^k \to \mathbb{R}$ be a bounded measurable function, then there exist $C, C' > 0$, such that
