    \pi_{(i)}:=(s_0\rightarrow s_0s_1 \rightarrow \dots \rightarrow s_0s_1\dots s_{i}).\addtocounter{equation}{1}\tag{\theequation} 
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.690794+00:00","domain":"probability theory","id":"claim_f847ab0686ab96521ba4c79546a2c472c127379b1f4fc9112328547af9245c87","kind":"concept","schema_version":1,"statement":"[Cor sum_hausdorff_range of arXiv:2605.29073, 'Volterra clocks and their pure-jump limits: \\hitting times of curved boundaries'] Let $(\phi^n,\tau^n)$ and $(\psi^n,\varsigma^n)$ be as in Proposition (prop:cont_image_jump of the paper). Write $y^n=\psi^n\circ \varsigma^n$ and $y=\psi \circ \varsigma$. If $D(\tau) \cap D(\varsigma) = \emptyset$, then, for all $t\in[0,T]$, we have
	\[
\limsup_{n\rightarrow \infty} d_{\mathrm{H}}\bigl(\hspace{1.5pt}(x^n+y^n)\bigl(B(t,\delta)\bigr) ,\hspace{1.2pt}
I_t\hspace{0.2pt}\bigr) \rightarrow 0\quad \text{as}\quad \delta \rightarrow 0,
	\]
where $I_t = \{x(t)+y(t)\}$ if $t\notin D(\tau) \cup D(\varsigma)$, $I_t = \{x(t)\} + \psi([\varsigma(t-),\varsigma(t)])$ if $t\in D(\varsigma)$ and $I_t = \{y(t)\} + \phi([\tau(t-),\tau(t)])$ if $t\in D(\tau)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.778713+00:00","domain":"probability theory","id":"claim_f848431413029ffc5b765e8cf203788b9c4efaf6f1ce1e89e230639069e3cd82","kind":"concept","schema_version":1,"statement":"[Theorem mintheorem of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Fix $\beta \in (0,\infty)$, and let $\tilde W:{\mathcal C }_\beta\to \mathbb{R}$ defined as $\tilde W(\omega)=\int_0^\beta W(\omega(s)) {\rm d} s$ for all $\omega \in {\mathcal C }_\beta$, where $W$ is a Soft-wall potential. Denote by  $\varphi:\mathbb{R} ^ d \to \mathbb{R}$ the $L^2(\mathbb{R}^d)$-normalized eigenfunction of the operator $-\Delta +W$ which corresponds to the principle eigenvalue 
        \begin{equation}
        \lambda(W)=\sup_{\varphi\in H^1(\mathbb{R}^d)\colon , \|\varphi\|_2=1}\Big(\langle W,\varphi^2\rangle-\|\nabla\varphi\|_2^2\Big).
    \end{equation}
    \noindent Then, setting
    \begin{equation}
     q^*({\rm d} x,{\rm d} y):=\varphi(x)\varphi(y)\frac{\mathbb{E}_x\left[e^{\tilde W -\beta\lambda (W)}; B_\beta \in {\rm d} y\right]}{{\rm d} y}\,{\rm d} x {\rm d} y,  
    \end{equation}
 we have that $\mu^*_{g,{\mathfrak m},W}$ defined in (equation minimizergen of the paper) with $q^*_{g,{\mathfrak m},W}$ replaced by $q^*$ in (equation pairscr of the paper) is an ergodic Markov process which corresponds to the solution to the problem
 \begin{equation}
     {\rm d} X_t=\frac{\nabla \varphi}{\varphi}{\rm d} t+{\rm d} B_t,\quad X_0 \text{ has distibution with density } \varphi^2 \text{ with respect to the Lebesgue measure}
 \end{equation}
 with invariant measure with density $\phi^2$, and it is the unique minimizer of $I_{{\mathfrak m},W,g}^{(sym)}$, when ${\mathfrak m}={\rm Leb}$ and $g\equiv p_\beta$. Moreover, $\mu^*_{g,{\mathfrak m},W}$ is a solution to the optimal transport problem:
$$\inf\{H(Q|\mathbb{P}_{\mathfrak m}): Q\circ\pi_0^{-1}=\phi^2(x){\rm d} x,Q\circ\pi_\beta^{-1}=\phi^2(x){\rm d} x\}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

