{"assumptions":[],"created_at":"2026-10-27T15:02:17.908064+00:00","domain":"probability theory","id":"claim_f87c5be63f2830f25c3e538fa885e81967d029e3d3b3fae7d7d9efc3fe6665b6","kind":"concept","schema_version":1,"statement":"[Lemma lem:convergencecycles of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Let $\gamma$ be a smooth, oriented, closed curve in $\Sigma\setminus \min(f)$ transverse to $V$. We denote by $[\gamma]$ the corresponding current of integration induced in the blow--up surface $\mathcal{S}$. Then 
\begin{align*}  
\varphi_f^{t*}[\gamma]\rightarrow  \sum_{a\in \mathrm{Crit}(f)_1} \left(\int_\Sigma U_a\wedge [\gamma]\right) S_a +\left( \int_{\Sigma}[\gamma_0]\wedge [\gamma] \right) [\partial\mathcal{S}_{in}]     
\end{align*}
when $t\rightarrow +\infty$ where the convergence on the r.h.s. holds in the sense of currents in the blow up surface $\mathcal{S}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.094339+00:00","domain":"probability theory","id":"claim_f882633f5edf11c65d8fa93780f140c709f0ffd1b71cdfa9f8d2e07147509aaa","kind":"concept","schema_version":1,"statement":"[Prop proposition:L* of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Under $\mathbf{N}_{x,r}$, the following convergence  holds     \begin{equation} 
        \lim_{k\to\infty} \sup_{t\geq 0}\Big|L_{t}(\rho,W)- \frac{1}{\varepsilon_k} \int_0^t {\mathrm{d}} s \,  \mathbbm{1}_{\{ \uptau(W_s) <H(\rho_s) < \uptau(W_s) + \varepsilon_k \}} \Big|=0, \quad \text{a.e.} 
    \end{equation}
    Furthermore, if under $\mathbf{N}_{x,r}$  we write $(s_i,t_i)_{i\in \mathcal{I}}$ for the connected components of $\{H(\rho_s)>\uptau(W_s):~s\geq 0\}$ and we let $(\rho^i,\overline{W}^i)_{i \in \mathcal{I}}$ be the associated subtrajectories, conditionally on $L_\sigma(\rho,W)$,  the point measure 
         \begin{equation}
             \sum_{i \in \mathcal{I}}\delta_{(L_{s_i}(\rho,W), \rho^i, \overline{W}^i )}
         \end{equation}
        is a Poisson point measure with intensity $\mathbbm{1}_{[0,L_\sigma(\rho,W)]}(\ell) {\mathrm{d}} \ell \,  \mathbb{N}_{x,0}({\mathrm{d}} \rho , {\mathrm{d}} \overline{W})$, independent of $\mathrm{tr}(\rho,W)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:13:22.535614+00:00","domain":"probability theory","id":"claim_f888d0155c786083df7d09db1525dbc684ccc82d151dab9861ca3dd3f90a1760","kind":"lemma","schema_version":1,"statement":"[Lemma lem.coarse_grained_VFj of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Let $v_{m}$ follow the canonical grain extension in Definition~(def.ConstantExtension_canonical of the paper) and fix $\mathsf{r} \in (\frac{50}{27}, 2)$. Every ${\scaleobj{1}{\square}}_m \in  \mathcal{G}^{(N)}_{k}$  satisfies the following estimates:
		\begin{itemize}
			\item For every $F \subseteq E_d({\scaleobj{1}{\square}}_m)$ with $\vert F \vert \leqslant N - j$, every ${\scaleobj{1}{\square}}' \subseteq {\scaleobj{1}{\square}}$ satisfying 
			\begin{align*}
				0 \leqslant h' \leqslant h \leqslant k-1, \quad &{\scaleobj{1}{\square}} \in \mathcal{P}^{(N,k)}_{h}({\scaleobj{1}{\square}}_m), \quad {\scaleobj{1}{\square}}' \in  \mathcal{P}^{(N,k)}_{h'}({\scaleobj{1}{\square}}_m), 
			\end{align*}
			and every edge $e \in  E_d\left(\frac{16}{15} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}}_m\right)$, we have
			\begin{multline}
				|\nabla V_m(F,j \vert {\scaleobj{1}{\square}})(e)| \leqslant \sum_{e' \in \mathcal{E}(\mathscr{C}_{**}^F(\mathsf{r} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}}_m))} \vert  \nabla V_m(F,j)(e')\vert  \mathbf{1}_{\left\{F_\circ = \emptyset\right\}}   \\
				+ \sum_{\ell=1}^j \sum_{\substack{|G|= \ell \\ G\subseteq E_d(\mathsf{r} {\scaleobj{1}{\square}}) \setminus F}} \sum_{e' \in \mathcal{E}(\mathscr{C}_{**}^F(\mathsf{r} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}}_m))} \left\vert \nabla V_m(F \cup G,j-\ell \vert {\scaleobj{1}{\square}})(e') \right\vert \mathbf{1}_{\left\{F_\circ = \emptyset\right\}} \\
				+2^{\vert F_\circ \vert} \sum_{e' \in \mathcal{E}(\mathscr{C}_{**}^F(\mathsf{r} {\scaleobj{1}{\square}}' \cap {\scaleobj{1}{\square}}_m))}  |\nabla V_m(F_*,j \vert {\scaleobj{1}{\square}})(e')| \Ind{F_\circ \subseteq E_d(\mathsf{r} {\scaleobj{1}{\square}}')}\mathbf{1}_{\left\{F_\circ \neq \emptyset\right\}}.
			\end{multline}
			\item There exists a finite positive constant $C \equiv C(i,j) = 2^i(j+1)$, such that for all positive integers satisfying $N \geqslant i+j$ and $k \geqslant h+2$, we have
			\begin{align}
				\widetilde{I}^{\, (N,k)}_{m,\alpha, h}(i,j) \leqslant C \left(I^{*  \, (N,k)}_{m,\alpha+1, h}(i,j) + \sum_{\substack{0 \leqslant \ell' \leqslant i, 0 \leqslant \ell \leqslant j\\ (\ell',\ell) \neq (0,0)}}\widetilde{I}^{\, (N,k)}_{m,\alpha+\ell+ \ell' + 2, h+1}(i-\ell'+\ell,j-\ell)\right).
			\end{align}
		\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:17:04.328511+00:00","domain":"probability theory","id":"claim_f8895d5014eb3270132753928d74d44c14d12ec636e37d381aad455ebaebaf64","kind":"theorem","schema_version":1,"statement":"[Corollary cor:equivalenceofensembles of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Let $f:\Omega\longrightarrow\mathbb{R}$ be a local function whose support is included in $\{0,\hdots ,\ell_0-1\}$ for some $\ell_0\ge 1$. Then, there exists a constant $C_3=C_3(f,\rho ,\mathcal{E})>0$ such that for any $\ell\ge\ell_0$, we have
    \begin{multline}
        \int_{\Omega}\bigg( \mathbb{E}_\ell[f] - \psi_f(\rho ,\mathcal{E}) - \nabla\psi_f(\rho ,\mathcal{E})\cdot \overline{\mathbf{u}}^\ell \\ - \frac12 \left( (\overline{\mathbf{u}}^\ell)^\top \mathrm{Hess}(\psi_f)(\rho ,\mathcal{E})\overline{\mathbf{u}}^\ell -\frac{1}{\ell}\mathrm{Tr}\big(\chi\mathrm{Hess}(\psi_f)\big)(\rho ,\mathcal{E})\right)\bigg)^2\,\mathrm{d}\mu_{\rho ,\mathcal{E}}(\eta )\le \frac{C_3}{\ell^3}
    \end{multline}
    where $\overline{\mathbf{u}}^\ell = \overline{\mathbf{u}}^\ell (\eta )$ is the column vector whose coordinates are $\xi_0^\ell -\rho$ and $\eta_0^\ell -\mathcal{E}$. In particular, 
    \begin{itemize}
        \item if $\psi_f(\rho ,\mathcal{E}) = 0$, we can choose the constant $C_3$ so that
        \begin{equation*}
            \mathrm{Var}_{\rho ,\mathcal{E}}\big( \mathbb{E}_\ell [f]\big) \le \frac{C_3}{\ell};
        \end{equation*}
        \item if $\psi_f(\rho ,\mathcal{E})=0$ and $\nabla\psi_f(\rho ,\mathcal{E})=0$, we can choose the constant $C_3$ so that
        \begin{equation*}
            \mathrm{Var}_{\rho, \mathcal{E}}\big( \mathbb{E}_\ell [f]\big) \le \frac{C_3}{\ell^2};
        \end{equation*}
        \item if $\psi_f(\rho ,\mathcal{E})=0$, $\nabla\psi_f(\rho ,\mathcal{E})=0$ and $\mathrm{Hess}(\psi_f)(\rho ,\mathcal{E})=0$, we can choose the constant $C_3$ so that
        \begin{equation*}
            \mathrm{Var}_{\rho ,\mathcal{E}}\big( \mathbb{E}_\ell [f]\big) \le \frac{C_3}{\ell^3}.
        \end{equation*}
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:28:49.114241+00:00","domain":"probability theory","id":"claim_f891ca5e7721f79eaeb2edcd868330e884cf9800000b1f780b70bf12f80b5e6e","kind":"lemma","schema_version":1,"statement":"[Lem LM24 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Let $x\in E$ and $B\in \mathscr{B}^n(E)$. Then the following statements hold:
