{"assumptions":[],"created_at":"2026-10-26T19:47:01.663148+00:00","domain":"probability theory","id":"claim_f90cefa09e4211324f623a10c49ccce4d0eb697cdf4bed1645b263a4ccc43437","kind":"concept","schema_version":1,"statement":"[Lemma 8 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] (i) Let $\phi(x)=\left(1+\frac{1}{x^2}\log \frac{2x-1}{2(x-1)}\right)^{\frac{1}{2}}-1$ and $1<q<\infty$. Suppose that $\|Z\|_{BMO_G}<\phi(q)$. Then, we have 
    \begin{align*}
        \sup_{\P\in\mathcal{P}}\sup_{\tau\in \mathcal{T}_0^T}\left\|\E^{\P}_\tau\left[\frac{\mathcal{E}(Z)_T^q}{\mathcal{E}(Z)_\tau^q}\right]\right\|_{L^\infty(\P)}\leq C_q,
    \end{align*}
    where $C_q>0$ is a constant depending only on $q$. 

    \noindent (ii) Given $1<r<\infty$, suppose that $\|Z\|_{BMO_G}<\frac{\sqrt{2}}{2}(\sqrt{r}-1)$. Then, we have
    \begin{align*}
        \sup_{\P\in\mathcal{P}}\sup_{\tau\in \mathcal{T}_0^T}\left\|\E^{\P}_\tau\left[\left(\frac{\mathcal{E}(Z)_\tau}{\mathcal{E}(Z)_T}\right)^{\frac{1}{r-1}}\right]\right\|_{L^\infty(\P)}\leq C_r,
    \end{align*}
    where $C_r>0$ is a constant depending only on $r$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.067711+00:00","domain":"probability theory","id":"claim_f90e12d5964502bf64b779a9d575566bfe18c51a1de3d748a9497f13c16ee745","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2606.27545, 'A simple proof of rapid mixing on random regular graphs beyond uniqueness'] Let $\mathcal{X} \subseteq \{0,1\}^V$ be a non-empty downward closed set family and suppose $\mu$ is a distribution fully supported on $\mathcal{X}$.  Suppose that for $\delta \in (0,1)$ we have that for all $\sigmabf \in \mathcal{X}$ the matrix $M_{\sigmabf}\in \R^{V\times V}$ given by
		\begin{equation}
			M_{\sigmabf}(u,v)=(1 - \delta)r_v(\sigmabf)\one_{u = v} - r_v(\sigmabf)(r_u(\sigmabf\cup \{v\}) - r_u(\sigmabf))  
		\end{equation}
		is positive semidefinite. Then continuous time Glauber dynamics for $\mu$ has spectral gap at least $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:52:57.718691+00:00","domain":"probability theory","id":"claim_f90ed45b259fe4d1c96a59aa8bedeb216bae6e03a3743c299637d86558efe95a","kind":"theorem","schema_version":1,"statement":"[Proposition 31 (Deterministic bias, mixed-damping regime) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Under Assumptions~\ref{ass:diagonal-covariance} and~\ref{ass:power-law}, for the mixed-damping regime \(\eta\gtrsim(1-\rho)^2\), the deterministic bias decomposes into $\cS_{\nesterov}(k) = \cS_{\mathrm{over}}(k) + \cS_{\mathrm{under}}(k)$, where the overdamped tail satisfies the two-sided bounds:
\begin{equation*}
    \cS_{\mathrm{over}}(k)
    \eqsim
    \begin{cases}
    \left(\frac{(1-\rho)^2}{\eta}\right)^s, &\qquad k\lesssim\frac{1}{1-\rho},\\
    \left(\frac{1-\rho}{\eta k}\right)^s, &\qquad k\gtrsim\frac{1}{1-\rho},
    \end{cases}
\end{equation*}
and $\cS_{\mathrm{under}}(k)$ represents the underdamped transient whose properties are formally established in Lemma~\ref{lem:nes_underdamped_transient_properties}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.884311+00:00","domain":"probability theory","id":"claim_f90f6a2ed8de358a26ad12f5074fd02c02dae8fe773002904a334368692fdf60","kind":"theorem","schema_version":1,"statement":"[Proposition 7 (Additive-mixture identity) of arXiv:2608.21466, 'Spectral partitioning for $k$-block averaging kernels of finite Markov chains'] Let $k\in\llbracket 2,n-1\rrbracket$.
	For every $k$-block partition $\mathcal O$,
	\begin{equation}
		H(\mathcal O)
		=\operatorname{Tr}\left(
		\frac{P^2}{4}
		+\frac{G_{\mathcal O}P}{2}
		+\frac{G_{\mathcal O}}{4}
		-\Pi
		\right).

	\end{equation}
	Moreover,
	\begin{equation}
		H(\mathcal O)
		=C_{P,k}
		+\frac12\operatorname{Tr}(Q_{\mathcal O}P),

	\end{equation}
	where
	\begin{equation}
		C_{P,k}
		:=\frac14\operatorname{Tr}(P^2)+\frac{k-2}{4}.

	\end{equation}
	Consequently, for fixed $P$ and $k$,
	\begin{equation*}
		\operatorname*{argmin}_{|\mathcal O|=k}H(\mathcal O)
		=
		\operatorname*{argmin}_{|\mathcal O|=k}
		\operatorname{Tr}(Q_{\mathcal O}P).

	\end{equation*}","status":"unverified"}

