{"assumptions":[],"created_at":"2026-10-27T18:51:26.749159+00:00","domain":"probability theory","id":"claim_f9bae805c30c7ec104e59d30c07143ba21175b17292a493842a1f0b081c8998e","kind":"concept","schema_version":1,"statement":"[Lemma tightness_tau_k of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix a choice sequence $\mathbf x$ that satisfies Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper) and~(item:lb of the paper). Then, for any sequence $(I_n)_{n\in\mathbb{N}}$ with $I_n\geq I_{\hyperref[ass:A]{\mathbf{x}}}$ for all large $n$, there exists $\zeta\in(0,1)$ such that
\begin{equation}
\mathbb{P}(\tau_{k,\ell}\geq I_n)= o(I_n^{-\zeta}).
\end{equation}
\proof
Let $(U_n^w)_{w\in[\ell]}$ be $\ell$ distinct uniform elements of $\mathcal{F}_n$. Here, $U_n^w$ corresponds to the step at which the frozen vertex $f_w$ is activated. By conditioning on $(U_n^w)_{w\in[\ell]}$, we obtain 
\begin{equation} 
\P{\tau_{k,\ell}<I_n}=\E{\P{\tau_{k,\ell}<I_n\,|\, (U_n^{w})_{w\in[\ell]}}}=\E{\P{\tau_{k,\ell}<I_n\,\Big|\, ( U_n^{(w)})_{w\in[\ell]}}},
\end{equation} 
where the $ U_n^{(w)}$ are the order-statistics of the $U_n^w$. That is, $ U_n^{(1)}>\cdots > U_n^{(\ell)}$. Conditionally on these random variables, the event $\{\tau_{k,\ell}<I_n\}$ holds when at each step $i\in[I_n,n]$ such that $x_i=1$ and $ U_n^{(w-1)}>i> U_n^{(w)}$ for some $w\in[\ell+1]$ (where we set $ U_n^{(0)}=n+1$ and $ U_n^{(\ell+1)}=1$), the $(m+1)\wedge A_i$ many roots that are selected contain at most one of the $k+w-1$ many active roots of interest (the active roots labelled $a_1,\ldots,a_k$ and the first $w-1$ roots that are activated among $f_1,\ldots,f_\ell$). As a result, we have 
\begin{equation}\begin{aligned}

\mathbb P\big(\tau_{k,\ell}<I_n\,\big|\, ( U_n^{(w)})_{w\in[\ell]}\big)= \prod_{w=1}^{\ell+1} \prod_{\substack{i=\max\{ U_n^{(w)}+1,I_n\}\\ x_i=1}}^{ U_n^{(w-1)}-1} \!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\!\P{\text{At most one root among $k+w-1$ chosen in step $i$}}
\end{aligned}\end{equation} 
By Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:lb of the paper),  we have $A_i\geq m+1$ for all $i\geq I_n$ and all large $n$. For $w\in[\ell+1]$, if $ U_n^{(w-1)}-1>I_n$ and $i\in[\max\{ U_n^{(w)}+1,I_n\}, U_n^{(w-1)}-1]$, we then have 
\begin{equation}\begin{aligned} 
\mathbb P({}&\text{At most one root among $k+w-1$ chosen in step $i$})\\ 
&=\frac{1}{\binom{A_i}{m+1}}\bigg(\binom{A_i-(k+(w-1))}{m+1}+(k+(w-1))\binom{A_i-(k+(w-1))}{m}\bigg)\\ 
&=1-\frac{1}{\binom{A_i}{m+1}}\bigg(\binom{A_i}{m+1}-\binom{A_i-(k+(w-1))}{m+1}-(k+(w-1))\binom{A_i-(k+(w-1))}{m}\bigg).
\end{aligned}\end{equation} 
By repeatedly applying Pascal's rule, we find that, for integers $s,t,r\geq 0$ such that $t-s\geq r$,
\begin{equation} 
\binom{t}{r}=\binom{t-1}{r-1}+\binom{t-1}{r}=\cdots=\binom{t-s}{r}+\sum_{\ell=1}^s \binom{t-\ell}{r-1}.
\end{equation} 
Applying this equality with $(1)$: $t=A_i$, $r=m+1$, and $s=k+(w-1)$ and $(2)$: $t=A_i-\ell$, $r=m+1$, and $s=k+(w-1)-\ell$, where $\ell\in[k+(w-1)-1]$, we arrive at 
\begin{equation}\begin{aligned} 
\binom{A_i}{m+1}{}&-\binom{A_i-(k+(w-1))}{m+1}-(k+(w-1))\binom{A_i-(k+(w-1))}{m}\\ 
={}&\sum_{\ell=1}^{k+(w-1)-1}\sum_{x=\ell+1}^{k+(w-1)}\binom{A_i-x}{m-1}\leq (k+(w-1))^2\binom{A_i-2}{m-1}\leq (k+(w-1))^2 A_i^{m-1}.
\end{aligned}\end{equation} 
As a result, we have the lower bound
\begin{equation} 
\mathbb P(\text{At most one root among $k+w-1$ chosen in step $i$})\geq 1-\frac{(k+(w-1))^2 A_i^{m-1}}{\binom{A_i}{m+1}}\geq 1-C A_i^{-2}, 
\end{equation} 
where the constant $C>0$ does not depend on $i$ and $w$. We use this in~(equation eq:ptaukl of the paper) to obtain 
\begin{equation} 
\P{\tau_{k,\ell}<I_n}\geq \mathbb E\Bigg[\prod_{w=1}^{\ell-1}\prod_{\substack{i=\max\{ U_n^{(w)}+1,I_n\}\\ x_i=1}}^{ U_n^{(w)-1}}\big(1-C A_i^{-2}\big)\Bigg]\geq 1-C\sum_{w=1}^{\ell-1}\mathbb E\Bigg[\sum_{\substack{i=\max\{ U_n^{(w)}+1,I_n\}\\ x_i=1}}^{ U_n^{(w)-1}} A_i^{-2}\Bigg].
\end{equation} 
We can further bound the right-hand side from below by $1-C\sum_{i=I_n}^n A_i^{-2}$. By using Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:lb of the paper), we finally obtain
\begin{equation} 
\P{\tau_{k,\ell}<I_n}=1-\mathcal{O}(I_n^{-2\delta}).
\end{equation} 
Choosing $\zeta\in(0,2\delta)$ concludes the proof.\qed (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

