{"assumptions":[],"created_at":"2026-10-26T19:29:52.204012+00:00","domain":"probability theory","id":"claim_f9dde3a541867e72f93ce3391daaabdae0b03d731d27ed70ea7f6353c896cce6","kind":"concept","schema_version":1,"statement":"[Proposition 12 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let {\rm\Cref{assumpNecessity_meanField}}.\ref{Glip_meanField} and {\rm\Cref{assumption:borelMeasurability_Lip2}} hold. We consider $(Y^{1}, Z^{1,1}, M^{1,\star}, \Z^{1,m,1,\star,})$ solving the following system of {\rm BSDEs}
\begin{align}
\notag Y^1_t &= g\big(X^1_{\cdot \land T}, \cL_{\hat\alpha}(X^1_{\cdot \land T})\big) + G\big(\varphi_1(X^1_{\cdot \land T}),\varphi_2(\cL_{\hat\alpha}(X^1_{\cdot \land T}))\big) + \int_t^T f_s\big(X^1_{\cdot \land s},\cL_{\hat\alpha}(X^1_{\cdot \land s},\hat\alpha_s),\hat\alpha_s\big) \d s \\
\notag &\quad - \frac{1}{2} \int_t^T \partial^2_{m,m}G\big(M^{1,\star}_s,N^{\star}_s\big) \big\|Z^{1,m,1,\star}_s\big\|^2 \d s - \int_t^T Z^{1,1}_s \cdot \d \big(W_s^{\hat\alpha}\big)^1, \; t \in [0,T], \; \P \text{\rm--a.s.}, \\
\notag M^{1,\star}_t &\;= \varphi_1(X^1_{\cdot \land T}) - \int_t^T Z^{1,m,1,\star}_s \cdot \d \big(W_s^{\hat\alpha}\big)^1, \; t \in [0,T], \; \P \text{\rm--a.s.}, \\
\notag N^{\star}_t &\coloneqq \varphi_2(\cL_{\hat\alpha}(X^1_{\cdot \land T})), \; t \in [0,T], \; \P\text{\rm--a.s.},\\
\notag \hat\alpha_t &\coloneqq \mathfrak{a}\big(t,X^1_{\cdot \land t},\cL_{\hat\alpha}(X^1_{\cdot \land t},\hat\alpha_t),Z^{1,1}_t,M^{1,\star}_t,Z^{1,m,1,\star}_t\big), \;  \mathrm{d}t\otimes\P\text{\rm--a.e.},\\
\frac{\d \P^{\hat\alpha}}{\d \P} &\coloneqq \cE\bigg( \int_0^\cdot b_s\big(X^1_{\cdot \land s},\cL_{\hat\alpha}(X^1_{\cdot \land s},\hat\alpha_s),\hat\alpha_s\big) \cdot \d W^1_s \bigg)_T,
\end{align}
where the $(\F^1,\P^{\hat\alpha})$--Brownian motion $(W^{\hat\alpha})^1$ is defined by
\begin{align*}
(W^{\hat\alpha}_t)^1 \coloneqq W^1_t-\int_0^t b_s\big(X^1_{\cdot \land s},\cL_{\hat\alpha}(X^1_{\cdot \land s},\hat\alpha_s),\hat\alpha_s\big) \d s, \; t \in [0,T].
\end{align*}
We additionally assume the existence of some $p \geq 1$ such that 
\begin{align*}
&\sup_{\alpha \in \cA^\smalltext{1}} \E^{\P^{\smalltext{\alpha}}} \Bigg[ \sup_{t \in [0,T]} \big|Y^{1}_t\big|^p + \bigg(\int_0^T \big\|{Z}_t^{1,1}\big\|^2 \d t\bigg)^\frac{p}{2} \Bigg] +\esssup_{\alpha \in \cA^\smalltext{1}} \Bigg(\sup_{t \in [0,T]} \big| M^{1,\star}_t\big| + \sup_{\tau \in \cT_{0,T}} \E^{\P^{\smalltext{\alpha}\smalltext{,}\smalltext{1}\smalltext{,}\smalltext{\tau}}_{\smalltext{\cdot}}} \bigg[ \int_\tau^T \big\|Z^{1,m,1,\star}_t\big\|^2 \d t \bigg] \Bigg) <+\infty.
\end{align*}
It then holds that $\hat\alpha$ is a sub-game--perfect mean-field equilibrium, and $J^1\big(t,\cdot,\hat\alpha;(\cL_{\hat\alpha}(X^1_{\cdot \land s}, \hat\alpha_s))_{s\in[0,T]}\big) = Y^{1}_t$, $\P\text{\rm--a.s.}$, for any $t\in [0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.571568+00:00","domain":"probability theory","id":"claim_f9e3b10ae23100c79db2e78d3c6a263785d625174c6d1f2565def220ed80467f","kind":"concept","schema_version":1,"statement":"[Theorem T:Zero of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose $\alpha>0$, $\beta\in(0,2)$, $\gamma \ge 0$, and $d \in \mathbb{N}$.
  The function $f(z)$, defined in~(equation E:f(x) of the paper), is an analytic function within
  the cone $|\arg z| < (1-\beta/2)\pi$.  Moreover, we have the following
  algebraic asymptotic expansion for $f(z)$ at zero:

  \begin{enumerate}[\rm (i)]

    \item If $\alpha>0$ satisfies the following condition
          \begin{align}
            \alpha \not\in \left\{\frac{2\ell_1+d}{\ell_2+1} :\: \ell_1, \ell_2 = 0, 1,2,\cdots\right\},
          \end{align}
          then
          \begin{align}
            f(z) \sim \sum_{\ell=0}^{\infty} h_{1,\ell}^* z^{\frac{d+2\ell}{\alpha}} + \sum_{\ell=0}^{\infty} h_{2,\ell}^*  z^{\ell+1} \quad \text{as $z\to 0$ with $|\arg z |< (1-\beta/2)\pi$},
          \end{align}
          where
          \begin{align}
            \begin{aligned}
              h_{1,\ell}^* & = \frac{2(-1)^\ell \pi \csc\left((d+2\ell)\pi/\alpha\right)}{\alpha \ell! \Gamma(\ell +d/2) \Gamma\left(\beta+\gamma - (d+2\ell) \beta/\alpha\right)} \quad \text{and} \\
              h_{2,\ell}^* & = \frac{(-1)^\ell \Gamma \left((d-(\ell+1) \alpha)/2\right)}{\Gamma \left((\ell+1) \alpha/2\right) \Gamma (\gamma - \ell \beta)}.
            \end{aligned}
          \end{align}

    \item Otherwise, suppose that
          \begin{align}
            \alpha = \frac{2\ell_1 +d}{\ell_2+1} \quad \text{for some $(\ell_1,\ell_2) \in \mathbb{N}_0^2$}.
          \end{align}
          Let $(\ell_1^*,\ell_2^*)$ be the smallest such integers, i.e.,
          \begin{align*} 
            (\ell_1^*,\ell_2^*) \coloneqq \ensuremath{\mathrm{Argmin}} \left\{(\ell_1,\ell_2)\in \mathbb{N}_0^2:\: \alpha = \frac{2\ell_1 +d}{\ell_2+1}\right\}.

          \end{align*}
          Denote $\mathcal{L}_1^c \coloneqq \mathbb{N}_0 \setminus \mathcal{L}_1$ and $\mathcal{L}_2^c \coloneqq \mathbb{N}_0 \setminus \mathcal{L}_2$ with
          \begin{align}
            \begin{aligned}
              \mathcal{L}_1 & \coloneqq \left\{\frac{(2\ell_1^*+d) r -d}{2}:\: \text{$r \in \mathbb{N}$ when $d$ is even or $r\in 2\mathbb{N}-1$ when $d$ is odd} \right\} \quad \text{and} \\
              \mathcal{L}_2 & \coloneqq \bigg\{(\ell_2^*+1) r - 1:\: \text{$r \in \mathbb{N}$ when $d$ is even or $r \in 2\mathbb{N}-1$ when $d$ is odd} \bigg\}.
            \end{aligned}
          \end{align}
          Then for $|\arg z|< (1-\beta/2) \pi$ and as $z\to 0$,
          \begin{align}
            \begin{aligned}
              f(z) = & \sum_{\ell\in \mathcal{L}_1^c} h_{1,\ell}^* z^{\frac{d+2\ell}{\alpha}}
              + \sum_{\ell\in \mathcal{L}_2^c} h_{2,\ell}^* z^{\ell+1}                                                                                                                             \\
                     & + \frac{(-1)^{\ell_1^*+\ell_2^*+1} \left(\ell_2^*+1\right)}{\ell_1^*!\: \Gamma \left(d/2+\ell_1^*+1\right) \Gamma \left(\gamma -\beta \ell_2^*\right)} z^{\ell_2^*+1}\log z
              + o\left(z^{\ell_2^*+1}\log z\right),
            \end{aligned}
          \end{align}
          where the coefficients $h_{j,\ell}^*$, $j=1,2$, are defined in~(equation E:hstar of the paper).

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:06:21.751151+00:00","domain":"probability theory","id":"claim_f9e54418f0f5af59049253e12d1312bbaa98edfa304a5f2c110b4c61208f22ec","kind":"lemma","schema_version":1,"statement":"[Lemma 47 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Let \(I,J\subset\mathbb R\setminus\{0\}\) be disjoint and finite, and define
\begin{equation}
