         \end{equation*}
  \item  if in addition, assume that $\overline{X},\underline{X}\in (L_G^1(\Omega))^m$ or $X$ has no mean-uncertainty, there exists a constant $c_X\in\mathbb{R}$ such that 
			\[\lim_{n\to\infty}\frac{1}{n}\sum_{k=0}^{n-1}U_\tau^kX=c_X,\text{ }\hat{\mathbb{E}}\text{-q.s.}\]
