    \mathrm{K}(\boldsymbol{\xi}^1, \boldsymbol{\eta}^{23}, \boldsymbol{\eta}^2 | \boldsymbol{\eta}^1,  \boldsymbol{\xi}^{23}, \boldsymbol{\xi}^2) \, \\
