where 
\begin{equation*}   
    (a_{123}, a_{12}, a_{23}, a_1,a_2,a_3)=\type({\boldsymbol \sigma}), \qquad 
    (b_{123}, b_{12}, b_{23}, b_1,b_2,b_3)=\type({\boldsymbol \tau}). 
