    \PP(|P_{k,n}(x)-2\sqrt{nx}|\geq \alpha \sqrt{x} n^{-1/6})\leq C_3e^{-c_3\alpha^2 n^{-1/3}}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.656525+00:00","domain":"probability theory","id":"claim_fbafe69c5ff8c575814cf32947668239bc0fe901bad8318adfd55359fc10b0ee","kind":"theorem","schema_version":1,"statement":"[Prop thin-chaos of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\alpha\in(0,1)$. For any $a<a_c(\alpha)$, let $\mathds A_{-a,a}$ be a subcritical two-valued set in a valid domain $D$. For any continuous, bounded  function $f:\mathbb C\to\mathbb R$, 
    \begin{align}
    \lim_{n\to \infty} (\field{e^{i\alpha \phi}}, f\1_{[\mathds A_{-a, a}]_n}) =0, 
