\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.204834+00:00","domain":"probability theory","id":"claim_fcead4c760c27aee9e5eea9331b00b9f85c503419e740f0cdfd3c5a5a282306b","kind":"concept","schema_version":1,"statement":"[Lemm Lemma_YO of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] The following statements hold true.
\begin{align*}
\lim_{\delta{\rightarrow} 0}\norm{J_{\delta}(x)-x}_{\mathcal{K}}=0,\quad x\in {\rm Dom}(F).
\end{align*}
For every $0<\delta<|\zeta_F|^{-1}$ ($0<\delta<\infty$ if $\zeta_F=0$), the function $F_\delta-\zeta_F{\operatorname{I}}_{{\mathcal{K}}}$ is dissipative on ${\mathcal{K}}$. Moreover for every $0<\delta<|\zeta_F|^{-1}$ it holds
\begin{align}
{\left\|J_\delta(x)-x\right\|}_{\mathcal{K}}&\leq \delta\left(\|F(x)\|_K+\max\{0,\zeta_F\}\| x\|_{\mathcal{K}}\right),\qquad x\in {\rm Dom}(F);\\
\|F_{\delta}(x)\|_{\mathcal{K}}&\leq (1+\delta \max\{0,\zeta_F\})(\|F(x)\|_{\mathcal{K}}+2 \max\{0,\zeta_F\}{\left\|x\right\|}_{\mathcal{K}}),\qquad x\in {\rm Dom}(F);\\
{\left\|F_\delta(x)-F_\delta(y)\right\|}_K&\leq \left(2\delta^{-1}+ \max\{0,\zeta_F\}\right){\left\|x-y\right\|}_K,\qquad x,y\in{\mathcal{K}}.\\
{\left\|J_\delta(x)-J_\delta(y)\right\|}_{\mathcal{K}} &\leq {\left\|x-y\right\|}_K,\qquad x,y\in{\mathcal{K}}.
\end{align}
For every $x,y\in \mathcal{K}$ and $0<\delta,\tau<|\zeta_F|^{-1}$ we have
\begin{equation}
{\left\|J_\delta(x)-J_\tau(y)\right\|}_{\mathcal{K}}\leq \zeta_F{\left\|x-y\right\|}_{\mathcal{K}}+ (\delta+\tau)({\left\|F(y)\right\|}_{\mathcal{K}}+{\left\|F(x)\right\|}_{\mathcal{K}}+|\zeta_F|{\left\|y\right\|}_{\mathcal{K}}+|\zeta_F|{\left\|x\right\|}_{\mathcal{K}}).
\end{equation} 
If ${\mathcal{K}}$ is a Hilbert space, then for every $x,y\in {\rm Dom}(F)$ there exists $B:=B(\zeta_F)$ such that for every $\delta,\tau>0$ we have
\begin{equation}
\scal{F_{\delta}(x)-F_\tau(y)}{x-y}_{\mathcal{K}}\leq \zeta_F{\left\|x-y\right\|}_{\mathcal{K}}^2+(\delta+\tau)B({\left\|F(x)\right\|}_{\mathcal{K}}^2+{\left\|F(y)\right\|}_{\mathcal{K}}^2+{\left\|x\right\|}_{\mathcal{K}}^2+{\left\|y\right\|}_{\mathcal{K}}^2)
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:15:54.984059+00:00","domain":"probability theory","id":"claim_fcf063381931ec9ad28d1db3031d3b9f53ce15701d9e107a5b306d06aef42494","kind":"definition","schema_version":1,"statement":"[Definition see, e.g., \cite{wijesekera_constructive_1990, simpson_proof_1994} of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] For an f-model $\mathfrak{M} = (W, \leq, \sqsubset, V)$, we define an \emph{intrinsic satisfaction relation} $\Vdash^i_\mathfrak{M}$ on $W \times \mathscr{L}_{\Box\Diamond}$ by:
  \begin{enumerate}
    \item $x \Vdash^i_\mathfrak{M} \psi_1 \to \psi_2 \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x\, (x' \Vdash^i_\mathfrak{M} \psi_1 \mathrel{\Rightarrow} x' \Vdash^i_\mathfrak{M} \psi_2)$
    \item $x \Vdash^i_\mathfrak{M} \Box \varphi     \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x\, \forall y' \sqsupset x'\, (y' \Vdash^i_\mathfrak{M} \varphi)$
    \item $x \Vdash^i_\mathfrak{M} \Diamond \varphi \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x\, \exists y' \sqsupset x'\, (y' \Vdash^i_\mathfrak{M} \varphi)$
    \item The other cases are identical to the classical $\Vdash_\mathfrak{M}$.
  \end{enumerate}
  We write $\mathfrak{M} \vDash^i \varphi$ (``$\varphi$ is \emph{(i-)valid in} $\mathfrak{M}$'') to mean $\forall x \in W\,(x \Vdash^i_\mathfrak{M} \varphi)$,
  and $\mathfrak{F} \vDash^i \varphi$ (``$\varphi$ is \emph{(i-)valid on} $\mathfrak{F}$'') to mean that $\mathfrak{M} \vDash^i \varphi$ for every $\mathfrak{M}$ based on $\mathfrak{F}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.594051+00:00","domain":"probability theory","id":"claim_fcf0f0ef259472dfc59a09cd1f2be61900cd9413d9e166be0dc8c921c5b8a424","kind":"concept","schema_version":1,"statement":"[Proposition prop-4.1 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let~$\beta>0$ and assume that~$\{v_k'\}_{k=0}^n$ and~$\{v_k''\}_{k=0}^n$ are bounded uniformly in~$n\ge1$.
Then for all~$n\ge1$ and all $x,y\in\Lambda_n$,
