{"assumptions":[],"created_at":"2026-10-28T00:48:45.306889+00:00","domain":"probability theory","id":"claim_fd3505260daade34ccb78d7fb07ce735ad23569d3db428050c47bde78bb2c5ca","kind":"lemma","schema_version":1,"statement":"[Lemma lem:shift_X of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Assume that $\eta \in \Omega$.  For any $k, \ell \in {\mathbb{N}}$, $k > \ell$, $h \in {\mathbb{Z}}_{\ge 0}$ and $i \in {\mathbb{Z}}$, we have
                    \begin{align}
                        \xi_{\ell + h}\left(\eta, s_{k + h}\left(\eta, i\right)\right) 
                &= \xi_{\ell}\left(\Psi_{h}\left(\eta\right), s_{k}\left(\Psi_{h}\left(\eta\right), i\right) \right) \\
                &= s_{k - \ell}\left( \Psi_{\ell + h}\left(\eta\right), i \right) - s_{\infty}\left(\Psi_{\ell + h}\left(\eta\right), 0\right)  .
                    \end{align}
                In particular, if $s_{k + h}(\eta, i) = X^{(j)}_{k + h}(\eta,0)$ for some $j \in {\mathbb{Z}}$, then 
                    \begin{align}
                        s_{k - \ell}\left(\Psi_{\ell + h}\left(\eta\right), i \right) = X^{(j)}_{k-\ell}\left(\Psi_{\ell + h}\left(\eta\right),0\right) ,
                    \end{align}
                and thus
                    \begin{align}
                        \xi_{\ell + h}\left(\eta, X^{(j)}_{k + h}\left(\eta,0\right)\right) &= \xi_{\ell}\left(\Psi_{h}\left(\eta\right), X^{(j)}_{k}\left(\Psi_{h}\left(\eta\right),0\right) \right) \\
                        &= X^{(j)}_{k - \ell}\left( \Psi_{\ell+h}\left(\eta\right),0 \right) - s_{\infty}\left(\Psi_{\ell + h}\left(\eta\right), 0\right) \\
                        &= X^{(j)}_{k - \ell}\left( \Psi_{\ell+h}\left(\tilde{\eta}\right) ,0 \right) . 
                    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:33:43.760934+00:00","domain":"probability theory","id":"claim_fd366329b1f46ad1ac6570b1e8c1612e65261ee26cdca7e3e685d98e101bd2f2","kind":"concept","schema_version":1,"statement":"[Prop cor:Pottsconopt of arXiv:2609.02682, 'LDP for tensor forms'] Suppose we have
\begin{align*}
		W_\infty>0 \,\,\,\lambda\text{-a.e.},\quad \mathcal{V}[W_\infty](x)=1\,\,\lambda\text{-a.e.},\quad
    \text{and} \newline \quad\alpha_r = \theta\geq0 \,\,\text{for all  } r\in [c]. 
		\end{align*}
        Then the following conclusions hold:






	\begin{itemize}
		\item[(i)] Let $\boldsymbol h$ be such that $h_1\ge \eta+\max_{2\le r\le c}h_r$, where $\eta=\eta(c,v)$ is as in~(prop:potts_diffalpha of the paper), part (ii). For every $\theta\geq 0$, let $(x_{\theta,\boldsymbol h,1},\ldots ,x_{\theta,\boldsymbol h,c})$ be the unique optimizer from~(prop:potts_diffalpha of the paper), part (ii). Then the good rate function $I_{W_\infty,(1,\ldots, 1)}({\cdot} )$ (from (equation eq:i2 of the paper)) simplifies  for  $t \in \big[\sum_{r=1}^c \mu_r^v, 1\big)$ as $$I_{W_\infty,(1,\ldots,1)}({ t})=\sum_{r=1}^c x_{\theta_{t},\boldsymbol h,r}\log{\frac{x_{\theta_{ t},\boldsymbol h,r}}{\mu_r}}.$$ Here $\theta_{ t}\geq 0$ denotes the unique solution to the equation $\sum_{r=1}^c x_{\theta_{ t},\boldsymbol h,r}^v=t$.







		\item[(ii)] Let $h_r=0$ for all $r\in [c]$ and $\theta_{\rm crit}$ be as in~(prop:potts_gibbs_ldp of the paper) part (ii). For any $\theta>\theta_{\rm crit}$, define $(x_{\theta,1},\ldots ,x_{\theta,c})$ as the unique optimizer which satisfies $x_{\theta,1}>\max_{2\le r\le c} x_{\theta,r}$, the existence of which is guaranteed by ~(prop:potts_gibbs_ldp of the paper) part (ii). Then the good rate function $I_{W_\infty,(1,\ldots,1)}$  simplifies as in part (i), on the range ${ t}$ where $t \in \big(y,1\big)$, where $y:= \lim_{\theta\downarrow \theta_{\rm crit}}\sum_{r=1}^c x^v_{{\theta},r}.$








	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.153670+00:00","domain":"probability theory","id":"claim_fd36a8c8c3479e7dd9192fd96950e11f9c2bd88c57cc16d694d6008fdc8ec494","kind":"theorem","schema_version":1,"statement":"[Proposition 4 (Basic inclusion relations) of arXiv:2608.29406, 'Partially Totally Real Submanifolds of Sasakian Manifolds'] Let \(M\) be a submanifold of a Sasakian manifold tangent to \(\xi\).
