{"assumptions":[],"created_at":"2026-10-26T20:24:47.658795+00:00","domain":"probability theory","id":"claim_fd532ee2d3c8a2aa17ef4a85f61ed626e116a3ff096f2fba119a45c1e43c184b","kind":"definition","schema_version":1,"statement":"[Definition 5 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] [Two-parameter $\left(  \mathbf{X,Y}\right)  $-controlled paths] Let $\omega_\mathbf{X}$, $\omega_\mathbf{Y}$ be controls defined on $[a,b]$ and $[c,d]$ respectively. Let  $p$ and $q$
be in $[1,\infty)$ with $\kappa=\left\lfloor p\right\rfloor $ and
$\lambda=\left\lfloor q\right\rfloor $ and assume that $\mathbf{X} \in \Omega G_{p, \omega_{\mathbf{X}}}([a,b], V)$, $\mathbf{Y} \in \Omega G_{q, \omega_{\mathbf{Y}}}([c,d], W)$. Denote by $\boxtimes_{\mathrm{ext}}$ the external tensor product, and write
$\boxtimes$ for $\boxtimes_{\mathrm{ext}}$ in the sequel.
Let
\[
Z:\left[  a,b\right]  \times\left[  c,d\right]  \rightarrow\mathrm{Hom}\left(
T^{<\kappa}\left(  V\right)  \boxtimes_{\mathrm{ext}} T^{<\lambda}\left(  W\right)
,F\right)
\]
and suppose
\begin{align*}
R^{1}  & :\Delta_{\left[  a,b\right]  }\times\left[  c,d\right]
\rightarrow \mathrm{Hom}\left(  T^{<\kappa}\left(  V\right)  \boxtimes_{\mathrm{ext}}
T^{<\lambda}\left(  W\right)  ,F\right)  \text{ and }\\
R^{2}  & :\left[  a,b\right]  \times\Delta_{\left[  c,d\right]  }
\rightarrow \mathrm{Hom}\left(  T^{<\kappa}\left(  V\right)  \boxtimes_{\mathrm{ext}}
T^{<\lambda}\left(  W\right)  ,F\right)
\end{align*}
are defined respectively by the identities
\begin{align}
Z_{t,u}  & = Z_{s,u}\circ\left[  L_{\mathbf{X}_{s,t}^{<\kappa}}\boxtimes_{\mathrm{ext}}
\text{id}_{T^{<\lambda}\left(  W\right)  }\right]  +R_{s,t}^{1}\left(
u\right)  \text{ and}\nonumber\\
Z_{s,v}  & =Z_{s,u}\circ\left[  \text{id}_{T^{<\kappa}\left(  V\right)
}\boxtimes_{\mathrm{ext}} L_{\mathbf{Y}_{u,v}^{<\lambda}}\right]  +R_{u,v}^{2}\left(
s\right)  .
\end{align}
Then we say that $Z$ is a two-parameter $\left(  \mathbf{X,Y}\right)
$-controlled path if there exist finite constants $C_{1}$ and $C_{2}$ such
that for all $a\leq s\leq t\leq b$ and $c\leq u\leq v\leq d$ and any $\eta\in
T^{<\kappa}\left(  V\right)  $ and $\xi\in T^{<\lambda}\left(  W\right)  $ we
have
\begin{equation}
\left \| R_{s,t}^{1}\left(  u\right)  \left[  \eta_{j}\boxtimes_{\mathrm{ext}}
\xi \right]  \right \| \leq C_{1}\omega_{\mathbf{X}}\left(
s,t\right)  ^{\left(  \kappa-j\right)  /p}\left \| \eta_{j}
\right \| \| \xi \|
\text{, }
\end{equation}
for all $\eta_{j}\in V^{\otimes j}$, $j\in\lbrack0:\kappa)$ and if also
\[
\left\| R_{u,v}^{2}\left(  s\right)  \left[  \eta \boxtimes_{\mathrm{ext}}
\xi _{k}\right]  \right\| \leq C_{2}\omega_{\mathbf{Y}}\left(
u,v\right)  ^{\left(  \lambda-k\right)  /q} \left\| \eta \right\| \left\| \xi_{k}\right\|,
\]
for all $\xi_{k}\in W^{\otimes k}$, $k\in\lbrack0:\lambda).$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.271897+00:00","domain":"probability theory","id":"claim_fd555ae439e1a6ce8cc0054b4ef2e96a9537f55db6c4e38189d1d62604f61d84","kind":"theorem","schema_version":1,"statement":"[Proposition prop: rand_series_ample of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Suppose that $E\to{\boldsymbol{T}}$ is a topological  metric vector bundle over the compact metric space ${\boldsymbol{T}}$. Let  ${\boldsymbol{X}}\subset C^0(E)$  be an ample  Banach space  of sections of $E$ embedded continuously  in $C^0(T)$. 

Suppose that $(u_n)_{n\in {{\mathbb N}}}$ is a sequence of sections  in ${\boldsymbol{X}}$ such that $\spa\big\{ u_n,\;\;n\in {{\mathbb N}}\,\big\}$ is dense in ${\boldsymbol{X}}$ and exists $\alpha>0$  such that
\begin{equation}
\Vert u_n\Vert_{{\boldsymbol{U}}}=O(n^\alpha)\;\;\mbox{as $n\to\infty$}.
\end{equation}
Fix a sequence of positive real numbers $(\lambda_n)_{n\geq 0}$ such that 
\begin{equation}
\liminf_{n\to \infty}\frac{\lambda_n}{n^\beta}>0, 
\end{equation}
for some  $\beta>0$.  Let $\mathfrak{a}\in \EuScript{S}({\mathbb R})$ be an even Schwartz  function such that $\mathfrak{a}(0)=1$. Fix a sequence of  $\mathrm{i.i.d.}$ standard normal random variables $(X_n)_{n\geq 0}$. Then the following hold.

\begin{enumerate}

\item For any $R >0$ the random series  
\begin{equation}
\sum_{n\in {{\mathbb N}}} \mathfrak{a}\big(\,  \lambda_n/R\,\big) X_n u_n
\end{equation}
converges  $\mathrm{a.s.}$ in ${\boldsymbol{X}}$. Denote by $\Phi^R$ the resulting continuous  Gaussian section  of $E$.

\item There exists $R_0$ such that $\forall R>R_0$ the  Gaussian section $\Phi^R$ is ample.

\end{enumerate}","status":"unverified"}

