{"assumptions":[],"created_at":"2026-10-27T17:24:45.891148+00:00","domain":"probability theory","id":"claim_fd58026e99744a224ae081ea63ad1dfef9ffda89d70e608d26275a5dbe673ea3","kind":"theorem","schema_version":1,"statement":"[Theorem thm:asympvar improvement of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $P\in \mathcal{L}(\pi)$ be $\pi$-reversible. Let $G$ be a locally compact topological group with Haar measure $\mu$ that acts on $\mathcal{X}$, and assume that $\pi$ is $G$-invariant. Let $A:=-L$ for simplicity of presentation. We further assume that marginals of $\nu$ on both coordinates are the Harr measure $\mu$, that is, $g,h\sim\mu$ and $(g,h)\overset{D}{=}(h^{-1}, g^{-1})$ so that $P_{da}(G,\nu) \in \mathcal{L}(\pi)$ (recall Proposition (prop:inheritance of properties of the paper)). The following statements hold:
    \begin{enumerate}[label=(\roman*)]
        \item If $f\in V'$, 
        \begin{equation*}
            v(f, P_{da}(G,\nu)) = v(f, P)-2\left\|\mathbf{P}_{A^{-1/2}V^\perp}A^{-1/2}[f]\right\|_\pi^2,
        \end{equation*}
        and $v(f, P_{da}(G,\nu))=v(f, P)$ iff $f\in AV'\cap V'$, where $AV':=\{A\phi: \phi\in V'\}$.

        \item Assume further that $P$ is compact. The worst-case asymptotic variance of $P_{da}(G,\nu)$ is at least no larger than that of $P$, that is,
        \begin{equation*}
            \sup_{f\in L_0^2(\pi), \|f\|_\pi=1} v(f, P_{da}(G,\nu))=\frac{2-\lambda(P_{da}(G,\nu))}{\lambda(P_{da}(G,\nu))}\leq \frac{2-\lambda(P)}{\lambda(P)}=\sup_{f\in L_0^2(\pi), \|f\|_\pi=1} v(f, P).
        \end{equation*}
    \end{enumerate}","status":"unverified"}

