{"assumptions":[],"created_at":"2026-10-26T20:24:59.505822+00:00","domain":"probability theory","id":"claim_fd8a19c4e5624466540b96481f793d488a1302854e9fa62dd3dda42527a44b5d","kind":"concept","schema_version":1,"statement":"[Proposition 101 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] \cite[Prop. 2.23]{Tappe}
Let $Y$ be a continuous $L(U,H)$-valued process, and let $Y'$ be a continuous $L(U,L(U,H))$-valued processes such that $(Y,Y') \in \scrd_X^{2 \alpha}([0,T],L(U,H))$ on $N_1^c$. Then the following statements are true:
\begin{enumerate}
\item The $H$-valued rough integral
\begin{align*}
\int_0^T Y_s \, d \mathbf{X}_s = \lim_{|\Pi| \to 0} \sum_{[u,v] \in \Pi} ( Y_u X_{u,v} + Y_u' \bbx_{u,v} )
\end{align*}
exists on $N_1^c$.

\item If $Y$ and $Y'$ are adapted and bounded, then there is a $\bbp$-nullset $N$ with $N_1 \subset N$ such that
\begin{align*}
\int_0^T Y_s \, d \mathbf{X}_s = \int_0^T Y_s|_{U_0} \, dX_s \quad \text{on $N^c$.}
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:56:37.641976+00:00","domain":"probability theory","id":"claim_fd8ecc11361e2ecf8d27f5f17a950ecc63d098142509d2dc42e7726eee80f58f","kind":"definition","schema_version":1,"statement":"[Def single site of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] We say that a Borel measure $\rho$ on $\mathbb R$ is \emph{admissible} if it satisfies the following properties:
\begin{enumerate}
    \item[$(i)$] $\rho$ is \emph{even}, which means that for every Borel measurable set $A\subset \mathbb R$, $\rho(A)=\rho(-A)$. 
    \item[$(ii)$] $\rho$ is \emph{super-Gaussian}, in the sense that, for every $a>0$, one has
    \begin{equation}
        \int_{\mathbb R}e^{au^2}\mathrm{d}\rho(u)<\infty.
    \end{equation}
    \item[$(iii)$] $\rho$ has a non-trivial support, i.e.\ $\rho(\mathbb{R}\setminus\{0\})>0$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:23:05.301841+00:00","domain":"probability theory","id":"claim_fd8f02fcdac2d94bc29456b39a12e35ed7b4a9a4b0065bef27fdb78c08e72a3c","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2608.21787, 'Stability of extremal hyperplane projections of balls in $\ell_p^n(\R)$'] There exists a positive constant $c_p$ depending only on $p$ such that for every $n \ge 1$ and every vector $a = (a_1, \ldots, a_n) \in \R^n$ with $\sum_{i=1}^na_i^2 = 1$ and $a_1 \ge a_2 \ge \ldots \ge a_n \ge 0$ we have:\begin{enumerate}
            \item[(a)] if $2 < p \le \infty$, then
            \begin{align*}
                \frac{\vol_{n-1}\left(\Proj_{a^{\perp}}B_p^n\right)}{\vol_{n-1}\left(\Proj_{a_{(1)}^{\perp}}B_p^n\right)} \ge 1 + c_p\left|a - a_{(1)}\right|^2;
            \end{align*}
            \item[(b)] if $p = \infty$, then
            \begin{align*}
                \frac{\vol_{n-1}\left(\Proj_{a^{\perp}}B_p^n\right)}{\vol_{n-1}\left(\Proj_{a_{(n)}^{\perp}}B_p^n\right)} \le 1 - \frac{c_{\infty}}{n}\sum_{i, j = 1}^n\left(a_i - a_j\right)^2;
            \end{align*}
            \item[(c)] if $2 < p < \infty$, then
            \begin{align*}
                \frac{\vol_{n-1}\left(\Proj_{a^{\perp}}B_p^n\right)}{\vol_{n-1}\left(\Proj_{a_{(n)}^{\perp}}B_p^n\right)} \le 1 - c_p\sum_{i=1}^n\left(a_i^2 - \frac 1 n\right)^2;
            \end{align*}
            \item[(d)] if $1 \le p < 2$, then
            \begin{align*}
                \frac{\vol_{n-1}\left(\Proj_{a^{\perp}}B_p^n\right)}{\vol_{n-1}\left(\Proj_{a_{(1)}^{\perp}}B_p^n\right)} \le 1 - c_p\left|a - a_{(1)}\right|^2.
            \end{align*}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.781867+00:00","domain":"probability theory","id":"claim_fd8f7bd197918400238663c839ee1f466ab4a881cdd5b8948a5c72080575b8b5","kind":"concept","schema_version":1,"statement":"[Prop Convergence of Moments of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For any fixed $j_1,j_2$, $k_1,\dots,k_{j_1}$, and $k'_1,\dots,k_{j_2}'$ we have
\begin{equation*}
    \begin{split}
        \mathbb{E}&\left[\Tilde{a}_{k_1}(t_1)\cdots \Tilde{a}_{k_{j_1}}(t_{j_1})\frac{1}{\sqrt{n}}\left(\Tilde{b}_{k'_1}(t_1')^2-n\right)\cdots\frac{1}{\sqrt{n}}\left(\Tilde{b}_{k'_{j_2}}(t_{j_2}')^2-n\right)\right]\\
        &=\mathbb{E}\left[A_{k_1}(t)\cdots A_{k_{j_1}}(t)B_{k_1}(t)\cdots B_{k_{j_2}}(t)\right]+O(1/n)\\
        & =\bigg(2^{j_1/2}\sum_{\pi \in \mathcal{P}_2(j_1)} \prod_{(i_1,i_2) \in \pi}e^{-(2k_{i_1}-1)|t_{i_1}-t_{i_2}|}\delta_{k_{i_1},k_{i_2}} \bigg)\\
        & \hspace{4cm}\times\bigg(2^{j_2/2}\sum_{\pi \in \mathcal{P}_2(j_2)} \prod_{(i_1,i_2) \in \pi}e^{-2k'_{i_1}|t_{i_1}'-t_{i_2}'|}\delta_{k'_{i_1},k'_{i_2}} \bigg)+O(1/\sqrt{n}).
    \end{split}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

