{"assumptions":[],"created_at":"2026-10-28T00:37:20.362896+00:00","domain":"probability theory","id":"claim_fd9a3aeacd46caffc1976efb068d5abae94d6b6941f12d153512c9db39decd5d","kind":"definition","schema_version":1,"statement":"[Definition e:pnfi of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] {\rm 

\smallskip\noindent{\bf Principle of  no future information} (PNFI). 
