{"assumptions":[],"created_at":"2026-10-27T22:31:02.833604+00:00","domain":"probability theory","id":"claim_fe05a29b86fad8380ca29c8207681a110bf809f8a3fa24e3236d8d52814b908c","kind":"theorem","schema_version":1,"statement":"[Thm eq:B2_0 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let $k_i > -\frac12$, $1 \le i \le d$. Then for $f$ being a polynomial of degree at most $n$ on ${\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}$, 
\begin{align}
 \sum_{1 \le i< j \le d_1} & \left \| \frac{1}{\sqrt{1-|\bm y|}}  D_{i,j}^{(\bm x)} f \right \|_{{\boldsymbol{\kappa}}}^2   + 
  \sum_{1\le i< j \le d_2} \left\| (\partial_{y_j} - \partial_{y_j}) f \right\|_{{\boldsymbol{\kappa}}} ^2 \\
    & + 
   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 
   \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2. \notag
\end{align}
Moreover, the inequality is sharp in the sense that the equality is attainable by some polynomial of degree $n$, and 
so are the next two inequalities,
\begin{align}
 \sum_{1 \le i< j \le d_1}  \left \| \frac{1}{\sqrt{1-|\bm y|}}  D_{i,j}^{(\bm x)} f \right \|_{{\boldsymbol{\kappa}}}^2   
    & +   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 \\
    & \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2, \notag
\end{align}
\begin{align}
  \sum_{1\le i< j \le d_2} \left\| (\partial_{y_j} - \partial_{y_j}) f \right\|_{{\boldsymbol{\kappa}}} ^2 & + 
   \sum_{i=1}^{d_2} \left \| \sqrt{y_i  (1-|\bm y|)}  \partial_{y_i} f\right\|_{{\boldsymbol{\kappa}}} ^2 \\
  & \le   n(n+ |{\boldsymbol{\kappa}}| + d_1 + d_2-1)\|f\|_{{\boldsymbol{\kappa}}}^2. \notag
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.300412+00:00","domain":"probability theory","id":"claim_fe07a998f99313534ea87a5bf14fe3125c13ca1c3b824e640bb9e0d1d235b335","kind":"concept","schema_version":1,"statement":"[Prop discretize of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] Given a strong solution $t\mapsto \text{\boldmath $x$}^{(t)}\in\mathbb{R}^N$ to the SDE

    \begin{align*}
{\rm d}\text{\boldmath $x$}^{(t)}=\text{\boldmath $a$}(\text{\boldmath $x$}^{(t)}){\rm d} t+\sigma{\rm d}\text{\boldmath $w$}^{(t)}
\end{align*}

    on $\mathbb{R}^N$ for some function $\text{\boldmath $a$}:\mathbb{R}^N\rightarrow\mathbb{R}^N$ and constant diffusion coefficient $\sigma$, along with a step
    size $\delta\in(0,1)$, consider the Euler-Maruyama scheme
    $\text{\boldmath $y$}^{(0)},\text{\boldmath $y$}^{(1)},\text{\boldmath $y$}^{(2)},\ldots$ defined recursively by
    $\text{\boldmath $y$}^{(0)}=\text{\boldmath $x$}^{(0)}$ and

    \begin{align*}
\text{\boldmath $y$}^{(n+1)}=\text{\boldmath $y$}^{(n)}+\delta
\text{\boldmath $a$}(\text{\boldmath $y$}^{(n)})+\sigma(\text{\boldmath $w$}^{(\delta(n+1))}-\text{\boldmath $w$}^{(\delta n)}).
\end{align*}

    Suppose that, for some positive constants $K_1,K_2,K_3$, we have that
    $\mathbb{E}[\|\text{\boldmath $x$}^{(0)}\|^2]\le K_1N$, $\| \text{\boldmath $a$}({\boldsymbol 0})\|^2\le K_2N$, and
    $\| \text{\boldmath $a$}(\text{\boldmath $u$})-\text{\boldmath $a$}(\text{\boldmath $v$})\|\le K_3\|\text{\boldmath $u$}-\text{\boldmath $v$}\|$ for all $\text{\boldmath $u$},\text{\boldmath $v$}\in\mathbb{R}^N$,
    i.e. the initial condition is bounded in $L^2$ and the drift
    coefficient is Lipschitz and bounded at the origin. Then there
    exists a constant $L$ depending only on $K_1,K_2,K_3$ such that
    for all $\delta>0$ and $T\in\delta\mathbb{N}$, we have that

    \begin{align*}
\mathbb{E}[\|\text{\boldmath $x$}^{(T)}-\text{\boldmath $y$}^{(T/\delta)}\|^2]\le Le^{LT}\delta N.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:44:27.925167+00:00","domain":"probability theory","id":"claim_fe0ad92907f82367b9642902e01519b401e3f9a442bb7f1bea0fb9f565b02715","kind":"lemma","schema_version":1,"statement":"[Lemma 8 of arXiv:2607.12667, 'Phase Transition of Eigenvalues of Covariances from the Spiked Mixture Model in High-dimen'] Let $\X \in \mathbb{R}^{d\times n}$ have \ac{iid} Gaussian entries $\mathcal{N}(0,1)$. Partition the columns as $X = \begin{bmatrix}
    \X_1 & \X_2
\end{bmatrix}$, with $\X_1 \in \mathbb{R}^{d\times n_1}$, $\X_2 \in \mathbb{R}^{d\times (n-n_1)}$, and $n_1 \sim B(n,\pi_1)$ an independent random variable sampled from the Binomial distribution. Set
\begin{align*}
    \Sb_n &:= \frac{\X\X^\mathsf{T}}{n}, &&\R_n(z):= (z\I- \Sb_n)^{-1}, \text{and } &&\A_n(z) := \R_n(z)\frac{\X_1\X_1^\mathsf{T}}{n_1},
\end{align*}
where $z \in \mathbb{C}\setminus \{\lambda_1(\Sb_n), \ldots, \lambda_d(\Sb_n)\}$.

Assume $d,n \to \infty$ with $d/n \to \gamma \in (0, \infty)$. Then, 
\begin{align*}
    \frac{1}{d}Tr(\A_n(z)) \xrightarrow[]{\text{a.s.}} T(z),
\end{align*}
where $T(z) = \int_t \frac{t}{z-t} d\mu_{\text{MP}(\gamma)}(t)$ is the $T$-transform of the \acl{MP} law of parameter $\gamma$. 
Moreover, this convergence is uniform on $\mathcal{K}(\eta) = \{z\in \mathbb{C},\: d(z,[a,b])> \eta\}$ for all real scalars $\eta>0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:55:18.058848+00:00","domain":"probability theory","id":"claim_fe0b09a5cc07f3a2a1abb4133ae223a60fbaaa827537cb85efbc94ae5c1f4926","kind":"lemma","schema_version":1,"statement":"[Lemma 47 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $t>0$ and $q\in\mcl Q_{\upa,c}$ for some $c>0$. Then, there are constants $b,N_0,r_0>0$ such that
\begin{align*}
    \frac{\d^2}{\d r^2}\bar F_N\Ll(t,\ q+a_i r q_i+N^{-\gamma/2}\sum_{j\neq i}a_j y_jq_j \Rr) \leq b,\quad\forall i\in\N,\  N\geq N_0, \  r\in[0,r_0).
\end{align*}
Moreover, the same statement holds for $\tilde F_N^x$ and $\bar F^x_{N+1}$ in place of $\bar F_N$, uniformly in $x\in[0,3]^{\N^4}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:25:06.127636+00:00","domain":"probability theory","id":"claim_fe0e0056be196474d70a99b56062c1562fbafe320a2d963c92403e0c8eefed18","kind":"lemma","schema_version":1,"statement":"[Lemma 23 of arXiv:2608.22342, 'Completely Positive Entropy and Fourier Central Limit Theorems for Stationary Random Measu'] The random element $Y$ belongs to $L^2_0(\eta;\mathscr H_s)$ and, for
$k\in\bZ^d$,
