{"assumptions":[],"created_at":"2026-10-27T20:14:57.712764+00:00","domain":"probability theory","id":"claim_fe20eaf5499dbd36fa04213210b80a60dca67f3fb32047ccfe79b3fe5c4c660b","kind":"concept","schema_version":1,"statement":"[Theorem thm:TLC of arXiv:2605.30999, 'Functional central limit theorems for $U$-statistics of $\beta$-mixing data'] Let $h\colon S^m\to\mathbb R$ be a symmetric kernel, where $\pr{S,\mathcal{S}}$ is a measurable space, let $\left(X_i\right)_{i\geqslant 1}$ be a strictly stationary sequence. Let $h_1\colon S\to \mathbb R$ be defined as 
\begin{equation}
    h_1\left(x\right)=\int h\pr{x,y_1,\dots,y_{m-1}}d\mathbb P_{X_0}\left(y_1\right)\dots 
    d\mathbb P_{X_0}\pr{y_{m-1}},\quad x\in S.
\end{equation}

Suppose that following conditions are satisfied:
\begin{equation}
    \sum_{k= 1}^\infty \int_0^{\alpha\left(\sigma\left(X_i,i\leqslant 0\right),\sigma\left(X_k\right)\right)}Q^2_{ h_1\left(X_0\right) }\left(u\right)du<\infty,
\end{equation}
\begin{equation}
 \mbox{the family }   \ens{H_{\bm{i},k}^2,k\in\llbracket 1,m\rrbracket,\bm{i}\in\operatorname{Inc}^k}
    \mbox{is uniformly integrable and}
\end{equation}
\begin{equation}
    \sum_{k=1}^{+\infty} k\beta\left(k\right)<+\infty.
\end{equation}


 Then the following convergence in distribution takes place: 
 \begin{equation*}
     \frac{\sqrt{n}}{\binom nm}\pr{U_{m,n}\left(h\right)-\E{U_{m,n}\left(h\right)} }
     \to m\sigma\mathcal{N},
 \end{equation*}
 where $\mathcal{N}$ has a standard normal distribution and $\sigma^2$ 
 is given by 
 \begin{equation}
    \sigma^2=\sum_{i\in\mathbb Z}\operatorname{Cov}\left(h_1\left(X_0\right),h_1\left(X_i\right)\right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:04:40.985629+00:00","domain":"probability theory","id":"claim_fe2636753cb0f451dba7646cd28cd929c9fd2240626b732d541263725f6d124b","kind":"concept","schema_version":1,"statement":"[Theorem thm:boundary_length_evolution of arXiv:2412.04005, '$\SLE_{\kappa}(\rho)$ processes in the light cone regime on\\ Liouville quantum gravity'] Suppose that we have the setup described in the statement of Theorem~(thm:quantum_natural_time_cutting of the paper) and the process $(L,R)$ is as described just above.  Then $(L,R)$ is an $\alpha$-stable L\'evy process with
\begin{align}
\alpha = 1 - \frac{2(\rho+2)}{\kappa} \in (1,2).
\end{align}
Moreover,  $L$ (resp.\ $R$) has only upward (resp.\ downward) jumps and the jump times of $L$ coincide with the jump times of $R$.  In the case that $\kappa \in (\frac{4}{3},2)$ and $\rho = \kappa - 4$ the sequence of jumps of $(L,-R)$ forms a Poisson point process (p.p.p.) $\Lambda^*$ whose law can be sampled from as follows.
\begin{itemize}
\item Firstly,  we sample a p.p.p.\  $\Lambda = \{(s_j,t_j) : j \in \mathbf{N} \}$ on $\mathbf{R}_+ \times \mathbf{R}_+$ with intensity measure given by $c(du \times t^{-4/\kappa}dt)$,  where $c > 0$ is a constant depending only on $\kappa$.
\item Next, we sample independently a sequence of i.i.d.\ random variables $(u_j)_{j \in \mathbf{N}}$ which are uniform on $[0,1]$ and consider 
\begin{align*}
\Lambda^* = \{(t_j u_j,  (1-u_j)t_j) : (s_j,t_j) \in \Lambda,  j \in \mathbf{N}\}.
\end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

