			\end{equation}
			and
			\begin{equation}
				\|G\|_{\underline L^2(\square_M)}+3^{sM}[G]_{\underline H^{s}(\square_M)}\le C 3^{(1-s)M}\|g\|_{\hat{\phantom{H}}\v@true\h@true\negph@nt{H}\underline{H}^{-s}(\square_M)}\, .
