{"assumptions":[],"created_at":"2026-10-26T20:57:44.949000+00:00","domain":"probability theory","id":"claim_ff170f543557e1149a85ff0a3f8dba9872df7097b45ac61e78c8b32d313204b6","kind":"lemma","schema_version":1,"statement":"[Lemma 6 (Approximate self-consistent equations) of arXiv:2606.24887, '2606.24887'] For all $x\in[N]$, $w \in \CC$ and $z \in \CC_+$ we have
		\begin{align*}
			1 &= -z G_{xx} - \bigg(\sum_{y}^{(x)} |X_{xy}|^{2}G^{\bset{x}}_{\ubarr{y}\ubarr{y}}\bigg) G_{xx} - w G_{ \ubarr{x}x}+ Y^1_{x} G_{xx} + Z^{1}_{x}G_{ \ubarr{x}x}\\
			0 &= -z G_{x\ubarr{x}} - \bigg(\sum_{y}^{(x)} |X_{xy}|^{2}G^{\bset{x}}_{\ubarr{y}\ubarr{y}}\bigg) G_{x\ubarr{x}} - w G_{ \ubarr{x}\ubarr{x}} + Y^1_{x} G_{x\ubarr{x}} + Z^{1}_{x}G_{ \ubarr{x}\ubarr{x}}\\
			0 &=  -z G_{\ubarr{x}x} - \bigg(\sum_{y}^{(x)} |X_{yx}|^{2}G^{\bset{x}}_{yy}\bigg) G_{\ubarr{x}x} -\barr{w} G_{xx} + Y^2_{x} G_{\ubarr{x}x} + Z^{2}_{x}G_{ xx}\\
			1 &=  -z G_{\ubarr{x}\ubarr{x}} - \bigg(\sum_{y}^{(x)} |X_{yx}|^{2}G^{\bset{x}}_{yy}\bigg) G_{\ubarr{x}\ubarr{x}} -\barr{w} G_{x\ubarr{x}} + Y^2_{x} G_{\ubarr{x}\ubarr{x}} + Z^{2}_{x}G_{ x\ubarr{x}}
		\end{align*}
		where the error terms are given by
		\begin{align*}
			Y_{x}^1 &= - \sum_{a \neq b}^{(x)} X_{xa} G^{\bset{x}}_{\ubarr{a}\ubarr{b}} \barr{X}_{xb}  - \sum_{a,b}^{(x)} \biggl(\frac{f}{N}\left[X_{xa} G_{\ubarr{a}\ubarr{b}}^{\bset{x}} + G_{\ubarr{a}\ubarr{b}}^{\bset{x}} \barr{X}_{xb} \right] + \frac{f^2}{N^2}G_{\ubarr{a}\ubarr{b}}^{\bset{x}}\biggr) ,\\

			Z_x^1 &=X_{xx} - \sum_{a,b}^{(x)} \left(X_{xa} + \frac{f}{N} \right) G_{\ubarr{a}b}^{\bset{x}} \left(X_{bx} + \frac{f}{N}\right)\\
			Y_{x}^2 &= - \sum_{a\neq b}^{(x)} \barr{X}_{ax} G_{ab}^{\bset{x}}X_{bx} - \sum_{a,b}^{(x)} \biggl(\frac{f}{N}\left[\barr{X}_{ax} G_{ab}^{\bset{x}} + G_{ab}^{\bset{x}} X_{bx} \right] + \frac{f^2}{N^2}G_{ab}^{\bset{x}}\biggr) \\
			Z_x^2 &= \barr{X}_{xx} - \sum_{a,b}^{(x)}\left(\barr{X}_{ax} + \frac{f}{N} \right) G_{a\ubarr{b}}^{\bset{x}} \left(\barr{X}_{xb} + \frac{f}{N}\right).
		\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.629220+00:00","domain":"probability theory","id":"claim_ff172c05577578084c8732fa6abfbf3532c25491c799b7d54c509fb82032a263","kind":"concept","schema_version":1,"statement":"[Theorem thm:upper_bound_comono_tech of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\alpha \in (0,2)\setminus\{1\}$, $\bm{X}$ and $\bm{Z}$ be as above and Assumptions~(\nameref{asm:S}) \& (\nameref{asm:C}) hold. Then, for every $q\in(0,1]$ with $\int_{\mathbb{R}^d\setminus B_{\bm{0}}(1)}|\bm{w}|^q\nu_{\bm{X}}^{\mathrm{d}}(\mathrm{d}\bm{w})<\infty$ 
we have $\mathds{E}\big[\sup_{s\in[0,1]} |\bm{R}^t_s|^q\big] = \mathcal{O} \big(t^{1-q/\alpha}G(t)^{-q}\big)$ as $t\downarrow 0$ and, if $p\ne\alpha-1$ and $q\in (0,\alpha)\cap(0,1]$ satisfy $q\notin\{\alpha/(p+1),\alpha/(\alpha\delta+1)\}$, we have, as $t \downarrow 0$,
\begin{align}
    \mathcal{W}_2\big(\bm{M}^{\bm{S}^t},\bm{M^Z}\big)
&=\mathcal{O}\big(G_2(t)+(1+G(t)^{p})t^{\min\{p/\alpha,\delta\}}\big),\\
\mathcal{W}_q\big(\bm{L}^{\bm{S}^t}, \bm{L}^{\bm{Z}}\big) 
&= \mathcal{O} \big( G_2(t)^q
    + (1+G(t)^{pq})(1+G_1(x))^{q(1+p)}
        t^{\min\{pq/\alpha,q\delta,1-q/\alpha\}}\big), \qquad \text{ and }\\
