{"assumptions":[],"created_at":"2026-10-27T13:52:23.564822+00:00","domain":"probability theory","id":"claim_ff67c64167eea2644515bc1ebd3b287618caf7d0e275f773c6d41280f869dce7","kind":"concept","schema_version":1,"statement":"[Theorem T:Dalang of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume that
  \begin{align*}
    \alpha >0, \quad
    \beta  \in (0,2],   \quad
    H      \in [1/2,1), \quad \text{and} \quad
    \ell   \in (0,2d).
  \end{align*}
  We have the following three cases (see Figure~(F:Dalang of the paper))
  \begin{enumerate}[\rm (i)]

    \item If either $\beta \in (0,2)$ and $\gamma \geq 0$ or $\beta = 2$ and
          $\gamma > 1$, then we have
          \begin{subequations}
            \begin{align}
              K(\alpha,\beta,\gamma;H,\ell;\nu,d) <\infty
               & \quad\Longleftrightarrow\quad \rho_0 = \beta + \gamma - 1 + H -\frac{\ell \beta}{2\alpha} >0 \quad \text{and}\quad \ell < 2\alpha \\
               & \quad\Longleftrightarrow\quad 0 <\ell < 2\alpha + \frac{2\alpha}{\beta}\min\left(0, \gamma + H -1\right). 
            \end{align}
          \end{subequations}

    \item If $\beta = 2$ and $\gamma = 0$, then
          \begin{align}
            K(\alpha,2,0;H,\ell;\nu,d) <\infty \quad\Longleftrightarrow\quad
            0 < \ell < \left(1/2+H\right) \alpha.
          \end{align}

    \item If $\beta = 2$ and $\gamma \in (0, 1]$, then
          \begin{align}
            K(\alpha,\beta,\gamma;H,\ell;\nu,d) <\infty \quad\Longleftarrow\quad
            0 < \ell <  \min\left(2, \gamma+H+1/2\right) \alpha .
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.839818+00:00","domain":"probability theory","id":"claim_ff6840f07b0392382bf594dd3940c0c323742742784061b41a98aff732706a29","kind":"definition","schema_version":1,"statement":"[Definition 4 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] A function $\rho \in L^1_\loc(I\times \R^d)$ is a (weak) solution of
