{"assumptions":[],"created_at":"2026-10-26T19:25:12.199334+00:00","domain":"probability theory","id":"claim_ff9e0332e0550f7420da859dfeacbb8ae8856f73fc0920bc57f57adafe4c81b8","kind":"concept","schema_version":1,"statement":"[Lem 54 (\hspace{-0.05em}{{\cite[Proof of Proposition~2) of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] {lalley2000rate}}}]

