 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_2)}\|_2 (\y^{(i_2)})^T(b_2\u^{(2,1)}+b_2\u^{(2,2)})\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2(a_1u^{(4,1)}+a_2u^{(4,2)}) +\sqrt{1-t}\|\y^{(i_2)}\|_2(c_1\h^{(1)}+c_2\h^{(2)})^T\x^{(i)}
\nonumber \\
